INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7a831a66-3043-41ca-88dd-cb335ff25fc8','Maximum sound level','The maximum sound level is the highest time-weighted (Fast or Slow) sound pressure level reached during a stated measurement interval, written for example as LAFmax or LASmax. The time weighting must be stated because it changes the value.','Maximum sound level is the loudest reading during a measurement. A meter setting called Fast or Slow smooths the signal first. The highest smoothed level is the maximum. You must say which weighting was used, because it changes the number.','It captures the peak of the meter''s smoothed reading during an event, useful for judging the loudest moment of noise.','Monitoring a passing truck, a technician records LAFmax = 82 dB; switching to Slow weighting gives a slightly lower LASmax because Slow averages over more time.','Sound Level',ARRAY['Minimum sound level','Maximum-event level','Peak C-weighted level','Fast time weighting','Slow time weighting']::text[],ARRAY['Confusing maximum sound level (a smoothed, time-weighted level) with peak level (true instantaneous).','Omitting the time weighting, making the value ambiguous.','Assuming Fast and Slow give the same maximum; Fast usually reads higher on transients.']::text[],ARRAY['Logging the loudest moment of a traffic pass-by.','Checking a venue against a maximum-level noise limit.','Comparing peak events in an environmental noise survey.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7a831a66-3043-41ca-88dd-cb335ff25fc8','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7a831a66-3043-41ca-88dd-cb335ff25fc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7a831a66-3043-41ca-88dd-cb335ff25fc8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e248363e-64cd-4690-995b-fb83cb4d2ebd','Maximum-event level','The maximum-event level is the highest sound level attained during a single defined noise event, such as one aircraft flyover or vehicle pass-by, usually expressed as a time-weighted A-level (for example LASmax). It describes only the loudest instant of the event, not its duration.','The maximum-event level is the loudest point of one noise event. An event might be a single plane flying over. The meter notes the highest level during that pass. It ignores how long the event lasted. A related measure, sound exposure level, adds duration back in.','It gives a single figure for the loudest moment of an isolated event, used in event-based noise monitoring like airport systems.','An airport monitor logs each flyover''s maximum-event level; a jet reading LASmax = 88 dB is compared against a night-time event limit.','Sound Level',ARRAY['Maximum sound level','Sound exposure level','Single-event level','Noise event','Slow time weighting']::text[],ARRAY['Assuming it accounts for duration; a short and a long event can share the same maximum.','Mixing it up with sound exposure level, which folds in duration.','Comparing values measured with different time weightings as if equal.']::text[],ARRAY['Airport noise monitoring of individual aircraft flyovers.','Assessing single vehicle pass-bys near a residence.','Setting per-event limits for outdoor concerts.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum-event level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e248363e-64cd-4690-995b-fb83cb4d2ebd','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e248363e-64cd-4690-995b-fb83cb4d2ebd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e248363e-64cd-4690-995b-fb83cb4d2ebd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '266b0b59-2f36-417c-bea2-ad9da710d9ad','Measurement surface','In sound-power determination, the measurement surface is the hypothetical surface, such as a hemisphere or rectangular box, that encloses the noise source and over which sound pressure or intensity is sampled. Its area is used with the average level to compute radiated sound power.','The measurement surface is an imaginary shape wrapped around a noisy machine. Engineers measure sound at points on this surface. They combine those readings with the surface area. This gives the total sound power the machine radiates. Common shapes are a half-sphere or a box.','It provides a defined area over which to average sound so that a source''s total radiated sound power can be calculated.','Using a hemispherical surface of radius 2 m, its area is 2*pi*r^2 = about 25.1 m^2; the average level over it plus 10*log10(25.1) gives the sound power level.','Acoustic Measurement',ARRAY['Sound power level','Sound intensity','Measurement points','Hemispherical surface','Reference box']::text[],ARRAY['Using the wrong surface area in the sound-power equation.','Placing measurement points too sparsely to represent the field.','Forgetting the surface must fully enclose the source for the method to hold.']::text[],ARRAY['Determining a machine''s sound power in a hemi-anechoic room.','Comparing appliance noise emissions for a datasheet.','Setting up an intensity scan around equipment on a factory floor.']::text[],'Intermediate','L_W = L_p_bar + 10*log10(S / S_0)','The sound power level equals the surface-averaged sound pressure level plus ten times the base-ten log of the measurement-surface area divided by the reference area of one square metre.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement surface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '266b0b59-2f36-417c-bea2-ad9da710d9ad','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='266b0b59-2f36-417c-bea2-ad9da710d9ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='266b0b59-2f36-417c-bea2-ad9da710d9ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '447dabd0-38fb-4577-934c-06cd7cc831cc','Mechanical damping','Mechanical damping is the dissipation of vibrational energy in a mechanical system, converting motion into heat and reducing oscillation amplitude over time. It is quantified by the damping ratio zeta or the quality factor Q of the resonance.','Mechanical damping is how a vibrating part loses energy. The motion turns into heat and dies away. More damping means vibrations fade faster. It is described by a damping ratio or a quality factor. A loudspeaker''s suspension adds mechanical damping.','It controls how quickly vibrations decay and how sharp a resonance is, shaping a system''s transient and frequency behaviour.','A resonator with damping ratio zeta = 0.05 has a quality factor Q = 1/(2*zeta) = 10, so its resonance peak is fairly narrow and rings for many cycles.','Mechanics',ARRAY['Mechanical resonance','Damping ratio','Quality factor','Qms','Moving mass']::text[],ARRAY['Assuming more damping is always better; too much dulls response and wastes output.','Confusing the damping ratio with the damping coefficient c; they are related but not equal.','Thinking damping changes the natural frequency greatly; light damping barely shifts it.']::text[],ARRAY['Tuning a loudspeaker suspension for a controlled low-frequency response.','Adding damping material to reduce panel ringing.','Analysing how fast a struck structure stops vibrating.']::text[],'Intermediate','zeta = c / (2*sqrt(k*m));  Q = 1/(2*zeta)','The damping ratio equals the damping coefficient divided by twice the square root of stiffness times mass; the quality factor is one over twice the damping ratio.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '447dabd0-38fb-4577-934c-06cd7cc831cc','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='447dabd0-38fb-4577-934c-06cd7cc831cc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='447dabd0-38fb-4577-934c-06cd7cc831cc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '135735eb-3297-4b95-baa6-624c8955815f','Mechanical resonance','Mechanical resonance is the frequency at which a mechanical system responds with maximum amplitude to a driving force, occurring where the system''s mass and stiffness reactances cancel. For a simple mass-spring system it is f = (1/2*pi)*sqrt(k/m).','Mechanical resonance is a system''s favourite vibration frequency. At this frequency a small push makes a big motion. It depends on the part''s mass and stiffness. A loudspeaker cone has such a resonance. Engineers must know it to control the response.','It identifies the frequency where a structure vibrates most easily, which must be managed to avoid excessive motion or coloured response.','A cone assembly with stiffness k = 2000 N/m and moving mass m = 0.02 kg resonates at f = (1/2*pi)*sqrt(2000/0.02) = about 50 Hz.','Mechanics',ARRAY['Mechanical damping','Free-air resonance','Moving mass','Compliance','Quality factor']::text[],ARRAY['Assuming heavier always means higher resonance; more mass lowers it.','Ignoring damping, which limits the peak height at resonance.','Confusing mechanical resonance with electrical or acoustic resonance in the same device.']::text[],ARRAY['Finding a loudspeaker driver''s free-air resonance fs.','Avoiding a structural resonance that a motor would excite.','Designing a mount to move a resonance out of the operating range.']::text[],'Intermediate','f = (1/(2*pi)) * sqrt(k/m)','The resonance frequency equals one over two pi times the square root of stiffness divided by mass.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '135735eb-3297-4b95-baa6-624c8955815f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='135735eb-3297-4b95-baa6-624c8955815f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='135735eb-3297-4b95-baa6-624c8955815f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f29adc76-42d3-46d6-9625-4435aed0b1e2','Medical ultrasound','Medical ultrasound is diagnostic or therapeutic use of sound at frequencies above human hearing, typically about 2-18 MHz for imaging, generated and received by piezoelectric transducers. Imaging works by pulse-echo: a pulse is sent, and reflections from tissue boundaries are timed and displayed.','Medical ultrasound uses very high sound to look inside the body. The frequencies are far above what we can hear, in the megahertz range. A crystal probe sends short pulses. Echoes bounce back from tissue and form an image. It is common for scanning during pregnancy.','It lets clinicians image internal structures safely and in real time using reflected high-frequency sound instead of ionising radiation.','A 5 MHz probe images at moderate depth; because sound travels about 1540 m/s in soft tissue, an echo from 5 cm deep returns in roughly 65 microseconds.','Ultrasound',ARRAY['Ultrasound','Piezoelectric crystal','Phased array ultrasound','Pulse-echo','Transducer']::text[],ARRAY['Assuming higher frequency always images deeper; higher frequency gives detail but less depth.','Confusing diagnostic imaging with high-intensity therapeutic ultrasound.','Thinking ultrasound uses radiation; it uses mechanical sound waves.']::text[],ARRAY['Obstetric imaging of a fetus.','Guiding a needle during a biopsy.','Comparing probe frequencies for depth versus resolution.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Medical ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f29adc76-42d3-46d6-9625-4435aed0b1e2','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f29adc76-42d3-46d6-9625-4435aed0b1e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f29adc76-42d3-46d6-9625-4435aed0b1e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ca1bbb6-5de5-4939-ba57-5092cee1436c','Mel-frequency spectrum','A mel-frequency spectrum is a spectrum whose frequency axis is warped to the mel scale, a perceptual pitch scale on which equal steps sound equally spaced to listeners. It is usually formed by grouping the power spectrum into overlapping triangular filters spaced on the mel scale.','A mel-frequency spectrum reshapes a normal spectrum to match hearing. The mel scale spaces pitches the way people perceive them. Low frequencies get fine detail and high ones get coarser bands. Speech recognition builds features from this spectrum.','It represents sound the way human hearing resolves pitch, giving compact, perceptually relevant features for speech and audio machine learning.','Converting to the mel scale, 1000 Hz maps to 2595*log10(1+1000/700) = about 1000 mel, the usual anchor point used before taking mel-frequency cepstral coefficients.','Spectral Analysis',ARRAY['Mel scale','MFCC','Power cepstrum','One-third-octave analysis','Liftering']::text[],ARRAY['Assuming the mel scale is linear; it is roughly linear low down and logarithmic higher up.','Confusing the mel spectrum with the final mel-frequency cepstral coefficients.','Treating one mel formula as exact; several close variants exist.']::text[],ARRAY['Building features for a speech-recognition front end.','Analysing music timbre in a perceptually relevant way.','Preprocessing audio for a machine-learning classifier.']::text[],'Intermediate','m = 2595 * log10(1 + f/700)','The mel value equals 2595 times the base-ten log of one plus the frequency in hertz divided by 700.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mel-frequency spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ca1bbb6-5de5-4939-ba57-5092cee1436c','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ca1bbb6-5de5-4939-ba57-5092cee1436c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ca1bbb6-5de5-4939-ba57-5092cee1436c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6be22538-a01c-450b-ab49-8e7f8abf6151','Minimum sound level','The minimum sound level is the lowest time-weighted (Fast or Slow) sound pressure level reached during a stated measurement interval, written for example as LAFmin or LASmin. As with the maximum, the time weighting must be stated.','Minimum sound level is the quietest reading during a measurement. A Fast or Slow setting smooths the signal first. The lowest smoothed level is the minimum. It often shows the background level between louder events. You must state the weighting used.','It captures the quietest smoothed level in an interval, useful for estimating background or residual noise.','During a quiet-street survey, a technician records LAFmin = 34 dB between passing cars, giving an estimate of the residual background level.','Sound Level',ARRAY['Maximum sound level','Residual noise','Background level','Fast time weighting','Slow time weighting']::text[],ARRAY['Treating the minimum as the true background; brief dips may not represent steady residual noise.','Omitting the time weighting, making the value ambiguous.','Assuming Fast and Slow give the same minimum; they can differ on fluctuating noise.']::text[],ARRAY['Estimating residual noise between traffic events.','Checking a quiet room''s floor level.','Documenting the range of levels in an environmental survey.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6be22538-a01c-450b-ab49-8e7f8abf6151','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6be22538-a01c-450b-ab49-8e7f8abf6151') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6be22538-a01c-450b-ab49-8e7f8abf6151');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '04df1b9a-61c0-49ee-b00e-6e20e1404b41','Mms','Mms is the total moving mass of a loudspeaker driver''s diaphragm assembly including the acoustic air load, one of the Thiele-Small parameters, usually quoted in grams. It differs from Mmd, which is the moving mass without the air load.','Mms is the total moving weight of a loudspeaker''s cone system. It includes the cone, coil, and former. It also adds the mass of air the cone drags along. It is a key driver specification given in grams. It helps set the driver''s resonance.','It quantifies the effective moving mass that, with the suspension compliance, sets a driver''s resonance and efficiency.','With Mms = 10 g and compliance Cms = 1 mm/N, the resonance is fs = 1/(2*pi*sqrt(0.01*1e-3)) = about 50 Hz.','Loudspeaker Parameter',ARRAY['Moving mass','Mmd','Thiele-Small parameters','Compliance','Mechanical resonance']::text[],ARRAY['Confusing Mms with Mmd; Mms includes the air-load mass and Mmd does not.','Assuming a heavier cone always lowers efficiency without considering the whole design.','Forgetting the air-load part changes with the driver''s environment.']::text[],ARRAY['Reading Thiele-Small data to model a woofer.','Comparing two drivers'' moving mass for efficiency.','Predicting how mass changes shift a driver''s resonance.']::text[],'Intermediate','f_s = 1 / (2*pi*sqrt(Mms * Cms))','The driver resonance frequency equals one over two pi times the square root of the moving mass times the mechanical compliance.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '04df1b9a-61c0-49ee-b00e-6e20e1404b41','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='04df1b9a-61c0-49ee-b00e-6e20e1404b41') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='04df1b9a-61c0-49ee-b00e-6e20e1404b41');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3570c753-67b7-4025-ac96-08ae9dfcf86e','Moving mass','Moving mass is the mass of the parts of a transducer that move as one during operation, such as a loudspeaker''s cone, voice coil, and former, plus any co-moving air load. In loudspeaker analysis it appears as Mmd (without air load) or Mms (with air load).','Moving mass is the weight of the parts that move together. In a loudspeaker that is the cone, coil, and former. Air pushed by the cone can add to it. This mass helps set the driver''s resonance and efficiency. Lighter moving mass usually raises efficiency.','It captures how much inertia the drive force must accelerate, directly affecting resonance, efficiency, and transient response.','Halving a driver''s moving mass, with all else equal, raises its resonance by a factor of sqrt(2) and can improve efficiency.','Loudspeaker Parameter',ARRAY['Mms','Mmd','Mechanical resonance','Voice coil','Diaphragm']::text[],ARRAY['Assuming lighter is always better; too light a cone may lack strength or bass extension.','Ignoring the air-load contribution to effective moving mass.','Confusing moving mass with the driver''s total physical weight.']::text[],ARRAY['Comparing driver designs for efficiency and transient response.','Explaining why a subwoofer cone is heavy while a tweeter dome is light.','Modelling how added mass lowers a driver''s resonance.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Moving mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3570c753-67b7-4025-ac96-08ae9dfcf86e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3570c753-67b7-4025-ac96-08ae9dfcf86e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3570c753-67b7-4025-ac96-08ae9dfcf86e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95cada95-2db0-4511-ae5b-4140dbd441c2','One-third-octave analysis','One-third-octave analysis splits a signal into contiguous frequency bands each one third of an octave wide, so each band''s width is a constant percentage (about 23%) of its centre frequency. Centre frequencies and filter tolerances follow ISO 266 and IEC 61260.','One-third-octave analysis divides sound into standard frequency bands. Each band is one third of an octave wide. The bands get wider as frequency rises. This matches how we hear better than fixed-width bins. It is common for room and noise measurements.','It gives a standardized, perceptually reasonable frequency breakdown for comparing spectra across instruments and reports.','The 1000 Hz band spans about 891-1122 Hz (1000*2^(-1/6) to 1000*2^(1/6)), a bandwidth near 231 Hz, about 23% of the centre frequency.','Spectral Analysis',ARRAY['Octave-band analysis','Constant-percentage bandwidth','ISO preferred frequencies','FFT analysis','Mel-frequency spectrum']::text[],ARRAY['Treating one-third-octave bands like fixed-width FFT bins; their width grows with frequency.','Mixing base-2 and base-10 band definitions without stating which is used.','Assuming it gives fine detail at low frequencies; bands there are narrow in hertz but coarse in resolution overall.']::text[],ARRAY['Measuring room response for equalisation.','Reporting environmental noise spectra.','Comparing loudspeaker frequency response in standard bands.']::text[],'Intermediate','f_upper/f_lower = 2^(1/3);  f_lower = f_c*2^(-1/6),  f_upper = f_c*2^(1/6)','For a one-third-octave band the upper edge divided by the lower edge equals the cube root of two, and the edges lie a sixth of an octave below and above the centre frequency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='One-third-octave analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95cada95-2db0-4511-ae5b-4140dbd441c2','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95cada95-2db0-4511-ae5b-4140dbd441c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95cada95-2db0-4511-ae5b-4140dbd441c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cd6e766e-1420-4f9a-be68-15e56ca6c865','Operational transfer-path analysis','Operational transfer-path analysis (OTPA) estimates how vibration or sound reaches a target from several sources using only operational (in-use) measurements, without separately measured frequency response functions. It builds a transmissibility matrix from simultaneous reference and target responses and inverts it to rank path contributions.','Operational transfer-path analysis finds how noise travels to a chosen point. It uses only measurements taken while the machine runs normally. It does not need special hammer or shaker tests. It ranks which paths carry the most noise. This speeds up troubleshooting compared with classic methods.','It quickly ranks noise and vibration transmission paths during normal operation, avoiding the slow separate frequency-response tests of classical transfer-path analysis.','An engineer records many operating conditions of a running vehicle, then inverts the transmissibility matrix to see that the engine-mount path dominates cabin noise at 120 Hz.','Vibration Analysis',ARRAY['Transfer-path analysis','Transmissibility','Frequency response function','Order tracking','Coherence']::text[],ARRAY['Assuming OTPA needs no care with crosstalk; correlated sources can bias results badly.','Confusing transmissibility with a true frequency response function.','Using too few operating conditions to condition the matrix inversion.']::text[],ARRAY['Ranking interior noise paths in a running vehicle.','Diagnosing which mount transmits most vibration in machinery.','Screening structure-borne paths before detailed classical analysis.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Operational transfer-path analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cd6e766e-1420-4f9a-be68-15e56ca6c865','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cd6e766e-1420-4f9a-be68-15e56ca6c865') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cd6e766e-1420-4f9a-be68-15e56ca6c865');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a6bb02c5-63fe-4e49-a95a-73d4ec7b121f','Order tracking','Order tracking analyses vibration or sound from rotating machinery in terms of orders, which are multiples of the shaft rotation frequency, rather than fixed frequencies. Signals are usually resampled to equal angular increments so that shaft-related components stay at fixed order lines even as speed changes.','Order tracking studies rotating machines by their shaft speed. An order is a multiple of the shaft''s turning rate. The data is resampled per rotation, not per second. This keeps engine-related tones on fixed lines during speed changes. It makes run-up and coast-down tests clear.','It keeps rotation-related components fixed during speed changes, so faults and harmonics of a running machine can be tracked and separated from fixed resonances.','At 3000 rpm the shaft turns at 50 Hz, so the second order sits at 100 Hz; order tracking pins this line even as the machine accelerates.','Vibration Analysis',ARRAY['Tachometer','Angular resampling','Kurtogram','Campbell diagram','Waterfall plot']::text[],ARRAY['Confusing an order (relative to shaft speed) with a fixed frequency in hertz.','Forgetting a speed reference (tacho) is needed to define orders.','Mistaking a fixed structural resonance for an order because it does not move with speed.']::text[],ARRAY['Analysing an engine run-up for harmonic content.','Diagnosing gear-mesh orders in a gearbox.','Separating a fixed resonance from speed-following tones.']::text[],'Advanced','order = f / f_rot = 60 * f / N','An order equals the frequency divided by the shaft rotation frequency, which also equals sixty times the frequency divided by the rotation speed in revolutions per minute.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Order tracking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a6bb02c5-63fe-4e49-a95a-73d4ec7b121f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a6bb02c5-63fe-4e49-a95a-73d4ec7b121f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a6bb02c5-63fe-4e49-a95a-73d4ec7b121f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eab6a3fa-b000-425a-b619-226846a2d973','Peak C-weighted level','The peak C-weighted sound level (LCpeak) is the highest instantaneous C-weighted sound pressure level in an interval, taken from the true peak of the pressure waveform with no time-weighting applied. It is used to control the risk of instant hearing damage from impulsive noise.','Peak C-weighted level catches the loudest instant of a sound. It uses the true peak pressure, not a smoothed value. A C-weighting filter is applied first. It matters for sudden loud noises like gunshots or presses. It protects hearing from instant damage.','It guards against immediate hearing injury from very short, loud impulses that a time-averaged level would understate.','Under EU Directive 2003/10/EC, action is required at 135 and 137 dB(C) peak, and 140 dB(C) is the exposure limit; a 137 dB(C) peak corresponds to about 142 Pa.','Sound Level',ARRAY['C-weighting','Peak sound level','Maximum sound level','Impulsive noise','Sound level meter']::text[],ARRAY['Confusing peak level (true instantaneous) with maximum level (time-weighted RMS).','Using A-weighting for peak limits, where regulations specify C-weighting.','UNSAFE: Assuming ordinary earmuffs suffice near sounds above the 140 dB(C) peak limit; exposure there is not permitted and demands engineering controls.']::text[],ARRAY['Assessing impulsive noise from a punch press or firearm.','Checking workplace compliance with peak action and limit values.','Documenting peak exposure for a hearing-conservation programme.']::text[],'Intermediate','L_Cpeak = 20*log10( p_Cpeak / p_0 )','The peak C-weighted level equals twenty times the base-ten log of the C-weighted peak sound pressure divided by the reference sound pressure.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak C-weighted level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eab6a3fa-b000-425a-b619-226846a2d973','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eab6a3fa-b000-425a-b619-226846a2d973') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eab6a3fa-b000-425a-b619-226846a2d973');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1aad27d-e5db-446e-bc1f-33af57f328e0','Phase mismatch','Phase mismatch is an unwanted difference in phase response between two measurement channels or paths that should be matched, such as the two microphones of a sound-intensity probe. In intensity measurement it is the dominant low-frequency error, characterised by the residual pressure-intensity index.','Phase mismatch is a phase error between two channels that should agree. In an intensity probe the two microphones must track closely. Even a tiny phase difference causes large errors at low frequencies. Calibration and phase matching keep this small. It limits how low the probe can measure.','Recognising and bounding phase mismatch protects the accuracy of two-channel measurements like sound intensity, where small phase errors cause large low-frequency errors.','A technician checks a probe''s residual pressure-intensity index with both mics in the same sound field; a large value warns that phase mismatch limits valid low-frequency measurement.','Measurement Error',ARRAY['Sound intensity','Pressure-intensity index','Probe orientation','Channel matching','Instantaneous phase']::text[],ARRAY['Assuming amplitude matching is enough; phase matching dominates intensity error at low frequency.','Ignoring the residual pressure-intensity index that quantifies the usable range.','Blaming the source for readings actually caused by channel phase mismatch.']::text[],ARRAY['Verifying a sound-intensity probe before a sound-power test.','Diagnosing odd low-frequency intensity results.','Matching a pair of microphones for a two-channel measurement.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase mismatch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1aad27d-e5db-446e-bc1f-33af57f328e0','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1aad27d-e5db-446e-bc1f-33af57f328e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1aad27d-e5db-446e-bc1f-33af57f328e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12bbbb1d-c589-43d3-a61b-0c3a28e72bbd','Phased array ultrasound','Phased array ultrasound uses a transducer built from many small elements that are pulsed with individually controlled time delays, so the combined beam can be steered and focused electronically without moving the probe. It is used in medical imaging and non-destructive testing.','Phased array ultrasound uses many small crystals in one probe. Each element fires at a slightly different time. These timed delays aim and focus the sound beam. The beam can sweep without moving the probe. It speeds up imaging and flaw detection.','It lets a fixed probe steer and focus the ultrasonic beam electronically, giving faster, more flexible imaging or inspection than a single-element probe.','For weld inspection, a technician programs element delays to sweep the beam through a range of angles, mapping flaws without repositioning the probe.','Ultrasound',ARRAY['Medical ultrasound','Beamforming','Piezoelectric crystal','Transducer array','Pulse-echo']::text[],ARRAY['Assuming it needs mechanical scanning; the beam is steered electronically.','Confusing beam steering with simple probe movement.','Overlooking that each element and its delay must be calibrated.']::text[],ARRAY['Non-destructive testing of welds and forgings.','Cardiac imaging with a sector probe.','Inspecting composite structures for delamination.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phased array ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12bbbb1d-c589-43d3-a61b-0c3a28e72bbd','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12bbbb1d-c589-43d3-a61b-0c3a28e72bbd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12bbbb1d-c589-43d3-a61b-0c3a28e72bbd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a4e0f34-dd63-43e2-b649-9ebdebffbe33','Piezoelectric crystal','A piezoelectric crystal is a material, such as quartz, that produces an electric charge when mechanically stressed (the direct effect) and deforms when an electric field is applied (the converse effect). This two-way coupling makes it the sensing and driving element in many transducers.','A piezoelectric crystal turns force into voltage and voltage into motion. Squeeze it and it makes a small charge. Apply voltage and it changes shape. This two-way action makes it useful in sensors and probes. Quartz and certain ceramics behave this way.','It converts between mechanical and electrical energy, serving as the active element in accelerometers, ultrasound probes, microphones, and oscillators.','In an accelerometer, vibration stresses the crystal and it outputs a charge proportional to acceleration, which a charge amplifier converts to a usable voltage.','Transducer',ARRAY['Piezoelectric effect','Accelerometer','Ultrasound','Transducer','Quartz']::text[],ARRAY['Assuming it responds to steady (DC) force; charge leaks away, so it suits dynamic signals.','Ignoring pyroelectric drift, where temperature change also creates charge.','Forgetting the high output impedance needs a charge or high-impedance amplifier.']::text[],ARRAY['Sensing vibration in an accelerometer.','Generating and receiving pulses in an ultrasound probe.','Setting a stable frequency in a quartz oscillator.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoelectric crystal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a4e0f34-dd63-43e2-b649-9ebdebffbe33','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a4e0f34-dd63-43e2-b649-9ebdebffbe33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a4e0f34-dd63-43e2-b649-9ebdebffbe33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9fdf624d-64de-4ce7-9dfc-732b3f802f78','Power cepstrum','The power cepstrum is the squared magnitude of the inverse Fourier transform of the logarithm of a signal''s power spectrum. Its independent variable is quefrency, which has units of time, and it reveals periodic structure such as echoes or harmonic spacing.','The power cepstrum is a spectrum of a spectrum. You take the log of the power spectrum, then transform it again. The result''s axis is quefrency, measured in time. Peaks reveal echoes or evenly spaced harmonics. Engineers use it to find repeating structure.','It turns repeating spectral structure, like echoes or harmonic families, into isolated peaks so they can be measured or removed.','An echo delayed by 2 ms shows as a cepstral peak at a quefrency of 2 ms; liftering that peak can suppress the echo.','Cepstral Analysis',ARRAY['Cepstrum','Liftering','Quefrency','Complex cepstrum','Mel-frequency spectrum']::text[],ARRAY['Confusing quefrency with frequency; quefrency has units of time.','Mixing up the power cepstrum with the complex cepstrum, which keeps phase.','Expecting harmonics to appear as many lines; they collapse to one cepstral peak at their spacing.']::text[],ARRAY['Detecting and timing echoes in a recording.','Estimating pitch period from harmonic spacing.','Analysing gear-mesh sidebands in machinery vibration.']::text[],'Advanced','C_p(tau) = | IFT{ log |FT{x(t)}|^2 } |^2','The power cepstrum is the squared magnitude of the inverse Fourier transform of the log of the signal''s power spectrum, expressed as a function of quefrency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Power cepstrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9fdf624d-64de-4ce7-9dfc-732b3f802f78','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9fdf624d-64de-4ce7-9dfc-732b3f802f78') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9fdf624d-64de-4ce7-9dfc-732b3f802f78');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3cd01202-07dd-4243-a049-fc0d11900547','Precision','In metrology, precision is the closeness of agreement between repeated measurement results obtained under stated conditions. It reflects only random scatter and is distinct from trueness (freedom from bias); accuracy combines both.','Precision means repeated readings agree closely with each other. It says nothing about being correct on average. A tight but off-target group is precise but not accurate. Random scatter, not bias, sets precision. It is often shown by the spread of results.','It describes how repeatable a measurement is, letting technicians judge random uncertainty separately from bias.','Ten repeat readings of a level giving a standard deviation of 0.05 dB indicate high precision, even if a calibration offset still makes them biased.','Metrology',ARRAY['Accuracy','Trueness','Repeatability','Uncertainty','Standard deviation']::text[],ARRAY['Treating precision and accuracy as the same; precise results can still be biased.','Reporting precision without stating the measurement conditions.','Assuming more decimal places means more precision.']::text[],ARRAY['Judging repeatability of a measurement setup.','Separating random scatter from calibration bias.','Reporting the spread of repeated readings in a test.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Precision');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3cd01202-07dd-4243-a049-fc0d11900547','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3cd01202-07dd-4243-a049-fc0d11900547') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3cd01202-07dd-4243-a049-fc0d11900547');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd8c4480-21be-48b0-9c45-360da137b56e','Precision microphone','A precision (measurement) microphone is a laboratory-grade condenser microphone with a known, stable sensitivity and a well-defined frequency response, built to standards such as IEC 61094. Such microphones are the acoustic front end of Class 1 sound level meters and calibration systems.','A precision microphone is a top-grade measuring microphone. It is often a condenser type with a known output. Its response stays flat across the audio range. It feeds trusted sound meters and calibrators. It is made to strict global standards.','It provides an accurate, stable, traceable conversion of sound pressure to voltage for reliable acoustic measurement.','Before a survey, a technician places a sound calibrator on a precision microphone and adjusts the meter so its known 114 dB output reads correctly.','Measurement Microphone',ARRAY['Condenser microphone','Free-field microphone','Pressure microphone','Precision-grade measurement','Sound calibrator']::text[],ARRAY['Assuming any studio condenser is a measurement microphone; measurement mics meet defined tolerances.','Ignoring free-field versus pressure response and using the wrong type for the field.','UNSAFE: Applying polarisation or phantom voltage to an incompatible capsule, which can damage it.']::text[],ARRAY['Calibrating and running a Class 1 sound level meter.','Making reference measurements in a laboratory.','Characterising a loudspeaker''s frequency response accurately.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Precision microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd8c4480-21be-48b0-9c45-360da137b56e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd8c4480-21be-48b0-9c45-360da137b56e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd8c4480-21be-48b0-9c45-360da137b56e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92755695-e4f5-46f5-a0a1-caebce34febc','Precision-grade measurement','A precision-grade measurement is one made with instruments meeting the tightest standardized tolerance class, namely Class 1 under IEC 61672 (historically ''Type 1'' under ANSI S1.4). The class defines allowable errors across frequency and the environmental range over which they hold.','Precision-grade means using the most accurate class of instruments. For sound level meters that is Class 1. This class has the tightest allowed errors. It was once called Type 1 in older standards. Such measurements are trusted for compliance and legal use.','It signals that a measurement meets the strict tolerance class needed for reliable, defensible results in compliance and reference work.','For a legal noise survey a technician uses a Class 1 (precision-grade) meter and matching microphone, since a Class 2 instrument would not meet the required tolerances.','Metrology',ARRAY['Class 1','Sound level meter','Precision microphone','Precision','Tolerance class']::text[],ARRAY['Assuming any digital meter is precision-grade; it must meet Class 1 tolerances.','Mixing IEC ''Class'' with older ANSI ''Type'' without noting they correspond.','Forgetting the class only holds within the specified environmental conditions.']::text[],ARRAY['Choosing an instrument for a legally defensible noise survey.','Verifying an instrument''s class before compliance work.','Distinguishing Class 1 reference work from Class 2 general surveys.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Precision-grade measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92755695-e4f5-46f5-a0a1-caebce34febc','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92755695-e4f5-46f5-a0a1-caebce34febc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92755695-e4f5-46f5-a0a1-caebce34febc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2834e79-0413-4ab5-9172-5f5cdadbd634','Probe orientation','Probe orientation is the alignment of a measurement probe, such as a microphone or sound-intensity probe, relative to the sound field or surface being measured. Because sensors are directional and intensity is a vector, orientation determines which field component is captured and affects accuracy.','Probe orientation is how you aim the measuring probe. Sensors are directional, so the angle matters. For an intensity probe, orientation sets which direction of energy is measured. Wrong aiming gives wrong readings. Standards tell you how to point the probe.','Correct probe orientation ensures the sensor captures the intended field component and meets the incidence conditions its calibration assumes.','For a sound-power scan the intensity probe axis is held normal to the measurement surface, so it reads the energy flowing outward through that surface.','Measurement Technique',ARRAY['Angle of incidence','Free-field microphone','Sound intensity','Measurement surface','Phase mismatch']::text[],ARRAY['Using a free-field microphone off-axis, where its calibration no longer applies.','Aiming an intensity probe off the surface normal, mixing in unwanted components.','Ignoring that random-incidence calibration assumes sound arrives from all directions.']::text[],ARRAY['Aiming an intensity probe during a sound-power scan.','Pointing a free-field microphone at a loudspeaker under test.','Choosing incidence for a diffuse-field room measurement.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Probe orientation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2834e79-0413-4ab5-9172-5f5cdadbd634','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2834e79-0413-4ab5-9172-5f5cdadbd634') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2834e79-0413-4ab5-9172-5f5cdadbd634');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02704b73-4bb6-42c0-bf8b-a3b4a091d8c3','Pulse-echo','A ranging technique in which a short acoustic or ultrasonic pulse is transmitted and the round-trip time to a reflecting target is measured; distance is derived from the wave speed and the measured delay. It underlies ultrasonic thickness gauging, sonar and medical ultrasound.','A device sends a short sound pulse. The pulse hits an object and bounces back. The device times the round trip. Knowing sound speed, it calculates the distance.','It measures distance, thickness or defect location without contact by timing a reflected pulse rather than sensing the target directly.','With sound speed c = 1480 m/s in water and an echo delay t = 2 ms, the target range is d = c*t/2 = 1480 x 0.002 / 2 = 1.48 m.','Measurement Method',ARRAY['Sonar','Time-domain reflectometry','Step response','Reciprocity measurement','Resolution']::text[],ARRAY['Forgetting the factor of two for the round trip and doubling the true distance.','Using an air sound speed for a measurement made in water or solid material.','Ignoring how temperature changes the propagation speed and biases the range.']::text[],ARRAY['Measuring steel plate thickness with an ultrasonic gauge.','Locating a fish school or seabed depth with sonar.','Finding a fault distance along a cable or pipe.']::text[],'Beginner','d = c * t / 2','Distance to the reflector equals the wave speed multiplied by the round-trip echo time, divided by two.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulse-echo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02704b73-4bb6-42c0-bf8b-a3b4a091d8c3','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02704b73-4bb6-42c0-bf8b-a3b4a091d8c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02704b73-4bb6-42c0-bf8b-a3b4a091d8c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '691c5071-9472-4f84-b772-1eca27e178fd','Q factor','A dimensionless measure of the sharpness of a resonance, defined as 2 pi times the energy stored per cycle divided by the energy dissipated per cycle, and equal to the resonant frequency divided by the -3 dB bandwidth for a simple resonator. Higher Q means lower loss and a narrower, taller resonance peak.','Q factor tells you how sharp a resonance is. A high Q means low energy loss and a narrow peak. A low Q means more damping and a broad peak. It has no units.','It quantifies resonator selectivity and damping, letting engineers compare filters, tuned circuits, loudspeakers and mechanical resonators.','A bandpass filter centred at f0 = 1000 Hz with a -3 dB bandwidth of 50 Hz has Q = f0 / BW = 1000 / 50 = 20.','Electrical Property',ARRAY['Resonant circuit','Reactance','Qts','Resolution','Bandwidth']::text[],ARRAY['Confusing high Q (narrow, low loss) with high damping, which is the opposite.','Measuring bandwidth at the wrong points instead of the -3 dB (half-power) points.','Assuming loudspeaker Q values are dimensionless bandwidth ratios rather than damping parameters.']::text[],ARRAY['Setting the Q of a parametric equaliser band.','Comparing the selectivity of two tuned filters.','Characterising the damping of a loudspeaker resonance.']::text[],'Intermediate','Q = f0 / BW = 2*pi*(E_stored / E_dissipated per cycle)','Q equals the resonant frequency divided by the minus three decibel bandwidth, or two pi times stored energy divided by energy lost each cycle.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Q factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '691c5071-9472-4f84-b772-1eca27e178fd','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='691c5071-9472-4f84-b772-1eca27e178fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='691c5071-9472-4f84-b772-1eca27e178fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa6b48f3-42fd-403b-ac29-78408ecdef6a','Qes','The electrical quality factor of a loudspeaker driver at its free-air resonance, describing the damping contributed by electrical losses in the voice coil coupled through the motor. It is one of the Thiele-Small parameters and is dimensionless.','Qes measures the electrical damping of a speaker at resonance. It comes from the voice coil and magnet acting as a brake. A low Qes means strong motor control. It has no units.','It quantifies how much the motor and voice-coil resistance damp cone motion, a key input to enclosure design and system alignment.','For a driver with fs = 30 Hz, Mms = 20 g, Re = 6 ohm and Bl = 7 T*m, Qes = 2*pi*fs*Mms*Re / (Bl^2) = 2*pi*30*0.02*6 / 49 = 0.46.','Loudspeaker Parameter',ARRAY['Qms','Qts','Re','Q factor','Reference efficiency']::text[],ARRAY['Confusing Qes (electrical damping) with Qms (mechanical damping).','Assuming Qes stays fixed when the amplifier output impedance changes the electrical damping.','Treating Qes as the total damping instead of combining it with Qms to get Qts.']::text[],ARRAY['Selecting a woofer for a sealed or vented box.','Measuring Thiele-Small parameters with an added-mass method.','Predicting low-frequency alignment of a driver.']::text[],'Intermediate','Qes = (2*pi*fs * Mms * Re) / (Bl)^2','Electrical Q equals two pi times resonance frequency times moving mass times voice-coil resistance, divided by the force factor squared.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Qes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa6b48f3-42fd-403b-ac29-78408ecdef6a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa6b48f3-42fd-403b-ac29-78408ecdef6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa6b48f3-42fd-403b-ac29-78408ecdef6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e0e5710b-527e-4280-be67-b35aa378c1a9','Qms','The mechanical quality factor of a loudspeaker driver at free-air resonance, describing the damping due to mechanical losses in the suspension (surround and spider). It is a dimensionless Thiele-Small parameter.','Qms measures the mechanical damping of a speaker at resonance. It comes from friction in the surround and spider. A high Qms means low mechanical loss. It has no units.','It quantifies suspension and material losses, complementing the electrical damping to define the driver''s total resonance behaviour.','With fs = 30 Hz, Mms = 20 g and mechanical resistance Rms = 1.2 kg/s, Qms = 2*pi*fs*Mms / Rms = 2*pi*30*0.02 / 1.2 = 3.14.','Loudspeaker Parameter',ARRAY['Qes','Qts','Q factor','Reference efficiency','Resonant circuit']::text[],ARRAY['Confusing Qms (mechanical loss) with Qes (electrical loss).','Assuming a high Qms alone means tight bass; total Q (Qts) governs alignment.','Ignoring that Qms drifts as the suspension breaks in or ages.']::text[],ARRAY['Assessing suspension losses on a new driver.','Diagnosing a stiff or worn surround from parameter drift.','Computing Qts from measured Qes and Qms.']::text[],'Intermediate','Qms = (2*pi*fs * Mms) / Rms','Mechanical Q equals two pi times resonance frequency times moving mass, divided by the mechanical resistance of the suspension.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Qms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e0e5710b-527e-4280-be67-b35aa378c1a9','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e0e5710b-527e-4280-be67-b35aa378c1a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e0e5710b-527e-4280-be67-b35aa378c1a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96fc9ca5-1dc2-4892-9eea-5e29c99cc526','Qts','The total quality factor of a loudspeaker driver at free-air resonance, formed by the parallel combination of the electrical (Qes) and mechanical (Qms) quality factors. This dimensionless Thiele-Small parameter largely determines the appropriate enclosure alignment.','Qts is the total damping of a speaker at resonance. It combines the electrical and mechanical damping. A low Qts suits vented boxes. A higher Qts suits sealed boxes.','It summarises overall resonance damping in one number, guiding the choice of sealed, vented or other enclosure alignments.','With Qes = 0.46 and Qms = 3.14, Qts = (Qes*Qms)/(Qes+Qms) = (0.46*3.14)/(0.46+3.14) = 0.40.','Loudspeaker Parameter',ARRAY['Qes','Qms','Reference efficiency','Q factor','Sd']::text[],ARRAY['Adding Qes and Qms directly instead of combining them in parallel.','Believing Qts alone fixes the box size; Vas and fs matter too.','Assuming a single ''best'' Qts rather than a value matched to an alignment.']::text[],ARRAY['Deciding between a sealed and vented enclosure.','Comparing woofers for a target box response.','Verifying a manufacturer''s published parameter set.']::text[],'Intermediate','Qts = (Qes * Qms) / (Qes + Qms)','Total Q equals the product of electrical and mechanical Q divided by their sum.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Qts');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96fc9ca5-1dc2-4892-9eea-5e29c99cc526','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96fc9ca5-1dc2-4892-9eea-5e29c99cc526') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96fc9ca5-1dc2-4892-9eea-5e29c99cc526');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5dd414d0-8d51-4c0a-abb2-944ca537161e','Quadrature signal','A pair of signals of the same frequency that differ in phase by 90 degrees, conventionally labelled in-phase (I) and quadrature (Q). Together they represent the amplitude and phase of a signal, forming the basis of complex baseband and IQ modulation.','A quadrature signal is two signals of the same frequency. One lags the other by ninety degrees. These are called I and Q. Together they carry amplitude and phase.','It lets a system encode both magnitude and phase, enabling IQ demodulation, complex spectra and phase-sensitive detection in analyzers.','A lock-in or vector analyzer multiplies the input by cos and sin references; the I and Q outputs give magnitude sqrt(I^2 + Q^2) and phase atan2(Q, I).','Signal Concept',ARRAY['Real cepstrum','Reassigned spectrogram','Sampling theorem','Resolution','Step response']::text[],ARRAY['Assuming quadrature means ''four'' signals; it means a 90-degree phase offset.','Swapping I and Q, which mirrors the spectrum and inverts the sign of frequency.','Forgetting that IQ imbalance creates an image at the mirror frequency.']::text[],ARRAY['Demodulating an IQ stream in a software-defined radio.','Recovering magnitude and phase in a vector network analyzer.','Phase-sensitive detection with a lock-in amplifier.']::text[],'Advanced','I(t) = A*cos(phi),  Q(t) = A*sin(phi);  magnitude = sqrt(I^2 + Q^2)','The in-phase and quadrature components are ninety degrees apart; their vector sum gives the signal magnitude and their ratio gives its phase.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quadrature signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5dd414d0-8d51-4c0a-abb2-944ca537161e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5dd414d0-8d51-4c0a-abb2-944ca537161e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5dd414d0-8d51-4c0a-abb2-944ca537161e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f86638a7-538b-4a25-b38c-e1bcc2a95e43','Re','The DC electrical resistance of a loudspeaker driver''s voice coil, measured at the coil''s terminals with a direct current. It is a Thiele-Small parameter, expressed in ohms, and sets the minimum impedance of the driver.','Re is the direct-current resistance of a speaker''s voice coil. You measure it with an ohmmeter. It is lower than the rated impedance. It is given in ohms.','It defines the coil''s baseline resistance, needed to compute electrical damping (Qes) and to interpret the impedance curve.','An ohmmeter across the terminals of an 8 ohm nominal woofer typically reads Re near 5.5 to 6.5 ohm; this value feeds directly into the Qes calculation.','Loudspeaker Parameter',ARRAY['Qes','Qts','Reactance','Reference efficiency','Sensitivity']::text[],ARRAY['UNSAFE: Measuring Re with the driver connected to a powered amplifier instead of disconnected.','Confusing Re (DC resistance) with the nominal or rated impedance, which is higher.','Assuming Re is constant; it rises as the voice coil heats up.']::text[],ARRAY['Checking a driver for an open or shorted voice coil.','Supplying Re to a Thiele-Small parameter calculation.','Interpreting the minimum of an impedance sweep.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Re');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f86638a7-538b-4a25-b38c-e1bcc2a95e43','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f86638a7-538b-4a25-b38c-e1bcc2a95e43') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f86638a7-538b-4a25-b38c-e1bcc2a95e43');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90a847ca-556c-4c5f-8996-19915b4e0116','Reactance','The opposition that inductance and capacitance present to alternating current, arising from stored energy rather than dissipation, and measured in ohms. Inductive reactance rises with frequency while capacitive reactance falls with frequency; reactance is the imaginary part of impedance.','Reactance is opposition to alternating current from coils and capacitors. It stores energy instead of wasting it. Coil reactance grows with frequency. Capacitor reactance shrinks with frequency. It is measured in ohms.','It describes how capacitors and inductors shift phase and shape frequency response, forming the reactive part of any impedance.','A 10 microfarad capacitor at 1 kHz has capacitive reactance Xc = 1/(2*pi*f*C) = 1/(2*pi*1000*10e-6) = 15.9 ohm.','Electrical Property',ARRAY['Resonant circuit','Q factor','Re','Resolution']::text[],ARRAY['Confusing reactance (energy stored, no loss) with resistance (energy dissipated).','Forgetting that inductive and capacitive reactance have opposite sign and can cancel.','Ignoring that reactance changes with frequency, unlike an ideal resistor.']::text[],ARRAY['Designing a passive crossover network.','Predicting phase shift in a filter stage.','Finding the frequency where two reactances cancel at resonance.']::text[],'Intermediate','XL = 2*pi*f*L;  XC = 1 / (2*pi*f*C)','Inductive reactance equals two pi times frequency times inductance; capacitive reactance equals one over two pi times frequency times capacitance.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reactance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90a847ca-556c-4c5f-8996-19915b4e0116','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90a847ca-556c-4c5f-8996-19915b4e0116') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90a847ca-556c-4c5f-8996-19915b4e0116');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7667aa9-c6e8-458d-b0de-33e365b58254','Real cepstrum','The inverse Fourier transform of the logarithm of the magnitude of a signal''s spectrum, giving a sequence indexed by quefrency (time). It reveals periodic structure in the spectrum, such as echoes or harmonic spacing, and discards phase.','The real cepstrum is a spectrum of a spectrum. You take the log of the magnitude spectrum. Then you inverse transform it. Peaks reveal echoes or repeated harmonic spacing.','It separates a source''s periodic excitation from a slowly varying envelope, useful for echo detection, pitch estimation and deconvolution.','For a signal X[k], the real cepstrum is c[n] = IDFT{ ln|X[k]| }; an echo delayed by tau produces a peak at quefrency n = tau.','DSP Analysis',ARRAY['Reassigned spectrogram','Spectral kurtosis','Quadrature signal','Sampling theorem','Pulse-echo']::text[],ARRAY['Confusing the real cepstrum with the complex cepstrum, which keeps phase.','Reading the cepstrum axis (quefrency) as ordinary frequency rather than time.','Forgetting the log step, which is what turns convolution into addition.']::text[],ARRAY['Detecting an echo delay in a room impulse response.','Estimating the fundamental period of voiced speech.','Separating vocal-tract envelope from glottal excitation.']::text[],'Advanced','c[n] = IDFT{ ln |X[k]| }','The real cepstrum is the inverse discrete Fourier transform of the natural log of the spectrum magnitude.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real cepstrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7667aa9-c6e8-458d-b0de-33e365b58254','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7667aa9-c6e8-458d-b0de-33e365b58254') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7667aa9-c6e8-458d-b0de-33e365b58254');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '732f7bc5-e4b3-4039-b56c-c5c28a964b8a','Reassigned spectrogram','A sharpened time-frequency representation formed by moving each spectrogram value from the centre of its analysis cell to the reassigned coordinate given by the signal''s local group delay and instantaneous frequency. The method of reassignment concentrates energy nearer the true ridges, improving readability without changing the underlying transform.','A reassigned spectrogram is a sharper time-frequency picture. It moves each energy point to where it truly belongs. This uses local timing and frequency estimates. The result shows crisper lines.','It counters the blur inherent in a fixed analysis window, giving sharper ridges for tones, chirps and transients.','An analyzer computes the short-time transform, then shifts each bin using phase-derivative estimates of instantaneous frequency and group delay before displaying the concentrated energy.','DSP Analysis',ARRAY['Real cepstrum','Spectral kurtosis','Resolution','Quadrature signal','Step response']::text[],ARRAY['Assuming reassignment adds information; it only relocates existing energy.','Expecting it to work well on noisy, low-energy regions where estimates are unreliable.','Confusing reassignment with simply using a shorter analysis window.']::text[],ARRAY['Sharpening a chirp or glissando in a spectrogram.','Resolving closely spaced partials in an instrument tone.','Localising a short transient in time and frequency.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reassigned spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '732f7bc5-e4b3-4039-b56c-c5c28a964b8a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='732f7bc5-e4b3-4039-b56c-c5c28a964b8a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='732f7bc5-e4b3-4039-b56c-c5c28a964b8a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd50d637d-cc22-4991-b04d-fd1c73733210','Reciprocity measurement','An absolute calibration technique that uses a reversible transducer, which behaves identically as a source and a receiver, to determine sensitivity without a pre-calibrated reference. In acoustics it is the primary method for establishing measurement-microphone pressure sensitivity.','Reciprocity calibration finds a transducer''s sensitivity. It works from first principles alone. It uses one device that acts as a speaker and a microphone. You do not need a pre-calibrated reference. This method sets the primary standard.','It provides a traceable, absolute sensitivity value, anchoring the calibration chain for microphones and other electroacoustic transducers.','A technician couples three microphones in pairs in a known cavity, measures the electrical transfer ratios, and solves for each microphone''s pressure sensitivity in mV/Pa.','Calibration Method',ARRAY['Sensitivity','Sensitivity coefficient','Sound level meter','Pulse-echo','Sonar']::text[],ARRAY['Assuming a reference microphone is required; reciprocity needs none.','Ignoring the coupler volume and environmental corrections, which bias the result.','Using a non-reversible transducer, which breaks the reciprocity assumption.']::text[],ARRAY['Establishing primary microphone calibration at a metrology lab.','Certifying reference microphones traceable to national standards.','Cross-checking a working microphone against an absolute value.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reciprocity measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd50d637d-cc22-4991-b04d-fd1c73733210','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d50d637d-cc22-4991-b04d-fd1c73733210') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d50d637d-cc22-4991-b04d-fd1c73733210');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fef3ce7-28f5-420c-97f6-8f4eb64bde18','Reference efficiency','The half-space power efficiency of a loudspeaker driver in its passband, computed from the Thiele-Small parameters as a fraction of electrical input power converted to acoustic output. It is expressed as a decimal fraction or percentage and correlates directly with sensitivity.','Reference efficiency shows how much electric power a speaker turns into sound. For most drivers this is only a small percent. A higher figure means the speaker is more sensitive. The value comes from the Thiele-Small parameters.','It predicts a driver''s acoustic output per watt from measured parameters, letting designers compare efficiency before building an enclosure.','With c = 343 m/s, fs = 40 Hz, Vas = 0.05 m^3 and Qes = 0.4: eta0 = 4*pi^2*fs^3*Vas/(c^3*Qes) = 39.48*64000*0.05/(4.035e7*0.4) = 0.0078, i.e. about 0.78%.','Loudspeaker Parameter',ARRAY['Qes','Qts','Sd','Sensitivity','Q factor']::text[],ARRAY['Mixing units, e.g. using Vas in litres without adjusting the constant.','Confusing reference efficiency with sensitivity in dB, which is a logarithmic restatement.','Expecting high efficiency and deep extension together from a small driver.']::text[],ARRAY['Comparing woofers for output per watt.','Estimating amplifier power needed for a target loudness.','Checking a datasheet''s sensitivity against its parameters.']::text[],'Advanced','eta0 = (4*pi^2 * fs^3 * Vas) / (c^3 * Qes)','Reference efficiency equals four pi squared times resonance frequency cubed times equivalent compliance volume, divided by the cube of sound speed times electrical Q.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference efficiency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fef3ce7-28f5-420c-97f6-8f4eb64bde18','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fef3ce7-28f5-420c-97f6-8f4eb64bde18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fef3ce7-28f5-420c-97f6-8f4eb64bde18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e1f8892-e687-413c-9fbc-f5014c5d938b','Residual sound level','In environmental noise measurement, the sound level that remains at a position when the specific sound under investigation is removed or suppressed. Under ISO 1996-1 it represents the acoustic background against which a specific source is assessed.','Residual sound level is the background noise left when the source you care about stops. It is what remains from all other sources. Engineers use it as a baseline. It comes from ISO 1996-1.','It establishes the baseline background so the contribution of a specific source can be separated and judged fairly.','To assess a factory, a technician measures the level with the plant off (residual) and with it on (total), then corrects the total for the residual contribution.','Acoustic Measurement',ARRAY['Specific sound level','Statistical sound level','Sound level meter','Sound exposure']::text[],ARRAY['Confusing residual sound with the specific sound being assessed.','Skipping the background correction when total and residual levels are close.','Assuming residual noise is constant rather than varying over time.']::text[],ARRAY['Assessing whether a new plant meets a noise limit.','Correcting a measured level for background contribution.','Documenting the baseline before a noisy activity starts.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Residual sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e1f8892-e687-413c-9fbc-f5014c5d938b','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e1f8892-e687-413c-9fbc-f5014c5d938b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e1f8892-e687-413c-9fbc-f5014c5d938b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb3cab37-46b4-468e-8258-9f96a788ae69','Resolution','The smallest difference in a quantity that a measurement system can distinguish. In spectrum analysis the frequency resolution equals the sampling rate divided by the transform length, or equivalently the reciprocal of the record duration.','Resolution is the smallest change a measurement can tell apart. In a spectrum, it is the gap between frequency bins. A longer record gives finer frequency resolution. Bigger steps give coarser resolution.','It sets the limit on how finely two closely spaced values, tones or events can be separated by an instrument.','An FFT of N = 4096 samples at fs = 48 kHz gives frequency resolution df = fs/N = 48000/4096 = 11.7 Hz, equal to 1/T for a 85 ms record.','Measurement Concept',ARRAY['Sampling theorem','Reassigned spectrogram','Spectral contamination','Q factor','Sensitivity']::text[],ARRAY['Confusing frequency resolution with accuracy; a fine bin can still read a biased value.','Confusing display resolution or bit depth with the true measurement resolution.','Expecting fine frequency resolution from a very short record.']::text[],ARRAY['Choosing an FFT length to separate two close tones.','Reading the least significant digit of a meter.','Trading frequency resolution against time resolution in a spectrogram.']::text[],'Intermediate','df = fs / N = 1 / T','Frequency resolution equals the sample rate divided by the transform length, which also equals one over the record duration.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb3cab37-46b4-468e-8258-9f96a788ae69','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb3cab37-46b4-468e-8258-9f96a788ae69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb3cab37-46b4-468e-8258-9f96a788ae69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '121cd7f9-302a-4929-ab4a-9cc8bcc2d164','Resonant circuit','A circuit containing inductance and capacitance whose reactances cancel at a resonant frequency, producing a peak (series) or dip (parallel) in impedance and a sharp response. The resonant frequency depends on the inductance and capacitance values.','A resonant circuit combines a coil and a capacitor. At one frequency their opposing effects cancel. This creates a strong peak or dip in response. That frequency is the resonant frequency.','It selects or rejects a specific frequency band, forming the core of filters, oscillators and tuned amplifiers.','With L = 10 mH and C = 100 nF, the resonant frequency is f0 = 1/(2*pi*sqrt(L*C)) = 1/(2*pi*sqrt(0.01*100e-9)) = 5033 Hz.','Electrical Circuit',ARRAY['Reactance','Q factor','Resolution','Reference efficiency']::text[],ARRAY['Confusing series resonance (low impedance) with parallel resonance (high impedance).','Assuming resonance depends on resistance; f0 depends on L and C only.','Ignoring circuit Q, which sets how sharp the resonance is.']::text[],ARRAY['Designing a notch or bandpass filter.','Tuning an oscillator to a target frequency.','Explaining a loudspeaker impedance peak at resonance.']::text[],'Intermediate','f0 = 1 / (2*pi*sqrt(L*C))','The resonant frequency equals one divided by two pi times the square root of inductance times capacitance.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonant circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '121cd7f9-302a-4929-ab4a-9cc8bcc2d164','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='121cd7f9-302a-4929-ab4a-9cc8bcc2d164') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='121cd7f9-302a-4929-ab4a-9cc8bcc2d164');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dea27060-7596-4056-bc8e-6131bf86a31d','Rocking mode','An unwanted resonance in which a loudspeaker diaphragm or voice-coil assembly tilts or rocks about an axis instead of moving as a rigid piston. It can cause voice-coil rub, distortion and asymmetric radiation, and is diagnosed with laser and modal measurements.','A rocking mode is when a speaker cone tilts side to side. It does not move straight in and out. This can make the coil rub the gap. The result is distortion and noise.','Recognising rocking modes helps designers and technicians locate a source of buzz, rub or distortion tied to non-piston cone motion.','A technician uses a laser vibrometer or scanning measurement to spot a tilting cone motion, then checks for coil rub or an uneven suspension causing it.','Loudspeaker Defect',ARRAY['Q factor','Resonant circuit','Sd','Sensitivity','Step response']::text[],ARRAY['Confusing a rocking mode with a normal breakup (bending) mode of the cone.','Assuming rocking is always audible; it may only appear at high excursion.','Blaming the amplifier for a rub that comes from a tilting coil.']::text[],ARRAY['Diagnosing a buzz at high drive level.','Investigating asymmetric suspension or offset in production.','Explaining rub-and-buzz failures in loudspeaker testing.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rocking mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dea27060-7596-4056-bc8e-6131bf86a31d','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dea27060-7596-4056-bc8e-6131bf86a31d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dea27060-7596-4056-bc8e-6131bf86a31d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a51acabc-519f-451f-a571-1470b88f3e94','Sampling theorem','The theorem stating that a band-limited signal can be represented exactly by its samples and reconstructed without error if the sampling rate exceeds twice the highest frequency present. This limiting rate is the Nyquist rate, and undersampling causes aliasing.','The sampling theorem says how fast you must sample a signal. You must sample faster than twice its highest frequency. Then you can rebuild the signal exactly. Sampling too slowly causes aliasing.','It sets the minimum sample rate for faithful digital capture, underpinning all analog-to-digital conversion and digital audio.','To capture audio up to 20 kHz without aliasing, the sample rate must exceed 2 x 20000 = 40000 Hz; standard 44.1 kHz and 48 kHz rates satisfy this.','DSP Concept',ARRAY['Resolution','Spectral contamination','Quadrature signal','Real cepstrum','Reassigned spectrogram']::text[],ARRAY['Confusing the Nyquist rate (2 x f_max) with the Nyquist frequency (fs/2).','Omitting an anti-alias filter and letting out-of-band energy fold in.','Assuming exactly 2 x f_max suffices; the rate must strictly exceed it.']::text[],ARRAY['Choosing a sample rate for an A/D converter.','Explaining why aliasing appears above half the sample rate.','Setting an anti-alias filter cutoff below Nyquist.']::text[],'Intermediate','fs > 2 * f_max','The sampling rate must be greater than twice the highest frequency contained in the signal.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sampling theorem');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a51acabc-519f-451f-a571-1470b88f3e94','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a51acabc-519f-451f-a571-1470b88f3e94') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a51acabc-519f-451f-a571-1470b88f3e94');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6301720a-f673-493a-bb9f-7e528d6be023','Sd','The effective radiating (piston) area of a loudspeaker diaphragm, taken to include roughly the cone plus about one third to one half of the surround, expressed in square metres. It is a Thiele-Small parameter used to relate cone excursion to displaced air volume.','Sd is the effective moving area of a speaker cone. It includes the cone and part of the surround. It is given in square metres. It sets how much air the cone pushes.','It converts cone motion into displaced air volume, needed for excursion, output and Vas calculations.','For an effective diameter of 0.13 m, Sd = pi*(d/2)^2 = pi*(0.065)^2 = 0.0133 m^2 (about 133 cm^2).','Loudspeaker Parameter',ARRAY['Reference efficiency','Qts','Sensitivity','Rocking mode','Re']::text[],ARRAY['Using the full outer frame diameter instead of the effective radiating diameter.','Measuring only the cone and ignoring the surround contribution.','Confusing area (Sd) with volume displacement (Vd = Sd x Xmax).']::text[],ARRAY['Computing displaced volume for maximum output.','Deriving Vas from measured parameters.','Comparing radiating area across driver sizes.']::text[],'Intermediate','Sd = pi * (d_eff / 2)^2','Effective radiating area equals pi times half the effective diameter, squared.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sd');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6301720a-f673-493a-bb9f-7e528d6be023','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6301720a-f673-493a-bb9f-7e528d6be023') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6301720a-f673-493a-bb9f-7e528d6be023');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a5454304-2fa3-47ff-96ca-eb87240120da','Sensitivity','The ratio of a transducer''s output to its input under stated conditions. A microphone''s sensitivity is its open-circuit output voltage per pascal (often in mV/Pa or dB re 1 V/Pa); a loudspeaker''s sensitivity is the sound pressure level produced at a stated distance for a stated input.','Sensitivity is output divided by input for a device. A microphone gives volts per pascal of sound. A loudspeaker gives loudness at one metre for a set input. Higher sensitivity means more output.','It lets engineers predict output from a known input, matching microphones to preamps and loudspeakers to amplifiers.','A microphone rated 12.5 mV/Pa exposed to 1 Pa (94 dB SPL) outputs 12.5 mV; a loudspeaker rated 88 dB at 2.83 V/1 m gives that level for that drive.','Transducer Property',ARRAY['Sensitivity coefficient','Reference efficiency','Sound level meter','Reciprocity measurement','Re']::text[],ARRAY['Comparing loudspeaker sensitivities cited at 1 W versus 2.83 V without noting impedance.','Confusing microphone sensitivity (V/Pa) with its maximum sound-level handling.','Ignoring the reference distance, which changes the stated loudspeaker figure.']::text[],ARRAY['Matching a microphone to a preamp''s gain range.','Estimating amplifier power for a target SPL.','Comparing two microphones for the same source.']::text[],'Intermediate','S = V_out / p (microphone);  L = L_ref for stated input at stated distance (loudspeaker)','Microphone sensitivity is output voltage divided by sound pressure; loudspeaker sensitivity is the sound level for a stated input at a stated distance.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a5454304-2fa3-47ff-96ca-eb87240120da','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a5454304-2fa3-47ff-96ca-eb87240120da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a5454304-2fa3-47ff-96ca-eb87240120da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08cd3e9c-642c-44bb-bf5e-10688f041c1c','Sensitivity coefficient','In measurement uncertainty analysis, the partial derivative of a measurement result with respect to one input quantity, describing how strongly that input influences the output. It weights each input''s uncertainty when they are combined into the overall uncertainty.','A sensitivity coefficient shows how much an input affects a result. It is the rate of change of output per input. It weights each input''s uncertainty. It comes from the uncertainty guide (GUM).','It converts each input''s uncertainty into its contribution to the result''s uncertainty during a combined uncertainty budget.','If a result y depends on input x, the sensitivity coefficient is c = dy/dx; its contribution to combined uncertainty is |c| times the standard uncertainty of x.','Uncertainty Concept',ARRAY['Sensitivity','Reciprocity measurement','Sound level meter','Resolution','Reference efficiency']::text[],ARRAY['Confusing a sensitivity coefficient (uncertainty weighting) with a device''s sensitivity.','Forgetting the coefficient carries units that convert the input''s units to the output''s.','Omitting a coefficient when an input has a large influence on the result.']::text[],ARRAY['Building an uncertainty budget for a calibration.','Ranking which input dominates a measurement''s uncertainty.','Propagating uncertainty through a measurement equation.']::text[],'Advanced','c_i = partial f / partial x_i','The sensitivity coefficient for an input is the partial derivative of the output function with respect to that input.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensitivity coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08cd3e9c-642c-44bb-bf5e-10688f041c1c','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08cd3e9c-642c-44bb-bf5e-10688f041c1c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08cd3e9c-642c-44bb-bf5e-10688f041c1c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af8a9712-ebf5-4608-be49-c87eb9ac4039','Short-term power','A loudspeaker power-handling rating defined by IEC 60268-5 as the electrical power a driver can withstand for short bursts of a specified test signal, repeated a set number of times, without permanent damage. It is higher than the long-term rating because heat does not fully accumulate.','Short-term power is how much power a speaker survives in brief bursts. The bursts follow a defined test signal. It is higher than the continuous rating. Heat does not fully build up.','It rates a driver''s tolerance to brief high-level transients, complementing the long-term thermal rating.','A technician applies the IEC 60268-5 short-term signal in bursts (for example 1 s on, repeated) at the rated power and checks for no permanent damage.','Loudspeaker Rating',ARRAY['Short-term stability','Reference efficiency','Sensitivity','Re','Sd']::text[],ARRAY['Confusing short-term power with continuous (long-term) power handling.','Reading a marketing ''peak'' figure as the standardised short-term rating.','Assuming short-term ratings guarantee safety at sustained high levels.']::text[],ARRAY['Comparing driver ratings for transient-heavy program.','Interpreting a datasheet''s power-handling figures.','Setting amplifier limiters below the rated capability.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Short-term power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af8a9712-ebf5-4608-be49-c87eb9ac4039','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af8a9712-ebf5-4608-be49-c87eb9ac4039') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af8a9712-ebf5-4608-be49-c87eb9ac4039');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7caaca63-82ab-4686-a553-6427355f44aa','Short-term stability','The degree to which an oscillator or frequency source keeps a constant output frequency over short averaging times, typically seconds or less. It is characterised statistically, for example by the Allan deviation, and in the frequency domain by phase noise.','Short-term stability is how steady a source frequency stays over short times. It covers seconds or fractions of a second. Engineers measure it with Allan deviation. Poor stability shows as jitter or phase noise.','It quantifies rapid frequency fluctuations of clocks and generators, which matters for timing, jitter and measurement repeatability.','A technician logs an oscillator''s frequency and computes the Allan deviation at a 1 s averaging time to specify its short-term stability.','Frequency Stability',ARRAY['Short-term power','Resolution','Quadrature signal','Sampling theorem','Sensitivity']::text[],ARRAY['Confusing short-term stability with long-term drift or ageing.','Using ordinary standard deviation, which does not converge for these processes.','Ignoring that phase noise and Allan deviation describe the same fluctuations differently.']::text[],ARRAY['Specifying a reference clock for an audio interface.','Comparing generator jitter for a measurement setup.','Assessing timing quality of a word-clock source.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Short-term stability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7caaca63-82ab-4686-a553-6427355f44aa','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7caaca63-82ab-4686-a553-6427355f44aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7caaca63-82ab-4686-a553-6427355f44aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a721c6a3-baed-481d-94cb-4270f2e5466f','Sonar','Sonar (SOund Navigation And Ranging) is a technique that uses underwater sound to detect, locate and characterise objects. Active sonar transmits a pulse and times its echo, while passive sonar only listens to radiated sound.','Sonar uses sound to sense objects underwater. Active sonar sends a ping and times the echo. Passive sonar just listens for sounds. The name means sound navigation and ranging.','It provides detection and ranging where light and radio fail, mapping the seabed and locating vessels, fish and obstacles underwater.','With water sound speed c = 1500 m/s and an echo delay of 0.1 s, active sonar gives range d = c*t/2 = 1500 x 0.1 / 2 = 75 m.','Measurement System',ARRAY['Pulse-echo','Step response','Resolution','Quadrature signal']::text[],ARRAY['Assuming a fixed water sound speed; it varies with temperature, salinity and depth.','Forgetting the factor of two for the round trip in active sonar.','Confusing active sonar (transmits) with passive sonar (listens only).']::text[],ARRAY['Mapping seabed depth with an echo sounder.','Detecting fish schools from a boat.','Locating a submerged obstacle by its echo.']::text[],'Beginner','d = c * t / 2 (active sonar)','Active sonar range equals the underwater sound speed times the echo round-trip time, divided by two.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a721c6a3-baed-481d-94cb-4270f2e5466f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a721c6a3-baed-481d-94cb-4270f2e5466f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a721c6a3-baed-481d-94cb-4270f2e5466f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e4940ec-19c9-4037-bbc5-82e26b442a42','Sound exposure','The time integral of the squared instantaneous sound pressure over a stated period, expressed in pascal-squared seconds (Pa^2*s). It quantifies the total acoustic energy a person or point receives and underlies noise-dose and hearing-risk assessment.','Sound exposure adds up sound energy over time. It squares the pressure and integrates it. The unit is pascal-squared seconds. It measures the total noise a person receives.','It captures cumulative acoustic energy, the basis for noise dose and estimating the risk of noise-induced hearing loss.','A steady 1 Pa (94 dB SPL) sound for 3600 s gives sound exposure E = p^2 * t = 1 x 3600 = 3600 Pa^2*s.','Acoustic Measurement',ARRAY['Sound level meter','Statistical sound level','Residual sound level','Sensitivity','Specific sound level']::text[],ARRAY['UNSAFE: Judging hearing risk from peak loudness alone and ignoring cumulative exposure over time.','Confusing sound exposure (Pa^2*s) with sound exposure level in decibels.','Forgetting that doubling the time doubles the exposure for a steady sound.']::text[],ARRAY['Estimating a worker''s daily noise dose.','Assessing hearing-risk compliance at a venue.','Comparing exposures from steady versus impulsive noise.']::text[],'Intermediate','E = integral of p^2(t) dt over the exposure period','Sound exposure is the integral over time of the squared instantaneous sound pressure across the stated period.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound exposure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e4940ec-19c9-4037-bbc5-82e26b442a42','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e4940ec-19c9-4037-bbc5-82e26b442a42') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e4940ec-19c9-4037-bbc5-82e26b442a42');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc998065-ba99-49ce-a1e4-7f59beedff5b','Sound level meter','An instrument that measures sound pressure level with defined frequency weightings (such as A or C) and time weightings (such as F or S), specified for accuracy by IEC 61672-1 into performance classes 1 and 2. It reports results in decibels referenced to 20 micropascals.','A sound level meter measures how loud a sound is. It applies standard weightings for frequency and time. The result is in decibels. IEC 61672-1 sets its accuracy classes.','It provides standardised, repeatable loudness measurements for noise assessment, compliance and environmental studies.','A technician sets A-weighting and Fast time weighting, calibrates with a 94 dB acoustic calibrator, then reads LAF at the measurement position.','Measurement Instrument',ARRAY['Sound exposure','Statistical sound level','Residual sound level','Specific sound level','Sensitivity']::text[],ARRAY['Skipping the field calibration with an acoustic calibrator before measuring.','Reporting a level without stating the frequency and time weighting used.','Using a Class 2 meter where a Class 1 measurement is required.']::text[],ARRAY['Measuring workplace or venue noise levels.','Documenting environmental noise for a permit.','Checking a sound system against a level limit.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc998065-ba99-49ce-a1e4-7f59beedff5b','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc998065-ba99-49ce-a1e4-7f59beedff5b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc998065-ba99-49ce-a1e4-7f59beedff5b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc5db32d-df5f-4645-8ddf-573c47873403','Specific sound level','Under ISO 1996-1, the sound level of the specific source under assessment, that is the component of the total sound that can be identified and attributed to that particular source. It is obtained by separating the source''s contribution from the residual background.','Specific sound level is the level of the source you are assessing. It is the part of the total sound from that one source. You separate it from the background. It comes from ISO 1996-1.','It isolates a particular source''s contribution so it can be compared against a limit or criterion.','A technician measures total level with the source on and residual with it off, then subtracts on an energy basis to obtain the specific sound level.','Acoustic Measurement',ARRAY['Residual sound level','Statistical sound level','Sound level meter','Sound exposure','Sensitivity']::text[],ARRAY['Confusing specific sound (the source) with residual sound (the background).','Subtracting decibels arithmetically instead of on an energy basis.','Ignoring tonal or impulsive adjustments the standard may require.']::text[],ARRAY['Assessing a single plant against a noise limit.','Separating a target source from environmental background.','Preparing a noise-impact report for one source.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Specific sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc5db32d-df5f-4645-8ddf-573c47873403','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc5db32d-df5f-4645-8ddf-573c47873403') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc5db32d-df5f-4645-8ddf-573c47873403');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34a9f976-174b-497b-8ba0-21f10dbae22a','Spectral contamination','The appearance of false or misplaced energy in a computed spectrum caused by processing artefacts such as spectral leakage from finite-length windowing, aliasing, or nonlinear distortion, rather than by the true signal. It biases amplitude and frequency estimates and can mask nearby components.','Spectral contamination is fake energy in a spectrum. It comes from leakage, aliasing, or distortion. It is not part of the real signal. It can hide or bias true components.','Naming this artefact helps analysts recognise and reduce measurement errors from windowing, aliasing and distortion in spectral analysis.','To reduce leakage-based contamination, a technician applies a suitable window (for example Hann) and ensures anti-alias filtering before the transform.','DSP Artefact',ARRAY['Spectral kurtosis','Resolution','Sampling theorem','Reassigned spectrogram','Real cepstrum']::text[],ARRAY['Reading leakage sidelobes as real signal components.','Using a rectangular window and blaming the source for the smearing.','Overlooking aliasing as a cause of energy at wrong frequencies.']::text[],ARRAY['Cleaning up a smeared FFT of a pure tone.','Choosing a window to reveal a weak tone near a strong one.','Diagnosing spurious peaks in a measured spectrum.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral contamination');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34a9f976-174b-497b-8ba0-21f10dbae22a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34a9f976-174b-497b-8ba0-21f10dbae22a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34a9f976-174b-497b-8ba0-21f10dbae22a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7fadd851-fc91-4cc4-a39c-7ed6785245ba','Spectral kurtosis','A frequency-domain statistic that measures the impulsiveness or non-Gaussianity of a signal at each frequency, computed from the fourth-order and second-order spectral moments. It is used to locate frequency bands where transient, impulsive energy is concentrated, notably in machine fault detection.','Spectral kurtosis shows where a signal is spiky in frequency. It is high where transients concentrate. It stays near zero for steady noise. It helps find fault bands in machines.','It highlights frequency bands carrying impulsive, transient content, guiding filter placement for fault detection and transient analysis.','An analyzer computes short-time spectra, then at each frequency takes the normalised fourth moment; peaks reveal bands to bandpass-filter for further diagnosis.','DSP Analysis',ARRAY['Spectral contamination','Reassigned spectrogram','Real cepstrum','Resolution','Sampling theorem']::text[],ARRAY['Assuming high spectral kurtosis means high energy; it means impulsiveness.','Forgetting the -2 normalisation, which sets Gaussian noise to zero.','Applying it to a single record instead of averaging over several.']::text[],ARRAY['Detecting a bearing fault in a vibration signal.','Selecting a band for envelope analysis.','Finding transient-rich regions in a noisy recording.']::text[],'Advanced','K(f) = <|X(f)|^4> / <|X(f)|^2>^2 - 2','Spectral kurtosis at a frequency is the averaged fourth power of the magnitude divided by the squared averaged second power, minus two.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral kurtosis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7fadd851-fc91-4cc4-a39c-7ed6785245ba','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7fadd851-fc91-4cc4-a39c-7ed6785245ba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7fadd851-fc91-4cc4-a39c-7ed6785245ba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7aa10b1-74b3-4583-8033-2ebe45cda4dd','Statistical sound level','A percentile (exceedance) sound level, written LN, equal to the level exceeded for N percent of the measurement interval. For example LA90 is the A-weighted level exceeded 90 percent of the time, often used as a background indicator, while LA10 approximates higher intrusive levels.','A statistical sound level is a percentile of the level over time. LN is the level passed for N percent of the period. L90 estimates the quiet background. L10 estimates louder events.','It describes fluctuating noise by percentiles rather than a single average, capturing both background and intrusive extremes.','Over a one-hour measurement, LAF90,1h is the A-weighted Fast level exceeded for 90 percent of the hour, commonly reported as the residual background.','Acoustic Measurement',ARRAY['Residual sound level','Specific sound level','Sound level meter','Sound exposure','Resolution']::text[],ARRAY['Confusing L90 (background) with L10 (higher intrusive levels).','Reading LN as an average; it is a percentile, not the mean.','Omitting the time and frequency weighting when quoting an LN value.']::text[],ARRAY['Reporting background level as LA90 for a noise study.','Characterising traffic noise with LA10 and LA90.','Separating steady background from intermittent events.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Statistical sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7aa10b1-74b3-4583-8033-2ebe45cda4dd','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7aa10b1-74b3-4583-8033-2ebe45cda4dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7aa10b1-74b3-4583-8033-2ebe45cda4dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '28e7fa5c-12f2-4164-855f-533a14343c36','Step response','The output of a system when its input changes abruptly from one constant level to another, i.e. a unit step. It equals the running integral of the impulse response and reveals rise time, overshoot, settling and low-frequency behaviour.','Step response is how a system reacts to a sudden input jump. The input steps from one level to another. The output shows rise, overshoot and settling. It equals the impulse response integrated.','It exposes a system''s transient behaviour and low-frequency and phase character in one intuitive time-domain test.','A technician feeds a square-wave or step into an amplifier or loudspeaker and reads rise time and overshoot on an oscilloscope to judge transient response.','System Response',ARRAY['Pulse-echo','Reassigned spectrogram','Resolution','Sampling theorem','Sonar']::text[],ARRAY['Confusing the step response with the impulse response; one is the integral of the other.','Reading overshoot as distortion rather than a transient property.','Ignoring that a driven square wave tests step response at each edge.']::text[],ARRAY['Judging amplifier transient behaviour with a square wave.','Assessing loudspeaker time alignment and phase.','Measuring settling time of a filter or control loop.']::text[],'Intermediate','s(t) = integral from -inf to t of h(tau) d tau','The step response equals the running time integral of the impulse response up to the present time.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Step response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '28e7fa5c-12f2-4164-855f-533a14343c36','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='28e7fa5c-12f2-4164-855f-533a14343c36') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='28e7fa5c-12f2-4164-855f-533a14343c36');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a8f10e33-fe04-4973-bfb1-efffef7b827e','Survey-grade measurement','A sound or noise measurement made with a general-purpose instrument in the lower accuracy class, such as a Class 2 (formerly Type 2) sound level meter, whose wider tolerances suit preliminary or screening surveys rather than reference or legal precision work. Under IEC 61672-1 a Class 2 instrument is permitted about a plus or minus 1.0 dB tolerance at the reference frequency, versus about plus or minus 0.7 dB for Class 1.','Some meters are precise, and some are only good enough for a rough check. A survey-grade reading comes from the lower-accuracy, general-purpose class of meter. It is fine for spotting problems and doing quick noise surveys. It is not accurate enough for legal or laboratory reports.','It provides a fast, lower-cost way to screen sound levels and flag areas needing further study, where full precision-grade accuracy is not required.','A technician doing a walk-through noise survey uses a Class 2 meter, accepting its roughly plus or minus 1.0 dB tolerance, then returns with a Class 1 meter for any measurement that must satisfy a regulation.','Measurement Grade',ARRAY['Sound level meter','Class 1 / Class 2','Leq','Calibration','Measurement uncertainty']::text[],ARRAY['Assuming survey-grade and precision-grade readings are interchangeable; they carry different tolerances.','UNSAFE: Relying on a survey-grade reading to certify legal hearing-exposure compliance, which usually requires a Class 1 or approved instrument.','Forgetting to field-calibrate the meter before a survey.']::text[],ARRAY['A quick noise walk-through of a venue before a show.','Screening a workspace to decide whether a formal noise study is needed.','Comparing rough SPL across seating areas during setup.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Survey-grade measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a8f10e33-fe04-4973-bfb1-efffef7b827e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a8f10e33-fe04-4973-bfb1-efffef7b827e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a8f10e33-fe04-4973-bfb1-efffef7b827e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8812554a-1515-4437-838f-c0ceea84b2a7','Suspension stiffness','The mechanical restoring property of a loudspeaker driver''s suspension (spider and surround), equal to the reciprocal of mechanical compliance and describing how much force is needed to move the cone a given distance. It is symbolized K_ms in newtons per metre and appears in the driver''s small-signal (Thiele-Small) model.','A speaker cone hangs on soft springs called the spider and surround. Stiffness measures how hard those springs push back. A stiff suspension resists motion strongly. Stiffness is just the opposite of compliance, which measures how easily the cone moves.','It sets the driver''s resonance frequency together with the moving mass and helps predict low-frequency behavior, cone control, and box tuning.','If a driver''s compliance is 1.0 mm/N (1.0e-3 m/N), its stiffness is K_ms = 1/0.001 = 1000 N/m; moving the cone 2 mm then needs F = 1000 x 0.002 = 2 N of force.','Loudspeaker Parameter',ARRAY['Mechanical compliance (Cms)','Thiele-Small parameters','Resonance frequency (Fs)','Moving mass (Mms)','Spider']::text[],ARRAY['Confusing stiffness with compliance; they are reciprocals, not the same quantity.','Assuming stiffness stays constant; it changes with excursion and age.','Ignoring how a stiffer suspension raises the resonance frequency.']::text[],ARRAY['Explaining why a broken-in driver has a lower resonance than a new one.','Modeling a woofer in enclosure design software.','Diagnosing a driver whose suspension has softened over time.']::text[],'Intermediate','K_ms = 1 / C_ms ;  F = K_ms * x','Suspension stiffness equals one divided by mechanical compliance. The restoring force equals stiffness multiplied by displacement.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Suspension stiffness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8812554a-1515-4437-838f-c0ceea84b2a7','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8812554a-1515-4437-838f-c0ceea84b2a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8812554a-1515-4437-838f-c0ceea84b2a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57ec9128-9ee9-40cc-adbc-758b1df6fed5','Synchronous averaging','A noise-reduction technique that averages many signal records that are aligned to a common trigger or period, so the repeating (synchronous) component reinforces while uncorrelated noise partly cancels. Also called time-synchronous averaging, it improves signal-to-noise ratio roughly in proportion to the square root of the number of averages.','Repeat a measurement many times and line up each copy exactly. Add them together and divide by how many you took. The part that repeats stays strong. The random noise, which differs each time, shrinks away.','It pulls a repetitive signal out of noise without changing the signal itself, which is vital in impulse-response and vibration measurements.','Averaging 100 synchronized records improves the amplitude signal-to-noise ratio by about the square root of 100, which is 10 times, or roughly 20 dB.','Signal Averaging',ARRAY['Signal-to-noise ratio','Triggering','Impulse response','Time-domain averaging','Coherent averaging']::text[],ARRAY['Confusing synchronous (time-domain) averaging with spectral (power) averaging; only synchronous averaging needs phase alignment.','Averaging records that are not truly aligned, which smears the result.','Expecting random noise to fully vanish rather than fall by the square root of the count.']::text[],ARRAY['Cleaning up a noisy loudspeaker impulse-response measurement.','Extracting a gear-mesh vibration from background machine noise.','Improving an evoked-response or repeated-stimulus measurement.']::text[],'Intermediate','y[n] = (1/M) * sum_{m=0}^{M-1} x[n + m*P] ;  SNR_gain = sqrt(M)','Average M records that are each one period apart. Random-noise amplitude falls by the square root of the number of averages.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Synchronous averaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57ec9128-9ee9-40cc-adbc-758b1df6fed5','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57ec9128-9ee9-40cc-adbc-758b1df6fed5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57ec9128-9ee9-40cc-adbc-758b1df6fed5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf5809de-4dce-4c10-a9ce-611ebc135f7b','Synchrosqueezing','A time-frequency post-processing method that sharpens a wavelet or short-time Fourier representation by reassigning its energy only along the frequency axis, onto each point''s estimated instantaneous frequency. Introduced in the form popularized by Daubechies, Lu and Wu, it concentrates smeared energy while remaining invertible, allowing signal reconstruction.','Normal time-frequency pictures look blurry. Synchrosqueezing sharpens them. It works out the true frequency at each moment. Then it moves the blurred energy to that exact frequency line. Because it only shifts in frequency, you can still rebuild the original signal.','It produces a crisp, readable time-frequency map of signals whose frequencies change over time, and lets you separate and reconstruct individual components.','A technician analyzing a swept-tone or a motor run-up feeds the wavelet transform through synchrosqueezing to see sharp, well-separated frequency tracks instead of a smeared blur.','Time-Frequency Analysis',ARRAY['Continuous wavelet transform','Reassignment method','Instantaneous frequency','Time-frequency representation','Spectrogram']::text[],ARRAY['Thinking it adds new frequency resolution; it only re-concentrates energy already present.','Confusing it with general reassignment, which moves energy in both time and frequency and is not invertible.','Applying it to broadband or non-oscillatory signals, where instantaneous frequency is ill-defined.']::text[],ARRAY['Reading a clean track of a rising engine or fan tone.','Separating close harmonics that a plain spectrogram blurs together.','Analyzing a chirp or glissando in acoustic signal processing.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Synchrosqueezing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf5809de-4dce-4c10-a9ce-611ebc135f7b','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf5809de-4dce-4c10-a9ce-611ebc135f7b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf5809de-4dce-4c10-a9ce-611ebc135f7b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1925b4f-ad60-489d-9735-5ae17eefb6b5','Thermal compression','The loss of loudspeaker output, relative to a linear system, caused mainly by voice-coil heating that raises the coil''s electrical resistance and reduces the current and power it draws. It is a form of power compression, expressed in decibels as the shortfall between expected and measured output at a given drive level.','Drive a speaker hard and its voice coil heats up. A hot coil has more resistance. More resistance means less current and less power reach the coil. So the speaker gets quieter than the input predicts. That lost loudness is thermal compression.','It quantifies how much sensitivity a driver loses under sustained high power, which limits real maximum output in sound-reinforcement systems.','Copper resistance rises about 0.39% per degree Celsius; a 150 C coil temperature rise gives roughly 1.6 times the cold resistance, which alone lowers constant-voltage power by about 10*log10(1.6) = 2 dB.','Loudspeaker Measurement',ARRAY['Power compression','Acoustic compression','Voice-coil temperature','Continuous power handling','Sensitivity']::text[],ARRAY['Confusing thermal (power) compression with signal-processor dynamic-range compression; they are unrelated.','Assuming output rises decibel-for-decibel with power even when the coil is hot.','Ignoring cooling and coil material, which strongly affect the amount of compression.']::text[],ARRAY['Explaining why a PA loses punch during long, loud passages.','Predicting the real maximum SPL of a driver at rated power.','Comparing power-compression figures on competing driver datasheets.']::text[],'Intermediate','R(T) = R0 * [1 + alpha*(T - T0)] ;  Compression_dB = L_linear - L_measured','Voice-coil resistance grows with temperature. Compression is the decibel gap between the expected linear output and the measured output.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1925b4f-ad60-489d-9735-5ae17eefb6b5','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1925b4f-ad60-489d-9735-5ae17eefb6b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1925b4f-ad60-489d-9735-5ae17eefb6b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d7f6b2b-c253-41a5-b9ba-738b6916af47','Time-average sound level','The equivalent continuous sound level, Leq, defined as the constant level that would carry the same total sound energy as the actual time-varying sound over a stated period T. It equals ten times the base-ten logarithm of the mean squared, frequency-weighted sound pressure over T divided by the squared reference pressure of 20 micropascals.','Real noise goes up and down over time. The time-average sound level, called Leq, turns it into one steady number. That number holds the same total energy as the changing sound. It is the main measure for noise exposure and environmental noise.','It reduces a fluctuating sound to a single energy-based figure, which is the basis for noise-exposure limits and environmental noise assessment.','If a sound is 90 dB for the first half of T and 80 dB for the second half, Leq = 10*log10[0.5*10^9.0 + 0.5*10^8.0] = 87.4 dB, closer to the louder level because energy averages.','Acoustic Metric',ARRAY['Leq / LAeq','Sound exposure level (SEL)','A-weighting','Sound pressure level','Noise dose']::text[],ARRAY['Averaging decibels arithmetically instead of averaging sound energy (pressure squared).','Reporting Leq without stating the time period T, which changes the value.','UNSAFE: Treating a modest Leq as safe when brief high peaks can still risk hearing damage; check peak and exposure limits too.']::text[],ARRAY['Measuring a concert''s average level for a noise permit.','Assessing worker noise exposure over a shift.','Reporting environmental noise near a venue or road.']::text[],'Intermediate','L_eq,T = 10*log10[ (1/T) * integral_0^T ( p^2(t) / p0^2 ) dt ]','Average the squared sound pressure over the time period. Divide by the squared reference pressure. Ten times its base-ten logarithm gives the time-average level.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-average sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d7f6b2b-c253-41a5-b9ba-738b6916af47','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d7f6b2b-c253-41a5-b9ba-738b6916af47') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d7f6b2b-c253-41a5-b9ba-738b6916af47');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e47eac57-22fb-47fb-a096-def94d1d9d5a','Time-averaged intensity','The net acoustic power flowing through unit area, equal to the time average of the product of instantaneous sound pressure and instantaneous particle velocity at a point. Expressed in watts per square metre, it is a vector quantity whose sign shows the direction of net energy flow, as used in sound-intensity measurement standards.','Sound carries energy as it moves through the air. Time-averaged intensity measures how much energy flows through one square metre each second. It multiplies pressure by the air''s motion at each instant. Then it averages that product over time.','It measures true net sound-power flow and its direction, which lets technicians rank noise sources and measure sound power even in ordinary rooms.','In a free plane wave, intensity equals p_rms^2 divided by the air impedance; with p_rms = 1 Pa and rho*c = 415 rayls, I = 1 / 415 = 2.4e-3 W/m^2.','Acoustic Metric',ARRAY['Sound intensity probe','Particle velocity','Sound power','Acoustic impedance','ISO 9614']::text[],ARRAY['Confusing intensity (a vector, net energy flow) with sound pressure level (a scalar).','Forgetting that reactive, non-propagating energy averages to zero in the net intensity.','Ignoring the phase match between the two microphones of an intensity probe.']::text[],ARRAY['Locating the loudest part of a machine with an intensity probe.','Measuring sound power on a factory floor without an anechoic room.','Checking sound leakage through a wall or panel.']::text[],'Advanced','I = <p(t)*u(t)> = (1/T) * integral_0^T p(t)*u(t) dt','Multiply sound pressure by particle velocity at each instant. Average that product over the time period to get net intensity.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-averaged intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e47eac57-22fb-47fb-a096-def94d1d9d5a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e47eac57-22fb-47fb-a096-def94d1d9d5a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e47eac57-22fb-47fb-a096-def94d1d9d5a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b503541-eba5-4da7-8a16-5dcec691308e','Time-of-flight','The time a wave takes to travel a known path between two points, from which distance is found by multiplying by the wave speed. In acoustics it converts a measured delay into a range, since distance equals the speed of sound multiplied by the travel time.','Sound takes time to travel from one place to another. Time-of-flight is that travel time. If you know how fast sound moves, the delay tells you the distance. Distance is just speed multiplied by time.','It turns a measured delay into a distance, which underlies rangefinding, driver time-alignment, and reflection analysis.','If an echo returns 20 ms after the pulse, the round trip is 343 * 0.020 = 6.86 m, so the reflecting surface is about 3.43 m away (one-way) at 343 m/s in 20 C air.','Measurement Method',ARRAY['Speed of sound','Impulse response','Time-windowed response','Delay / latency','Reflection']::text[],ARRAY['Forgetting to halve the round-trip time when finding one-way distance in pulse-echo.','Using a fixed 343 m/s when temperature and humidity shift the speed of sound.','Ignoring the electrical and processing latency inside the measurement chain.']::text[],ARRAY['Time-aligning a subwoofer to a main speaker in a PA.','Finding the distance to a reflecting wall from an impulse response.','Ultrasonic distance ranging.']::text[],'Beginner','t = d / c ;  d = c * t','Travel time equals distance divided by wave speed. Distance equals wave speed multiplied by the measured travel time.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-of-flight');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b503541-eba5-4da7-8a16-5dcec691308e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b503541-eba5-4da7-8a16-5dcec691308e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b503541-eba5-4da7-8a16-5dcec691308e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f63e1aa3-7c9f-434f-8174-40678e282156','Time-windowed response','A frequency response computed after multiplying a measured impulse response by a finite time window, so that energy arriving after a chosen cutoff, such as room reflections, is excluded. This quasi-anechoic technique trades low-frequency resolution for a reflection-free result, with the lowest reliable frequency set roughly by the reciprocal of the window length.','A speaker measurement in a normal room also catches echoes off the walls. Time windowing keeps only the first, direct sound and cuts the echoes. This gives a cleaner response, like an echo-free room. The trade-off is weaker detail at low frequencies.','It lets technicians obtain near-anechoic loudspeaker response in an ordinary room by removing reflections that arrive after the direct sound.','If the first reflection arrives 5 ms after the direct sound, windowing to 5 ms yields valid data only above about 1/0.005 = 200 Hz; a longer window lowers that limit but lets reflections back in.','Measurement Method',ARRAY['Impulse response','Quasi-anechoic measurement','Windowing','Reflection','Frequency resolution']::text[],ARRAY['Setting the window too long, which readmits reflections into the result.','Trusting low-frequency data below the window''s frequency limit.','Forgetting that a shorter window worsens frequency resolution.']::text[],ARRAY['Measuring a loudspeaker''s on-axis response in a normal room.','Separating a driver''s direct sound from a boundary reflection.','Comparing quasi-anechoic curves during speaker setup.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-windowed response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f63e1aa3-7c9f-434f-8174-40678e282156','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f63e1aa3-7c9f-434f-8174-40678e282156') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f63e1aa3-7c9f-434f-8174-40678e282156');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b627e0f0-79a5-4af1-b465-56115c8a3a64','Time–frequency representation','A two-dimensional description of a signal''s energy or amplitude jointly over time and frequency, revealing how its spectral content changes moment to moment. Common forms include the short-time Fourier transform and its squared magnitude, the spectrogram, along with wavelet and quadratic (Cohen-class) distributions.','A normal spectrum shows which frequencies are present but not when. A time-frequency representation shows both at once. It maps signal energy across time on one axis and frequency on the other. This reveals how a sound''s pitch and tone change over time.','It exposes how non-stationary signals, whose frequencies vary with time, evolve, which a single fixed spectrum cannot show.','A technician views a spectrogram by sliding a short window along the signal, taking the Fourier transform in each window; a narrow window sharpens time detail while a wide window sharpens frequency detail.','Time-Frequency Analysis',ARRAY['Spectrogram','Short-time Fourier transform','Wavelet transform','Wigner–Ville distribution','Windowing']::text[],ARRAY['Expecting sharp time and sharp frequency at once; the window sets a trade-off between them.','Reading a spectrogram''s window length as the signal''s true resolution limit.','Confusing the linear STFT with quadratic distributions that add cross-terms.']::text[],ARRAY['Watching how a musical note''s harmonics decay over time.','Analyzing a swept sine or a machine run-up.','Spotting transient clicks hidden in a steady tone.']::text[],'Intermediate','X(t,f) = integral x(tau)*w(tau - t)*e^{-j2*pi*f*tau} d(tau) ;  S(t,f) = |X(t,f)|^2','Slide a short window along the signal and take the Fourier transform inside each position. The squared magnitude gives the energy at each time and frequency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time–frequency representation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b627e0f0-79a5-4af1-b465-56115c8a3a64','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b627e0f0-79a5-4af1-b465-56115c8a3a64') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b627e0f0-79a5-4af1-b465-56115c8a3a64');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9487227d-72f5-47bc-905d-8da95ee24599','Ultrasonic imaging','The formation of images from ultrasound, sound above the roughly 20 kHz limit of human hearing, usually by the pulse-echo method: short pulses are transmitted and the depth of each reflecting boundary is found from the round-trip echo time and the medium''s sound speed. It underlies medical ultrasound and non-destructive material testing.','Ultrasound is sound too high for people to hear. Ultrasonic imaging sends short pulses into an object. Echoes bounce back from boundaries inside it. The time each echo takes gives its depth. Many echoes together build a picture.','It sees inside bodies or materials without cutting them open, using reflected high-frequency sound to map internal structure and flaws.','In soft tissue where sound travels about 1540 m/s, an echo returning 130 microseconds after the pulse maps a boundary at depth d = 1540 * 130e-6 / 2 = 0.10 m, or 10 cm.','Ultrasound',ARRAY['Ultrasonic transducer','Pulse-echo','Time-of-flight','Non-destructive testing','Acoustic impedance']::text[],ARRAY['Forgetting to halve the round-trip time when computing echo depth.','Assuming one fixed sound speed across tissues or materials of different density.','Ignoring that higher frequency sharpens resolution but shortens penetration depth.']::text[],ARRAY['Medical sonography of internal organs.','Checking a weld or casting for hidden cracks.','Measuring material or wall thickness from one side.']::text[],'Intermediate','d = c * t / 2','Depth equals the medium''s sound speed times the round-trip echo time, divided by two.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9487227d-72f5-47bc-905d-8da95ee24599','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9487227d-72f5-47bc-905d-8da95ee24599') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9487227d-72f5-47bc-905d-8da95ee24599');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09e9dd88-df7a-4697-a309-2e3f12c55944','Ultrasonic transducer','A device that converts electrical energy into ultrasound and ultrasound back into electrical signals, most often using a piezoelectric element that vibrates when driven and generates charge when struck by returning sound. Its thickness-mode resonance frequency is set by the element thickness and the material''s sound speed.','An ultrasonic transducer turns electricity into high-pitched sound and back again. Most use a piezoelectric crystal. The crystal flexes when voltage is applied. It also makes voltage when sound pushes on it. Its thickness sets the frequency it works at.','It is the send-and-receive element of any ultrasound system, generating the pulses and detecting the echoes used for imaging, ranging, and testing.','For a piezoceramic disc with longitudinal sound speed about 4000 m/s vibrating in thickness mode, a 1 mm thickness gives a resonance near f = 4000 / (2 * 0.001) = 2 MHz.','Ultrasound',ARRAY['Piezoelectric effect','Ultrasonic imaging','Resonance frequency','Acoustic impedance matching','Transducer bandwidth']::text[],ARRAY['Assuming a transducer only transmits; the same element usually receives echoes too.','Overlooking the matching and backing layers that set bandwidth and damping.','Confusing thickness-mode resonance with the pulse''s usable bandwidth.']::text[],ARRAY['Choosing a probe frequency for a given imaging depth.','Selecting a transducer for weld or thickness inspection.','Pairing a transmit and receive element in a ranging system.']::text[],'Intermediate','f0 = v / (2 * d)','The thickness-mode resonance frequency equals the material''s sound speed divided by twice the element thickness.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09e9dd88-df7a-4697-a309-2e3f12c55944','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09e9dd88-df7a-4697-a309-2e3f12c55944') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09e9dd88-df7a-4697-a309-2e3f12c55944');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'edd17bd8-7df2-4ae3-8bf0-0444894e7fee','Validation','Objective confirmation, through evidence, that a method, instrument, or system fulfills the requirements for a specific intended use. In quality and metrology vocabulary it is distinguished from verification: validation asks whether the requirements suit the intended application, not merely whether specified requirements are met.','Validation asks a simple question: does this really work for the job we need it for. It gathers evidence that a method or tool fits its intended use. It differs from verification. Verification only checks that stated requirements are met.','It gives documented confidence that a measurement method or system is fit for its intended purpose before results are trusted or reported.','Before adopting a new loudspeaker-measurement procedure, a technician validates it by measuring reference units and confirming the results match known values within accepted limits, then records that evidence.','Quality / Metrology',ARRAY['Verification','Calibration','Traceability','Measurement uncertainty','Quality management']::text[],ARRAY['Using ''validation'' and ''verification'' as synonyms; validation targets fitness for the intended use.','Treating a one-time check as validation without documented, repeatable evidence.','Assuming a calibrated instrument makes the whole method automatically valid.']::text[],ARRAY['Qualifying a new test procedure before production use.','Documenting that a measurement setup suits a certification requirement.','Auditing a lab''s methods against a quality standard.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Validation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'edd17bd8-7df2-4ae3-8bf0-0444894e7fee','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='edd17bd8-7df2-4ae3-8bf0-0444894e7fee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='edd17bd8-7df2-4ae3-8bf0-0444894e7fee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '606c2c80-0ccb-4319-a9dc-338208c5a41e','Vibrometer','An instrument that measures the vibration (displacement, velocity, or acceleration) of a surface. A common non-contact type is the laser Doppler vibrometer, which detects the Doppler frequency shift of laser light reflected from a moving surface, where the shift is proportional to the surface velocity.','A vibrometer measures how a surface vibrates. A laser version does it without touching the object. It shines a laser on the surface. The reflected light changes frequency as the surface moves. That change reveals the surface''s speed.','It measures surface motion precisely, without adding mass, which is essential for testing loudspeaker cones, panels, and delicate structures.','For a helium-neon laser at 633 nm, a surface moving at 1 m/s produces a Doppler shift of f_D = 2 * 1 / 633e-9 = 3.16 MHz, which the instrument converts to velocity.','Vibration Measurement',ARRAY['Laser Doppler vibrometer','Accelerometer','Doppler shift','Cone breakup','Modal analysis']::text[],ARRAY['Assuming a contact sensor''s mass never affects a light structure''s motion; it can.','Ignoring that a laser vibrometer needs an adequately reflective surface.','Confusing measured velocity with displacement without integrating.']::text[],ARRAY['Mapping cone breakup modes on a loudspeaker driver.','Measuring panel vibration in an enclosure.','Studying vibration of small or fragile parts without loading them.']::text[],'Intermediate','f_D = 2 * v / lambda','The Doppler frequency shift equals twice the surface velocity divided by the laser wavelength.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibrometer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '606c2c80-0ccb-4319-a9dc-338208c5a41e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='606c2c80-0ccb-4319-a9dc-338208c5a41e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='606c2c80-0ccb-4319-a9dc-338208c5a41e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1cbbdff3-1461-49a5-88bf-45346c559142','Waterfall plot','A three-dimensional display that stacks a series of spectra taken at successive times, showing frequency on one axis, time (or another parameter) on a second, and amplitude on the third. In loudspeaker work the cumulative spectral decay plot is a waterfall that reveals how energy at each frequency dies away after the input stops, exposing resonances and ringing.','A waterfall plot stacks many spectra taken one after another. It shows frequency, time, and level together in one 3D view. For speakers, it shows how sound at each frequency fades after the signal stops. Slow-fading ridges reveal resonances and ringing.','It shows how a system''s spectrum changes over time, making stored energy, resonances, and decay easy to see rather than hidden in a single curve.','A technician reads a cumulative spectral decay waterfall of a loudspeaker; a ridge that lingers at one frequency long after the rest has decayed flags a resonance to damp.','Data Display',ARRAY['Cumulative spectral decay','Spectrogram','Resonance','Impulse response','Decay time']::text[],ARRAY['Reading absolute low-frequency detail from a short-window cumulative decay plot.','Confusing the time/decay axis with a simple repeated-measurement axis.','Overinterpreting ridges caused by the analysis window rather than the device.']::text[],ARRAY['Finding a lingering cone or cabinet resonance in a speaker.','Comparing decay behavior before and after adding damping.','Showing how a room''s modes ring after a sound stops.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waterfall plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1cbbdff3-1461-49a5-88bf-45346c559142','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1cbbdff3-1461-49a5-88bf-45346c559142') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1cbbdff3-1461-49a5-88bf-45346c559142');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da0041bb-378d-46c2-9341-d6679089b37f','Wigner–Ville distribution','A quadratic time-frequency distribution that maps a signal''s energy jointly over time and frequency by Fourier-transforming its instantaneous autocorrelation with respect to the time lag. It gives very high joint concentration, ideal for a single linear chirp, but produces interference (cross) terms when several components are present.','The Wigner-Ville distribution is a sharp time-frequency picture. It shows a signal''s energy across time and frequency very precisely. For one changing tone it is extremely clear. But with several tones at once, false ghost patterns appear between them.','It offers the highest time-frequency concentration of the classic distributions, useful for analyzing single sweeping-frequency components.','A technician analyzing a single linear chirp uses the Wigner-Ville distribution to see an almost ideal thin line, but switches to a spectrogram or smoothed version when multiple tones create confusing cross-terms.','Time-Frequency Analysis',ARRAY['Cohen class','Cross-terms','Spectrogram','Instantaneous frequency','Time–frequency representation']::text[],ARRAY['Mistaking cross-term artifacts for real signal components.','Expecting clean results for multi-component signals without smoothing.','Forgetting that its values can go negative, unlike a true energy density.']::text[],ARRAY['Analyzing a single frequency-swept tone with maximum sharpness.','Estimating an instantaneous frequency track.','Teaching the trade-off between concentration and cross-terms in time-frequency analysis.']::text[],'Advanced','W_x(t,f) = integral x(t + tau/2) * x*(t - tau/2) * e^{-j2*pi*f*tau} d(tau)','Form the product of the signal shifted forward and backward in time by half the lag. Take the Fourier transform of that product over the lag to get energy at each time and frequency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wigner–Ville distribution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da0041bb-378d-46c2-9341-d6679089b37f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da0041bb-378d-46c2-9341-d6679089b37f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da0041bb-378d-46c2-9341-d6679089b37f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d67118c-fc71-4c2a-b73d-917bc9dbaf38','Xlim','A loudspeaker driver''s mechanical excursion limit: the maximum peak cone displacement before physical failure occurs. As defined in Eminence''s specification practice, Xlim is the smallest of four failure conditions: the spider crashing on the top plate, the voice coil bottoming on the back plate, the coil leaving the top of the gap, or the cone reaching its physical travel limit.','A speaker cone can only move so far before it breaks. Xlim marks that hard mechanical limit. It is the smallest safe distance among several failure points. Pushing past Xlim is almost certain to damage the driver. It is different from Xmax, the clean-sounding limit.','It marks the point beyond which mechanical damage is likely, guiding safe power and excursion limits for a driver.','A technician sizing a high-pass filter and limiter keeps peak excursion below the rated Xlim so the coil and spider never reach a hard stop, protecting the driver even though sound quality already suffers past Xmax.','Loudspeaker Parameter',ARRAY['Xmax','Xmech','Excursion','Cone displacement','Driver protection']::text[],ARRAY['Confusing Xlim with Xmax; Xmax is the linear (low-distortion) limit, Xlim is the mechanical damage limit.','Assuming clean sound up to Xlim; distortion rises well before it, near Xmax.','Treating Xlim as a continuous safe operating point rather than a do-not-exceed peak.']::text[],ARRAY['Setting limiter thresholds to protect a subwoofer.','Comparing the safe excursion headroom of competing drivers.','Diagnosing a driver damaged by over-excursion.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Xlim');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d67118c-fc71-4c2a-b73d-917bc9dbaf38','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d67118c-fc71-4c2a-b73d-917bc9dbaf38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d67118c-fc71-4c2a-b73d-917bc9dbaf38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '083e3245-507e-41cf-a7cd-e83a2893cd63','Xmech','A loudspeaker driver''s mechanical peak-displacement limit: the maximum one-way cone excursion before the moving assembly reaches a hard mechanical stop and risks permanent damage, such as the voice coil bottoming, the spider crashing, or the coil leaving the gap. Manufacturers use Xmech (and Xdamage or Xlim) for essentially the same mechanical limit, distinct from the linear limit Xmax.','Xmech is the hard limit on how far a speaker cone can move. Past it, moving parts hit their stops and can break. It is the mechanical damage point, not the clean-sound point. Different makers may call it Xmech, Xdamage, or Xlim.','It sets the absolute excursion a driver must not exceed, so system limiters and filters keep the moving parts clear of their mechanical stops.','When Xmech is larger than Xmax, a technician can allow brief peaks above the linear Xmax for extra loudness, as long as excursion still stays safely below the mechanical Xmech limit.','Loudspeaker Parameter',ARRAY['Xlim','Xmax','Xdamage','Excursion','Driver protection']::text[],ARRAY['Confusing Xmech with Xmax; Xmax is the low-distortion linear limit, Xmech is the mechanical damage limit.','Assuming Xmech equals Xmax plus a fixed margin; the ratio varies by driver.','Running a driver continuously near Xmech, where distortion is already high and damage risk is real.']::text[],ARRAY['Setting excursion-based protection for a high-output woofer.','Judging how much peak headroom a driver has above its linear range.','Reading a datasheet that lists both Xmax and a mechanical limit.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Xmech');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '083e3245-507e-41cf-a7cd-e83a2893cd63','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='083e3245-507e-41cf-a7cd-e83a2893cd63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='083e3245-507e-41cf-a7cd-e83a2893cd63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a601a5a0-f9a2-464a-8209-84717721a951','ABX testing','ABX testing is a double-blind listening method in which a subject hears known samples A and B, then an unknown sample X that is randomly either A or B, and must judge whether X matches A or B. Correct-identification counts are assessed statistically, usually with the binomial distribution, to decide whether a real audible difference exists.','ABX testing checks if two sounds really differ to the ear. You hear sample A, sample B, then a hidden sample X. You guess whether X is A or B. Doing this many times shows if the difference is real or just guessing.','It provides an unbiased, statistically testable way to decide whether a claimed audible difference between two signals, devices, or settings actually exists.','A technician might run 16 ABX trials comparing a lossy codec to the original; scoring about 13 or more correct exceeds the roughly 5 percent chance level and indicates an audible difference.','Listening Test',ARRAY['Double-blind test','Codec-artifact recognition','Anchoring bias','MUSHRA','Level matching']::text[],ARRAY['Running too few trials, so results cannot reach statistical significance.','Failing to level-match A and B, letting a loudness difference masquerade as a quality difference.','Treating a single lucky correct answer as proof of an audible difference.']::text[],ARRAY['Comparing a 256 kbps lossy file against the original master.','Testing whether a cable or converter change is actually audible.','Validating a plugin setting before committing to it on a mix.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ABX testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a601a5a0-f9a2-464a-8209-84717721a951','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a601a5a0-f9a2-464a-8209-84717721a951') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a601a5a0-f9a2-464a-8209-84717721a951');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '763b4acf-f2e4-4bec-8e16-94af01ba4630','Age-related high-frequency loss','Age-related high-frequency loss, or presbycusis, is the progressive, largely symmetrical sensorineural decline in hearing sensitivity that accompanies ageing and affects the highest frequencies first. It reflects cumulative loss of cochlear hair cells and neural elements, and typically steepens above about 2 kHz.','Hearing usually gets worse as people age. The highest pitches fade first. This is called presbycusis. It happens because tiny hair cells in the ear wear out over time. It cannot be reversed, so protecting your ears early matters.','The concept explains why older listeners lose treble detail and helps set realistic expectations for hearing ability and monitoring across age groups.','A technician should not assume every listener hears to 20 kHz; ISO 7029 shows a typical 70-year-old male may have thresholds raised by 30 dB or more at 4 kHz relative to a young adult.','Hearing Health',ARRAY['Audible frequency range','Auditory fatigue','Sensorineural hearing loss','Cochlear mechanics','Air conduction']::text[],ARRAY['UNSAFE: Cranking monitors louder to ''hear the highs'' worsens noise exposure and accelerates hearing damage.','Assuming presbycusis affects all frequencies equally rather than the high end first.','Confusing age-related loss with noise-induced loss, which shows a characteristic notch near 4 kHz.']::text[],ARRAY['Explaining why an older mixer rolls off less high frequency than a younger colleague expects.','Interpreting an audiogram that slopes downward at high frequencies.','Planning listening panels with an age-diverse group of subjects.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Age-related high-frequency loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '763b4acf-f2e4-4bec-8e16-94af01ba4630','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='763b4acf-f2e4-4bec-8e16-94af01ba4630') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='763b4acf-f2e4-4bec-8e16-94af01ba4630');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1deb1c43-1401-4264-8b77-e310a13a0607','Air conduction','Air conduction is the normal pathway by which airborne sound reaches the cochlea: sound enters the ear canal, vibrates the eardrum, and is transmitted through the middle-ear ossicles to the fluid of the inner ear. It is the route tested by standard pure-tone audiometry using headphones or loudspeakers.','Air conduction is how we normally hear. Sound travels down the ear canal as air pressure waves. It shakes the eardrum, then three tiny bones pass the motion inward. Finally the inner ear turns it into nerve signals.','It describes the standard route of hearing and provides the baseline against which bone-conduction results are compared to locate a hearing problem.','In pure-tone audiometry a technician plays tones through headphones to measure air-conduction thresholds; comparing them with bone-conduction thresholds reveals whether a loss is conductive or sensorineural.','Auditory Pathway',ARRAY['Bone conduction','Audible frequency range','Cochlear mechanics','Auditory nerve firing','Basilar-membrane frequency mapping']::text[],ARRAY['Thinking air conduction and bone conduction are unrelated rather than two paths to the same cochlea.','Assuming headphones bypass the middle ear; air conduction still uses the eardrum and ossicles.','Forgetting that a blocked ear canal or middle-ear problem impairs air conduction specifically.']::text[],ARRAY['Running a headphone-based hearing screening.','Comparing air- and bone-conduction thresholds to classify a hearing loss.','Explaining how sealed earphones deliver sound to the eardrum.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air conduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1deb1c43-1401-4264-8b77-e310a13a0607','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1deb1c43-1401-4264-8b77-e310a13a0607') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1deb1c43-1401-4264-8b77-e310a13a0607');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24985187-1a3e-4532-9ecb-c5c058d62a56','Air-column resonance','Air-column resonance is the formation of standing waves in the air inside a tube, producing strong response at frequencies determined by the tube length and end conditions. A pipe open at both ends resonates at f_n = n·c/(2L); a pipe closed at one end resonates only at odd harmonics, f_n = n·c/(4L).','Air inside a tube can vibrate strongly at certain pitches. This is air-column resonance. It is what makes wind instruments sound. The tube length sets the pitches. A tube closed at one end sounds an octave lower than an open one of the same length.','It explains how wind instruments and ports select and reinforce specific frequencies, and why open and closed tubes give different harmonic series.','For an open tube 0.50 m long with sound speed 343 m/s, the lowest resonance is 343 / (2 × 0.50) = 343 Hz; closing one end drops it to 343 / (4 × 0.50) = 171.5 Hz.','Instrument Acoustics',ARRAY['Bore shape','Standing wave','Bell radiation','Brass directivity','Bowing excitation']::text[],ARRAY['Using the open-pipe formula for a stopped pipe, which halves the true fundamental.','Ignoring the end correction, which makes the effective length slightly longer than the physical tube.','Forgetting that a closed tube produces only odd harmonics, not the full series.']::text[],ARRAY['Predicting the pitch of an organ pipe or flute.','Understanding why a stopped pipe sounds an octave below an open one.','Tuning a bass-reflex port to a target resonance.']::text[],'Intermediate','Open pipe: f_n = n·c/(2L);  Closed pipe: f_n = n·c/(4L), n = 1,3,5,...','For a tube open at both ends, the resonant frequency equals the harmonic number times the speed of sound divided by twice the tube length. For a tube closed at one end, only odd harmonics occur, at the harmonic number times the speed of sound divided by four times the length.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-column resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24985187-1a3e-4532-9ecb-c5c058d62a56','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24985187-1a3e-4532-9ecb-c5c058d62a56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24985187-1a3e-4532-9ecb-c5c058d62a56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5a40fd98-9341-434c-b2a1-5f7666387562','Aliasing recognition','Aliasing recognition is the ear-training skill of identifying the artifacts that arise when signal content above half the sampling rate folds back into the audible band as false, usually inharmonic tones. It typically appears as harsh, metallic, or dissonant components during poor sample-rate conversion, aggressive digital processing, or under-sampled synthesis.','Aliasing happens when digital audio is sampled too coarsely. High sounds fold back as wrong, false tones. These often sound harsh or metallic. Learning to spot them helps you catch bad conversion or processing early.','It helps technicians detect a specific digital fault so they can raise oversampling, fix conversion settings, or filter before sampling.','If a bright synth sweep produces descending whistles that move opposite to the note, a technician recognizes aliasing and enables an oversampled or anti-aliased mode.','Artifact Recognition',ARRAY['Nyquist frequency','Codec-artifact recognition','Clipping recognition','Bandwidth limitation','Sample rate']::text[],ARRAY['Confusing aliasing whistles with intended harmonics or effects.','Assuming a high sample rate alone prevents aliasing without proper anti-alias filtering.','Blaming the monitors when the fault is in the digital signal path.']::text[],ARRAY['Auditioning a non-linear plugin on a bright source.','Checking a sample-rate conversion between 96 kHz and 44.1 kHz.','Evaluating a software synthesizer at high pitches.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aliasing recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5a40fd98-9341-434c-b2a1-5f7666387562','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5a40fd98-9341-434c-b2a1-5f7666387562') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5a40fd98-9341-434c-b2a1-5f7666387562');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37cf8943-6ca0-4114-8fb4-8c832e1d64ed','Ambisonic decoding','Ambisonic decoding is the process of converting an ambisonic scene, represented in spherical-harmonic (B-format) components, into signals for a specific set of loudspeakers or into binaural headphone feeds. The decoder weights the harmonic components to reconstruct the intended sound field at the listening position.','Ambisonics stores a full 3D sound field as a set of math channels. Decoding turns those channels into feeds for real speakers or headphones. The decoder must know the speaker layout. It then rebuilds the direction of each sound.','It renders a layout-independent ambisonic recording or mix onto whatever speaker array or headphones are available at playback.','A technician loads a first-order B-format file and selects a decoder matched to a cube of eight speakers, or a binaural decoder using head-related transfer functions for headphones.','Spatial Audio',ARRAY['Ambisonic encoding','Binaural rendering of immersive mixes','Audio objects','Bed channels','HRTF']::text[],ARRAY['Using a decoder built for a different speaker layout than the actual rig.','Confusing the fixed encoding with the layout-specific decoding step.','Ignoring ambisonic order, which limits spatial resolution regardless of the decoder.']::text[],ARRAY['Playing a VR ambisonic bed over a dome of loudspeakers.','Rendering a 360-degree scene to binaural for headphones.','Choosing a decoder for an irregular speaker arrangement.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambisonic decoding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37cf8943-6ca0-4114-8fb4-8c832e1d64ed','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37cf8943-6ca0-4114-8fb4-8c832e1d64ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37cf8943-6ca0-4114-8fb4-8c832e1d64ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '772b84ea-7dd1-4d4e-846e-1d3b59de970a','Ambisonic encoding','Ambisonic encoding represents a sound field, or the position of a source, as a set of spherical-harmonic components (B-format) that describe sound arriving from all directions around a point. Higher ambisonic order adds more harmonic components and finer directional resolution.','Ambisonic encoding captures sound from every direction around one point. It stores the field as a set of math channels called B-format. More channels mean sharper direction. A source is placed by setting its angle and height.','It provides a speaker-independent, rotatable representation of a full 3D sound field, ideal for capture, mixing, and later flexible playback.','A technician pans a dialogue source to a given azimuth and elevation, encoding it into first- or higher-order B-format that can later be rotated to follow a listener''s head.','Spatial Audio',ARRAY['Ambisonic decoding','Audio objects','Binaural rendering of immersive mixes','Bed channels','Spherical harmonics']::text[],ARRAY['Confusing the B-format channels with ordinary loudspeaker signals.','Assuming first-order ambisonics gives pinpoint localization; its spatial resolution is limited.','Mixing incompatible channel-ordering or normalization conventions, such as FuMa and ACN/SN3D.']::text[],ARRAY['Recording with a first-order ambisonic microphone.','Authoring a rotatable 360 soundtrack for VR.','Encoding point sources into a higher-order ambisonic mix.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambisonic encoding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '772b84ea-7dd1-4d4e-846e-1d3b59de970a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='772b84ea-7dd1-4d4e-846e-1d3b59de970a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='772b84ea-7dd1-4d4e-846e-1d3b59de970a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0765fe58-eef3-40d3-b514-f52d49d0d043','Anchoring bias','Anchoring bias is a cognitive bias in which an early or salient reference value disproportionately influences subsequent judgments. In audio listening tests it can skew ratings when the first item heard, or a known reference, biases how later items are scored.','Anchoring bias means the first thing you hear sets your standard. Later sounds get judged against it, even unfairly. In listening tests this can distort scores. Good test design uses hidden references and random order to reduce it.','Recognizing anchoring bias helps designers of listening tests control an error source so quality ratings reflect the audio, not the order or framing.','A technician running a MUSHRA test randomizes stimulus order and includes a hidden reference and anchor, so no single early item unduly sets each listener''s scale.','Listening Bias',ARRAY['ABX testing','MUSHRA','Confirmation bias','Level matching','Double-blind test']::text[],ARRAY['Presenting stimuli in a fixed order, letting the first item anchor all later ratings.','Telling listeners which sample is the ''expensive'' or ''reference'' one before they judge.','Confusing anchoring bias with simple loudness differences between samples.']::text[],ARRAY['Designing a subjective codec-quality test.','Auditioning gear where price or brand is known in advance.','Interpreting why the first mix played often scores highest.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anchoring bias');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0765fe58-eef3-40d3-b514-f52d49d0d043','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0765fe58-eef3-40d3-b514-f52d49d0d043') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0765fe58-eef3-40d3-b514-f52d49d0d043');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2559a7fc-e6e3-405c-88a9-9dac227f2d14','Attack and release recognition','Attack and release recognition is the ear-training skill of identifying how quickly a sound or a dynamics processor rises to full level (attack) and how quickly it falls back (release). It underlies judging transients, envelope shaping, and the audible behavior of compressors and gates.','Every sound has a start and an ending shape. Attack is how fast it gets loud. Release is how fast it fades. Learning to hear these helps you set compressors and gates. It also helps you judge punch and sustain.','It lets a technician diagnose and set time-based dynamics controls by ear, matching processing to the natural envelope of a source.','Hearing a snare lose its click, a technician recognizes an over-fast compressor attack and lengthens it so the transient passes before gain reduction clamps down.','Ear Training',ARRAY['Attack time','Release time','Transient','Clipping recognition','Auditory adaptation']::text[],ARRAY['Confusing a slow release that pumps with distortion.','Assuming a fast attack always sounds punchier; it can dull transients instead.','Judging attack and release without level-matching, so loudness masks the envelope change.']::text[],ARRAY['Dialing in a drum-bus compressor by ear.','Setting a noise gate''s release so it does not chatter.','Shaping a synth envelope to match a track''s groove.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attack and release recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2559a7fc-e6e3-405c-88a9-9dac227f2d14','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2559a7fc-e6e3-405c-88a9-9dac227f2d14') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2559a7fc-e6e3-405c-88a9-9dac227f2d14');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c6b2322-e7a8-4607-87e4-ab1e08d7c4b9','Audible frequency range','The audible frequency range is the span of frequencies a healthy young human can hear, conventionally stated as about 20 Hz to 20 kHz. Sensitivity is not uniform across this band and the upper limit falls with age and noise exposure.','People hear a limited range of pitches. It runs roughly from 20 Hz to 20,000 Hz. We hear middle pitches best. The top limit drops as we age. Very low and very high sounds need much more energy to notice.','It defines the working band for audio systems and sets the basis for sample rates, bandwidth choices, and hearing expectations.','Knowing the top limit falls with age, a technician does not rely on hearing a 19 kHz tone; a sine sweep and a meter confirm content above the range a listener can perceive.','Hearing Fundamentals',ARRAY['Age-related high-frequency loss','Bandwidth limitation','Equal-loudness contour','Air conduction','Sample rate']::text[],ARRAY['Treating 20 Hz to 20 kHz as exact for everyone rather than a healthy young-adult average.','Assuming sensitivity is flat across the band; the ear is far less sensitive at the extremes.','Believing all adults still hear to 20 kHz.']::text[],ARRAY['Justifying a 44.1 kHz sample rate against the 20 kHz upper limit.','Explaining why sub-bass needs high levels to be felt.','Setting the frequency span of an analyzer display.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audible frequency range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c6b2322-e7a8-4607-87e4-ab1e08d7c4b9','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c6b2322-e7a8-4607-87e4-ab1e08d7c4b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c6b2322-e7a8-4607-87e4-ab1e08d7c4b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '15a316fc-9284-468b-819b-a739768beb95','Audio objects','Audio objects are individual sound elements carried with positional and behavioral metadata, so that a renderer places them in space at playback rather than fixing them to specific channels. They are the core of object-based audio systems such as Dolby Atmos and MPEG-H.','An audio object is a single sound plus data about where it should go. The playback system reads that data and positions the sound. This differs from fixed channels. It lets the same mix adapt to many speaker layouts.','Objects let a mix render correctly across many playback layouts and support flexible, interactive placement of individual sounds.','In an immersive session a technician assigns a helicopter to an audio object with a moving position, letting the renderer steer it across whatever speakers or headphones the listener uses.','Spatial Audio',ARRAY['Bed channels','Binaural rendering of immersive mixes','Ambisonic encoding','Audio Definition Model','Renderer']::text[],ARRAY['Confusing objects, which carry position metadata, with fixed bed channels.','Assuming an object always plays from one speaker rather than being rendered across many.','Overusing objects for sounds better handled by the bed, wasting object count.']::text[],ARRAY['Panning a discrete effect in a Dolby Atmos mix.','Delivering an object-based master for varied home layouts.','Combining a channel bed with moving objects.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio objects');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '15a316fc-9284-468b-819b-a739768beb95','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='15a316fc-9284-468b-819b-a739768beb95') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='15a316fc-9284-468b-819b-a739768beb95');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d5f3968-86c1-4f5f-882f-a162f795518a','Auditory adaptation','Auditory adaptation is the gradual decline in the perceived loudness or neural response to a steady, unchanging sound during continued exposure. It is a normal, reversible reduction in sensitivity that recovers quickly once the sound stops or changes.','A steady sound seems to fade the longer you hear it. This is auditory adaptation. Your ear and brain respond less to something that does not change. It comes back fast once the sound stops. It is normal, not damage.','It explains why a constant tone or hum seems to recede over time and why the ear responds more strongly to change than to steady stimuli.','Aware of adaptation, a technician takes short breaks and re-checks a static tone or noise floor with fresh ears rather than trusting a judgment made after long, steady exposure.','Auditory Perception',ARRAY['Auditory fatigue','Loudness','Auditory nerve firing','Masking','Temporal integration']::text[],ARRAY['Confusing reversible adaptation with damaging auditory fatigue or a threshold shift.','Trusting a loudness judgment made after long exposure to a steady sound.','Assuming the source got quieter when only perception adapted.']::text[],ARRAY['Judging a steady room hum after minutes of listening.','Re-evaluating a sustained pad after a short break.','Explaining why a constant alarm seems to fade.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory adaptation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d5f3968-86c1-4f5f-882f-a162f795518a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d5f3968-86c1-4f5f-882f-a162f795518a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d5f3968-86c1-4f5f-882f-a162f795518a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e0f7d17-edb7-488d-82db-d0c37f86aa7b','Auditory fatigue','Auditory fatigue is a temporary reduction in hearing sensitivity following exposure to loud sound, measured as a temporary threshold shift that recovers over minutes to hours. Repeated or severe episodes can progress toward permanent, noise-induced hearing loss.','Loud sound can make your hearing dull for a while. This is auditory fatigue, or a temporary threshold shift. It usually recovers with quiet rest. But repeated heavy exposure can turn into permanent loss. Protecting your ears prevents this.','It warns that loud exposure temporarily degrades hearing and serves as an early sign that noise doses are approaching dangerous levels.','A technician noticing dullness and ringing after a loud show treats it as a temporary threshold shift, and manages exposure using limits such as OSHA''s 90 dBA over 8 hours or NIOSH''s 85 dBA recommendation.','Hearing Health',ARRAY['Temporary threshold shift','Age-related high-frequency loss','Auditory adaptation','Noise dose','Hearing protection']::text[],ARRAY['UNSAFE: Ignoring post-show dullness and ringing and returning to loud levels, risking permanent damage.','Treating temporary threshold shift as harmless rather than a warning sign.','Assuming full recovery is guaranteed after any exposure, regardless of level or duration.']::text[],ARRAY['Assessing hearing after a long, loud mixing session.','Setting monitoring levels to stay within a safe daily noise dose.','Deciding when to use hearing protection at a concert.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory fatigue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e0f7d17-edb7-488d-82db-d0c37f86aa7b','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e0f7d17-edb7-488d-82db-d0c37f86aa7b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e0f7d17-edb7-488d-82db-d0c37f86aa7b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08cb80fe-26d6-4871-8744-6f5579f13735','Auditory illusions','Auditory illusions are perceptions in which what is heard differs systematically from the physical stimulus, revealing how the auditory system infers pitch, location, and grouping. Examples include the missing fundamental, the Shepard tone, and Deutsch''s octave and scale illusions.','Sometimes we hear something different from what is really there. These are auditory illusions. For example, a tone can seem to rise forever. Or we hear a low pitch that is not present. They show how the brain builds sound perception.','They expose the rules the brain uses to organize sound, informing both scientific models of hearing and creative sound design.','A technician recognizing the missing-fundamental effect trusts that a small speaker can suggest a bass note from its harmonics, even without reproducing the fundamental itself.','Auditory Perception',ARRAY['Missing fundamental','Binaural beats','Precedence effect','Pitch perception','Auditory scene analysis']::text[],ARRAY['Assuming perception always matches the physical waveform.','Confusing an illusion, which is systematic, with a random mishearing.','Thinking the missing fundamental means the low frequency is physically present.']::text[],ARRAY['Explaining perceived bass on small loudspeakers.','Designing an endlessly rising Shepard-tone effect.','Discussing why headphones can produce different illusions than speakers.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory illusions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08cb80fe-26d6-4871-8744-6f5579f13735','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08cb80fe-26d6-4871-8744-6f5579f13735') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08cb80fe-26d6-4871-8744-6f5579f13735');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1861265d-7e10-4ab4-93cf-bba02751b4fe','Auditory nerve firing','Auditory nerve firing is the generation of electrical action potentials by auditory-nerve fibers in response to cochlear stimulation. Frequency is coded both by which fibers respond (place coding along the tonotopic map) and by the timing of firings, which phase-lock to the waveform up to a few kilohertz.','The ear turns sound into nerve pulses. Each nerve fiber connects to one spot on the cochlea. That spot responds best to one pitch. Fibers also fire in step with low-frequency waves. Together this tells the brain pitch and loudness.','It is the stage where mechanical cochlear motion becomes the neural code the brain uses to represent pitch, timing, and level.','Understanding that phase-locking weakens above a few kHz helps a technician appreciate why timing cues and low-frequency pitch are coded differently from high-frequency content.','Auditory Physiology',ARRAY['Basilar-membrane frequency mapping','Cochlear mechanics','Air conduction','Pitch perception','Tonotopy']::text[],ARRAY['Assuming a single fiber can fire on every cycle of a high-frequency tone; firing rate saturates and cannot follow very fast waves.','Ignoring timing (temporal) cues and treating pitch as purely place-based.','Confusing firing rate with perceived pitch rather than loudness and coding together.']::text[],ARRAY['Explaining how the ear encodes a complex tone.','Discussing limits of temporal pitch coding at high frequencies.','Relating hair-cell motion to neural signals.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory nerve firing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1861265d-7e10-4ab4-93cf-bba02751b4fe','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1861265d-7e10-4ab4-93cf-bba02751b4fe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1861265d-7e10-4ab4-93cf-bba02751b4fe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87dffee3-bc2c-4fc9-ade5-03339447a862','Bandwidth limitation','Bandwidth limitation is the restriction of a signal''s or system''s usable frequency range, whether deliberate, as in band-limiting filters, or unintended, as from component or channel constraints. It sets the lowest and highest frequencies that pass with acceptable level.','Every audio path can only pass a range of pitches well. Bandwidth limitation is the narrowing of that range. Sometimes it is done on purpose with filters. Sometimes gear or a link cannot carry the full range. Either way, the extremes are lost.','It defines how much of the audio spectrum a system carries and is used deliberately to remove out-of-band content or to fit a signal into a channel.','Before sampling, a technician applies an anti-alias low-pass filter to band-limit content below the Nyquist frequency, preventing high frequencies from folding back as aliases.','Signal Fundamentals',ARRAY['Aliasing recognition','Audible frequency range','Low-pass filter','Nyquist frequency','Frequency response']::text[],ARRAY['Assuming a wider bandwidth is always better, ignoring noise and aliasing considerations.','Confusing bandwidth limitation with simple level attenuation.','Forgetting that telephone and codec paths impose their own narrow bandwidth.']::text[],ARRAY['Setting an anti-alias filter before an analog-to-digital converter.','Diagnosing dull sound from a band-limited transmission link.','Choosing a high-pass to remove sub-band rumble.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bandwidth limitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87dffee3-bc2c-4fc9-ade5-03339447a862','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87dffee3-bc2c-4fc9-ade5-03339447a862') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87dffee3-bc2c-4fc9-ade5-03339447a862');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8d2dfc6-c289-438c-95c1-7693318e45b4','Basilar-membrane frequency mapping','Basilar-membrane frequency mapping is the tonotopic arrangement by which each place along the cochlea''s basilar membrane responds best to a particular frequency, high frequencies near the base and low frequencies near the apex. The place-to-frequency relationship for the human cochlea is well described by Greenwood''s function.','The cochlea sorts sound by pitch along its length. High pitches peak near the entrance. Low pitches peak deep inside near the tip. Each spot has its own best pitch. This orderly layout is the frequency map of the ear.','It explains how the ear performs a physical frequency analysis, giving the brain a place code for pitch across the audible range.','Using Greenwood''s function for the human cochlea, the midpoint of the membrane (x = 0.5) maps to about 165.4 × (10^(2.1 × 0.5) − 0.88) ≈ 1.7 kHz.','Auditory Physiology',ARRAY['Cochlear mechanics','Auditory nerve firing','Critical band','Tonotopy','Air conduction']::text[],ARRAY['Reversing the layout: high frequencies map to the base, not the apex.','Treating the map as linear in frequency rather than roughly logarithmic.','Assuming a single place responds to only one exact frequency, ignoring the finite tuning width.']::text[],ARRAY['Explaining place coding of pitch in the cochlea.','Relating cochlear-implant electrode position to pitch.','Understanding why critical bands are wider at high frequencies.']::text[],'Advanced','F = A·(10^(a·x) − k),  with A = 165.4, a = 2.1, k = 0.88','The characteristic frequency at a place equals a constant A times the quantity ten raised to the power of a constant a times the relative distance, minus a constant k. For the human cochlea A is 165.4 hertz, a is 2.1, and k is 0.88.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Basilar-membrane frequency mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8d2dfc6-c289-438c-95c1-7693318e45b4','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8d2dfc6-c289-438c-95c1-7693318e45b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8d2dfc6-c289-438c-95c1-7693318e45b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0bc4f77-7d95-4db3-878f-ddf339bcf536','Bed channels','Bed channels are the fixed, channel-based layer of an immersive mix, such as a 7.1.2 arrangement, over which dynamic audio objects are added. They carry ambience, music, and other content tied to speaker positions rather than to positional metadata.','An immersive mix has two parts. The bed is a set of fixed speaker channels. It holds steady content like ambience and music. On top of the bed sit moving objects. Together they build the full 3D scene.','The bed provides a stable channel-based foundation for immersive content, reserving the flexible object layer for sounds that need to move or be placed precisely.','A technician places crowd ambience and music into a 7.1.2 bed, then adds discrete effects as objects, keeping the object count manageable.','Spatial Audio',ARRAY['Audio objects','Binaural rendering of immersive mixes','Ambisonic decoding','Channel-based audio','Renderer']::text[],ARRAY['Placing moving sounds in the bed, where they cannot follow the listener''s layout as objects would.','Confusing the fixed bed with the flexible object layer.','Assuming the bed alone gives full immersive placement without objects.']::text[],ARRAY['Building a Dolby Atmos mix with a 7.1.2 bed.','Deciding what content belongs in the bed versus objects.','Delivering an immersive master with bed and object layers.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bed channels');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0bc4f77-7d95-4db3-878f-ddf339bcf536','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0bc4f77-7d95-4db3-878f-ddf339bcf536') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0bc4f77-7d95-4db3-878f-ddf339bcf536');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ca76a0e-3aa5-47ae-85ac-d3c09d8ad4b9','Bell radiation','Bell radiation is the emission of sound from the flared bell of a wind or brass instrument, where the widening bore acts as an acoustic horn coupling the internal air column to the surrounding air. The bell raises radiation efficiency and directivity most strongly at high frequencies.','Many wind instruments end in a flared bell. Sound leaves the instrument mainly there. The bell works like a horn. It helps high notes escape and aim outward. Low notes spread more widely and leak from tone holes too.','It explains how the flared end shapes an instrument''s loudness, tone, and directional pattern, especially in the high frequencies.','Knowing the bell beams high frequencies forward, a technician aims a trumpet microphone slightly off the bell axis to tame harshness while keeping brightness.','Instrument Acoustics',ARRAY['Brass directivity','Bore shape','Air-column resonance','Horn loading','Bowing excitation']::text[],ARRAY['Assuming all frequencies radiate equally from the bell; high frequencies are far more directional.','Ignoring that low-frequency sound also escapes from open tone holes, not only the bell.','Miking directly on the bell axis and capturing an overly harsh, bright tone.']::text[],ARRAY['Positioning a microphone on a trumpet or trombone.','Explaining why brass sounds brighter aimed straight at you.','Understanding the horn action of an instrument bell.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bell radiation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ca76a0e-3aa5-47ae-85ac-d3c09d8ad4b9','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ca76a0e-3aa5-47ae-85ac-d3c09d8ad4b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ca76a0e-3aa5-47ae-85ac-d3c09d8ad4b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6a3888e-a340-40a3-80b7-4f2821e2698a','Bell-filter frequency recognition','Bell-filter frequency recognition is the ear-training skill of identifying the center frequency of a bell, or peaking, equalizer boost or cut. A bell filter affects a band of frequencies symmetrically around a center, with width set by its Q.','A bell EQ boosts or cuts a band of pitches. It peaks at a center frequency. This skill is hearing which center frequency is being changed. It helps you reach for the right EQ band quickly. Practice with sweeps builds this skill.','It lets a technician quickly identify and correct problem frequencies by ear when using peaking equalizers.','Hearing a nasal honk on a vocal, a technician recognizes it near 1 kHz and applies a narrow bell cut there rather than sweeping blindly.','Ear Training',ARRAY['Peaking filter','Q factor','Attack and release recognition','Bandwidth limitation','Equalization']::text[],ARRAY['Confusing a bell boost with a shelf, which lifts everything past a corner frequency.','Judging center frequency without accounting for the filter''s Q and width.','Guessing octaves too high or too low because of unfamiliarity with the band.']::text[],ARRAY['Sweeping an EQ to find a resonant honk.','Ear-training drills matching a boost to its frequency.','Correcting a harsh band on a mixed track.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bell-filter frequency recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6a3888e-a340-40a3-80b7-4f2821e2698a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6a3888e-a340-40a3-80b7-4f2821e2698a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6a3888e-a340-40a3-80b7-4f2821e2698a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41dd3c72-a8eb-49b2-9ade-06cc07ab082c','Binaural beats','Binaural beats are a perceived slow fluctuation heard when two tones of slightly different frequency are presented separately, one to each ear. The perceived beat rate equals the frequency difference between the two ears, and the effect is strongest for low carrier frequencies below about 1 kHz.','Play a slightly different tone in each ear. Your brain hears a slow throb. This is a binaural beat. Its speed equals the difference between the two tones. It only works well at low pitches and needs headphones.','It demonstrates that the brain compares timing between the ears, providing evidence for central binaural processing.','Feeding 440 Hz to the left ear and 444 Hz to the right through headphones produces a perceived 4 Hz beat, since 444 − 440 = 4 Hz.','Binaural Hearing',ARRAY['Interaural time difference','Binaural summation','Auditory illusions','Monaural beats','Precedence effect']::text[],ARRAY['Confusing binaural beats, which arise centrally in the brain, with monaural beats from two tones mixed acoustically.','Expecting the effect to work over loudspeakers, where both ears hear both tones.','Assuming binaural beats work well at high carrier frequencies; the effect fades above about 1 kHz.']::text[],ARRAY['Demonstrating central binaural processing in a lab.','Explaining why headphones are required to hear the effect.','Distinguishing binaural from acoustic beating.']::text[],'Intermediate','f_beat = |f_L − f_R|','The perceived binaural beat frequency equals the absolute difference between the tone frequency in the left ear and the tone frequency in the right ear.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural beats');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41dd3c72-a8eb-49b2-9ade-06cc07ab082c','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41dd3c72-a8eb-49b2-9ade-06cc07ab082c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41dd3c72-a8eb-49b2-9ade-06cc07ab082c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21a52485-b055-4d14-8283-2b5cb4026cfb','Binaural rendering of immersive mixes','Binaural rendering of immersive mixes is the process of converting a multichannel or object-based 3D mix into a two-channel signal for headphones, using head-related transfer functions to recreate directional cues. The result aims to place sounds around and above the listener over ordinary stereo headphones.','Immersive mixes use many speakers. Headphones have only two. Binaural rendering folds the 3D mix into two channels. It uses ear-shaped filters called HRTFs. These add the cues that make sounds seem to come from all around you.','It delivers an immersive spatial experience over standard headphones by simulating how sound from each direction reaches the two ears.','A technician auditions a Dolby Atmos mix on headphones through a binaural renderer, checking that overhead and rear objects are convincingly placed before delivery.','Spatial Audio',ARRAY['HRTF','Audio objects','Bed channels','Ambisonic decoding','Interaural time difference']::text[],ARRAY['Assuming a generic HRTF fits every listener; individual ear shapes vary and affect localization.','Confusing binaural rendering with ordinary stereo downmixing, which lacks 3D cues.','Expecting binaural cues to survive when played back over loudspeakers instead of headphones.']::text[],ARRAY['Checking an immersive mix on headphones.','Delivering a binaural version for mobile listeners.','Comparing generic and personalized HRTFs.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural rendering of immersive mixes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21a52485-b055-4d14-8283-2b5cb4026cfb','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21a52485-b055-4d14-8283-2b5cb4026cfb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21a52485-b055-4d14-8283-2b5cb4026cfb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e05f9e9-7ec0-4ab2-9906-0ebecdc62be9','Binaural summation','Binaural summation is the improvement in detection and loudness obtained when a sound is heard with both ears rather than one. Detection thresholds are roughly 3 dB lower binaurally, and a sound presented to both ears is judged about twice as loud as the same sound to one ear.','Two ears hear better than one. A sound is easier to detect with both ears. It also sounds louder. Roughly, the threshold improves by about 3 dB. A sound in both ears seems about twice as loud as in one.','It quantifies the advantage of two-eared listening for sensitivity and loudness, informing monitoring and hearing-test practice.','A technician expects a faint tone to be easier to catch over headphones in both ears than in one, consistent with the roughly 3 dB binaural threshold advantage.','Binaural Hearing',ARRAY['Binaural beats','Loudness','Air conduction','Interaural level difference','Auditory adaptation']::text[],ARRAY['Confusing binaural summation with binaural beats; summation is about loudness and detection, not a perceived throb.','Assuming two ears double the sound pressure rather than improving detection and perceived loudness.','Ignoring binaural summation when comparing mono headphone use to both ears.']::text[],ARRAY['Explaining why both-ear listening reveals faint detail.','Comparing single-ear versus two-ear monitoring.','Discussing loudness perception over headphones.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural summation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e05f9e9-7ec0-4ab2-9906-0ebecdc62be9','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e05f9e9-7ec0-4ab2-9906-0ebecdc62be9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e05f9e9-7ec0-4ab2-9906-0ebecdc62be9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e44d661d-bf02-4bf8-b961-15da3bdc1889','Bone conduction','Bone conduction is the transmission of sound to the cochlea through vibration of the skull bones, bypassing the outer and middle ear. It is used in bone-conduction audiometry and in headsets that place transducers against the skull rather than in the ear canal.','Sound can reach the inner ear through the skull. This is bone conduction. It skips the ear canal and eardrum. It is why your own voice sounds different on a recording. Some headsets use it to leave the ear canal open.','It provides a route to the cochlea that skips the outer and middle ear, useful for diagnosing hearing loss and for open-ear listening devices.','In audiometry a technician places a bone vibrator on the mastoid; if bone-conduction thresholds are normal but air-conduction thresholds are raised, the loss is conductive.','Auditory Pathway',ARRAY['Air conduction','Cochlear mechanics','Sensorineural hearing loss','Conductive hearing loss','Auditory nerve firing']::text[],ARRAY['Assuming bone conduction uses the eardrum; it bypasses the outer and middle ear entirely.','Confusing bone- and air-conduction thresholds when reading an audiogram.','Thinking bone-conduction headsets deliver the same low-frequency power as sealed earphones.']::text[],ARRAY['Performing bone-conduction audiometry.','Explaining why recorded voices sound unfamiliar.','Choosing an open-ear bone-conduction headset.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bone conduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e44d661d-bf02-4bf8-b961-15da3bdc1889','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e44d661d-bf02-4bf8-b961-15da3bdc1889') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e44d661d-bf02-4bf8-b961-15da3bdc1889');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1390d01-bdc7-4098-abf0-3bce5bc06595','Bore shape','Bore shape is the internal cross-sectional profile of a wind instrument''s air column, most often cylindrical or conical. It governs which harmonics the air column supports and how the instrument overblows: a cylindrical tube closed at one end favors odd harmonics and overblows a twelfth, while a conical bore supports the full harmonic series and overblows an octave.','A wind instrument is a tube of air. Its inside can be straight-sided or cone-shaped. This bore shape sets which pitches sound. A clarinet''s straight closed tube jumps a twelfth when overblown. A saxophone''s cone jumps an octave.','It determines an instrument''s harmonic content, register jumps, and tonal character, distinguishing families such as clarinets from saxophones.','Knowing a clarinet''s cylindrical bore overblows a twelfth, a technician understands its wide register gap and why its low register is rich in odd harmonics.','Instrument Acoustics',ARRAY['Air-column resonance','Bell radiation','Bore','Overblowing','Brass directivity']::text[],ARRAY['Assuming all wind instruments overblow at the octave; a cylindrical closed bore overblows a twelfth.','Confusing bore shape effects with reed or mouthpiece differences alone.','Treating a clarinet and saxophone as acoustically alike despite different bores.']::text[],ARRAY['Explaining why a clarinet and saxophone differ in tone and register.','Understanding overblowing intervals on woodwinds.','Relating bore profile to harmonic content.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bore shape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1390d01-bdc7-4098-abf0-3bce5bc06595','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1390d01-bdc7-4098-abf0-3bce5bc06595') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1390d01-bdc7-4098-abf0-3bce5bc06595');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fde5f6b7-e107-4444-aaf1-d329a8406eda','Bowing excitation','Bowing excitation is the stick-slip mechanism by which a bow drives a string into sustained vibration on instruments such as the violin. Friction alternately grips and releases the string, producing the Helmholtz motion that sustains a rich harmonic tone.','A bow makes a string sing by grabbing and slipping. The rosined hair sticks, drags the string, then lets go. This repeats hundreds of times a second. The pattern is called Helmholtz motion. It sustains the note as long as you bow.','It explains how a steady bow stroke converts into sustained string vibration and the characteristic sawtooth-like waveform of bowed strings.','Understanding stick-slip motion, a technician expects bow speed and pressure to change tone and knows scratchy sound signals a breakdown of stable Helmholtz motion.','Instrument Acoustics',ARRAY['Helmholtz motion','String resonance','Bore shape','Bell radiation','Attack and release recognition']::text[],ARRAY['Thinking the bow simply drags the string smoothly rather than gripping and slipping.','Assuming bowed strings vibrate in a simple sine shape rather than a sawtooth-like Helmholtz motion.','Ignoring how bow speed and pressure alter the excitation and tone.']::text[],ARRAY['Explaining how a violin sustains a note.','Diagnosing scratchy bowed-string sound.','Relating bow technique to tone and dynamics.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bowing excitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fde5f6b7-e107-4444-aaf1-d329a8406eda','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fde5f6b7-e107-4444-aaf1-d329a8406eda') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fde5f6b7-e107-4444-aaf1-d329a8406eda');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2ea54e6-ec8f-44d0-8b7f-94af9dd35e79','Brass directivity','Brass directivity describes how a brass instrument radiates sound with a strongly frequency-dependent pattern, low frequencies spreading nearly omnidirectionally and high frequencies beaming forward from the bell. The radiation becomes markedly more directional as frequency rises.','Brass instruments do not spread all pitches evenly. Low notes go everywhere. High notes shoot straight out of the bell. So a trumpet sounds brighter aimed at you. Step off to the side and the tone gets duller.','It explains how a listener''s or microphone''s angle to the bell changes the perceived brightness and level of a brass instrument.','For a bright, present trumpet a technician mics close and near the bell axis; to soften it, moving the mic off-axis reduces the beamed high frequencies.','Instrument Acoustics',ARRAY['Bell radiation','Bore shape','Air-column resonance','Directivity','Off-axis response']::text[],ARRAY['Assuming brass radiates equally in all directions like a point source.','Miking straight on the bell axis and capturing an overly harsh, bright tone.','Ignoring that low frequencies remain nearly omnidirectional while highs beam forward.']::text[],ARRAY['Choosing microphone angle for a trumpet or trombone.','Explaining why brass brightness changes with seating position.','Predicting off-axis tone in a live brass section.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brass directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2ea54e6-ec8f-44d0-8b7f-94af9dd35e79','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2ea54e6-ec8f-44d0-8b7f-94af9dd35e79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2ea54e6-ec8f-44d0-8b7f-94af9dd35e79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57c0fb2a-5028-4f80-b9a7-9d051bbdf8cd','Clipping recognition','Clipping recognition is the ear-training skill of identifying the harsh distortion that occurs when a signal exceeds a system''s maximum level and its peaks are flattened. Clipping adds strong high-order harmonics and, in digital systems, an abrupt, gritty edge.','When a signal is too loud for the gear, its peaks get chopped flat. This is clipping. It adds harsh, gritty distortion. Learning to hear it lets you catch overloads fast. Then you lower the level before damage or ruined takes.','It lets a technician detect level overload by ear and correct gain staging before it degrades the recording or endangers equipment.','Hearing a gritty crackle on loud snare hits, a technician recognizes clipping and lowers the input gain until peaks sit safely below the converter''s maximum.','Artifact Recognition',ARRAY['Aliasing recognition','Codec-artifact recognition','Headroom','Total harmonic distortion','Gain staging']::text[],ARRAY['Confusing clipping distortion with intended overdrive or fuzz effects.','UNSAFE: Ignoring sustained clipping into loudspeakers, whose added high-frequency energy can overheat tweeters.','Assuming a meter that is not pinned means no clipping, when brief peaks can still clip.']::text[],ARRAY['Setting input gain to avoid converter overload.','Diagnosing harsh distortion on loud passages.','Checking a master for inter-sample or peak clipping.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clipping recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57c0fb2a-5028-4f80-b9a7-9d051bbdf8cd','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57c0fb2a-5028-4f80-b9a7-9d051bbdf8cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57c0fb2a-5028-4f80-b9a7-9d051bbdf8cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2b41ac6-34b7-4d8c-ac56-1ab637ea55f1','Cochlear mechanics','Cochlear mechanics is the study of how sound-induced fluid motion sets up a traveling wave along the basilar membrane, peaking at a place determined by frequency. Outer hair cells actively amplify and sharpen this response, giving the cochlea its sensitivity, wide dynamic range, and fine frequency selectivity.','Inside the cochlea, sound makes fluid move. This creates a wave along a coiled membrane. The wave peaks at a spot set by pitch. Tiny outer hair cells boost the motion there. This active step makes hearing sharp and very sensitive.','It explains how the inner ear separates frequencies and achieves its great sensitivity and dynamic range through active amplification.','Knowing outer hair cells provide active gain that loud noise can damage, a technician treats hearing protection as guarding this delicate amplifier, not just the eardrum.','Auditory Physiology',ARRAY['Basilar-membrane frequency mapping','Auditory nerve firing','Air conduction','Critical band','Cochlear amplifier']::text[],ARRAY['Treating the cochlea as a passive filter and ignoring active outer-hair-cell amplification.','Assuming the traveling wave peaks at the same place for all frequencies.','Confusing the mechanical traveling wave with the neural signal in the auditory nerve.']::text[],ARRAY['Explaining how the ear analyzes frequency.','Discussing why loud noise damages outer hair cells.','Relating cochlear tuning to critical bands.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cochlear mechanics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2b41ac6-34b7-4d8c-ac56-1ab637ea55f1','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2b41ac6-34b7-4d8c-ac56-1ab637ea55f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2b41ac6-34b7-4d8c-ac56-1ab637ea55f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d768b36-2e27-44ba-a863-3d6142d40f47','Codec-artifact recognition','Codec-artifact recognition is the ear-training skill of identifying the characteristic distortions introduced by lossy audio compression, such as pre-echo on transients, swirly or watery high frequencies, and loss of stereo width. These artifacts arise when a perceptual codec discards or coarsely quantizes information it models as inaudible.','Lossy files like MP3 throw away some sound to save space. This can leave tell-tale flaws. You may hear swirly highs, a smeared cymbal, or a narrower image. Learning these clues helps you spot low-quality files by ear.','It helps a technician judge encoding quality by ear and catch a low-bitrate or badly encoded file before it reaches a listener.','Hearing a cymbal turn watery and a faint smear before each drum hit, a technician recognizes lossy pre-echo and requests a higher-bitrate or lossless source.','Artifact Recognition',ARRAY['Aliasing recognition','Clipping recognition','ABX testing','Perceptual coding','Masking']::text[],ARRAY['Blaming the monitors or source for artifacts that are baked into a lossy file.','Assuming a high bitrate guarantees no audible artifacts on difficult material.','Confusing normal high-frequency roll-off with codec swirl or smearing.']::text[],ARRAY['Checking whether a delivered file is truly lossless.','Comparing codec quality in an ABX test.','Diagnosing swirly highs on a streamed track.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Codec-artifact recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d768b36-2e27-44ba-a863-3d6142d40f47','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d768b36-2e27-44ba-a863-3d6142d40f47') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d768b36-2e27-44ba-a863-3d6142d40f47');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7a75e7b-4ac4-4e6f-963c-de1b005022f2','Coincident stereo','Coincident stereo is a two-microphone technique in which the capsules are placed as close together as possible, one above the other, so their diaphragms share almost the same point in space. Because arrival times are nearly identical, the stereo image is built from level differences produced by the directional microphone patterns, as in X-Y and Blumlein arrangements.','Coincident stereo puts two microphones at almost the same spot. One sits just above the other. Sound reaches both at the same time. The stereo picture comes from level differences, not timing. X-Y and Blumlein setups work this way.','It creates a stereo image using only level differences between channels, which keeps the recording robust when the two channels are later summed to mono.','A technician sets two cardioid microphones at one point with capsules crossed at about 90 degrees, so louder-side capture places instruments across the stereo field.','Stereo Technique',ARRAY['Blumlein pair','X-Y microphone technique','Fold-down compatibility','Interchannel level difference','Downmixing']::text[],ARRAY['Believing coincident pairs use arrival-time cues; they rely on level differences from the polar patterns.','Spacing the capsules apart, which adds comb filtering and hurts mono compatibility.','Confusing coincident X-Y with near-coincident ORTF, which adds a small time difference.']::text[],ARRAY['Recording a choir where the mix must fold down to mono for broadcast.','Capturing a drum overhead image that stays phase-stable.','Choosing a Blumlein pair for a natural room stereo image.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coincident stereo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7a75e7b-4ac4-4e6f-963c-de1b005022f2','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7a75e7b-4ac4-4e6f-963c-de1b005022f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7a75e7b-4ac4-4e6f-963c-de1b005022f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1de53869-9348-41c3-be71-7d584c2b3d06','Comb-filter identification','Comb-filter identification is the trained listening skill of recognizing the hollow, phasey coloration produced when a signal is summed with a short-delayed copy of itself. The interference creates evenly spaced peaks and notches across frequency, so the ear learns to detect the characteristic tonal signature.','Comb filtering happens when a sound mixes with a slightly delayed copy of itself. This makes a row of peaks and dips in the tone. It sounds hollow, metallic, or phasey. Training your ears to spot this helps you fix it fast.','It lets an engineer hear phase-cancellation coloration by ear so problems from reflections or mixed microphones can be diagnosed quickly.','Hearing a hollow sweep as a source moves, a technician suspects two arrivals and repositions a microphone or applies delay to reduce the notches.','Auditory Training',ARRAY['Comb filter','Early-reflection recognition','Delay identification','Phase cancellation','Coincident stereo']::text[],ARRAY['Mistaking comb-filter coloration for a broken microphone or faulty equalizer.','Assuming a graphic equalizer can fully remove comb filtering; the fix is usually timing or placement.','Overlooking that summing two spaced microphones on one source causes it.']::text[],ARRAY['Diagnosing a hollow vocal from a lavalier reflecting off a script.','Spotting phase issues when blending close and room drum microphones.','Ear-training drills that add a variable short delay to a source.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comb-filter identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1de53869-9348-41c3-be71-7d584c2b3d06','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1de53869-9348-41c3-be71-7d584c2b3d06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1de53869-9348-41c3-be71-7d584c2b3d06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47e8dbfb-0c85-4ef7-b263-dea37cfeba0a','Combination tones','Combination tones are pitches the ear itself generates when two loud tones sound together, arising from nonlinear distortion in the cochlea rather than from energy in the incoming sound. The most audible are the simple difference tone at f2 minus f1 and the cubic difference tone at 2f1 minus f2.','Combination tones are extra pitches your ear creates. They appear when two loud tones play together. They are not in the real sound. The inner ear makes them by adding a little distortion. The most heard one sits at the difference between the two frequencies.','The concept explains phantom pitches heard with loud tone pairs and is evidence that the healthy cochlea behaves nonlinearly.','With f1 = 1000 Hz and f2 = 1200 Hz played loudly, a listener may hear a difference tone at 200 Hz and a cubic difference tone at 800 Hz.','Psychoacoustic Effect',ARRAY['Nonlinearity','Distortion identification','Harmonic excitation','Otoacoustic emissions','Difference tone']::text[],ARRAY['Thinking combination tones are present in the source signal instead of created in the ear.','Confusing them with beats, which are a slow loudness pulsing, not a new pitch.','Assuming they appear at any level; they grow strongly only when the primaries are loud.']::text[],ARRAY['Explaining phantom low pitches heard from loud pure-tone pairs.','Understanding why nonlinear distortion adds sum and difference products.','Teaching the cochlea''s nonlinear response in a hearing-science module.']::text[],'Advanced','f_diff = f2 - f1 ;  f_cubic = 2*f1 - f2','The difference tone equals the higher frequency minus the lower. The cubic difference tone equals twice the lower frequency minus the higher.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Combination tones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47e8dbfb-0c85-4ef7-b263-dea37cfeba0a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47e8dbfb-0c85-4ef7-b263-dea37cfeba0a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47e8dbfb-0c85-4ef7-b263-dea37cfeba0a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'afe2e922-ee45-4134-b061-a8ea4af3b218','Compression identification','Compression identification is the trained ability to hear when dynamic-range compression is acting on a signal and to judge how hard it is working. Cues include reduced dynamic contrast, audible gain movement or ''pumping'', changed attack transients, and a raised, denser noise or ambience floor.','Compression identification means hearing when a compressor is working. You notice the loud and soft parts get closer together. You may hear pumping as the level breathes. Attacks can soften and the background can rise. Trained ears judge how much is applied.','It helps an engineer set and verify compression by ear, and to reverse-engineer processing already applied to a source.','Hearing the room ambience surge up between vocal phrases, a technician recognizes heavy compression and eases the ratio or raises the threshold.','Auditory Training',ARRAY['Dynamic range compression','Attack and release','Distortion identification','Pumping','Makeup gain']::text[],ARRAY['Judging compression only by loudness while ignoring transient and ambience changes.','Confusing pumping from compression with a noise problem in the signal chain.','Assuming more compression always sounds louder rather than denser and flatter.']::text[],ARRAY['Matching a mix''s compression to a reference track by ear.','Detecting over-compression on a broadcast feed.','Ear-training tasks comparing bypassed and compressed versions.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'afe2e922-ee45-4134-b061-a8ea4af3b218','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='afe2e922-ee45-4134-b061-a8ea4af3b218') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='afe2e922-ee45-4134-b061-a8ea4af3b218');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba26c681-ec14-42ae-af97-3f05d4813ee4','Controlled listening-test design','Controlled listening-test design is the planning of subjective audio evaluations so that results reflect real perceptual differences rather than bias or chance. It specifies matched levels, blinding, randomized presentation order, hidden references and anchors, enough trials for statistics, and a defined rating scale, following recommendations such as ITU-R BS.1116 and BS.1534.','Controlled listening-test design plans a fair hearing test. Levels are matched so nothing seems louder by accident. Listeners do not know which sample is which. The order is shuffled. Enough trials are run for real statistics. Standards give the rules.','It exists to make subjective sound-quality judgments trustworthy and repeatable by removing bias and controlling every variable except the one under test.','A technician level-matches two codecs, hides the reference, randomizes trials, and collects enough ratings to test whether a preference is statistically real.','Test Methodology',ARRAY['Double-blind testing','Expectation bias','Level matching','MUSHRA','Hidden reference and anchor']::text[],ARRAY['Skipping level matching, so the louder sample is wrongly judged better.','Running too few trials to reach any statistical significance.','Letting listeners know which system is ''the good one'' before rating.']::text[],ARRAY['Evaluating a lossy codec against the original for quality loss.','Comparing two microphones without listeners knowing the brands.','Designing a MUSHRA session with hidden reference and anchors.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Controlled listening-test design');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba26c681-ec14-42ae-af97-3f05d4813ee4','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba26c681-ec14-42ae-af97-3f05d4813ee4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba26c681-ec14-42ae-af97-3f05d4813ee4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10b494e2-3b97-48e9-b324-517af107c536','Coupled drumheads','Coupled drumheads describes a two-headed drum in which the top (batter) and bottom (resonant) membranes are joined by the enclosed air and shell, so they vibrate as a linked system. The coupling splits modes into pairs and adds air-cavity resonance, shaping pitch, sustain, and tone beyond that of a single head.','Many drums have two heads, one you hit and one underneath. The air inside the shell links them. So the two heads move as one connected system. This coupling changes the pitch, sustain, and tone. Tuning both heads sets the sound.','It explains why a two-headed drum''s pitch, decay, and timbre depend on both heads and the trapped air, not just the struck head.','A technician tunes the resonant head relative to the batter head to lengthen or shorten sustain and control the note the coupled system produces.','Musical Acoustics',ARRAY['Drumhead overtones','Helmholtz resonance','Membrane modes','Sympathetic resonance']::text[],ARRAY['Tuning only the batter head and ignoring the resonant head''s effect on sustain.','Assuming the enclosed air plays no part in the drum''s pitch.','Expecting each head to ring at its own single frequency independently.']::text[],ARRAY['Tuning a tom''s two heads for a defined pitch and decay.','Explaining why removing the bottom head changes tone and sustain.','Studying air-coupled modes in a drum for acoustics coursework.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coupled drumheads');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10b494e2-3b97-48e9-b324-517af107c536','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10b494e2-3b97-48e9-b324-517af107c536') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10b494e2-3b97-48e9-b324-517af107c536');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba1a373f-4b3d-4dc5-bec8-ece2c2254cbb','Cylindrical versus conical bores','Cylindrical versus conical bores contrasts the two main wind-instrument tube shapes. A cylindrical tube closed at one end (like a clarinet) resonates mainly at odd harmonics and sounds an octave lower than an open tube of the same length, whereas a conical tube (like an oboe or saxophone) supports the full harmonic series and behaves like an open pipe.','Wind instruments use two tube shapes. A straight (cylindrical) tube closed at one end favours odd harmonics. It also plays about an octave lower than an open tube. A cone-shaped (conical) tube gives the full set of harmonics. This is why a clarinet and a saxophone sound different.','It explains why bore shape sets an instrument''s harmonic content, register, and how it overblows, which is fundamental to woodwind acoustics.','For a clarinet-like tube of length 0.30 m with sound speed 343 m/s, the fundamental is about 343 / (4 x 0.30) = 286 Hz, and the next resonance is near the third harmonic, not the second.','Musical Acoustics',ARRAY['End correction','Formants in musical instruments','Harmonic excitation','Overblowing','Standing wave']::text[],ARRAY['Thinking a clarinet overblows to the octave; a cylindrical closed tube overblows to the twelfth.','Treating a conical bore like a closed cylinder instead of an open pipe.','Forgetting to add the end correction to the physical tube length.']::text[],ARRAY['Explaining why a clarinet is weak in even harmonics.','Comparing register jumps on a saxophone versus a clarinet.','Estimating a woodwind''s fundamental from its bore length.']::text[],'Advanced','closed-cylindrical: f_n = (2n - 1) * c / (4L)   ;   open/conical: f_n = n * c / (2L)','For a cylinder closed at one end, resonant frequencies are odd multiples of the speed of sound divided by four times the length. For an open or conical tube, they are whole multiples of the speed of sound divided by twice the length.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cylindrical versus conical bores');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba1a373f-4b3d-4dc5-bec8-ece2c2254cbb','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba1a373f-4b3d-4dc5-bec8-ece2c2254cbb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba1a373f-4b3d-4dc5-bec8-ece2c2254cbb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7bdcb880-ee4f-4142-b92e-e9b9df95382c','Cymbal modes','Cymbal modes are the many closely spaced natural vibration patterns of a thin, curved metal plate. Because these modes are dense and strongly inharmonic, and because a struck cymbal shows nonlinear, near-chaotic energy spread from low to high modes, a cymbal produces a bright, shimmering crash with no single clear pitch.','A cymbal is a thin curved metal plate. It can vibrate in a great many patterns at once. These patterns are packed close together and are not tuned to each other. So a cymbal has a shimmering wash of sound. It has no single clear note.','The idea explains why cymbals sound pitchless and shimmering, and why their energy builds up into the high frequencies after a strike.','Knowing high modes dominate the shimmer, a technician places a bright condenser overhead and controls harshness with high-frequency equalization rather than a narrow notch.','Musical Acoustics',ARRAY['Inharmonicity','Plate modes','Nonlinearity','Overtones']::text[],ARRAY['Trying to tune a cymbal to a musical pitch as if it were a drum or bar.','Assuming cymbal partials are harmonic multiples of a fundamental.','Ignoring that nonlinear behaviour spreads energy upward in frequency over time.']::text[],ARRAY['Choosing microphones and equalization for cymbal shimmer.','Explaining why cymbals lack a definite pitch.','Studying nonlinear plate vibration in acoustics coursework.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cymbal modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7bdcb880-ee4f-4142-b92e-e9b9df95382c','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7bdcb880-ee4f-4142-b92e-e9b9df95382c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7bdcb880-ee4f-4142-b92e-e9b9df95382c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90825fda-b086-47c7-81fa-6db39fdf7a65','Delay identification','Delay identification is the trained skill of hearing that a delay effect is present and estimating its time and feedback. Short delays under a few milliseconds fuse with the source and colour its tone, while longer delays are heard as separate slap or repeating echoes.','Delay identification means hearing an echo effect and judging its timing. Very short delays blend in and change the tone. Longer delays sound like a slap or repeats. Trained ears estimate the delay time and how many repeats there are.','It lets an engineer detect and quantify delay by ear, whether as an intended effect or an accidental timing error in a signal path.','Hearing a single crisp echo after a snare, a technician taps the tempo and estimates the delay near 120 milliseconds, then matches or removes it.','Auditory Training',ARRAY['Precedence effect','Comb-filter identification','Early-reflection recognition','Slapback echo','Latency']::text[],ARRAY['Confusing very short delay coloration with equalization rather than timing.','Assuming any audible echo is reverb rather than a discrete delay.','Ignoring that repeats reveal the feedback amount, not just the delay time.']::text[],ARRAY['Detecting monitor latency in an in-ear mix.','Estimating a slapback delay time on a vocal.','Ear-training drills with adjustable delay and feedback.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90825fda-b086-47c7-81fa-6db39fdf7a65','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90825fda-b086-47c7-81fa-6db39fdf7a65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90825fda-b086-47c7-81fa-6db39fdf7a65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '05c7e805-5dfa-4353-9864-2126f73acddd','Depth recognition','Depth recognition is the perception of how far away a sound source is. Cues include overall loudness, the ratio of direct to reverberant energy, loss of high frequencies from air absorption over distance, and reduced clarity of early detail, which together place a source near or far in a mix or room.','Depth recognition is judging how far away a sound is. Quieter usually means farther. More room reverb compared to direct sound means farther. Distant sounds also lose some high frequencies. Together these cues set the sense of distance.','It underlies the sense of front-to-back distance in listening, letting engineers place sources at believable depths in a mix.','To push a backing vocal back, a technician lowers its level, adds reverb to raise the reverberant share, and gently rolls off the extreme highs.','Spatial Perception',ARRAY['Direct-to-reverberant balance','Air absorption','Reverberation','Loudness']::text[],ARRAY['Using level alone for distance while ignoring the direct-to-reverberant ratio.','Confusing depth (front-to-back) with lateral pan position.','Forgetting that high-frequency loss is a strong distance cue outdoors.']::text[],ARRAY['Layering a mix so lead and backing vocals sit at different depths.','Judging how far a talker is in a room recording.','Designing distance cues for an immersive audio scene.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Depth recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '05c7e805-5dfa-4353-9864-2126f73acddd','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='05c7e805-5dfa-4353-9864-2126f73acddd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='05c7e805-5dfa-4353-9864-2126f73acddd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca2890eb-a6ad-42e7-9076-030392a7c0a8','Diplacusis','Diplacusis is a pitch-perception anomaly in which the same tone is heard at a different pitch by each ear, so a single note can seem doubled or out of tune. The most common form, diplacusis binauralis, usually accompanies asymmetric cochlear damage or hearing loss in one ear.','Diplacusis means the two ears hear the same tone at slightly different pitches. One note can seem doubled or out of tune. It often follows damage or hearing loss in one ear. Musicians may notice it most on sustained notes.','The term names a hearing disorder that engineers and musicians should recognize as a personal perceptual issue, not a fault in the equipment.','A technician who hears a steady tone as two slightly different pitches between ears should suspect diplacusis and seek an audiological check rather than retuning gear.','Auditory Physiology',ARRAY['Pitch perception','Cochlear damage','Tinnitus','Hearing loss']::text[],ARRAY['Blaming equipment tuning for what is a personal hearing anomaly.','Confusing diplacusis with tinnitus, which is a phantom sound rather than a pitch shift.','Assuming it always affects both ears equally.']::text[],ARRAY['A mix engineer noticing a sustained tone sounds doubled between ears.','An audiologist explaining a musician''s pitch complaint.','Recognizing a perceptual symptom of asymmetric hearing loss.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diplacusis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca2890eb-a6ad-42e7-9076-030392a7c0a8','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca2890eb-a6ad-42e7-9076-030392a7c0a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca2890eb-a6ad-42e7-9076-030392a7c0a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eae227c6-f30b-4401-b636-a6e9efff870e','Direct-to-reverberant balance','Direct-to-reverberant balance is the ratio of energy arriving straight from a source to the energy arriving as reverberation. Expressed in decibels, it is a primary cue for perceived distance and clarity, with a high ratio sounding close and dry and a low ratio sounding distant and diffuse.','This is the balance between direct sound and room reverb. More direct sound makes a source seem close and clear. More reverb makes it seem far and washed out. Engineers set this balance to control distance and clarity.','It quantifies the main perceptual cue for source distance and clarity, guiding microphone distance and reverb levels in a mix.','If the direct sound carries 1.0 units of energy and the reverberation 0.25 units, the ratio is 10 x log10(1.0 / 0.25) = about +6 dB, a fairly close, clear sound.','Spatial Perception',ARRAY['Depth recognition','Reverberation','Critical distance','Early-reflection recognition','Clarity (C50/C80)']::text[],ARRAY['Confusing the direct-to-reverberant ratio with the room''s reverberation time.','Adding reverb level without noticing it lowers the ratio and pushes sources back.','Assuming closer microphone placement changes only level, not the ratio.']::text[],ARRAY['Setting microphone distance to control how close a source feels.','Balancing dry signal against a reverb return for depth.','Explaining why a distant talker sounds unclear in a live room.']::text[],'Intermediate','DRR (dB) = 10 * log10( E_direct / E_reverb )','The direct-to-reverberant ratio in decibels equals ten times the base-ten logarithm of the direct sound energy divided by the reverberant sound energy.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direct-to-reverberant balance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eae227c6-f30b-4401-b636-a6e9efff870e','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eae227c6-f30b-4401-b636-a6e9efff870e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eae227c6-f30b-4401-b636-a6e9efff870e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b164cc96-ff06-40f5-bf84-47f0b2d581be','Distance-based amplitude panning','Distance-based amplitude panning (DBAP) is a multi-loudspeaker panning method that sets each speaker''s gain from the distance between that speaker and a virtual source position, regardless of the listener''s location. Gains fall off with distance and are normalized so the total radiated power stays constant, making it well suited to irregular speaker layouts and installations.','DBAP is a way to place a sound across many speakers. It sets each speaker''s level from how far it sits from the target spot. Nearer speakers play louder. The levels are scaled so the total power stays the same. It works even with speakers in odd positions.','It lets sound be positioned over arbitrary, non-standard speaker arrays without assuming a single central listening spot, common in installations and spatial art.','With two speakers equally distant from the virtual source and rolloff a = 1, each gets gain k / d, and normalization gives about 0.707 to each so their powers sum to one.','Spatial Audio',ARRAY['Vector base amplitude panning','Amplitude panning','Downmixing','Elevation channels','Panning law']::text[],ARRAY['Assuming DBAP needs a symmetric speaker layout; its strength is handling irregular arrays.','Forgetting the normalization step, so total loudness changes as the source moves.','Confusing DBAP with VBAP, which uses direction from a central listener, not distance.']::text[],ARRAY['Panning a source across an irregular gallery speaker installation.','Spatializing sound in a venue with no single sweet spot.','Programming an interactive spatial-audio artwork.']::text[],'Advanced','g_i = k / d_i^a ,   with   k = 1 / sqrt( sum_j ( 1 / d_j^(2a) ) )','Each speaker gain equals a normalization constant divided by its distance to the virtual source raised to the rolloff power. The constant is one over the square root of the sum, over all speakers, of one divided by each distance raised to twice the rolloff power.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distance-based amplitude panning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b164cc96-ff06-40f5-bf84-47f0b2d581be','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b164cc96-ff06-40f5-bf84-47f0b2d581be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b164cc96-ff06-40f5-bf84-47f0b2d581be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '477adec9-7205-4866-a73d-7a63512ca66c','Distortion identification','Distortion identification is the trained skill of hearing nonlinear distortion in a signal and telling its type and cause. Cues include added harmonics and gritty or fuzzy texture from clipping, intermodulation roughness on complex material, and level-dependent onset that reveals a gain stage driven too hard.','Distortion identification means hearing distortion and naming its cause. Clipping adds harshness and grit. Complex sounds can turn rough from intermodulation. Distortion that grows with level points to a stage driven too hard. Trained ears spot which stage is the problem.','It helps an engineer detect and locate nonlinear distortion by ear so a gain-staging or device fault can be corrected before it spoils a recording.','Hearing grit appear only on loud peaks, a technician traces it to an overdriven preamp input and lowers gain to keep peaks below clipping.','Auditory Training',ARRAY['Clipping','Total harmonic distortion','Intermodulation distortion','Combination tones','Gain staging']::text[],ARRAY['Blaming the loudspeaker when the distortion started earlier in the chain.','Confusing intended harmonic saturation with a fault.','Assuming all distortion is clipping and ignoring intermodulation products.']::text[],ARRAY['Locating an overdriven gain stage in a signal path.','Judging whether saturation is musical or a defect.','Ear-training drills comparing clean and distorted versions.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '477adec9-7205-4866-a73d-7a63512ca66c','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='477adec9-7205-4866-a73d-7a63512ca66c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='477adec9-7205-4866-a73d-7a63512ca66c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '78d52f7c-4de7-495c-ac17-590399f37786','Double-blind testing','Double-blind testing is an evaluation method in which neither the listener nor the person running the test knows which item is being presented during each trial. Hiding the identity of sources removes conscious and unconscious bias, so any measured preference reflects audible differences rather than expectation.','In a double-blind test, the listener does not know which sample is which. The person running it does not know either, in the moment. This hides all labels and prices. So the results show real hearing, not expectation. It is the fair way to compare gear.','It exists to strip bias out of subjective audio comparisons so that reported differences can be trusted as genuinely audible.','To test whether a cable is audible, a technician level-matches the options and uses a blind switch box so neither party knows which is playing on each trial.','Test Methodology',ARRAY['Controlled listening-test design','Expectation bias','ABX testing','Level matching','Hidden reference and anchor']::text[],ARRAY['Calling a test ''double-blind'' when the operator still knows and can cue the listener.','Skipping level matching, which lets a loudness difference masquerade as quality.','Confusing single-blind (listener only) with true double-blind.']::text[],ARRAY['Comparing two amplifiers without the listener seeing the brands.','Running an ABX test on a codec setting.','Removing bias from a monitor-speaker shootout.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Double-blind testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '78d52f7c-4de7-495c-ac17-590399f37786','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='78d52f7c-4de7-495c-ac17-590399f37786') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='78d52f7c-4de7-495c-ac17-590399f37786');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7564b8f-7047-4752-a60e-4cae95434d71','Downmixing','Downmixing is the process of combining a multichannel audio program into fewer channels, such as 5.1 to stereo, using defined summing coefficients. Standard schemes attenuate the center and surround channels (commonly by about 3 dB, a factor of 0.707) as they are folded into left and right so the summed result keeps a sensible balance and level.','Downmixing folds many channels into fewer. A common case is 5.1 surround down to two-channel stereo. The center and surround channels are lowered as they mix in. A drop of about 3 dB is typical. This keeps the stereo balance and loudness sensible.','It lets one multichannel master play correctly on systems with fewer speakers, ensuring surround content still works in stereo or mono.','A common 5.1 stereo downmix is Lo = L + 0.707*C + 0.707*Ls, so the center and left-surround feeds enter the left channel about 3 dB down.','Multichannel Audio',ARRAY['Fold-down compatibility','Multichannel stereo','Lo/Ro and Lt/Rt','Surround sound','Distance-based amplitude panning']::text[],ARRAY['Summing channels at full level, which overloads and unbalances the downmix.','Ignoring that different standards define different downmix coefficients.','Confusing an Lo/Ro stereo downmix with a matrix-encoded Lt/Rt for surround decoding.']::text[],ARRAY['Folding a 5.1 film mix to stereo for a laptop.','Checking a surround master''s mono compatibility.','Setting downmix coefficients in an encoder.']::text[],'Intermediate','Lo = L + k*C + k*Ls ;  Ro = R + k*C + k*Rs ;  k ~ 0.707 (-3 dB)','Left downmix output equals left plus the center and left-surround channels each scaled by about zero point seven-zero-seven. The right output is formed the same way from right, center, and right-surround.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Downmixing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7564b8f-7047-4752-a60e-4cae95434d71','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7564b8f-7047-4752-a60e-4cae95434d71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7564b8f-7047-4752-a60e-4cae95434d71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b81ffe1b-3ba1-4349-be7f-5133b4b08d04','Drumhead overtones','Drumhead overtones are the higher vibration modes of a circular membrane under tension. Their frequencies follow the zeros of Bessel functions rather than a whole-number harmonic series, so an ideal drumhead''s overtones are inharmonic; on real drums, air loading and the shell shift some modes toward more pitched relationships.','A drumhead can vibrate in many patterns above its lowest one. These overtones are not simple whole-number multiples. Their spacing follows Bessel-function math, so they sound inharmonic. Air inside the drum can pull some modes closer to a musical set. This is why drums are only loosely pitched.','It explains why a stretched membrane sounds inharmonic and only loosely pitched, and how tuning and loading shape a drum''s tone.','For a membrane of radius 0.15 m, tension 4000 N/m, and areal density 0.26 kg/m^2, the fundamental is about (2.405 / (2*pi*0.15)) * sqrt(4000/0.26) = about 316 Hz.','Musical Acoustics',ARRAY['Membrane modes','Coupled drumheads','Inharmonicity','Bessel function','Overtones']::text[],ARRAY['Assuming drumhead overtones are harmonic multiples like a string''s.','Ignoring that air loading in a real drum shifts the mode ratios.','Treating the (0,1) fundamental as if it fully defines the drum''s pitch.']::text[],ARRAY['Tuning a tom to emphasize a chosen mode relationship.','Explaining why drums are inharmonic in an acoustics class.','Predicting a drumhead''s fundamental from tension and size.']::text[],'Advanced','f_mn = ( alpha_mn / (2*pi*a) ) * sqrt( T / sigma )','A mode frequency equals its Bessel zero divided by two pi times the membrane radius, multiplied by the square root of the tension per unit length divided by the areal density.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Drumhead overtones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b81ffe1b-3ba1-4349-be7f-5133b4b08d04','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b81ffe1b-3ba1-4349-be7f-5133b4b08d04') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b81ffe1b-3ba1-4349-be7f-5133b4b08d04');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c83e0bf-57a0-4915-94e3-57081c938069','Early-reflection recognition','Early-reflection recognition is the trained skill of hearing the first strong reflections that arrive within roughly the first 50 to 80 milliseconds after the direct sound. These early reflections are not heard as separate echoes but fuse with the direct sound, adding coloration, apparent size, and a sense of the room''s surfaces.','Early reflections are the first bounces off nearby surfaces. They arrive within about the first fifty to eighty milliseconds. You do not hear them as separate echoes. They blend with the direct sound. They add color and a sense of room size.','It lets an engineer hear and manage the early reflections that shape tonal color, clarity, and perceived space in rooms and mixes.','Hearing a hard early reflection colour a vocal, a technician adds absorption at the first-reflection point on the wall or moves the source away from it.','Auditory Training',ARRAY['Precedence effect','Comb-filter identification','Direct-to-reverberant balance','Reverberation','Reflection point']::text[],ARRAY['Expecting early reflections to sound like distinct echoes instead of fused coloration.','Confusing early-reflection color with an equalization problem.','Overlooking that first-reflection points on nearby surfaces cause them.']::text[],ARRAY['Treating first-reflection points in a control room.','Judging how a room colors a close-miked source.','Ear-training tasks that vary early-reflection level and timing.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Early-reflection recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c83e0bf-57a0-4915-94e3-57081c938069','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c83e0bf-57a0-4915-94e3-57081c938069') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c83e0bf-57a0-4915-94e3-57081c938069');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '170a3c9a-3c5f-44d8-ba33-936f9dd3d11c','Elevation channels','Elevation channels are loudspeaker feeds placed above the listener''s ear-level plane in immersive audio systems, adding a height dimension to horizontal surround. Standards such as ITU-R BS.2051 define layouts (for example 7.1.4, where the ''.4'' denotes four height speakers) that use these upper channels to convey overhead and raised images.','Elevation channels are speaker feeds placed above your ears. They add height to normal surround sound. A layout like 7.1.4 has four of them up high. They carry sounds that seem overhead or raised. Immersive formats use them for a dome of sound.','They add a vertical dimension to surround reproduction, letting engineers place and move sounds above the listener in immersive formats.','Mixing in 7.1.4, a technician routes rain and flyover effects to the four ceiling-level height speakers to lift those images above the listener.','Immersive Audio',ARRAY['Elevation perception','Height channels','Immersive audio','Downmixing','Distance-based amplitude panning']::text[],ARRAY['Reading the ''.4'' in 7.1.4 as subwoofers rather than height speakers.','Assuming height images work without physical or virtualized elevation channels.','Confusing bed channels at ear level with the added elevation channels.']::text[],ARRAY['Setting up a 7.1.4 immersive monitoring room.','Routing overhead effects in an object-based mix.','Explaining a Dolby Atmos speaker layout to a client.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Elevation channels');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '170a3c9a-3c5f-44d8-ba33-936f9dd3d11c','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='170a3c9a-3c5f-44d8-ba33-936f9dd3d11c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='170a3c9a-3c5f-44d8-ba33-936f9dd3d11c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9a0ec24-bd3e-4e87-aa49-82b02b52a651','Elevation perception','Elevation perception is the hearing system''s ability to judge a source''s height, above, at, or below ear level. Because the two ears give little time or level difference for sources on the vertical median plane, elevation is judged mainly from direction-dependent spectral cues created by the pinna, and is aided by head movement.','Elevation perception is judging how high or low a sound is. Left-right timing and level cues barely change with height. Instead, the outer ear (pinna) filters the sound differently by angle. The brain reads these spectral clues to sense height. Moving the head helps too.','It explains how listeners locate sources in the vertical plane, which is central to height channels and binaural rendering.','To place a sound overhead in binaural audio, a technician applies a head-related transfer function whose pinna-shaped spectral notches match that elevation.','Spatial Perception',ARRAY['Head-related transfer function','Pinna cues','Front-back confusion','Elevation channels','Median plane']::text[],ARRAY['Thinking interaural time and level differences set elevation; they mainly set left-right.','Ignoring the pinna''s spectral notches, the key height cue.','Assuming generic ear filters give everyone equally good height perception.']::text[],ARRAY['Rendering height in binaural headphone audio.','Explaining why height is harder to localize than left-right.','Designing personalized head-related transfer functions.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Elevation perception');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9a0ec24-bd3e-4e87-aa49-82b02b52a651','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9a0ec24-bd3e-4e87-aa49-82b02b52a651') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9a0ec24-bd3e-4e87-aa49-82b02b52a651');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20405245-6490-4724-b1c6-23bc4935ad9a','End correction','End correction is the small added length that makes an air column behave acoustically longer than its physical tube, because the vibrating air extends slightly beyond an open end. For a tube of radius a, the correction is about 0.61a at an unflanged open end and about 0.85a at a flanged one, and it lowers the resonant frequencies accordingly.','Air keeps moving a little past the open end of a pipe. This makes the pipe act longer than it really is. The extra length is the end correction. It is roughly 0.61 times the radius at a plain open end. This lowers the pipe''s resonant pitch.','It corrects resonance calculations for real pipes and wind instruments so predicted pitches match measured ones.','For an unflanged tube of radius 0.01 m, the end correction is about 0.61 x 0.01 = 0.0061 m, added to the physical length before computing resonance.','Musical Acoustics',ARRAY['Cylindrical versus conical bores','Standing wave','Resonant frequency','Open pipe','Effective length']::text[],ARRAY['Using the physical length only, which predicts a slightly high resonance.','Adding one correction to a tube that has two open ends.','Using the unflanged value at a flanged (baffled) opening, or vice versa.']::text[],ARRAY['Predicting a flute or organ pipe''s pitch accurately.','Designing a port length for a loudspeaker enclosure.','Explaining why a pipe sounds slightly flat of the simple length prediction.']::text[],'Advanced','L_eff = L + delta ,   delta ~ 0.61*a (unflanged)   or   delta ~ 0.85*a = (8/(3*pi))*a (flanged)','The effective acoustic length equals the physical length plus an end correction. The correction is about zero point six one times the radius for a plain open end, and about zero point eight five times the radius for a flanged end.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='End correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20405245-6490-4724-b1c6-23bc4935ad9a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20405245-6490-4724-b1c6-23bc4935ad9a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20405245-6490-4724-b1c6-23bc4935ad9a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e14cfc87-6b86-4802-a4e0-99e51c6af8b2','Expectation bias','Expectation bias is the tendency for a listener''s prior beliefs, such as knowing a device''s price, brand, or that a change was made, to shape what they report hearing. It can create audible-seeming differences that vanish under blind conditions, and is a principal reason sighted audio comparisons are unreliable.','Expectation bias is hearing what you expect to hear. Knowing the price or brand colors your judgment. A change you were told about can seem to help even when it does nothing. Blind tests remove this bias. That is why sighted listening is unreliable.','Naming this bias explains why controlled, blind procedures are needed before any claimed audible difference can be trusted.','To avoid it, a technician evaluating a plugin hides which setting is active and level-matches them, so the choice reflects sound rather than the label.','Test Methodology',ARRAY['Double-blind testing','Controlled listening-test design','Placebo effect','Confirmation bias','Level matching']::text[],ARRAY['Trusting a sighted A/B comparison as proof of an audible difference.','Assuming trained ears are immune to expectation bias.','Overlooking that a louder or newer option is favored for reasons other than quality.']::text[],ARRAY['Explaining why a costly cable ''sounds better'' when its brand is known.','Justifying blind procedures in a monitor shootout.','Reviewing marketing claims of audible improvement.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Expectation bias');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e14cfc87-6b86-4802-a4e0-99e51c6af8b2','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e14cfc87-6b86-4802-a4e0-99e51c6af8b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e14cfc87-6b86-4802-a4e0-99e51c6af8b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b16da03-8845-4aa3-867a-0ecfe9ad0845','Fold-down compatibility','Fold-down compatibility is the property of a multichannel or stereo program that it still sounds correct when combined into fewer channels, such as stereo to mono or surround to stereo. It depends on phase relationships and downmix coefficients, since out-of-phase content can partly cancel and shift balances when channels are summed.','Fold-down compatibility means a mix still works with fewer channels. Surround should fold to stereo without losing key sounds. Stereo should fold to mono without cancellation. Out-of-phase parts can disappear when channels sum. Good mixes check this before release.','It ensures content made for many channels still plays acceptably on stereo or mono systems, protecting the mix across playback devices.','A technician monitors the mono sum of a stereo mix and finds a widened, out-of-phase synth nearly disappears, then narrows it to restore fold-down balance.','Multichannel Audio',ARRAY['Downmixing','Mono compatibility','Phase cancellation','Coincident stereo','Multichannel stereo']::text[],ARRAY['Never checking the mono or stereo fold-down before delivery.','Using heavy out-of-phase widening that cancels in the fold-down.','Assuming a good surround mix automatically folds down well.']::text[],ARRAY['Checking a broadcast mix that may be heard in mono.','Verifying a surround film mix folds to stereo cleanly.','Testing a widened stereo master for mono cancellation.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fold-down compatibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b16da03-8845-4aa3-867a-0ecfe9ad0845','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b16da03-8845-4aa3-867a-0ecfe9ad0845') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b16da03-8845-4aa3-867a-0ecfe9ad0845');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2ea8b23-31d4-4d0e-a2c1-e9b8080a01d5','Formants in musical instruments','Formants in musical instruments are fixed resonance peaks in an instrument''s frequency response that emphasize certain frequency bands regardless of the note being played. Set by the body, air cavity, or bore rather than by pitch, these stable peaks give an instrument its recognizable timbre, much as vocal-tract formants define vowels.','A formant is a fixed emphasized band of frequencies. It stays in the same place whatever note is played. The instrument''s body or air cavity creates it. These stable peaks give each instrument its own tone color. Voices use formants to make vowels the same way.','The concept explains why an instrument keeps a recognizable tone color across its range, because its resonances, not the played pitch, shape the spectrum.','Knowing a violin''s body formants sit in the low kilohertz, a technician boosts that band gently to add character rather than sweeping arbitrarily.','Musical Acoustics',ARRAY['Formant','Timbre','Resonance','Cylindrical versus conical bores','Harmonic excitation']::text[],ARRAY['Thinking formants move with the played note; they stay at fixed frequencies.','Confusing a formant (a resonance band) with a single harmonic partial.','Assuming timbre comes only from harmonic amplitudes, ignoring body resonances.']::text[],ARRAY['Equalizing to flatter an instrument''s natural formant region.','Explaining why different violins have distinct tone.','Comparing instrument and vocal-tract formants in a timbre lesson.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formants in musical instruments');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2ea8b23-31d4-4d0e-a2c1-e9b8080a01d5','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2ea8b23-31d4-4d0e-a2c1-e9b8080a01d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2ea8b23-31d4-4d0e-a2c1-e9b8080a01d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'defcd2d7-874d-45db-a499-208157af09bb','Frequency identification','Frequency identification is the trained skill of hearing a tone or a boosted band and naming its approximate frequency. Engineers develop it through practice so they can quickly point to problem regions, such as an 800 Hz boxiness or a 3 kHz harshness, and reach for the right equalizer band.','Frequency identification is naming the pitch or band you hear. A trained engineer hears harshness and thinks around three kilohertz. They hear boxiness and think a few hundred hertz. This skill speeds up equalizing. It comes from ear-training practice.','It lets an engineer translate a heard tonal problem straight into the correct equalizer frequency, saving time when mixing or tuning a room.','Hearing a nasal honk, a technician recognizes it near 1 kHz, sets a narrow cut there, and confirms the honk reduces.','Auditory Training',ARRAY['Equalization','Critical bands','Comb-filter identification','Octave','Timbre']::text[],ARRAY['Guessing exact hertz values rather than the correct broad region.','Ignoring that our frequency resolution is finer in the midrange than at the extremes.','Confusing a fundamental''s pitch with the harmonic region actually being boosted.']::text[],ARRAY['Quickly finding a feedback frequency to notch in a live mix.','Naming a resonant room mode by ear.','Ear-training drills that boost random equalizer bands to identify.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'defcd2d7-874d-45db-a499-208157af09bb','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='defcd2d7-874d-45db-a499-208157af09bb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='defcd2d7-874d-45db-a499-208157af09bb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a3e983ff-fa7d-4c08-93a4-449a42de2b39','Front-back confusion','Front-back confusion is a localization error in which a source in front is heard as behind, or vice versa, because the interaural time and level differences are nearly the same for those mirrored directions. These ambiguous positions form the ''cone of confusion'', and listeners resolve them with pinna spectral cues and small head movements.','Front-back confusion is placing a front sound behind, or the reverse. The left-right timing and level cues match for both directions. These matching spots form a ''cone of confusion''. The outer ear''s filtering and small head turns help sort it out. Headphones without head tracking make it worse.','It explains a common localization error and why pinna cues and head movement, or head tracking, are needed to disambiguate front from back.','To reduce front-back errors in a virtual-reality mix, a technician enables head tracking so head turns change the cues and resolve the ambiguity.','Spatial Perception',ARRAY['Cone of confusion','Head tracking','Pinna cues','Elevation perception','Head-related transfer function']::text[],ARRAY['Blaming equipment for a normal perceptual ambiguity.','Thinking interaural cues alone can separate front from back; they cannot.','Ignoring that static headphone listening increases the confusion.']::text[],ARRAY['Reducing front-back errors in binaural or virtual-reality audio.','Explaining why a listener turns their head to locate a sound.','Evaluating a head-related transfer function''s localization accuracy.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front-back confusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a3e983ff-fa7d-4c08-93a4-449a42de2b39','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a3e983ff-fa7d-4c08-93a4-449a42de2b39') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a3e983ff-fa7d-4c08-93a4-449a42de2b39');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3e8565e6-4ac8-4735-a627-1052194a93ae','Hair-cell transduction','Hair-cell transduction is the conversion of sound-induced motion in the cochlea into electrical signals by sensory hair cells. Deflection of the stereocilia bundle tugs on tip links that open mechanically gated ion channels, letting potassium and calcium enter and depolarize the cell, which then releases neurotransmitter to the auditory nerve.','Hair-cell transduction turns sound motion into nerve signals. Tiny hairs on each cell bend when sound moves the inner-ear fluid. Bending opens gated channels through fine tip links. Ions flow in and the cell fires a signal. This is how hearing begins.','It is the fundamental step that turns mechanical sound vibration into the neural signals the brain interprets as hearing.','Understanding that hair cells do not regrow, a technician respects hearing-protection limits, since transduction cells lost to loud exposure are not replaced.','Auditory Physiology',ARRAY['Cochlea','Stereocilia','Inner hair cells','Outer hair cells','Basilar membrane']::text[],ARRAY['UNSAFE: Assuming damaged hair cells recover, so overexposure to loud sound is harmless.','Confusing inner hair cells (main sensors) with outer hair cells (cochlear amplifier).','Thinking the hairs are nerves rather than sensory cells that drive nerves.']::text[],ARRAY['Explaining the first step of hearing in a training module.','Understanding why noise exposure causes permanent hearing loss.','Relating cochlear physiology to frequency place-coding.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hair-cell transduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3e8565e6-4ac8-4735-a627-1052194a93ae','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3e8565e6-4ac8-4735-a627-1052194a93ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3e8565e6-4ac8-4735-a627-1052194a93ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0bff2b15-f35d-4353-95ad-b6be1374df34','Harmonic excitation','Harmonic excitation is the deliberate generation of new harmonic overtones from a signal, usually by mild nonlinear processing, to add brightness, presence, or perceived detail. Because the ear associates added upper harmonics with clarity and can infer a fundamental from them, exciters and enhancers use this to make sources cut through without simply boosting existing energy.','Harmonic excitation adds new overtones to a sound. A gentle nonlinear process creates them from the original signal. The ear reads extra high harmonics as brightness and detail. So a source seems clearer and more present. Exciters and enhancers work this way.','It adds perceived brightness and presence by synthesizing harmonics, rather than by boosting frequencies that may be weak or missing.','A technician adds a touch of harmonic excitation to a dull vocal to lift its air and presence, using less than a plain high-shelf boost would need.','Audio Enhancement',ARRAY['Aural exciter','Harmonic distortion','Combination tones','Saturation','Missing fundamental']::text[],ARRAY['Overusing excitation until the source becomes harsh and fatiguing.','Assuming it boosts existing highs; it actually creates new harmonic content.','Confusing the generic method with the trademarked ''Aural Exciter'', owned by Aphex.']::text[],ARRAY['Adding presence to a dull vocal or acoustic guitar.','Restoring perceived detail in a bandlimited recording.','Explaining how psychoacoustic enhancers create brightness.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic excitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0bff2b15-f35d-4353-95ad-b6be1374df34','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0bff2b15-f35d-4353-95ad-b6be1374df34') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0bff2b15-f35d-4353-95ad-b6be1374df34');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '129ac12d-5591-432d-93ef-d20055abcfc9','Harmonic grouping','Harmonic grouping is the auditory system''s tendency to fuse frequency components that are whole-number multiples of a common fundamental into a single perceived sound with one pitch. As part of auditory scene analysis, this harmonic relationship is a strong grouping cue that lets the ear separate one voice or instrument from overlapping sources.','Harmonic grouping means the ear binds related partials into one sound. Frequencies that are whole-number multiples of a base note fuse together. The brain hears them as a single voice with one pitch. This helps you pick one instrument out of a mix. It is part of how hearing sorts a scene.','It explains how the auditory system binds harmonically related partials into one source, a key mechanism for separating overlapping sounds.','Knowing mistuned harmonics can pop out as a separate sound, a technician avoids pitch artifacts that would split one instrument into two perceived sources.','Auditory Scene Analysis',ARRAY['Auditory scene analysis','Pitch perception','Missing fundamental','Timbre','Harmonic excitation']::text[],ARRAY['Assuming the ear analyzes every partial separately rather than grouping them.','Confusing harmonic grouping with masking, which is about audibility not fusion.','Overlooking that a mistuned harmonic can be heard as a separate tone.']::text[],ARRAY['Explaining how listeners follow one voice in a dense mix.','Understanding why a complex tone has a single clear pitch.','Diagnosing artifacts that split a source into two perceived sounds.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic grouping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '129ac12d-5591-432d-93ef-d20055abcfc9','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='129ac12d-5591-432d-93ef-d20055abcfc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='129ac12d-5591-432d-93ef-d20055abcfc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd57638f5-ca4d-4a69-bf1d-1515c5526e11','Head tracking','Head tracking is the real-time sensing of a listener''s head orientation, and sometimes position, so that rendered spatial audio updates to keep virtual sources fixed in the world as the head turns. In binaural and immersive systems it feeds the head-related transfer function processing, greatly improving localization and reducing front-back confusion and in-head localization.','Head tracking senses which way your head is turned. The audio then updates so sounds stay put in the room as you move. This makes headphone audio feel external and stable. It sharply cuts front-back mistakes. Virtual reality and spatial headphones rely on it.','It keeps virtual sound sources anchored in space as the listener moves, adding the head-movement cue that makes binaural audio convincing.','In a virtual-reality mix, a technician enables head tracking so a source stays in front when the listener turns, resolving front-back ambiguity.','Immersive Audio',ARRAY['Head-related transfer function','Binaural rendering','Front-back confusion','Elevation perception','Immersive audio']::text[],ARRAY['Assuming binaural audio needs no head tracking to sound external.','Ignoring that tracking latency can break the illusion or cause discomfort.','Confusing head tracking (orientation sensing) with the head-related transfer function itself.']::text[],ARRAY['Adding head tracking to spatial-audio headphones.','Improving localization in a virtual-reality sound scene.','Reducing in-head localization on headphone playback.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Head tracking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd57638f5-ca4d-4a69-bf1d-1515c5526e11','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d57638f5-ca4d-4a69-bf1d-1515c5526e11') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d57638f5-ca4d-4a69-bf1d-1515c5526e11');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c91f89b-864c-4dc8-8f47-fc8521e9bf73','Head-related transfer functions','A head-related transfer function (HRTF) is the direction- and frequency-dependent filter that describes how a listener''s head, torso and outer ear (pinna) shape a sound on its way to the eardrum. Measured as a pair for the two ears, HRTFs encode the interaural time and level differences and the pinna spectral cues the auditory system uses to place a source in three dimensions.','An HRTF is a set of filters. It describes how your head and ears change a sound before it reaches each eardrum. The change depends on where the sound comes from. Headphone systems use these filters to fake a 3D position.','HRTFs capture the acoustic cues the brain uses for localization, so they let engineers synthesize convincing spatial audio over headphones.','A technician loads an HRTF set into a binaural renderer to position virtual sources around a headphone listener in a game or VR mix.','Binaural Localization',ARRAY['Individualized HRTFs','Localization','Height localization','Binaural rendering','Interaural level difference']::text[],ARRAY['Assuming one generic HRTF works equally well for every listener.','Confusing an HRTF (the ear filter) with reverb or room response.','Thinking HRTFs only affect level, ignoring their time and spectral cues.']::text[],ARRAY['Building a virtual-reality audio scene rendered over headphones.','Choosing an HRTF profile in a spatial-audio plug-in.','Explaining why headphone 3D audio can collapse for some users.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Head-related transfer functions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c91f89b-864c-4dc8-8f47-fc8521e9bf73','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c91f89b-864c-4dc8-8f47-fc8521e9bf73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c91f89b-864c-4dc8-8f47-fc8521e9bf73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '415079ee-8c64-482e-aaf3-ec016f2cae49','Hearing threshold','The hearing threshold is the lowest sound pressure level a listener can just detect at a given frequency under stated conditions. The standard reference sound pressure is 20 micropascals (0 dB SPL), and human hearing is most sensitive in roughly the 2 to 5 kHz region, where the threshold dips below 0 dB SPL.','The hearing threshold is the quietest sound you can just hear. It changes with frequency. Ears are most sensitive around 2 to 5 kHz. Very low and very high tones must be much louder to be heard.','It defines the bottom of the audible dynamic range and anchors loudness scales, audiometry and equal-loudness contours.','With reference pressure p0 = 20 microPa, a just-audible 1 kHz tone at p = 20 microPa gives L = 20 log10(20/20) = 0 dB SPL.','Auditory Thresholds',ARRAY['Equal-loudness contours','Minimum audible field','Loudness','Middle-ear transfer','Masking recognition']::text[],ARRAY['Treating 0 dB SPL as silence rather than a fixed reference pressure.','Assuming the threshold is flat across frequency.','Confusing minimum audible field (free field) with minimum audible pressure (headphone).']::text[],ARRAY['Reading an audiogram against age-normal thresholds.','Explaining why a subwoofer needs high level to be audible.','Calibrating the noise floor target of a quiet listening room.']::text[],'Intermediate','L_p = 20 * log10(p / p0)','Sound pressure level in decibels equals twenty times the base-ten logarithm of the sound pressure divided by the reference pressure.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '415079ee-8c64-482e-aaf3-ec016f2cae49','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='415079ee-8c64-482e-aaf3-ec016f2cae49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='415079ee-8c64-482e-aaf3-ec016f2cae49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '04394af2-318a-4d05-8560-482600f12d4f','Height localization','Height localization is the ability to judge the vertical elevation of a sound source. It relies mainly on direction-dependent spectral cues created by the pinna and torso, especially peaks and notches in the 5 to 16 kHz range, rather than on interaural time or level differences.','Height localization is hearing whether a sound is high or low. Both ears get almost the same timing and level for elevation. Instead the outer ear adds spectral notches. The brain reads these to judge height.','It lets listeners place sources up or down, which matters for immersive and object-based audio formats with height channels.','A technician verifies overhead loudspeakers by checking that a source panned to a ceiling channel is heard as elevated, not just louder.','Binaural Localization',ARRAY['Head-related transfer functions','Localization','Pinna cues','Metadata-driven rendering','Elevation']::text[],ARRAY['Assuming height comes from time or level differences between the ears.','Expecting strong elevation cues below a few kHz.','Thinking generic loudspeaker layouts guarantee accurate height for every listener.']::text[],ARRAY['Auditioning an immersive mix with ceiling speakers.','Diagnosing weak overhead imaging in a cinema.','Testing elevation accuracy of a binaural renderer.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Height localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '04394af2-318a-4d05-8560-482600f12d4f','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='04394af2-318a-4d05-8560-482600f12d4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='04394af2-318a-4d05-8560-482600f12d4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3df2eb0b-8afd-4aea-b3dd-81de0d0e7950','High-pass and low-pass recognition','High-pass and low-pass recognition is the trained perceptual skill of identifying, by ear, whether a signal has had its low frequencies or its high frequencies attenuated by a filter. It is a core auditory-training target because it links a heard tonal change to a specific filter type and cutoff region.','This is hearing what a filter did to a sound. A high-pass filter removes lows, leaving a thin sound. A low-pass filter removes highs, leaving a dull sound. Trained listeners learn to name which one happened.','It builds the listener''s ability to connect timbral changes to filter actions, which speeds accurate equalization and fault-finding.','During ear training a technician hears a processed loop and identifies it as low-pass filtered near 4 kHz because the top-end air is gone.','Listening Skills',ARRAY['Listener training and perceptual learning','Noise-color identification','Masking recognition','Equalization','Timbre']::text[],ARRAY['Confusing a high-pass result (thin) with a low-pass result (dull).','Guessing cutoff frequency without a level-matched reference.','Assuming a loudness change is a filter change.']::text[],ARRAY['An ear-training drill on filter type identification.','Judging whether a mic sounds thin or dull on a source.','Reverse-engineering an EQ move heard on a reference track.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='High-pass and low-pass recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3df2eb0b-8afd-4aea-b3dd-81de0d0e7950','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3df2eb0b-8afd-4aea-b3dd-81de0d0e7950') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3df2eb0b-8afd-4aea-b3dd-81de0d0e7950');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f5b7dba-1f55-4ff3-aa7b-75fba483786c','Higher-order spatial aliasing','Higher-order spatial aliasing is the corruption of the reconstructed sound field in higher-order Ambisonics and spherical microphone arrays at frequencies where the wavelength becomes small relative to the array. Spatially detailed (high-order) components are captured or reproduced without error only while the product of wavenumber and radius stays below the Ambisonic order (kr < N); above the resulting frequency, energy folds into wrong spatial modes.','Ambisonics is a way to record sound direction. It works well only up to a set pitch limit. Above that limit, short sound waves fool the mics. The heard direction then comes out wrong. Using more microphones raises the limit. But making the array physically larger lowers it. So a higher-order array stays accurate up to a higher pitch.','It sets the usable upper frequency for accurate spatial capture and playback, guiding array size and Ambisonic order choices.','For a spherical array of radius r = 0.042 m at order N = 4, the aliasing frequency is about f = Nc/(2*pi*r) = 4*343/(2*pi*0.042) ~ 5.2 kHz.','Spatial Audio',ARRAY['Metadata-driven rendering','Localization','Spherical microphone array','Interchannel correlation','Ambisonics']::text[],ARRAY['Assuming higher order fixes aliasing at all frequencies rather than raising the limit.','Ignoring array radius when predicting the usable bandwidth.','Confusing spatial aliasing with ordinary time-domain sampling aliasing.']::text[],ARRAY['Specifying a spherical microphone for a broadband capture.','Explaining high-frequency image blur in an Ambisonic recording.','Choosing Ambisonic order for a fixed loudspeaker rig.']::text[],'Advanced','f_alias ~ N * c / (2 * pi * r)','The spatial aliasing frequency is about the Ambisonic order times the speed of sound, divided by two pi times the array radius.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Higher-order spatial aliasing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f5b7dba-1f55-4ff3-aa7b-75fba483786c','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f5b7dba-1f55-4ff3-aa7b-75fba483786c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f5b7dba-1f55-4ff3-aa7b-75fba483786c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e41ee03-6b1b-4fb3-aa60-e34402f6fa14','Image shift with listener movement','Image shift with listener movement is the change in the apparent position of a phantom stereo image when the listener moves away from the central sweet spot. As the path-length and level balance from the two loudspeakers changes, the precedence effect pulls the image toward the nearer, earlier speaker.','A stereo image sits between two speakers only in the sweet spot. Move to one side and the image jumps toward the nearer speaker. Its sound arrives first and louder. This is why off-centre listeners lose the centre image.','It explains the limited sweet spot of two-channel stereo and motivates centre channels and careful listener seating.','A technician warns that a hard-panned centre vocal will collapse to the left speaker for guests seated left of centre.','Stereo Perception',ARRAY['Image-position recognition','Precedence effect','Intensity stereophony','Localization','Interchannel correlation']::text[],ARRAY['Assuming the phantom centre stays centred everywhere in the room.','Blaming speaker faults for an image that only shifts off-axis.','Ignoring arrival-time (precedence) effects and thinking only about level.']::text[],ARRAY['Setting up a home or studio listening position.','Explaining why cinema centre dialogue uses a dedicated channel.','Judging stereo width while walking across the room.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Image shift with listener movement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e41ee03-6b1b-4fb3-aa60-e34402f6fa14','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e41ee03-6b1b-4fb3-aa60-e34402f6fa14') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e41ee03-6b1b-4fb3-aa60-e34402f6fa14');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3942ac0-68a6-4eb9-8ed5-1ec11b405a0b','Image-position recognition','Image-position recognition is the perceptual and trained skill of judging where a phantom or real source appears within a stereo or surround stage. It depends on interchannel level and time differences that the auditory system maps to an azimuth between the loudspeakers.','This is naming where a sound sits in the stereo picture. It could be left, centre, or part way across. Listeners judge this from level and timing differences. Training makes these judgments faster and more exact.','It underpins accurate panning decisions and quality control of a mix''s spatial balance.','In an ear-training test a listener reports a snare at about 30 percent left, matching the mix engineer''s pan setting.','Stereo Perception',ARRAY['Image shift with listener movement','Level-difference identification','Localization','Intensity stereophony','Interchannel correlation']::text[],ARRAY['Assuming pan-pot percentage maps linearly to perceived position.','Ignoring how timing differences move the image, not just level.','Judging position while sitting off the centre line.']::text[],ARRAY['Grading a stereo mix''s placement in ear training.','Setting pan positions during a mix.','Checking that a phantom centre is truly centred.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Image-position recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3942ac0-68a6-4eb9-8ed5-1ec11b405a0b','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3942ac0-68a6-4eb9-8ed5-1ec11b405a0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3942ac0-68a6-4eb9-8ed5-1ec11b405a0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d55633c-8383-47a3-b1f2-d75e22590a6e','Individualized HRTFs','Individualized HRTFs are head-related transfer functions measured or modeled for one specific listener rather than taken from a generic dummy head or average. Because pinna and head geometry vary between people, individualized sets typically improve localization accuracy, reduce front-back confusions and lessen in-head localization in binaural playback.','Every person''s ears and head have a different shape. A one-size 3D filter fits no one well. A personal HRTF is measured from your own ears. It gives sharper, more life-like 3D sound on headphones.','They tailor binaural rendering to a listener''s anatomy, improving externalization and reducing localization errors.','A technician captures or scans a user''s ears to build a personal HRTF that fixes front-back confusion in a VR headset.','Binaural Localization',ARRAY['Head-related transfer functions','Localization','Height localization','Binaural rendering','Front-back confusion']::text[],ARRAY['Believing a generic HRTF suits every listener equally.','Expecting individualization to remove all localization error.','Confusing HRTF personalization with simple headphone EQ.']::text[],ARRAY['Personalizing spatial audio on a phone or headset.','Research on binaural localization accuracy.','Reducing in-head localization for a headphone mix.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Individualized HRTFs');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d55633c-8383-47a3-b1f2-d75e22590a6e','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d55633c-8383-47a3-b1f2-d75e22590a6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d55633c-8383-47a3-b1f2-d75e22590a6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67350ccf-20ff-404e-ac47-5a51f37a61d7','Inharmonic percussion spectra','Inharmonic percussion spectra are the sets of partials produced by many percussion instruments whose frequencies are not simple integer multiples of a fundamental. Bells, cymbals, gongs and drums vibrate in modes governed by their plate or membrane geometry, giving clustered, non-harmonic partials and often no single clear pitch.','Most percussion does not make a neat harmonic series. Its overtones sit at odd, non-integer spacings. That is why a cymbal or bell has a clangy, pitch-blurred sound. The shape of the object sets these frequencies.','It explains why many percussion instruments have ambiguous pitch and a metallic timbre, guiding mic choice and tuning expectations.','A technician does not tune a ride cymbal to a musical note, because its inharmonic partials give no single stable pitch.','Musical Acoustics',ARRAY['Membrane modes','Instrument body modes','Timbre','Noise-color identification','Pitch']::text[],ARRAY['Expecting percussion overtones to follow a harmonic series.','Assuming every struck instrument has a definite pitch.','Confusing loud high partials with distortion rather than natural inharmonicity.']::text[],ARRAY['Tuning drums versus leaving cymbals untuned.','Explaining a bell''s ambiguous perceived pitch.','EQing metallic percussion in a mix.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inharmonic percussion spectra');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67350ccf-20ff-404e-ac47-5a51f37a61d7','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67350ccf-20ff-404e-ac47-5a51f37a61d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67350ccf-20ff-404e-ac47-5a51f37a61d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '990418ec-8fb0-4a12-a64f-d95ad7500207','Instrument body modes','Instrument body modes are the resonant vibration patterns of an instrument''s structure, such as a guitar top plate, violin body or drum shell, together with the enclosed air. These modes emphasize particular frequency bands, shaping the instrument''s timbre and radiation pattern.','An instrument''s body can vibrate in set patterns. Each pattern boosts a certain frequency band. These body resonances colour the tone. They are a big reason two guitars can sound different.','They shape an instrument''s characteristic timbre and how it radiates sound, informing mic placement and instrument design.','A technician moves a guitar mic off the soundhole to avoid a boomy air-body resonance around 100 Hz.','Musical Acoustics',ARRAY['Membrane modes','Inharmonic percussion spectra','Timbre','Resonance','Radiation pattern']::text[],ARRAY['Assuming body modes are the same as the played string pitch.','Ignoring the enclosed-air (Helmholtz) resonance of the body.','Treating one mic position as ideal for every instrument body.']::text[],ARRAY['Choosing mic placement on an acoustic guitar.','Explaining tonal differences between violins.','Taming a boomy body resonance with EQ.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instrument body modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '990418ec-8fb0-4a12-a64f-d95ad7500207','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='990418ec-8fb0-4a12-a64f-d95ad7500207') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='990418ec-8fb0-4a12-a64f-d95ad7500207');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a115a4e5-f5bc-4f67-bfd9-3bd298bfcb85','Intensity stereophony','Intensity stereophony is a stereo technique in which the phantom image position is set by interchannel level (intensity) differences alone, with no significant time differences. It is produced by coincident microphone pairs such as XY or Blumlein, and by pan pots, so the two channels stay mono-compatible.','Intensity stereo places sounds using level differences only. The two channels carry the same timing. Louder on the left pulls the image left. Coincident mic pairs and pan pots work this way. It sums to mono cleanly.','It gives stable, mono-compatible imaging based on level differences, favored for broadcast and coincident recording.','A technician records a choir with an XY pair so the mix stays solid when the broadcast is folded to mono.','Stereo Technique',ARRAY['Near-coincident stereo','Level-difference identification','Interchannel correlation','Mid/side stereo','Localization']::text[],ARRAY['Confusing intensity stereo with spaced (time-difference) techniques.','Assuming pan pots add time differences; they only change level.','Expecting wide spacious imaging from a coincident pair.']::text[],ARRAY['Recording an ensemble with an XY or Blumlein pair.','Panning tracks in a mono-safe broadcast mix.','Teaching the difference between level and time stereo cues.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity stereophony');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a115a4e5-f5bc-4f67-bfd9-3bd298bfcb85','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a115a4e5-f5bc-4f67-bfd9-3bd298bfcb85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a115a4e5-f5bc-4f67-bfd9-3bd298bfcb85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5318a771-67ab-4343-a8b8-a9c1292d3981','Interchannel correlation','Interchannel correlation is a normalized measure of how similar two audio channels are, expressed as a correlation coefficient from +1 to -1. A value of +1 means the channels are identical (mono), 0 means they are unrelated, and -1 means they are inverted copies that cancel when summed to mono.','This number says how alike two channels are. Plus one means identical, like mono. Zero means unrelated. Minus one means opposite, so they cancel in mono. Engineers watch it on a correlation meter to protect mono compatibility.','It quantifies stereo width and mono compatibility, warning when summing to mono will cancel content.','A phase meter reading r = -0.6 on a bass track warns the technician that summing to mono will weaken the low end.','Stereo Metering',ARRAY['Negative correlation','Mid/side stereo','Intensity stereophony','Interaural cross-correlation','Mono compatibility']::text[],ARRAY['Reading correlation as absolute phase rather than similarity of the two channels.','Assuming a low correlation always means a problem rather than width.','Ignoring that a -1 reading predicts mono cancellation.']::text[],ARRAY['Watching a correlation meter during a stereo master.','Checking a bassline for mono safety.','Comparing width of two stereo microphone techniques.']::text[],'Intermediate','r = sum(L_n * R_n) / sqrt(sum(L_n^2) * sum(R_n^2))','The correlation coefficient equals the summed product of the left and right samples divided by the square root of the product of their summed squares.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interchannel correlation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5318a771-67ab-4343-a8b8-a9c1292d3981','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5318a771-67ab-4343-a8b8-a9c1292d3981') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5318a771-67ab-4343-a8b8-a9c1292d3981');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e5a8255-e5e5-402d-a02c-f3f8af2e6c93','Level-difference identification','Level-difference identification is the trained skill of detecting and estimating differences in level between two signals, channels or ears. In localization it corresponds to interaural level differences (ILD), the frequency-dependent level cue that dominates lateralization above roughly 1.5 kHz.','This is hearing that one thing is louder than another and by how much. Between the ears, a level difference is called an ILD. It helps place high sounds left or right. Training sharpens these judgments.','It builds sensitivity to level cues used both for mix balance and for binaural localization.','In ear training a listener detects a 1 dB boost on one channel, matching the pan or gain move applied.','Listening Skills',ARRAY['Image-position recognition','Intensity stereophony','Localization','Interaural level difference','Loudness matching']::text[],ARRAY['Confusing an overall loudness change with a between-channel level difference.','Assuming level cues dominate localization at low frequencies.','Judging small level steps without a matched reference.']::text[],ARRAY['An ear-training drill on decibel discrimination.','Balancing left-right level in a mix.','Explaining why high sounds lateralize by level.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Level-difference identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e5a8255-e5e5-402d-a02c-f3f8af2e6c93','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e5a8255-e5e5-402d-a02c-f3f8af2e6c93') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e5a8255-e5e5-402d-a02c-f3f8af2e6c93');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c80d9331-14d6-42ff-9f93-94ac5c952a0d','Lip-reed oscillation','Lip-reed oscillation is the sound-generating mechanism of brass instruments, in which the player''s tensioned lips act as a pressure-controlled valve that opens and closes at the note frequency. The lips couple to the air column, and their vibration locks to one of the instrument''s resonances to sustain a tone.','A brass player''s buzzing lips make the sound. The lips work like a valve that flaps open and shut. Air pressure and lip tension set the rate. The instrument''s tube then locks the buzz to a note.','It explains how brass instruments turn steady breath pressure into a sustained pitched tone through lip-air coupling.','A technician expects a trumpet''s fundamental and harmonics to shift as the player changes lip tension, so mic gain must handle wide dynamics.','Musical Acoustics',ARRAY['Instrument body modes','Resonance','Harmonic series','Timbre','Air column']::text[],ARRAY['Thinking a mouthpiece reed, not the lips, makes the sound.','Assuming pitch comes only from the tube, not lip tension.','Ignoring the strong coupling between lips and air column.']::text[],ARRAY['Explaining how a bugle plays different notes without valves.','Setting mic gain for a loud brass section.','Teaching brass sound production in acoustics.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lip-reed oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c80d9331-14d6-42ff-9f93-94ac5c952a0d','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c80d9331-14d6-42ff-9f93-94ac5c952a0d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c80d9331-14d6-42ff-9f93-94ac5c952a0d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85d6eebc-604c-42e4-bf42-0bc7da580e19','Listener training and perceptual learning','Listener training and perceptual learning is the systematic practice that improves a listener''s ability to detect, identify and label subtle sound features such as EQ changes, distortion, or spatial cues. Repeated feedback-driven exposure produces measurable, lasting gains in auditory discrimination.','Ears can be trained like any skill. With practice and feedback, you hear finer details. You learn to name EQ moves, distortion, or width. These gains last and make you a faster, more reliable listener.','It develops reliable critical-listening skills that underpin mixing, quality control and evaluation of audio systems.','A technician runs daily EQ-matching drills and steadily identifies smaller boosts and narrower bands over weeks.','Listening Skills',ARRAY['High-pass and low-pass recognition','Masking recognition','Noise-color identification','Loudness matching','Memory limitations in audio comparison']::text[],ARRAY['Assuming golden ears are innate and cannot be trained.','Practicing without feedback, so errors go uncorrected.','Expecting improvement without level-matched, controlled comparisons.']::text[],ARRAY['Following a structured technical ear-training course.','Preparing for a critical-listening certification.','Calibrating a team of listeners before a subjective test.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Listener training and perceptual learning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85d6eebc-604c-42e4-bf42-0bc7da580e19','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85d6eebc-604c-42e4-bf42-0bc7da580e19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85d6eebc-604c-42e4-bf42-0bc7da580e19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e81c69a-9248-49dd-ba44-96dee83eb828','Localization','Localization is the perception of the direction and distance of a sound source. Horizontal direction is judged mainly through the duplex mechanism: interaural time differences dominate below about 1.5 kHz and interaural level differences above it, while pinna spectral cues and head movement resolve elevation and front-back ambiguity.','Localization is knowing where a sound comes from. Timing between the ears places low sounds. Level between the ears places high sounds. The outer ear adds up-down cues. Together they point you to the source.','It is the basis of spatial hearing, guiding stereo and immersive reproduction and sound-system design.','A technician pans a source and checks it localizes at the intended angle using both level and, where present, time cues.','Binaural Localization',ARRAY['Head-related transfer functions','Interaural level difference','Interaural time difference','Precedence effect','Height localization']::text[],ARRAY['Believing one cue explains all directions across all frequencies.','Ignoring front-back confusions that head movement resolves.','Assuming level cues work well at low frequencies.']::text[],ARRAY['Positioning sources in a surround mix.','Explaining the duplex theory in training.','Diagnosing why a source images poorly.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e81c69a-9248-49dd-ba44-96dee83eb828','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e81c69a-9248-49dd-ba44-96dee83eb828') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e81c69a-9248-49dd-ba44-96dee83eb828');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4e4bb90-aff0-4cc3-a5ca-30fa44bfb9fd','Loudness bias','Loudness bias is the well-documented tendency for listeners to prefer or rate more highly the louder of two otherwise similar signals in a comparison. Because even small level differences skew judgments, valid subjective tests require careful level matching to remove this confound.','Louder usually sounds better, even when it is not. A small volume boost can win a comparison unfairly. This is loudness bias. Fair listening tests must match levels first so loudness does not decide.','It warns that uncontrolled level differences invalidate A/B comparisons, so it drives strict level matching in testing.','Before comparing two compressors a technician level-matches their outputs so the louder one does not automatically win.','Perceptual Bias',ARRAY['Loudness matching','Memory limitations in audio comparison','Listener training and perceptual learning','Loudness','Level-difference identification']::text[],ARRAY['Comparing processors without matching output loudness first.','Assuming a preferred setting is better when it is merely louder.','Trusting quick A/B tests that ignore level.','Confusing higher level with higher quality.']::text[],ARRAY['Level-matching before an A/B plug-in shootout.','Designing a blind listening test.','Explaining why a louder master seemed to win.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness bias');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4e4bb90-aff0-4cc3-a5ca-30fa44bfb9fd','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4e4bb90-aff0-4cc3-a5ca-30fa44bfb9fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4e4bb90-aff0-4cc3-a5ca-30fa44bfb9fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7136c21d-a15c-409b-bb82-f044def350b0','Loudness matching','Loudness matching is the procedure of adjusting two signals to equal perceived loudness so they can be compared fairly. It removes loudness bias, and in practice is done by aligning measured loudness (for example integrated loudness in LUFS) and confirming by ear.','Loudness matching makes two sounds equally loud before you compare them. It cancels the unfair pull of extra volume. Engineers match measured loudness, then check by ear. Only then is an A/B test fair.','It ensures comparisons reflect real differences in quality or processing, not level, protecting the validity of listening tests.','A technician trims two masters to the same integrated loudness (for example -14 LUFS) before judging which sounds better.','Listening Skills',ARRAY['Loudness bias','Loudness','Memory limitations in audio comparison','Listener training and perceptual learning','Level-difference identification']::text[],ARRAY['Matching peak level instead of perceived loudness.','Skipping the by-ear check after meter matching.','Assuming equal fader positions means equal loudness.']::text[],ARRAY['Preparing a fair plug-in A/B comparison.','Aligning reference tracks for mastering.','Setting up a controlled subjective test.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7136c21d-a15c-409b-bb82-f044def350b0','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7136c21d-a15c-409b-bb82-f044def350b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7136c21d-a15c-409b-bb82-f044def350b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '00ba4f88-a34c-42d1-ae1f-23d3ede1bc38','Magnetic pickup aperture','Magnetic pickup aperture is the effective sensing width of an electric-instrument pickup along the string. Because the pickup responds to string motion over a finite length, it averages the string''s displacement and forms a comb-filter response that attenuates harmonics whose wavelength along the string matches the aperture, shaping the tone.','A guitar pickup senses the string over a small length, not a single point. This averaging acts like a comb filter. It weakens certain high harmonics. The aperture width is one reason pickups have their own tone.','It explains part of a pickup''s characteristic frequency response and why pickup position and width change the tone.','A technician expects a wide-aperture humbucker to sound darker than a narrow single-coil because it rolls off more high harmonics.','Musical Acoustics',ARRAY['Instrument body modes','Comb filtering','Harmonic series','Timbre','Pickup position']::text[],ARRAY['Assuming a pickup senses the string at a single point.','Crediting all tonal differences to coil count, ignoring aperture.','Confusing aperture comb filtering with amplifier EQ.']::text[],ARRAY['Comparing single-coil and humbucker tone.','Explaining why pickup placement changes brightness.','Modeling an electric guitar''s frequency response.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetic pickup aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '00ba4f88-a34c-42d1-ae1f-23d3ede1bc38','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='00ba4f88-a34c-42d1-ae1f-23d3ede1bc38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='00ba4f88-a34c-42d1-ae1f-23d3ede1bc38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2d5aa15-cc09-47da-b015-fefc4957753b','Masking recognition','Masking recognition is the trained ability to hear when one sound reduces or removes the audibility of another. It draws on simultaneous masking, where a louder tone or noise hides a nearby-frequency sound within the same critical band, and on temporal masking that occurs just before and after a loud sound.','Masking is when a loud sound hides a quieter one. It is strongest when they share a frequency region. It can also happen just before or after a loud burst. Trained listeners learn to notice when masking is at work.','It helps engineers predict when parts of a mix will hide each other, guiding EQ, arrangement and lossy-codec understanding.','A technician carves a 3 kHz dip in a synth so it stops masking the vocal that lives in the same critical band.','Listening Skills',ARRAY['Hearing threshold','Critical bands','Listener training and perceptual learning','High-pass and low-pass recognition','Loudness']::text[],ARRAY['Thinking masking only happens at the exact same frequency, not across a band.','Ignoring temporal (pre- and post-) masking.','Assuming louder always fixes a masked part rather than clearing space.']::text[],ARRAY['Freeing a vocal that a guitar is masking.','Explaining how perceptual audio codecs discard masked detail.','Ear-training drills on detecting masked tones.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masking recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2d5aa15-cc09-47da-b015-fefc4957753b','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2d5aa15-cc09-47da-b015-fefc4957753b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2d5aa15-cc09-47da-b015-fefc4957753b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5fd3d4f-69cd-4af3-87a4-9e59613f021e','McGurk-style audiovisual influence on speech','The McGurk effect is an audiovisual illusion in which watching a talker''s mouth changes the speech sound a listener perceives. In the classic demonstration an auditory /ba/ paired with a visual /ga/ is commonly heard as /da/, showing that vision is integrated with hearing during speech perception.','What you see a mouth do changes what you hear it say. A spoken ''ba'' with a lip shape for ''ga'' is often heard as ''da''. This is the McGurk effect. Sight and sound merge in speech.','It demonstrates that speech perception is multisensory, which matters for dialogue, lip-sync and evaluating audio with picture.','A technician keeps audio and video in tight sync, knowing mismatched lips can change or blur the perceived dialogue.','Multisensory Perception',ARRAY['Localization','Listener training and perceptual learning','Speech perception','Lip-sync','Audiovisual integration']::text[],ARRAY['Assuming hearing works independently of vision.','Thinking the effect only appears in poor listeners.','Ignoring lip-sync error as merely cosmetic.']::text[],ARRAY['Checking dialogue with picture for lip-sync.','Explaining why visuals affect perceived speech.','Designing an audiovisual perception demonstration.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='McGurk-style audiovisual influence on speech');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5fd3d4f-69cd-4af3-87a4-9e59613f021e','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5fd3d4f-69cd-4af3-87a4-9e59613f021e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5fd3d4f-69cd-4af3-87a4-9e59613f021e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39b2c8d5-eb07-4c36-b916-57763d812798','Membrane modes','Membrane modes are the standing-wave vibration patterns of a stretched membrane, such as a drumhead. For an ideal circular membrane the mode frequencies are set by the zeros of Bessel functions and are inharmonically spaced, which is why an isolated drumhead has an indefinite pitch.','A drumhead can vibrate in set patterns called modes. Each mode has nodal lines and a frequency. These frequencies are not a neat harmonic series. That is why a lone drumhead has no clear single pitch.','They explain the timbre and pitch ambiguity of membrane percussion and how tuning and loading shift the modes.','For an ideal circular head of radius a with wave speed c, the fundamental mode is about f01 = 2.405*c/(2*pi*a).','Musical Acoustics',ARRAY['Inharmonic percussion spectra','Instrument body modes','Timbre','Resonance','Bessel functions']::text[],ARRAY['Expecting drumhead modes to form a harmonic series.','Assuming a bare head has a clear pitch like a string.','Ignoring how air loading and the shell shift real mode frequencies.']::text[],ARRAY['Explaining why a timpano needs an air cavity for definite pitch.','Tuning lugs to even out a drumhead''s modes.','Teaching two-dimensional standing waves.']::text[],'Advanced','f_mn = alpha_mn * c / (2 * pi * a)','A mode frequency equals its Bessel zero times the membrane wave speed, divided by two pi times the membrane radius.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Membrane modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39b2c8d5-eb07-4c36-b916-57763d812798','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39b2c8d5-eb07-4c36-b916-57763d812798') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39b2c8d5-eb07-4c36-b916-57763d812798');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3745d7f5-ff66-4d53-841c-2070a35c6764','Memory limitations in audio comparison','Memory limitations in audio comparison refer to the short duration and low fidelity of auditory sensory (echoic) memory, which makes accurate comparison of sounds separated in time unreliable. Fine timbral and level details fade within a few seconds, so long switching gaps degrade discrimination.','Your ear-memory for fine detail is short. Small differences fade within seconds. So comparing two sounds with a long gap is hard. Fast, level-matched switching gives the most reliable judgments.','It explains why quick, tightly switched, level-matched A/B tests are more reliable than slow or remembered comparisons.','A technician uses instant A/B switching rather than recalling how a mix sounded yesterday, because echoic memory is brief.','Perceptual Bias',ARRAY['Loudness bias','Loudness matching','Listener training and perceptual learning','Level-difference identification','A/B testing']::text[],ARRAY['Trusting long-term memory of a sound for fine comparisons.','Using slow switching that outlasts echoic memory.','Comparing across days without a reference and level match.']::text[],ARRAY['Running a fast-switching A/B listening test.','Explaining why yesterday''s mix impression is unreliable.','Designing a valid subjective evaluation protocol.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Memory limitations in audio comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3745d7f5-ff66-4d53-841c-2070a35c6764','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3745d7f5-ff66-4d53-841c-2070a35c6764') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3745d7f5-ff66-4d53-841c-2070a35c6764');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b94ebee5-a43c-4966-9b07-b09a03099c99','Metadata-driven rendering','Metadata-driven rendering is the object-based audio approach in which audio elements carry descriptive metadata (such as position, size and gain) and a renderer converts them to the available loudspeakers or headphones at playback. Standards such as the ITU-R Audio Definition Model let the same content adapt to different reproduction layouts.','Object-based audio ships sounds plus instructions about where they go. A renderer then places them on whatever speakers you have. The same file adapts to stereo, surround, or headphones. This is metadata-driven rendering.','It lets one immersive program adapt to many playback layouts without a separate mix for each, enabling scalable spatial audio.','A technician authors a dialogue object with position metadata so it renders correctly on a 7.1.4 rig and on headphones alike.','Spatial Audio',ARRAY['Higher-order spatial aliasing','Localization','Head-related transfer functions','Object-based audio','Height localization']::text[],ARRAY['Confusing object-based audio with fixed channel-based mixing.','Assuming metadata guarantees identical results on every layout.','Ignoring the renderer''s role in the final loudspeaker feed.']::text[],ARRAY['Authoring an immersive object-based mix.','Delivering audio in an ADM BWF file.','Explaining why one file plays back on many systems.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Metadata-driven rendering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b94ebee5-a43c-4966-9b07-b09a03099c99','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b94ebee5-a43c-4966-9b07-b09a03099c99') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b94ebee5-a43c-4966-9b07-b09a03099c99');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93607027-0f32-4bfc-aca0-af8f6ab46b90','Mid/side stereo','Mid/side (M/S) stereo represents a stereo signal as a mid (sum) component and a side (difference) component instead of left and right. Encoding uses M = L + R and S = L - R; decoding recovers L = M + S and R = M - S (with a scaling factor), which allows independent control of centre versus width and stays mono-compatible.','Mid/side splits stereo into a centre part and a difference part. Mid is left plus right. Side is left minus right. You can then adjust centre and width on their own. Summed to mono, the side cancels cleanly.','It lets engineers control stereo width and centre balance separately and check mono compatibility easily.','To widen a mix a technician raises the side (L - R) level; to narrow it toward mono, they lower it.','Stereo Technique',ARRAY['Intensity stereophony','Interchannel correlation','Negative correlation','Near-coincident stereo','Mono compatibility']::text[],ARRAY['Forgetting the scaling factor, so decoded level doubles.','Assuming M/S changes tone rather than width and balance.','Boosting side so far that mono playback loses content.']::text[],ARRAY['Recording with a mid-side microphone pair.','Widening or narrowing a stereo master.','Checking mono compatibility of a mix.']::text[],'Intermediate','M = L + R ; S = L - R  (decode: L = (M + S)/2 , R = (M - S)/2)','Mid equals left plus right; side equals left minus right; the left and right channels are recovered by adding and subtracting mid and side, then halving.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mid/side stereo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93607027-0f32-4bfc-aca0-af8f6ab46b90','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93607027-0f32-4bfc-aca0-af8f6ab46b90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93607027-0f32-4bfc-aca0-af8f6ab46b90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd01bbd5d-ab03-40a2-b0fa-9cc2b89ad52a','Middle-ear transfer','Middle-ear transfer is the mechanical process by which the eardrum and ossicles (malleus, incus, stapes) carry sound from the air-filled ear canal to the fluid-filled cochlea. Acting as an impedance-matching transformer, it uses the eardrum-to-stapes area ratio and ossicular lever to overcome the large impedance mismatch between air and cochlear fluid.','The middle ear passes sound from air to inner-ear fluid. Air and fluid do not match well. The eardrum and tiny bones act like a matching transformer. This boosts pressure so little sound is lost.','It matches airborne sound to the cochlear fluid so that hearing is efficient rather than mostly reflected away.','A technician understands that middle-ear efficiency shapes the audiogram, since conductive loss here raises measured thresholds.','Auditory System',ARRAY['Hearing threshold','Occlusion effect','Impedance matching','Cochlea','Equal-loudness contours']::text[],ARRAY['Thinking the middle ear amplifies electrically rather than matching impedance.','Ignoring the area ratio and lever action in the pressure gain.','Confusing conductive (middle-ear) loss with sensorineural loss.']::text[],ARRAY['Explaining why air-to-fluid transfer needs matching.','Interpreting a conductive hearing loss.','Teaching the mechanics of the auditory periphery.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Middle-ear transfer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd01bbd5d-ab03-40a2-b0fa-9cc2b89ad52a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d01bbd5d-ab03-40a2-b0fa-9cc2b89ad52a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d01bbd5d-ab03-40a2-b0fa-9cc2b89ad52a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72a5c97a-5339-4897-ba89-c9b599a54f39','Near-coincident stereo','Near-coincident stereo uses two directional microphones spaced a few centimetres apart and angled outward, so the phantom image is formed by both interchannel level and time differences. Common configurations include ORTF (110 degrees, 17 cm) and NOS, giving a wider, more spacious image than a fully coincident pair while remaining reasonably mono-compatible.','Near-coincident stereo spaces two angled mics a few centimetres apart. This gives both level and slight timing differences. The result sounds wider than a coincident pair. ORTF is a common example.','It trades a little mono compatibility for greater width and spaciousness, useful for realistic ensemble and room capture.','A technician sets up an ORTF pair, 17 cm apart at 110 degrees, to record an orchestra with a natural wide image.','Stereo Technique',ARRAY['Intensity stereophony','Interchannel correlation','Localization','Mid/side stereo','Image-position recognition']::text[],ARRAY['Confusing near-coincident with widely spaced omni techniques.','Ignoring the mild comb filtering from the small spacing.','Assuming ORTF is fully mono-compatible like a coincident pair.']::text[],ARRAY['Recording an ensemble with an ORTF pair.','Choosing a stereo technique for a room''s ambience.','Explaining the mix of time and level cues in stereo.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-coincident stereo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72a5c97a-5339-4897-ba89-c9b599a54f39','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72a5c97a-5339-4897-ba89-c9b599a54f39') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72a5c97a-5339-4897-ba89-c9b599a54f39');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86ee59c0-153d-4e62-8199-aa3c1309f565','Negative correlation','Negative correlation between two audio channels means their interchannel correlation coefficient is below zero, indicating the channels tend to move in opposite directions. In the extreme (-1) the channels are polarity-inverted copies that cancel completely when summed to mono, so strong negative correlation is a mono-compatibility warning.','Negative correlation means two channels tend to move oppositely. On a meter the pointer swings below zero. At minus one they fully cancel in mono. So a strongly negative reading warns of lost sound when folded to mono.','It flags out-of-phase content that will weaken or cancel on mono playback, prompting corrective action.','Seeing r = -0.8 on the bass, a technician mono-sums the low end so it does not disappear on a mono club system.','Stereo Metering',ARRAY['Interchannel correlation','Mid/side stereo','Mono compatibility','Polarity inversion','Intensity stereophony']::text[],ARRAY['Confusing negative correlation with simply low level.','Assuming any negative reading is fine and ignoring mono checks.','Treating negative correlation as an absolute polarity fault everywhere.']::text[],ARRAY['Spotting phase problems on a correlation meter.','Protecting a bassline for mono playback.','Diagnosing a widener plug-in pushed too far.']::text[],'Intermediate','r = sum(L_n * R_n) / sqrt(sum(L_n^2) * sum(R_n^2)) ,  r < 0','The correlation coefficient uses the same channel formula as interchannel correlation, and negative correlation is any resulting value below zero.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Negative correlation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86ee59c0-153d-4e62-8199-aa3c1309f565','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86ee59c0-153d-4e62-8199-aa3c1309f565') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86ee59c0-153d-4e62-8199-aa3c1309f565');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1eb8b012-40f6-4b85-9fe5-c462f9218e16','Noise-color identification','Noise-color identification is the trained skill of recognizing types of broadband noise by their spectral balance. White noise has equal power per hertz (flat spectrum), pink noise has equal power per octave (a -3 dB per octave slope), and brown/red noise falls faster (about -6 dB per octave), each with a distinct perceived brightness.','Different noises have different tonal balance. White noise sounds bright and hissy. Pink noise sounds more even and full. Brown noise sounds dull and low. Trained listeners name the color by its brightness.','It links a heard spectral balance to a defined noise type, useful for system testing, ear training and calibration.','Hearing a hissy, treble-heavy test signal, a technician identifies it as white rather than pink noise.','Listening Skills',ARRAY['High-pass and low-pass recognition','Listener training and perceptual learning','Masking recognition','Pink noise','Spectral balance']::text[],ARRAY['Confusing white noise (flat per hertz) with pink noise (flat per octave).','Assuming all noise sounds the same.','Thinking pink noise is simply quieter white noise.']::text[],ARRAY['Choosing pink noise to set system levels.','Ear-training drills on noise types.','Explaining why white noise sounds brighter than pink.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise-color identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1eb8b012-40f6-4b85-9fe5-c462f9218e16','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1eb8b012-40f6-4b85-9fe5-c462f9218e16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1eb8b012-40f6-4b85-9fe5-c462f9218e16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b773be2d-5796-46ef-ab49-5048d01f8bd7','Occlusion effect','The occlusion effect is the increased perceived loudness and boominess of a person''s own low-frequency, bone-conducted sound (such as their voice or chewing) when the ear canal is sealed by an earplug, earmold or insert earphone. Sealing the canal traps low-frequency vibration that would normally escape through the open canal, raising sound pressure at the eardrum, typically below about 1 kHz.','Plug your ear and your own voice sounds boomy and loud. Normally low tones from your body escape the open ear canal. A seal traps them inside. That extra low-frequency pressure is the occlusion effect.','It explains a common complaint with earplugs, hearing aids and in-ear monitors, and guides fit and venting choices.','A technician deep-fits or vents in-ear monitors so a singer''s own voice is less boomy from the occlusion effect.','Auditory System',ARRAY['Middle-ear transfer','Hearing threshold','Bone conduction','In-ear monitors','Ear canal']::text[],ARRAY['Blaming boomy own-voice on the microphone rather than a canal seal.','Assuming a deeper seal always worsens it; a deep bony-canal fit reduces it.','Confusing the occlusion effect with outside-noise leakage.']::text[],ARRAY['Fitting in-ear monitors for a vocalist.','Explaining hearing-aid own-voice boominess.','Choosing vented versus sealed ear tips.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Occlusion effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b773be2d-5796-46ef-ab49-5048d01f8bd7','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b773be2d-5796-46ef-ab49-5048d01f8bd7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b773be2d-5796-46ef-ab49-5048d01f8bd7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83b18d1f-26c2-46be-92e0-80c49486603d','Open and closed pipes','In wind-instrument acoustics, a pipe open at both ends supports standing waves with displacement antinodes at each end and resonates at every integer multiple of a fundamental f1 = v/(2L). A pipe closed at one end has a displacement node at the closed end and an antinode at the open end, so it resonates only at odd multiples of v/(4L) and sounds one octave below an open pipe of equal length.','A pipe open at both ends makes a full set of harmonics. A pipe closed at one end makes only the odd harmonics. The closed pipe also sounds one octave lower for the same length. This is why a clarinet acts like a closed pipe. The pipe length sets the lowest note.','It explains why wind instruments and organ pipes of a given length produce particular pitches and tone colours, and why closed-pipe instruments behave differently from open ones.','A technician tuning organ pipes uses these ratios: an open pipe 0.5 m long gives f1 = 343/(2*0.5) = 343 Hz, while a same-length pipe stopped at one end gives 343/(4*0.5) = 171.5 Hz with odd harmonics only.','Instrument Acoustics',ARRAY['Resonating body','Reed oscillation','Register changes','Resonance identification','Standing wave']::text[],ARRAY['Assuming a closed pipe produces all harmonics; it produces only odd ones.','Forgetting that a closed pipe sounds an octave lower than an open pipe of the same length.','Confusing pressure nodes with displacement nodes at the ends.','Ignoring the end correction, which makes the effective length slightly longer.']::text[],ARRAY['Designing or tuning organ pipes to hit target pitches.','Explaining why a clarinet (closed) overblows a twelfth while a flute (open) overblows an octave.','Predicting the note produced when blowing across a bottle top.']::text[],'Intermediate','Open-open: f_n = n*v/(2L), n = 1,2,3,...   Closed-open: f_n = (2n-1)*v/(4L), n = 1,2,3,...','For a pipe open at both ends, each resonance equals its harmonic number times the speed of sound divided by twice the pipe length. For a pipe closed at one end, resonances occur only at odd multiples of the speed of sound divided by four times the length.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open and closed pipes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83b18d1f-26c2-46be-92e0-80c49486603d','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83b18d1f-26c2-46be-92e0-80c49486603d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83b18d1f-26c2-46be-92e0-80c49486603d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8765e721-16bc-43e9-b153-6ea42fbe379a','Open-string and stopped-string behavior','The fundamental frequency of a string fixed at both ends is set by its sounding length, tension, and mass per unit length. An open string vibrates over its full length; stopping it at a fret or with a finger shortens the sounding length and raises the pitch in inverse proportion to that length.','An open string vibrates along its whole length. Pressing a string down makes the vibrating part shorter. A shorter length gives a higher pitch. Halving the length raises the pitch by one octave. Tighter or lighter strings also sound higher.','It underpins how fretted and bowed string instruments change pitch, letting a player raise a note by shortening the string rather than retuning it.','A guitarist stopping a 0.65 m string exactly halfway (at the 12th fret) halves the sounding length, so the frequency doubles and the note rises one octave above the open string.','Instrument Acoustics',ARRAY['Pluck position and harmonic content','Resonating body','Pickup placement','Piano-string inharmonicity','Register changes']::text[],ARRAY['Thinking pitch rises in direct, not inverse, proportion to length.','Forgetting that tension and string mass also set the frequency.','Assuming a stopped string always sounds duller; timbre depends on pluck point, not stopping.','Believing the fret position adds tension rather than shortening length.']::text[],ARRAY['Setting intonation on a fretted instrument.','Explaining why the 12th fret gives the octave.','Understanding why heavier strings tune lower at the same length.']::text[],'Beginner','f = (1/(2L))*sqrt(T/mu);   stopped length L'' -> f'' = f*(L/L'')','The open-string fundamental equals one over twice the sounding length, times the square root of the tension divided by the mass per unit length. Shortening the string to a new length scales the frequency up by the ratio of the old length to the new length.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open-string and stopped-string behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8765e721-16bc-43e9-b153-6ea42fbe379a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8765e721-16bc-43e9-b153-6ea42fbe379a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8765e721-16bc-43e9-b153-6ea42fbe379a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2dc5418f-fdb7-4ef9-8e47-f651187d5603','Order effects in listening tests','A bias in subjective audio evaluation where the order in which stimuli are presented influences listener ratings, through mechanisms such as anchoring on the first item, adaptation, contrast between neighbours, and fatigue over a session. It is controlled by randomising or counterbalancing presentation order across listeners and trials.','The order you hear things can change how you rate them. The first sample can set a mental anchor. A weak sample can flatter the one right after it. Tiredness late in a test also shifts scores. Randomising the order for each listener removes this bias.','Naming this bias lets test designers guard against it, so results reflect real differences between stimuli rather than the accident of playback order.','When comparing three codecs, a technician randomises the play order for every listener and rotates a reference so no single item always comes first, then averages across the balanced orders.','Listening-Test Method',ARRAY['Sighted versus blind listening','Preference versus detection','Practical significance','Selective attention']::text[],ARRAY['Playing stimuli in the same fixed order for every listener.','Blaming a rating gap on quality when it came from position in the sequence.','Running long sessions without breaks, letting fatigue bias later trials.','Assuming a single trained expert is immune to order effects.']::text[],ARRAY['Designing a codec quality panel.','Running an A/B loudspeaker comparison.','Training a listening panel and checking for sequence bias.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Order effects in listening tests');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2dc5418f-fdb7-4ef9-8e47-f651187d5603','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2dc5418f-fdb7-4ef9-8e47-f651187d5603') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2dc5418f-fdb7-4ef9-8e47-f651187d5603');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ec41828-74bb-4b6d-983a-f72725194868','Outer-ear filtering','The direction- and frequency-dependent shaping of incoming sound by the pinna, concha, and ear canal before it reaches the eardrum. It produces spectral peaks and notches, including a broad ear-canal resonance in the 2.5-4 kHz region that boosts sensitivity there, and contributes to loudness and to vertical and front-back localisation.','The outer ear is not just a funnel; it filters sound. The ear canal adds a boost around three kilohertz. The folds of the ear add peaks and dips higher up. These changes depend on where the sound comes from. The brain uses them to judge direction.','This natural filtering raises hearing sensitivity in the speech range and supplies spectral cues the brain needs to place sounds in elevation and to tell front from back.','A technician designing headphones or a measurement microphone accounts for this: a diffuse-field or free-field target curve compensates for the roughly 10-15 dB ear-canal boost near 3 kHz so tonal balance sounds natural.','Auditory Anatomy',ARRAY['Pinna cues','Room-size perception','Selective attention','Resonance identification']::text[],ARRAY['Treating the outer ear as a flat funnel with no frequency response.','Confusing the fixed ear-canal resonance with direction-dependent pinna notches.','Assuming headphone targets should be flat at the eardrum.','Ignoring that this filtering differs between individuals.']::text[],ARRAY['Choosing a headphone target response.','Explaining why hearing is most sensitive near 3 kHz.','Understanding why closed-eyes elevation judgements rely on outer-ear cues.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Outer-ear filtering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ec41828-74bb-4b6d-983a-f72725194868','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ec41828-74bb-4b6d-983a-f72725194868') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ec41828-74bb-4b6d-983a-f72725194868');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b8d531c5-33d3-46d3-a387-88f2b447856f','Phantom fundamental','The perception of a pitch at a fundamental frequency that is physically weak or absent, evoked by the presence of its higher harmonics whose common spacing the auditory system interprets as the fundamental period. Also called the missing fundamental or residue pitch.','You can hear a bass note even when its lowest tone is missing. The higher harmonics are evenly spaced. The ear reads that spacing as the missing low note. This is why small speakers can seem to reproduce deep bass. The brain fills in the pitch.','It explains how the ear derives a stable low pitch from the pattern of harmonics, so instruments and small speakers convey a bass line even when the true fundamental is weak.','A technician voicing a small speaker relies on this: harmonics at 80, 120, and 160 Hz let a listener perceive a 40 Hz pitch, so the bass line reads even though the driver barely radiates 40 Hz.','Pitch Perception',ARRAY['Resonance identification','Register changes','Selective attention','Room-size perception']::text[],ARRAY['Believing the speaker actually reproduces the missing low fundamental.','Confusing the perceived pitch with a distortion product added by the driver.','Thinking boosting the fundamental band restores what the driver cannot radiate.','Assuming the effect needs the fundamental present at all.']::text[],ARRAY['Explaining perceived bass from small loudspeakers or phones.','Understanding why a bass note''s pitch stays clear when its lowest partial is filtered out.','Discussing psychoacoustic bass-enhancement processors.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phantom fundamental');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b8d531c5-33d3-46d3-a387-88f2b447856f','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b8d531c5-33d3-46d3-a387-88f2b447856f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b8d531c5-33d3-46d3-a387-88f2b447856f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c0be8985-f273-4eba-92ee-ef61343bcd38','Phase-change audibility','The extent to which changing the relative phase of a sound''s components alters its perceived quality. For steady harmonic tones the ear is largely insensitive to the absolute phase of components (Ohm''s acoustic law), but phase changes become audible for closely spaced partials, for transients, and when they alter interaural timing used for localisation.','Shifting the phase of tones often makes little audible difference. Steady musical tones sound about the same after a phase change. But phase matters for sharp transients and for very close tones. It also matters between the two ears, where timing sets direction. So phase can be audible or not, depending on the signal.','Knowing when phase is and is not audible tells engineers where phase accuracy matters (transients, stereo imaging) and where it can be relaxed (steady monaural tones).','A technician judging an all-pass filter or crossover checks transients and stereo image, not just a steady sine, because a phase shift that is inaudible on a held tone may smear a snare hit or shift the image.','Auditory Perception',ARRAY['Phase-difference stereophony','Polarity-error recognition','Phase-scope interpretation','Predelay recognition']::text[],ARRAY['Claiming absolute phase is always inaudible.','Confusing a polarity inversion with a frequency-dependent phase shift.','Ignoring that interaural phase strongly affects low-frequency localisation.','Testing only steady sines and concluding phase never matters.']::text[],ARRAY['Evaluating an all-pass or linear-phase filter.','Judging crossover phase behaviour in a loudspeaker.','Debating whether a phase-rotation plug-in is audible on a mix.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase-change audibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c0be8985-f273-4eba-92ee-ef61343bcd38','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c0be8985-f273-4eba-92ee-ef61343bcd38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c0be8985-f273-4eba-92ee-ef61343bcd38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d48bffd-7174-47c4-844f-1570828f174d','Phase-difference stereophony','Stereo techniques that encode source direction mainly as time or phase differences between the two channels, as produced by spaced-microphone (A-B) arrays. They rely on the ear''s interaural time-difference cue, dominant at low frequencies, to form phantom images, in contrast to level-difference (intensity) stereophony.','This stereo method uses timing between the two channels. Spaced microphones capture a sound at slightly different times. The ear turns those time gaps into a sense of direction. It differs from methods that use only loudness differences. Timing cues work best for low frequencies.','It provides a way to capture width and spaciousness by preserving arrival-time differences between channels, exploiting the ear''s low-frequency timing cue for localisation.','An engineer using a spaced-pair (A-B) recording sets microphone spacing to trade image width against centre stability, knowing the resulting phase differences also affect mono compatibility.','Stereo Technique',ARRAY['Phase-scope interpretation','Phase-change audibility','Polarity-error recognition','Predelay recognition']::text[],ARRAY['Assuming spaced-mic phase differences sum cleanly to mono; they can cause comb filtering.','Confusing interaural time cues (low frequency) with level cues (high frequency).','Thinking wider spacing always improves the image.','Ignoring the effect of channel time differences on downmix.']::text[],ARRAY['Choosing between spaced (A-B) and coincident (X-Y) miking.','Diagnosing mono-compatibility problems in a spaced recording.','Explaining phantom-image formation from timing cues.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase-difference stereophony');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d48bffd-7174-47c4-844f-1570828f174d','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d48bffd-7174-47c4-844f-1570828f174d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d48bffd-7174-47c4-844f-1570828f174d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a6ecf5f-ffa4-4204-886c-6fff51f498e3','Phase-scope interpretation','Reading a phase or vector scope (a goniometer or Lissajous display) that plots the left channel against the right to judge stereo width, mono compatibility, and polarity. A near-vertical trace indicates mono or narrow content, a 45-degree tilt one dominant channel, a broad pattern a wide image, and a horizontal spread signals out-of-phase content that may cancel in mono.','A phase scope draws the left and right signals against each other. A tall, thin line means the sound is nearly mono. A wide, round shape means a broad stereo image. A flat, horizontal shape warns of out-of-phase signals. Those can cancel when the mix is summed to mono.','The display gives engineers a fast visual check of stereo balance and phase problems that could collapse when a mix is played in mono.','While mastering, a technician watches the goniometer: if the trace flattens toward horizontal on the low end, they narrow or mono the bass to protect mono playback.','Metering',ARRAY['Polarity-error recognition','Phase-difference stereophony','Predelay recognition','Phase-change audibility']::text[],ARRAY['Mistaking a wide image for an out-of-phase signal.','Reading the scope without also checking the correlation meter.','Assuming a vertical line is always a fault rather than valid mono content.','Ignoring that the pattern is signal-dependent and moves constantly.']::text[],ARRAY['Checking mono compatibility before broadcast.','Spotting a swapped or inverted channel during setup.','Judging stereo width while mastering.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase-scope interpretation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a6ecf5f-ffa4-4204-886c-6fff51f498e3','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a6ecf5f-ffa4-4204-886c-6fff51f498e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a6ecf5f-ffa4-4204-886c-6fff51f498e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a1eba8b-455d-4e7b-bded-ff9dff7ebdf0','Piano-string inharmonicity','The tendency of a real piano string''s overtones to fall progressively sharp of exact harmonic multiples because the string has bending stiffness. The nth partial frequency is well modelled by f_n = n*f1*sqrt(1 + B*n^2), where B is the inharmonicity coefficient that grows with string stiffness and thickness.','Piano strings are stiff, not perfectly flexible. Because of this stiffness, the overtones drift sharp. Each higher overtone is a little sharper than a simple harmonic. Thicker, shorter bass strings show this most. Tuners stretch the tuning to keep the piano sounding right.','It explains why piano overtones are stretched and why tuners tune octaves slightly wide (stretch tuning) so that partials of different notes agree.','For a string with B = 0.0005 and f1 = 100 Hz, the 8th partial is f8 = 8*100*sqrt(1 + 0.0005*64) = 800*sqrt(1.032) = 812.7 Hz, about 27 cents sharp of a pure 800 Hz eighth harmonic.','Instrument Acoustics',ARRAY['Open-string and stopped-string behavior','Resonating body','Pluck position and harmonic content','Register changes']::text[],ARRAY['Assuming piano partials are exact integer harmonics.','Ignoring that the sharpening grows with the square of the partial number.','Treating stretch tuning as an error rather than a correction for inharmonicity.','Expecting the same B for bass and treble strings.']::text[],ARRAY['Explaining piano stretch tuning to a trainee.','Designing a pitch-detection or auto-tune algorithm for piano.','Understanding why sampled pianos model stretched partials.']::text[],'Advanced','f_n = n*f1*sqrt(1 + B*n^2)','The frequency of the nth partial equals the harmonic number times the fundamental, all multiplied by the square root of one plus the inharmonicity coefficient times the square of the harmonic number.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piano-string inharmonicity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a1eba8b-455d-4e7b-bded-ff9dff7ebdf0','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a1eba8b-455d-4e7b-bded-ff9dff7ebdf0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a1eba8b-455d-4e7b-bded-ff9dff7ebdf0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4dca9711-8c0a-4e0b-9f63-f7208575b723','Pickup placement','The position of a magnetic or piezo pickup along a vibrating string determines which harmonics it senses strongly, because a pickup located at a node of a given harmonic captures little of that harmonic. Bridge pickups, near a point where many low harmonics have small motion, emphasise higher harmonics for a brighter tone, while neck pickups sense more low-harmonic motion for a warmer tone.','Where a pickup sits under the string changes its tone. A pickup near the bridge hears more high harmonics, so it sounds bright. A pickup near the neck hears more low harmonics, so it sounds warm. This is because a harmonic barely moves at its nodes. The pickup senses whatever motion is above it.','It lets instrument builders and players shape tone by choosing pickup position, giving distinct bright and warm voices without changing the strings.','A technician chasing a thinner, brighter guitar sound selects the bridge pickup or moves an adjustable pickup toward the bridge, where string motion favours higher harmonics.','Instrument Pickup',ARRAY['Pluck position and harmonic content','Open-string and stopped-string behavior','Resonating body','Piano-string inharmonicity']::text[],ARRAY['Believing only the pickup type, not its position, sets the tone.','Ignoring that a pickup at a harmonic''s node captures little of that harmonic.','Forgetting that pickup height also changes level and tone.','Assuming neck and bridge pickups differ only in output level.']::text[],ARRAY['Selecting bridge versus neck pickup for a part.','Positioning a pickup during an instrument build.','Explaining tone differences between guitar pickup positions.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pickup placement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4dca9711-8c0a-4e0b-9f63-f7208575b723','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4dca9711-8c0a-4e0b-9f63-f7208575b723') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4dca9711-8c0a-4e0b-9f63-f7208575b723');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47cf1e2f-6b4d-4ecc-bf97-36378953f418','Pinna cues','Spectral cues created when sound reflects and diffracts off the folds of the pinna (outer ear), producing elevation- and front/back-dependent peaks and notches, notably notches that move through the 6-10 kHz region with source elevation. The brain uses these cues to localise sound, especially in the median plane where left-right interaural cues are ambiguous.','The folds of the outer ear reshape a sound''s tone colour. The change depends on where the sound comes from. Sounds from above and below make different peaks and dips. The brain reads these to judge height and front versus back. Both ears can share the same timing, so these cues fill the gap.','Pinna cues let a listener judge elevation and resolve front-back confusion, where the two-ear time and level differences alone cannot tell direction.','A technician building binaural or headphone spatial audio applies each listener''s head-related transfer function so pinna notches are reproduced, otherwise elevation and front-back cues collapse and sources seem stuck inside the head.','Localization Cue',ARRAY['Outer-ear filtering','Room-size perception','Sound-field rotation','Scene-based audio']::text[],ARRAY['Assuming direction comes only from left-right differences between the ears.','Ignoring that pinna cues are highly individual.','Expecting good elevation from generic head-related transfer functions.','Confusing pinna notches with room reflections.']::text[],ARRAY['Designing binaural rendering for headphones.','Explaining front-back confusion in localisation.','Understanding why blocked or altered ears harm elevation judgement.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pinna cues');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47cf1e2f-6b4d-4ecc-bf97-36378953f418','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47cf1e2f-6b4d-4ecc-bf97-36378953f418') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47cf1e2f-6b4d-4ecc-bf97-36378953f418');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'adab28cb-daa3-41e4-a0e6-ab31342f8cea','Pluck position and harmonic content','Plucking a string at a fraction of its length suppresses harmonics that have a node at the pluck point and emphasises others, so plucking near the bridge (a small fraction of the length) yields a bright, harmonic-rich tone, while plucking near the centre gives a mellow tone dominated by low harmonics. The nth mode''s initial amplitude scales with sin(n*pi*beta)/n^2 for a pluck at fractional position beta.','Where you pluck a string changes its tone. Plucking near the middle sounds soft and round. Plucking near the bridge sounds bright and sharp. A harmonic with a node at the pluck point is silenced. So the pluck point decides which harmonics ring.','It lets players and engineers control timbre by choosing the pluck or strike point, without changing the instrument or strings.','Plucking exactly at the midpoint (beta = 1/2) makes sin(n*pi/2) zero for every even n, so the 2nd, 4th, and 6th harmonics vanish and the tone is hollow and mellow.','Instrument Acoustics',ARRAY['Pickup placement','Open-string and stopped-string behavior','Resonating body','Piano-string inharmonicity']::text[],ARRAY['Thinking pluck strength, not position, sets the timbre.','Forgetting that a harmonic with a node at the pluck point is not excited.','Assuming near-bridge plucking is louder rather than brighter.','Ignoring that higher harmonics fall off with the square of their number.']::text[],ARRAY['Explaining bright sul ponticello versus mellow sul tasto tone.','Coaching pick placement for a desired guitar tone.','Modelling plucked-string synthesis.']::text[],'Intermediate','a_n proportional to sin(n*pi*beta) / n^2','The initial amplitude of the nth harmonic is proportional to the sine of the harmonic number times pi times the fractional pluck position, divided by the square of the harmonic number.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pluck position and harmonic content');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'adab28cb-daa3-41e4-a0e6-ab31342f8cea','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='adab28cb-daa3-41e4-a0e6-ab31342f8cea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='adab28cb-daa3-41e4-a0e6-ab31342f8cea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd35c0c5-864b-4c4b-b3e4-542228f4796e','Polarity-error recognition','The skill of detecting when one signal path is inverted in polarity relative to another (a broadband sign flip, often from a swapped balanced-line conductor). When the two paths are summed it is heard as thin, weak bass and a vague, unstable centre image, and is confirmed with a correlation or phase meter or by listening in mono.','A polarity error means one signal is flipped in sign. When it mixes with a normal signal, the two partly cancel. The result sounds thin, with weak bass and a blurry centre. You can spot it by summing to mono. A correlation meter also reveals it.','Catching a polarity error prevents bass loss and image collapse that appear when channels are summed, which is common on mono playback systems.','A technician who hears a thin, hollow kick drum on a two-mic setup flips the polarity switch on one preamp; if the low end fills in, one microphone was wired or phased inverted.','Listening Skill',ARRAY['Phase-scope interpretation','Phase-change audibility','Phase-difference stereophony','Predelay recognition']::text[],ARRAY['Confusing polarity inversion (broadband sign flip) with a time or phase delay.','Assuming one inverted microphone is inaudible until the channels are summed.','Fixing polarity by adding delay instead of flipping the sign.','Believing a polarity flip changes the sound of a single isolated channel.']::text[],ARRAY['Checking a multi-microphone drum setup.','Diagnosing weak bass when a stereo mix is summed to mono.','Tracing a miswired balanced cable.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polarity-error recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd35c0c5-864b-4c4b-b3e4-542228f4796e','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd35c0c5-864b-4c4b-b3e4-542228f4796e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd35c0c5-864b-4c4b-b3e4-542228f4796e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c5ed894-018c-42a5-bcdc-d844e67ecfce','Practical significance','The judgment of whether a measured or statistically significant difference is large enough to matter perceptually or operationally, as opposed to statistical significance, which only indicates a result is unlikely to be due to chance. A tiny difference can be statistically significant with a large sample yet have no audible or practical consequence.','A result can be statistically real but still too small to matter. Statistics only tell you a difference is probably not random. They do not tell you the difference is big enough to hear. With many listeners, even trivial gaps pass the test. You must ask if the difference actually matters.','It keeps evaluators from over-reacting to small but statistically detectable differences, focusing decisions on effects large enough to hear or to affect a product.','If a codec scores 0.1 higher on a 100-point scale with p < 0.05 over 200 listeners, a technician checks the effect size and audibility before claiming the codecs sound meaningfully different.','Evaluation Concept',ARRAY['Preference versus detection','Order effects in listening tests','Sighted versus blind listening','Selective attention']::text[],ARRAY['Treating a low p-value as proof the difference is audible or important.','Ignoring effect size and reporting only significance.','Letting a very large sample turn trivial gaps into ''significant'' findings.','Confusing statistical with practical significance.']::text[],ARRAY['Interpreting a large listening-test dataset.','Deciding whether a measured improvement justifies a design change.','Reporting results to non-technical stakeholders.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Practical significance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c5ed894-018c-42a5-bcdc-d844e67ecfce','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c5ed894-018c-42a5-bcdc-d844e67ecfce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c5ed894-018c-42a5-bcdc-d844e67ecfce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55e4d155-a3d9-45bb-a8eb-918f92e87ead','Predelay recognition','The ability to hear the short gap, typically about 10-100 ms, between a direct sound and the onset of its reverberation tail. Setting this predelay lets a mix engineer preserve transient clarity and control perceived source distance and room size without smearing the direct sound.','Predelay is the small gap before reverb starts. It separates the dry sound from its tail. A short gap glues the reverb to the source. A longer gap keeps vocals clear and up front. Too long, and it turns into a distinct echo.','Recognising predelay lets an engineer keep a source clear and set its sense of distance and space, using the gap the ear reads as the delay before a room responds.','On a lead vocal, a technician sets around 30 ms of reverb predelay so consonants stay crisp and the voice sits forward, then lengthens it for a bigger, more distant impression.','Listening Skill',ARRAY['Reverb-time recognition','Room-size perception','Phase-difference stereophony','Resonance identification']::text[],ARRAY['Confusing predelay with reverb decay time.','Setting predelay so long it becomes an audible slap echo.','Assuming predelay only changes room size and not clarity.','Ignoring predelay when a mix sounds cluttered.']::text[],ARRAY['Dialling in vocal reverb in a mix.','Creating a sense of distance for a source.','Keeping transients clear while adding space.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Predelay recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55e4d155-a3d9-45bb-a8eb-918f92e87ead','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55e4d155-a3d9-45bb-a8eb-918f92e87ead') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55e4d155-a3d9-45bb-a8eb-918f92e87ead');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66a38236-598c-4ff7-84ce-39a9eedddda2','Preference versus detection','A distinction in listening tests between detecting whether two stimuli differ at all (a discrimination task, such as ABX) and preferring one over another (a hedonic, affective judgment). A difference must first be detectable before a reliable preference can exist, and the two tasks ask fundamentally different questions of the listener.','Detecting a difference is not the same as liking one better. A detection test asks: can you tell them apart? A preference test asks: which do you like more? You cannot truly prefer sounds you cannot even tell apart. Good tests keep these two questions separate.','Separating the two prevents false claims, so a preference is only trusted once a difference has been shown to be audible.','Before running a preference vote on two cables, a technician first runs a blind ABX detection test; if listeners cannot detect a difference, a preference result is not meaningful.','Listening-Test Method',ARRAY['Sighted versus blind listening','Order effects in listening tests','Practical significance','Selective attention']::text[],ARRAY['Reporting a preference when the difference was never shown to be detectable.','Treating ''sounds better'' as proof that a difference exists.','Using a preference test to establish audibility.','Mixing detection and preference questions in one trial.']::text[],ARRAY['Deciding which test type a claim requires.','Evaluating whether two components sound different at all.','Designing a two-stage audibility-then-preference study.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Preference versus detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66a38236-598c-4ff7-84ce-39a9eedddda2','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66a38236-598c-4ff7-84ce-39a9eedddda2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66a38236-598c-4ff7-84ce-39a9eedddda2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '536aec07-e6be-46d0-b0d3-ca7c358eadf3','Q-factor recognition','Recognising, by ear or on an analyser, how narrow or broad a filter or resonance is. The quality factor Q equals a resonance''s centre frequency divided by its -3 dB bandwidth, so a high Q is a sharp, narrow peak or notch and a low Q is a broad, gentle one.','Q describes how narrow a filter or resonance is. A high Q is sharp and focused. A low Q is broad and gentle. You find it by dividing the centre frequency by the width. A narrow ringing tone points to high Q.','Knowing Q lets an engineer pick the right filter width, using narrow high-Q cuts to remove a single problem tone and broad low-Q moves for musical tonal shaping.','A resonance centred at 1000 Hz with a -3 dB bandwidth of 100 Hz has Q = 1000/100 = 10 (narrow); widening the band to 1000 Hz drops Q to 1, a broad, musical shape.','Equalization',ARRAY['Resonance identification','Resonating body','Reverb-time recognition','Room-size perception']::text[],ARRAY['Confusing high Q (narrow) with high gain.','Forgetting Q is defined by the -3 dB bandwidth.','Using a broad low-Q cut to fix a single narrow resonance.','Assuming the same Q sounds equally wide at low and high centre frequencies.']::text[],ARRAY['Setting equaliser bandwidth to notch feedback.','Describing a filter''s sharpness in a spec.','Identifying a ringing room mode by its narrowness.']::text[],'Intermediate','Q = f0 / (f2 - f1) = f0 / BW','The quality factor equals the centre frequency divided by the bandwidth, where the bandwidth is the distance between the two frequencies that are three decibels down from the peak.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Q-factor recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '536aec07-e6be-46d0-b0d3-ca7c358eadf3','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='536aec07-e6be-46d0-b0d3-ca7c358eadf3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='536aec07-e6be-46d0-b0d3-ca7c358eadf3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82209ba9-f9f4-4a99-99ce-0c716a1e42f9','Quantization-distortion recognition','Identifying the audible artefacts of quantisation in digital audio - a granular, signal-correlated distortion on low-level or decaying signals rather than smooth random noise - which arises when each sample''s amplitude is rounded to the nearest available level. The theoretical best-case signal-to-quantisation-noise ratio for an N-bit uniform quantiser on a full-scale sine is about 6.02N + 1.76 dB.','Quantisation rounds each sample to a fixed level. On quiet or fading sounds this rounding is audible. It sounds gritty and tied to the signal, not like smooth hiss. More bits give a lower, quieter error. Dither turns this ugly distortion into gentle noise.','Recognising it tells an engineer when bit depth or dithering is inadequate, since the error is worst on the quiet passages where it is most exposed.','A 16-bit uniform quantiser gives a best-case ratio of 6.02*16 + 1.76 = 98.1 dB; if a fade-out sounds gritty, the technician adds dither so the error becomes benign noise instead of correlated distortion.','Digital Audio',ARRAY['Phase-change audibility','Resonance identification','Q-factor recognition','Room-size perception']::text[],ARRAY['Confusing raw quantisation distortion with the noise added by dither.','Thinking adding bits changes the 1.76 dB constant rather than the 6.02N term.','Assuming quantisation error is always inaudible.','Expecting the error to sound like smooth hiss rather than signal-tied distortion.']::text[],ARRAY['Choosing bit depth for a recording or bounce.','Deciding when to apply dither.','Diagnosing grit on a quiet fade-out.']::text[],'Advanced','SQNR_max (dB) = 6.02*N + 1.76','The best-case signal-to-quantisation-noise ratio in decibels, for a full-scale sine wave in a uniform quantiser, is about six point zero two times the number of bits, plus one point seven six.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quantization-distortion recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82209ba9-f9f4-4a99-99ce-0c716a1e42f9','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82209ba9-f9f4-4a99-99ce-0c716a1e42f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82209ba9-f9f4-4a99-99ce-0c716a1e42f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18ef8ff3-2b9d-4d47-a2f3-c297822e6a4e','Reed oscillation','The self-sustained vibration of a cane or synthetic reed in woodwind instruments, in which airflow through the narrow reed opening couples with the instrument''s air column. Pressure feedback from the column opens and closes the reed once per cycle, and the reed acts as a pressure-controlled valve whose oscillation frequency is governed mainly by the air column rather than by the reed''s own natural frequency.','A reed is a springy flap driven by the player''s breath. Air pressure inside the instrument opens and closes it. This happens over and over, sustaining a steady tone. The air column, not the reed alone, mostly sets the pitch. The reed works like a fast valve.','It explains how a small breath-driven reed keeps a woodwind''s air column vibrating, turning steady breath into a sustained musical tone.','A technician troubleshooting a squeaking clarinet checks reed strength and embouchure, because a mismatched reed can lock onto its own resonance instead of following the air column.','Instrument Acoustics',ARRAY['Open and closed pipes','Register changes','Resonating body','Resonance identification']::text[],ARRAY['Thinking the reed''s own resonance sets the note; the air column dominates.','Confusing single-reed and double-reed valve action.','Ignoring that the reed-airflow coupling is nonlinear.','Assuming a stiffer reed simply plays higher in pitch.']::text[],ARRAY['Diagnosing a woodwind squeak.','Explaining why clarinets and saxophones behave like closed pipes.','Modelling reed instruments in physical-modelling synthesis.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reed oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18ef8ff3-2b9d-4d47-a2f3-c297822e6a4e','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18ef8ff3-2b9d-4d47-a2f3-c297822e6a4e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18ef8ff3-2b9d-4d47-a2f3-c297822e6a4e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc19bb9e-c5a8-44d0-93b1-a3eb00060c7d','Register changes','Audible shifts in tone quality and vibratory behaviour as a sound source moves between operating ranges - for example a clarinet overblowing a twelfth into its next register, or a singer transitioning between chest and head voice. They occur because a different resonance or harmonic becomes dominant across the change.','A register change is a jump between an instrument''s or voice''s ranges. The tone colour shifts noticeably at the change. A clarinet jumps up by a twelfth, not an octave. A singer may shift from chest to head voice. The change happens because a different resonance takes over.','Understanding register changes explains why timbre and playing technique shift across an instrument''s or singer''s range, and where awkward transition points lie.','A technician miking a clarinet expects a tonal shift across the register break near the throat notes and may adjust microphone position so both registers stay even in level and tone.','Instrument Acoustics',ARRAY['Open and closed pipes','Reed oscillation','Resonating body','Resonance identification']::text[],ARRAY['Expecting a clarinet to overblow an octave like a flute rather than a twelfth.','Treating vocal registers as purely learned rather than physical.','Ignoring the register break, or passaggio, when balancing a recording.','Assuming register changes are simply changes in loudness.']::text[],ARRAY['Miking a clarinet across its register break.','Coaching a singer through the passaggio.','Explaining timbre shifts across an instrument''s range.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Register changes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc19bb9e-c5a8-44d0-93b1-a3eb00060c7d','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc19bb9e-c5a8-44d0-93b1-a3eb00060c7d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc19bb9e-c5a8-44d0-93b1-a3eb00060c7d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a6caaa7-e4df-4255-aa7d-a5a750aebd4e','Resonance identification','The skill of locating a resonant frequency - a frequency at which a room, instrument body, or system responds with a pronounced amplitude peak and audible ringing - by ear or with a swept tone or analyser, in order to tame or exploit it.','A resonance is a frequency that rings and stands out. Resonance identification means finding that frequency. You can sweep a tone until one note jumps out. An analyser shows it as a tall peak. Once found, you can cut it or use it.','Finding resonances lets an engineer control problem peaks and ringing in rooms, instruments, and systems, improving clarity and tone.','To find a boomy room mode, a technician sweeps a sine slowly; the frequency where the level jumps and lingers is the resonance, which they then treat or notch with a narrow filter.','Listening Skill',ARRAY['Q-factor recognition','Resonating body','Reverb-time recognition','Room-size perception']::text[],ARRAY['Confusing a room mode with a fault in the source or speaker.','Boosting a band to find a resonance, then forgetting to switch to a cut.','Mistaking a broad tonal tilt for a narrow resonance.','Assuming one measurement position reveals all room resonances.']::text[],ARRAY['Hunting a boomy room mode.','Finding a ringing frequency in a drum or guitar body.','Ringing out a PA system before a show.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonance identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a6caaa7-e4df-4255-aa7d-a5a750aebd4e','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a6caaa7-e4df-4255-aa7d-a5a750aebd4e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a6caaa7-e4df-4255-aa7d-a5a750aebd4e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e336607-8eaa-4fbc-a1fc-dd8406f1370d','Resonating body','A structure - such as a guitar''s soundboard and box, a violin body, or a drum shell - that is set into vibration by a driver like a string, reed, or membrane, and radiates sound far more efficiently than the driver alone. Its own resonances shape the instrument''s loudness and timbre.','A thin string moves very little air by itself. A resonating body couples that motion to a larger surface. This surface pushes air far better, so the sound is louder. The body''s own resonances colour the tone. It does not add energy; it radiates it better.','The resonating body lets a small driver produce a loud, tonally rich sound by improving how efficiently vibration is turned into radiated air motion.','A technician comparing two acoustic guitars listens for how each body''s resonances favour certain notes, and mikes over the body, not just the strings, to capture that radiated tone.','Instrument Acoustics',ARRAY['Resonance identification','Open and closed pipes','Pickup placement','Snare-wire response']::text[],ARRAY['Thinking the body amplifies energy rather than radiating it more efficiently.','Ignoring the air (Helmholtz) resonance of a hollow body.','Assuming a bigger body is always louder.','Treating all body resonances as flaws to remove.']::text[],ARRAY['Comparing the tone of two acoustic instruments.','Choosing microphone position over an instrument body.','Explaining why a solid-body electric guitar is quiet unamplified.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonating body');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e336607-8eaa-4fbc-a1fc-dd8406f1370d','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e336607-8eaa-4fbc-a1fc-dd8406f1370d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e336607-8eaa-4fbc-a1fc-dd8406f1370d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5fd3843-f160-46d5-800a-b42299b0ff13','Reverb-time recognition','Judging the reverberation time (RT60) - the time for a room''s sound to decay by 60 dB after the source stops - by ear or by measurement. The Sabine equation estimates it as RT60 = 0.161*V/A in metric units, where V is room volume and A is the total absorption in sabins.','Reverb time is how long a room keeps ringing after a sound stops. It is measured as the time to drop by sixty decibels. Big, hard rooms ring for a long time. Soft, absorbent rooms fall silent fast. Sabine''s formula estimates it from room size and absorption.','Estimating reverb time lets engineers match a space to its use - short for speech clarity, longer for music - and set artificial reverb to sound believable.','For a 200 cubic-metre room with 40 metric sabins of absorption, RT60 = 0.161*200/40 = 0.81 s, a reasonable value for a small live room but too long for a speech studio.','Room Acoustics',ARRAY['Room-size perception','Predelay recognition','Resonance identification','Resonating body']::text[],ARRAY['Confusing reverb time with predelay or with echo.','Forgetting RT60 is defined by a 60 dB decay.','Using the metric constant (0.161) with volumes measured in feet.','Assuming Sabine''s formula is exact in very absorptive or oddly shaped rooms.']::text[],ARRAY['Estimating whether a room suits speech or music.','Specifying acoustic treatment to hit a target reverb time.','Setting a plate or hall reverb decay to match a real space.']::text[],'Intermediate','RT60 = 0.161 * V / A   (SI units);  A = sum of S_i * alpha_i','The reverberation time in seconds equals the constant zero point one six one times the room volume in cubic metres, divided by the total absorption in metric sabins. The total absorption is the sum of each surface area times its absorption coefficient.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverb-time recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5fd3843-f160-46d5-800a-b42299b0ff13','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5fd3843-f160-46d5-800a-b42299b0ff13') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5fd3843-f160-46d5-800a-b42299b0ff13');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '293039aa-8313-42b1-abeb-d4f7707f170c','Room-size perception','The auditory impression of how large a space is, cued mainly by the time delay and pattern of early reflections, the predelay before reverberation, and the reverberation time and level. These cues let a listener sense a small room versus a large hall even with the eyes closed.','Your ears can judge a room''s size without looking. Early echoes that arrive quickly suggest a small room. Longer gaps and long reverb suggest a big hall. The pattern of reflections carries this information. The brain reads it to sense the space.','It explains how listeners sense the size of a space, and guides engineers who want a recording or reverb to convey a particular room scale.','To make a track feel like a large hall, a technician lengthens reverb predelay and decay and spaces the early reflections wider, cueing the ear toward a bigger space.','Spatial Perception',ARRAY['Predelay recognition','Reverb-time recognition','Outer-ear filtering','Resonance identification']::text[],ARRAY['Equating loudness with room size.','Ignoring early reflections and judging size from reverb tail alone.','Confusing predelay with reverb decay time.','Assuming a single cue, not a combination, sets the impression.']::text[],ARRAY['Designing reverb to suggest a specific room scale.','Explaining why a recording feels large or small.','Understanding blindfolded judgements of room size.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room-size perception');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '293039aa-8313-42b1-abeb-d4f7707f170c','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='293039aa-8313-42b1-abeb-d4f7707f170c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='293039aa-8313-42b1-abeb-d4f7707f170c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c69ababa-0f2e-40b7-a09f-9b615c3df794','Scene-based audio','A next-generation-audio representation that encodes an entire sound field as a set of spatial basis-function signals, typically Higher Order Ambisonics, rather than as discrete channels or objects. The scene is therefore independent of the playback loudspeaker layout and can be rotated and rendered to any speaker or headphone setup. It is carried within MPEG-H 3D Audio (ISO/IEC 23008-3) and described by the ITU-R BS.2076 Audio Definition Model.','Scene-based audio stores the whole sound field, not fixed channels. It uses a set of spatial signals called Ambisonics. The mix does not assume any speaker layout. A renderer maps it to any speakers or headphones. It can also be rotated as a whole.','It lets one immersive mix play back correctly on many different systems and adapt to head movement, which suits virtual reality, 360-degree video, and next-generation broadcast.','A technician delivering VR audio authors a Higher Order Ambisonics scene, then lets the player rotate and render it to the user''s headphones as they turn their head, without re-mixing for each layout.','Spatial Audio Format',ARRAY['Sound-field rotation','Pinna cues','Phase-difference stereophony','Room-size perception']::text[],ARRAY['Confusing scene-based (Ambisonics) with object-based or channel-based audio.','Thinking Ambisonics is limited to first order.','Assuming a scene needs one fixed speaker layout.','Believing higher order gives no benefit in spatial resolution.']::text[],ARRAY['Authoring immersive audio for VR or 360 video.','Delivering one mix that renders to many playback systems.','Combining scene-based beds with audio objects in next-generation audio.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scene-based audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c69ababa-0f2e-40b7-a09f-9b615c3df794','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c69ababa-0f2e-40b7-a09f-9b615c3df794') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c69ababa-0f2e-40b7-a09f-9b615c3df794');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a8ae59e-974b-4db1-a453-1895e57c7259','Selective attention','The auditory system''s ability to focus on one sound source, such as a single talker, while suppressing competing sounds - the cocktail-party effect. It exploits cues such as spatial location, pitch, timbre, and level differences to segregate the target stream from the background.','In a noisy room you can still follow one voice. Your hearing locks onto that talker and pushes the rest back. It uses direction, pitch, and tone to pick the voice out. This is called the cocktail-party effect. It works best when the target sounds different from the noise.','It explains how listeners follow one source in a crowd, and why systems that preserve spatial and spectral cues help intelligibility in noise.','A technician mixing dialogue in a busy scene pans and equalises voices so they differ in space and tone from the background, helping listeners'' selective attention lock onto the target line.','Auditory Perception',ARRAY['Order effects in listening tests','Pinna cues','Outer-ear filtering','Room-size perception']::text[],ARRAY['Thinking selective attention physically removes the background sound.','Ignoring the role of two-ear spatial cues in separating sources.','Assuming it works equally well for all listeners and hearing losses.','Confusing attention with simple loudness of the target.']::text[],ARRAY['Mixing dialogue against noisy backgrounds.','Explaining why hearing loss makes crowded rooms hard.','Designing conferencing systems that keep spatial cues.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Selective attention');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a8ae59e-974b-4db1-a453-1895e57c7259','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a8ae59e-974b-4db1-a453-1895e57c7259') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a8ae59e-974b-4db1-a453-1895e57c7259');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96b7bed5-50ab-43c7-8882-2e6de4e7b03d','Shepard tones','An auditory illusion of an endlessly rising or falling pitch, created by superimposing tones spaced an octave apart whose amplitudes follow a fixed bell-shaped spectral envelope. As the set glides upward the highest components fade out while new low ones fade in, so pitch class cycles without any net change.','A Shepard tone seems to rise forever without getting higher. It stacks tones one octave apart. A fixed loudness curve keeps the top and bottom soft. As it climbs, high tones fade out and low tones fade in. The ear hears endless rising with no real change.','It demonstrates that pitch has a circular (pitch-class) dimension, and it is used to create tension and endless-motion effects in sound design and film scoring.','A sound designer builds a Shepard-tone glide under a film chase to create a sense of endlessly rising tension, keeping the fixed spectral envelope so no octave ever seems to jump.','Auditory Illusion',ARRAY['Phantom fundamental','Register changes','Selective attention','Resonance identification']::text[],ARRAY['Believing the pitch actually rises without limit.','Confusing a Shepard glide with an ordinary rising glissando.','Ignoring that the fixed spectral envelope is essential to the illusion.','Assuming the octave spacing can be changed freely without breaking it.']::text[],ARRAY['Scoring endless-tension effects in film.','Demonstrating pitch circularity in a psychoacoustics class.','Designing risers in electronic music.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shepard tones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96b7bed5-50ab-43c7-8882-2e6de4e7b03d','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96b7bed5-50ab-43c7-8882-2e6de4e7b03d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96b7bed5-50ab-43c7-8882-2e6de4e7b03d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '870dbc9b-86d3-4c12-b614-9b3f3c301f4c','Sighted versus blind listening','The contrast between listening tests where the listener knows the identity of the equipment or condition (sighted) and those where that information is hidden (blind, such as ABX or double-blind). Blind testing removes expectation and brand bias, so reported differences reflect audible differences rather than non-auditory influences.','In a sighted test you know which device you are hearing. That knowledge can bias what you think you hear. In a blind test the identity is hidden. This removes expectation and brand bias. What remains is closer to a true audible difference.','Blind testing lets evaluators separate real audible differences from expectation and bias, giving trustworthy evidence for or against a claim.','Before endorsing a preamp''s sound, a technician runs a level-matched, double-blind comparison; if listeners cannot pick it out blind, the sighted impressions were likely bias, not audible difference.','Listening-Test Method',ARRAY['Preference versus detection','Order effects in listening tests','Practical significance','Selective attention']::text[],ARRAY['Trusting sighted impressions as proof of an audible difference.','Failing to match levels between the conditions being compared.','Using too small a panel or no statistics.','Assuming trained experts do not need blinding.']::text[],ARRAY['Testing whether two amplifiers sound different.','Removing brand bias from a component evaluation.','Designing a credible audio comparison for publication.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sighted versus blind listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '870dbc9b-86d3-4c12-b614-9b3f3c301f4c','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='870dbc9b-86d3-4c12-b614-9b3f3c301f4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='870dbc9b-86d3-4c12-b614-9b3f3c301f4c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2311045d-a27a-4765-be4e-41fa205a87d7','Snare-wire response','The behaviour of the metal snare wires (snares) stretched across a snare drum''s bottom head, which rattle against that head when the drum is struck or when nearby sound excites it, adding the drum''s characteristic bright, noisy snap. Their tension and contact with the head set the sensitivity, sustain, and amount of buzz.','Snare wires are coiled metal strands under the bottom drumhead. When the drum is hit, they rattle against the head. This adds the sharp, buzzy snap of a snare drum. Their tension sets how sensitive and buzzy they are. Loud nearby sounds can also set them buzzing.','The snare wires give the snare drum its defining crisp, noisy character, and their adjustment controls how tight, sensitive, or buzzy that sound is.','A technician getting a rattly, over-buzzing snare loosens the wire tension slightly or gates the microphone, since over-tight wires choke the response while nearby toms can trigger sympathetic buzz.','Instrument Acoustics',ARRAY['Resonating body','Resonance identification','Reed oscillation','Pluck position and harmonic content']::text[],ARRAY['Over-tightening the wires, which chokes rather than crisps the sound.','Ignoring sympathetic buzz triggered by other instruments.','Thinking the snares sit on the top (batter) head rather than the bottom.','Blaming the microphone for buzz that is really loose sympathetic snares.']::text[],ARRAY['Tuning a snare drum''s wire tension.','Reducing sympathetic snare buzz on a drum kit.','Miking and gating a snare in a live mix.']::text[],'Beginner',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Snare-wire response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2311045d-a27a-4765-be4e-41fa205a87d7','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2311045d-a27a-4765-be4e-41fa205a87d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2311045d-a27a-4765-be4e-41fa205a87d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2b6bc9c-c0b2-43e1-ae38-7a0d41b681e2','Sound-field rotation','Rotating an entire captured or synthesised sound scene around the listener. In the Ambisonics or Higher Order Ambisonics (scene-based) domain this is done cleanly as a matrix operation applied to the spatial components, and it is used to align a recording to picture or to follow a virtual-reality listener''s head movement.','Sound-field rotation turns a whole scene around the listener. In Ambisonics it is a simple matrix step on the spatial channels. Every source turns together, keeping their relative positions. It is used to match audio to picture. It also follows a VR user''s head as they turn.','It lets an engineer re-orient an immersive scene after capture, keeping audio locked to the visual world or to a moving head without re-recording.','For a 360 video whose camera faced the wrong way, a technician applies a yaw rotation to the Ambisonics scene so the sound turns with the picture, all as one matrix on the spatial channels.','Spatial Audio Processing',ARRAY['Scene-based audio','Pinna cues','Phase-difference stereophony','Room-size perception']::text[],ARRAY['Confusing rotating the whole field with panning one source.','Thinking rotation requires re-recording the scene.','Assuming rotation degrades quality when done in a proper Ambisonics format.','Ignoring that low Ambisonic order limits spatial sharpness after rotation.']::text[],ARRAY['Aligning Ambisonic audio to 360 video.','Head-tracking playback in virtual reality.','Re-orienting an immersive field in post-production.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field rotation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2b6bc9c-c0b2-43e1-ae38-7a0d41b681e2','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2b6bc9c-c0b2-43e1-ae38-7a0d41b681e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2b6bc9c-c0b2-43e1-ae38-7a0d41b681e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3fe9ee3b-e9d5-4dd2-b2d7-d34114339afb','Sound-field translation','The re-computation of a captured or synthesized sound field so it is correct for a listening position that differs from the original capture point, letting a listener move within the scene. In object- and scene-based spatial audio it underlies six-degrees-of-freedom (6DoF) rendering, where changing listener position alters the level, delay and direction of each source.','A sound field is the pattern of sound around a point. Translation moves that pattern to a new listening spot. Sources then grow louder, softer, or shift direction as you move. This lets a listener walk around inside a virtual scene. It is key for VR and 6DoF audio.','It lets spatial-audio systems present a consistent scene from many positions, so listeners in VR or AR can move and hear the scene update naturally.','A VR audio engineer enables sound-field translation so a user stepping toward a virtual violin hears it grow louder and shift to the correct angle.','Spatial Audio',ARRAY['Spherical harmonics','Time-difference stereophony','Sum-and-difference matrices','Binaural rendering','Ambisonics']::text[],ARRAY['Assuming one Ambisonic recording is automatically correct at any position; low-order fields degrade quickly away from the sweet spot.','Confusing rotation of a sound field (head turning) with translation (moving through space).','Ignoring that translation needs distance and depth information the original capture may not contain.']::text[],ARRAY['Rendering 6DoF audio for a VR walkthrough.','Reproducing an ambisonic scene for a listener who leaves the sweet spot.','Designing a museum exhibit where visitors move among virtual sources.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field translation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3fe9ee3b-e9d5-4dd2-b2d7-d34114339afb','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3fe9ee3b-e9d5-4dd2-b2d7-d34114339afb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3fe9ee3b-e9d5-4dd2-b2d7-d34114339afb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0745f1f2-f5a3-491b-9f74-2f37a5aa725a','Soundboard coupling','The mechanical transfer of vibrational energy from a string (or other primary vibrator) to a large radiating plate such as a piano soundboard or guitar top, which then couples that energy efficiently to the surrounding air. Coupling strength shapes loudness and tone and how quickly the string''s energy decays.','A vibrating string alone moves very little air. A soundboard is a thin, wide plate joined to the string. The string shakes the board, and the board pushes lots of air. This makes the instrument loud enough to hear. Stronger coupling means louder sound but faster decay.','It exists because thin strings radiate sound poorly; the soundboard acts as an impedance-matching radiator that turns string motion into audible acoustic power.','A technician diagnosing a dull-sounding guitar checks the bridge-to-top coupling, since a loose or overbuilt top weakens energy transfer and reduces volume.','Instrument Acoustics',ARRAY['Standing waves on strings','String modes','Sympathetic string resonance','Wolf tones','Radiation efficiency']::text[],ARRAY['Thinking the string itself produces most of the sound rather than the radiating soundboard.','Assuming more coupling is always better; it also shortens sustain.','Ignoring that soundboard resonances color the tone unevenly across pitch.']::text[],ARRAY['Explaining why an unplugged solid-body electric guitar is quiet.','Voicing a piano soundboard during restoration.','Comparing sustain between lightly and heavily braced acoustic guitar tops.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Soundboard coupling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0745f1f2-f5a3-491b-9f74-2f37a5aa725a','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0745f1f2-f5a3-491b-9f74-2f37a5aa725a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0745f1f2-f5a3-491b-9f74-2f37a5aa725a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8462a34b-a09a-4f34-bf69-6757dbe69ea3','Spaced-pair stereo','A stereo microphone technique using two spaced, usually omnidirectional, microphones so that an off-center source reaches one microphone earlier than the other, producing interchannel time-of-arrival differences that create the stereo image. Interchannel level differences are small, so timing differences dominate the imaging.','Spaced-pair stereo uses two microphones set apart. A sound off to one side reaches the near mic first. This small time gap between channels builds the stereo picture. Wider spacing gives a bigger, more spacious sound. Engineers call this an A-B pair.','It captures a wide, spacious stereo image and natural room sound by encoding source direction mainly as interchannel time-of-arrival differences.','Recording an orchestra with two omnis spaced 0.5 m apart, a source at 30 degrees gives about 0.73 ms of interchannel delay: Delta_t = 0.5 x sin30 / 343.','Stereo Technique',ARRAY['Time-difference stereophony','Sum-and-difference matrices','Stereo-width recognition','Precedence effect','Coincident microphone technique']::text[],ARRAY['Spacing the microphones too far apart, causing an exaggerated hole-in-the-middle image.','Forgetting that spaced pairs can sum poorly to mono because of comb filtering.','Assuming interchannel level differences, not time differences, form the image.']::text[],ARRAY['Recording a symphony orchestra for a spacious stereo image.','Capturing room ambience to blend with close microphones.','Miking a grand piano with a spaced pair.']::text[],'Intermediate','Delta_t = d * sin(theta) / c','The interchannel time difference equals the microphone spacing times the sine of the source angle, divided by the speed of sound.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spaced-pair stereo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8462a34b-a09a-4f34-bf69-6757dbe69ea3','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8462a34b-a09a-4f34-bf69-6757dbe69ea3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8462a34b-a09a-4f34-bf69-6757dbe69ea3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0759894c-ef33-42e0-97ec-03fa81becf58','Spectral-tilt recognition','The critical-listening skill of perceiving and identifying the overall slope of a sound''s spectrum - how energy is balanced between low and high frequencies - independent of individual narrow peaks. A downward tilt is heard as darker or duller; an upward tilt is heard as brighter or thinner.','Spectral tilt is the overall balance from bass to treble. Recognizing it means hearing if a sound leans dark or bright. It ignores single narrow bumps in the tone. A dull sound has less high energy. A bright sound has more high energy. Ear training builds this skill.','It helps engineers judge tonal balance quickly, so they can match sources, spot microphone or room coloration, and set broad equalization correctly.','During mixing, a trained engineer hears a downward spectral tilt on a vocal and applies a gentle high-shelf boost to restore brightness.','Critical Listening',ARRAY['Timbre','Equalization','Stereo-width recognition','Training transfer','Frequency balance']::text[],ARRAY['Confusing a single resonant peak with an overall spectral tilt.','Judging tilt at the wrong loudness, since perceived balance changes with level.','Overcorrecting tilt with steep equalization instead of small shelving moves.']::text[],ARRAY['Matching the tone of two microphones on the same source.','Detecting a dull room or dull monitor.','Ear-training exercises with high- and low-shelf filters.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral-tilt recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0759894c-ef33-42e0-97ec-03fa81becf58','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0759894c-ef33-42e0-97ec-03fa81becf58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0759894c-ef33-42e0-97ec-03fa81becf58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce7d1a20-925d-4a52-9966-6c0464191647','Spherical harmonics','A set of orthogonal basis functions defined on the surface of a sphere, indexed by degree l and order m, used to represent any direction-dependent function such as a sound field. In Ambisonics they encode the spatial components of a sound field, and a system of order L uses (L+1)^2 channels.','A sphere surrounds a listening point. Spherical harmonics are simple wave-like shapes drawn on that sphere. Adding them together can describe sound from any direction. Ambisonics uses them to store a whole 3D sound field. Higher orders use more shapes and give sharper direction.','They give Ambisonics a compact, rotatable mathematical description of a full-sphere sound field, so it can be recorded, manipulated and decoded to many loudspeaker layouts.','An engineer working in first-order Ambisonics handles four channels (degrees up to l = 1) and can rotate the whole scene by mixing the harmonic components.','Spatial Audio',ARRAY['Sound-field translation','Ambisonics','Sum-and-difference matrices','Binaural rendering','Directivity']::text[],ARRAY['Confusing Ambisonic order with the number of loudspeakers; order sets spatial resolution, not the speaker count.','Mixing incompatible channel orderings or normalizations, such as FuMa versus ACN and SN3D.','Assuming first-order Ambisonics gives pinpoint localization; its spatial resolution is limited.']::text[],ARRAY['Encoding a 360-degree video soundtrack in Ambisonics.','Rotating an ambisonic bed to follow head movement in VR.','Decoding an ambisonic mix to a dome of loudspeakers.']::text[],'Advanced','ACN = l^2 + l + m,  with degree l >= 0 and order -l <= m <= l','The Ambisonic Channel Number equals the degree squared plus the degree plus the order, giving each spherical-harmonic component a unique channel index.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical harmonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce7d1a20-925d-4a52-9966-6c0464191647','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce7d1a20-925d-4a52-9966-6c0464191647') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce7d1a20-925d-4a52-9966-6c0464191647');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c81769a1-67f7-4f32-ad59-1beb4adbf548','Standing waves on strings','The stationary vibration pattern that forms on a string fixed at both ends when reflected traveling waves interfere, producing fixed nodes and moving antinodes. Only wavelengths that fit an integer number of half-wavelengths between the ends are supported, giving a harmonic series of natural frequencies.','A string is tied down at both ends. Plucking it sends waves that bounce back and forth. These waves add into a fixed pattern that seems to stand still. Points that never move are called nodes. Only certain pitches fit the string. Tighter or shorter strings sound higher.','Standing waves explain why a string has a definite pitch and a set of harmonics, which is the basis of how string instruments make musical tones.','For a string 0.65 m long with T = 70 N and mu = 0.0004 kg/m, the fundamental is f_1 = (1/1.30) x sqrt(70/0.0004), which is about 322 Hz.','Instrument Acoustics',ARRAY['String modes','String stiffness and inharmonicity','Soundboard coupling','Sympathetic string resonance','Harmonic series']::text[],ARRAY['Thinking the wave travels along the string when the pattern actually stays fixed.','Forgetting pitch depends on tension, length and mass together, not length alone.','Assuming real strings are perfectly harmonic; stiffness shifts the higher modes sharp.']::text[],ARRAY['Tuning a guitar or piano string to a target pitch.','Explaining harmonics when a player lightly touches a node.','Choosing string gauge to reach a desired tension and tone.']::text[],'Intermediate','f_n = (n / 2L) * sqrt(T / mu),  n = 1, 2, 3, ...','The nth natural frequency equals n divided by twice the string length, times the square root of tension divided by mass per unit length.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Standing waves on strings');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c81769a1-67f7-4f32-ad59-1beb4adbf548','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c81769a1-67f7-4f32-ad59-1beb4adbf548') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c81769a1-67f7-4f32-ad59-1beb4adbf548');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'acdeb764-0119-4fa3-b399-7ef73b0d6f5f','Statistical significance','A judgment, in a hypothesis test, that an observed effect is unlikely to have arisen by chance under the null hypothesis, declared when the p-value falls at or below a preset significance level alpha (commonly 0.05). It indicates the data are inconsistent with ''no effect''; it does not measure the size or importance of the effect.','A test asks if a result could be just luck. The p-value is the chance of seeing such a result by luck. If it is at or below a set cutoff, we call it significant. A common cutoff is 0.05, or one in twenty. Significant does not mean large or important.','It gives a shared, rule-based way to decide whether measured differences, for example between two codecs or two microphones in a listening test, are more than random variation.','In a blind listening test, a technician finds listeners preferred codec A with p = 0.02; since 0.02 is at or below 0.05, the preference is statistically significant.','Statistics',ARRAY['Null hypothesis','p-value','Confidence interval','Blind listening test','Effect size']::text[],ARRAY['Reading a significant result as proof of a large or important effect.','Treating p = 0.05 as the probability that the null hypothesis is true.','Running many tests and reporting only the significant ones (p-hacking).','Confusing ''not significant'' with ''proven no effect''.']::text[],ARRAY['Analyzing results of a double-blind codec preference test.','Deciding if a measured THD difference between units is real.','Reporting subjective audio-quality scores under ITU-R BS.1116.']::text[],'Intermediate','Reject H0 when p <= alpha,  where p = P(result at least this extreme | H0 true)','An effect is called statistically significant when the p-value - the probability of a result at least this extreme if the null hypothesis were true - is at or below the chosen significance level.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Statistical significance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'acdeb764-0119-4fa3-b399-7ef73b0d6f5f','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='acdeb764-0119-4fa3-b399-7ef73b0d6f5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='acdeb764-0119-4fa3-b399-7ef73b0d6f5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a28a267e-33b8-439f-8736-300b359e2108','Stereo-width recognition','The critical-listening skill of judging the perceived lateral extent of a stereo image - how far sounds spread between and beyond the loudspeakers - and identifying its causes, such as interchannel level and time differences, side-channel energy, or mono-compatibility problems.','Stereo width is how wide the sound spreads left to right. Recognizing it means hearing whether a mix feels narrow or wide. A narrow mix sits near the center. A wide mix reaches out to the speakers. Trained ears also spot when width hurts mono playback.','It lets engineers control spaciousness and imaging, balance width against mono compatibility, and detect processing that collapses or over-widens the stereo picture.','Checking a mix, an engineer recognizes an over-wide chorus, then narrows the side channel with a mid-side tool to keep it mono-safe.','Critical Listening',ARRAY['Sum-and-difference matrices','Time-difference stereophony','Spaced-pair stereo','Spectral-tilt recognition','Phantom image']::text[],ARRAY['Confusing loudness with width; a louder side channel is not always wider.','Judging width on headphones and assuming it holds on loudspeakers.','Widening so far that the mix loses center focus or mono compatibility.']::text[],ARRAY['Evaluating stereo width before a mono broadcast fold-down.','Comparing microphone techniques for image width.','Ear-training with mid-side balance exercises.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stereo-width recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a28a267e-33b8-439f-8736-300b359e2108','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a28a267e-33b8-439f-8736-300b359e2108') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a28a267e-33b8-439f-8736-300b359e2108');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e35fdc7a-26b1-4a43-96ab-9bc037cd00b0','String modes','The set of discrete vibration patterns (normal modes) a string fixed at both ends can sustain, each with a characteristic frequency and a fixed number of nodes. The lowest is the fundamental, and for an ideal flexible string the higher modes form a harmonic series at integer multiples of the fundamental.','A string can vibrate in several patterns at once. Each pattern is called a mode. The simplest mode is the whole string swinging as one. Higher modes split the string into equal parts. Their pitches are whole-number multiples of the lowest one. Together they give the string its rich tone.','The mode set determines a string''s harmonic content and timbre, and it explains techniques like sounding natural harmonics by touching a node.','A guitarist lightly touches the string over the 12th fret (its midpoint node) to silence the fundamental and sound the second mode, one octave higher.','Instrument Acoustics',ARRAY['Standing waves on strings','String stiffness and inharmonicity','Soundboard coupling','Sympathetic string resonance','Harmonic series']::text[],ARRAY['Assuming all modes are present equally; the plucking position sets which modes are strong.','Believing the higher modes are exactly harmonic on real, stiff strings.','Confusing a mode number with a fret number.']::text[],ARRAY['Playing natural harmonics on a guitar or violin.','Explaining timbre differences from plucking near the bridge versus the center.','Modeling a string in physical-modeling synthesis.']::text[],'Intermediate','f_n = n * f_1,  where f_1 = (1/2L)*sqrt(T/mu),  n = 1, 2, 3, ...','Each mode''s frequency is an integer multiple of the fundamental, and the fundamental equals one over twice the length times the square root of tension over mass per unit length.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='String modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e35fdc7a-26b1-4a43-96ab-9bc037cd00b0','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e35fdc7a-26b1-4a43-96ab-9bc037cd00b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e35fdc7a-26b1-4a43-96ab-9bc037cd00b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5bfbcf3-33bf-4778-8e2c-df6cc0234612','String stiffness and inharmonicity','Real strings have bending stiffness, so their higher modes are stretched progressively sharp instead of forming an exact harmonic series. The resulting inharmonicity is described by a coefficient B in f_n = n*f_0*sqrt(1+B*n^2); B increases with string diameter and Young''s modulus and decreases with length and tension.','An ideal string gives evenly spaced overtones. A real string resists bending, so it is a bit stiff. This stiffness pushes the higher overtones slightly sharp. Thicker, shorter strings show it more. Piano tuners answer it with stretch tuning. The effect is called inharmonicity.','It explains why piano partials drift sharp and why pianos are tuned with octave ''stretch'', and it matters for realistic string synthesis.','With B = 0.0004 on a piano string, the 10th partial is stretched by sqrt(1 + 0.0004 x 100) = 1.0198, about 34 cents sharp of a pure harmonic.','Instrument Acoustics',ARRAY['Standing waves on strings','String modes','Wolf tones','Soundboard coupling','Stretch tuning']::text[],ARRAY['Assuming piano partials are exactly harmonic when they are progressively sharp.','Thinking piano octaves should be tuned to a pure 2:1 frequency ratio.','Ignoring that thick, wound bass strings have the largest inharmonicity.']::text[],ARRAY['Setting stretch tuning on an acoustic or digital piano.','Designing wound bass strings to reduce stiffness.','Tuning inharmonicity parameters in a physical-modeling piano.']::text[],'Advanced','f_n = n * f_0 * sqrt(1 + B*n^2);   B = pi^3 * E * a^4 / (4 * L^2 * T)','The nth partial equals n times the fundamental times the square root of one plus the inharmonicity coefficient times n squared; the coefficient grows with stiffness and the fourth power of the string radius.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='String stiffness and inharmonicity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5bfbcf3-33bf-4778-8e2c-df6cc0234612','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5bfbcf3-33bf-4778-8e2c-df6cc0234612') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5bfbcf3-33bf-4778-8e2c-df6cc0234612');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69cd2045-0a26-43c7-bb08-367ef550f291','Sum-and-difference matrices','A linear encode/decode pair that converts a stereo left/right signal into a mid (sum) and side (difference) representation and back: M = L + R and S = L - R, with the inverse L = (M + S)/2 and R = (M - S)/2. It underlies mid-side recording, stereo-width control and stereo matrix systems.','Two channels, left and right, can be re-mixed. Add them to get a mid, or center, signal. Subtract them to get a side signal. The side holds the stereo difference. You can undo this to recover left and right. Changing the side level widens or narrows the image.','It provides a mono-compatible way to encode stereo and a simple, reliable control over stereo width, since raising or lowering the side channel widens or narrows the image.','An engineer using mid-side processing lowers the side (S) level by 3 dB to narrow a too-wide overhead pair while keeping the center image intact.','Stereo Technique',ARRAY['Stereo-width recognition','Spaced-pair stereo','Time-difference stereophony','Spherical harmonics','Mid-side recording']::text[],ARRAY['Forgetting the 1/2 (or 1/sqrt(2)) scaling, which causes a level change on decode.','Boosting the side channel so far the mix fails in mono.','Confusing mid-side processing with plain left-right processing.']::text[],ARRAY['Recording with a mid-side microphone pair.','Adjusting stereo width during mastering.','Building an FM-style stereo sum-and-difference matrix.']::text[],'Intermediate','Encode: M = L + R,  S = L - R.   Decode: L = (M + S)/2,  R = (M - S)/2','The mid channel is the sum of left and right; the side channel is their difference; left and right are recovered by adding and subtracting mid and side, then halving.','363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sum-and-difference matrices');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69cd2045-0a26-43c7-bb08-367ef550f291','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69cd2045-0a26-43c7-bb08-367ef550f291') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69cd2045-0a26-43c7-bb08-367ef550f291');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '563e715f-342a-44e9-8b78-56a885c8ce08','Sympathetic string resonance','The forced vibration of an undamped string when sound energy at one of its natural frequencies reaches it from another vibrating string or source, causing it to sound without being played directly. It arises through shared frequencies and mechanical or airborne coupling, usually via the instrument''s bridge and body.','Leave a string free to move. Play another note nearby at a matching pitch. The free string starts to vibrate on its own. This is called sympathetic resonance. It adds ring and richness to the sound. Sitars and pianos use it on purpose.','It enriches an instrument''s tone and sustain and is used deliberately by adding resonating strings, as on a sitar or viola d''amore, or by lifting piano dampers.','A pianist presses the sustain pedal so undamped strings resonate sympathetically and add bloom; a recordist may close-mic to control this ring.','Instrument Acoustics',ARRAY['Standing waves on strings','String modes','Soundboard coupling','Wolf tones','Resonance']::text[],ARRAY['Thinking the extra ring is a fault rather than sympathetic resonance.','Assuming only exact unisons couple; octaves and other harmonics also excite strings.','Ignoring that the bridge and body carry the coupling energy.']::text[],ARRAY['Hearing piano strings ring with the sustain pedal down.','Muting unwanted resonance while recording guitar.','Explaining the drone strings on a sitar.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sympathetic string resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '563e715f-342a-44e9-8b78-56a885c8ce08','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='563e715f-342a-44e9-8b78-56a885c8ce08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='563e715f-342a-44e9-8b78-56a885c8ce08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da6cda84-e319-4502-b895-af132f997c66','Temporal grouping','In auditory scene analysis, the perceptual process by which the auditory system groups acoustic events that are close in time, or that share a common onset or rhythm, into a single stream, and separates events with differing timing into distinct streams. It is one basis for hearing rhythm, phrasing and separate sound sources.','Our ears sort sounds into groups over time. Sounds close together seem to belong together. Sounds far apart seem separate. This is temporal grouping. It helps us hear rhythm and phrases. It also helps us follow one voice in noise.','It helps listeners organize a stream of sound into meaningful units and separate simultaneous sources, which is central to understanding music and speech.','A mix engineer uses tight timing and shared onsets so backing vocals group into one blended part rather than scattering into distinct voices.','Auditory Perception',ARRAY['Auditory scene analysis','Precedence effect','Stereo-width recognition','Training transfer','Stream segregation']::text[],ARRAY['Confusing temporal (time-based) grouping with spectral (frequency-based) grouping.','Assuming grouping is purely physical rather than perceptual.','Ignoring that timing cues can override level or pitch cues in streaming.']::text[],ARRAY['Aligning double-tracked parts so they fuse.','Explaining why fast notes form a perceived melody line.','Designing rhythmic cues in game audio.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal grouping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da6cda84-e319-4502-b895-af132f997c66','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da6cda84-e319-4502-b895-af132f997c66') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da6cda84-e319-4502-b895-af132f997c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1fc16638-dad1-4736-adb7-387cb5d7cea8','Time-difference stereophony','The creation of a stereo phantom image using interchannel time (arrival-delay) differences rather than level differences, so that delaying one channel shifts the image toward the earlier channel. It is the principle behind spaced-microphone arrays and is closely related to the precedence effect.','Stereo can be built from timing, not just level. If the left channel arrives a little earlier, the sound leans left. Small delays between channels move the image sideways. Spaced microphones work this way. Large delays trigger the precedence effect. Then the earlier sound wins.','It gives a natural, spacious way to place and spread sounds in stereo, and it explains how spaced-microphone recordings and delay-based panners form images.','Using a delay panner, an engineer delays the right channel by about 0.5 ms to nudge a mono source slightly left without changing its level.','Stereo Technique',ARRAY['Spaced-pair stereo','Sum-and-difference matrices','Precedence effect','Stereo-width recognition','Interaural time difference']::text[],ARRAY['Confusing interchannel time differences (between the loudspeakers) with interaural time differences (between the ears).','Using large delays that cause comb filtering when summed to mono.','Assuming only level panning can create a stereo image.']::text[],ARRAY['Spaced-pair orchestral recording.','Haas-style delay panning of a mono source.','Explaining imaging in an ORTF near-coincident pair.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-difference stereophony');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1fc16638-dad1-4736-adb7-387cb5d7cea8','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1fc16638-dad1-4736-adb7-387cb5d7cea8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1fc16638-dad1-4736-adb7-387cb5d7cea8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ac49990-d948-45a3-bd1e-d25778e02ff3','Tone holes','Openings along the bore of a woodwind instrument that, when opened or closed, change the effective acoustic length of the vibrating air column and therefore the sounding pitch. The first open hole below the mouthpiece largely defines the effective end of the air column, though the exact behavior depends on hole size, height and spacing.','A woodwind is a tube of vibrating air. Holes are drilled along its side. Opening a hole shortens the working length of the air. Shorter air columns give higher notes. Closing holes lengthens it and lowers the pitch. Hole size and spacing shape the exact tuning.','Tone holes let a single wind instrument play many pitches by changing the air column''s effective length instead of building a separate tube for each note.','A repair technician levels a leaking tone-hole seat and adjusts pad height, since a poorly sealing or too-low pad flattens and weakens the note.','Instrument Acoustics',ARRAY['Woodwind directivity','Standing waves on strings','Register key','Bore resonance','Effective length']::text[],ARRAY['Thinking a hole must be at the very end of the tube to set pitch; the first open hole dominates.','Ignoring that hole size and pad height affect both tuning and tone.','Assuming open-hole and closed-hole keywork tune identically.']::text[],ARRAY['Regulating pad heights on a saxophone.','Explaining fingering-to-pitch relationships on a clarinet.','Diagnosing a leaking tone hole that weakens the low notes.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tone holes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ac49990-d948-45a3-bd1e-d25778e02ff3','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ac49990-d948-45a3-bd1e-d25778e02ff3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ac49990-d948-45a3-bd1e-d25778e02ff3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf48466f-4306-4684-8089-788cdbb8280f','Training transfer','In skill learning, the degree to which an ability practiced in one context, such as structured ear-training exercises, carries over to performance in a different context, such as real mixing decisions. Transfer can be positive, negative or absent, and it is generally greater when practice conditions resemble the target task.','Training transfer means a learned skill helps in a new task. You practice one thing and get better at another. Ear-training drills should help real mixing. Transfer works best when practice is like the real job. Sometimes a habit can even hurt the new task.','The concept guides how ear-training and technical drills are designed, so practiced skills actually improve real-world audio work rather than just test scores.','An instructor designs equalization-matching drills using real music, not just test tones, so the skill transfers to everyday mixing.','Critical Listening',ARRAY['Spectral-tilt recognition','Stereo-width recognition','Temporal grouping','Ear training','Skill acquisition']::text[],ARRAY['Assuming any practice automatically transfers to real tasks.','Training only with artificial tones and expecting music skills to follow.','Ignoring that some learned habits transfer negatively.']::text[],ARRAY['Designing a technical ear-training curriculum.','Evaluating whether drills improved real mixing skill.','Choosing realistic practice material for students.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Training transfer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf48466f-4306-4684-8089-788cdbb8280f','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf48466f-4306-4684-8089-788cdbb8280f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf48466f-4306-4684-8089-788cdbb8280f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0bcf2ff9-18d8-409a-b050-5c715ce4db61','Tritone paradox','An auditory illusion, described by Diana Deutsch, in which a pair of octave-ambiguous Shepard tones a tritone apart is heard as ascending by some listeners and descending by others. The perceived direction depends systematically on the pitch classes used and on the listener, and it has been linked to speech and dialect background.','Shepard tones are notes with no clear octave. Play two of them a tritone apart. Some people hear the pair go up. Others hear the same pair go down. This split is the tritone paradox. Diana Deutsch found it. Your language background may set which way you hear it.','It shows that pitch-class perception is ambiguous and shaped by the listener, challenging the assumption that pitch direction is heard the same way by everyone.','A sound designer aware of the paradox avoids using ambiguous Shepard-tone pairs for a cue that every listener must read the same way.','Auditory Perception',ARRAY['Shepard tone','Pitch class','Temporal grouping','Auditory illusion','Octave equivalence']::text[],ARRAY['Assuming every listener hears the tone pair move in the same direction.','Confusing the tritone paradox with the continuous Shepard-Risset glissando.','Thinking the effect is a recording trick rather than a perceptual one.']::text[],ARRAY['Demonstrating pitch illusions in a psychoacoustics class.','Explaining listener disagreement about a Shepard-tone cue.','Studying links between language background and pitch perception.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tritone paradox');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0bcf2ff9-18d8-409a-b050-5c715ce4db61','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0bcf2ff9-18d8-409a-b050-5c715ce4db61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0bcf2ff9-18d8-409a-b050-5c715ce4db61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c6b00be5-fb41-40ce-ab5a-a0f64bb80422','Wolf tones','An unstable, warbling note on bowed string instruments (often near F to F-sharp on the cello) that occurs when the played pitch coincides with a strong body or air resonance, so energy alternates between the string and the body and produces a beating, stuttering tone. It is a coupling problem between the string and the instrument''s resonant structure.','Some notes on a cello sound rough and warble. This happens at one troublesome pitch. There the string matches a strong body resonance. Energy jumps back and forth between them. The note then beats or stutters. Players call it a wolf tone.','The concept explains a real playability defect and guides fixes, such as fitting a wolf-eliminator mass, so the problem note plays cleanly.','A cellist plagued by a wolf near F clamps a wolf-eliminator onto the tailpiece string to shift the resonance and tame the warble.','Instrument Acoustics',ARRAY['Sympathetic string resonance','Soundboard coupling','Standing waves on strings','String modes','Body resonance']::text[],ARRAY['Blaming the player or string when the cause is body-string resonance coupling.','Assuming a wolf tone can be tuned away rather than damped.','Expecting every instrument to have its wolf at the same pitch.']::text[],ARRAY['Diagnosing a warbling note on a cello or double bass.','Fitting and positioning a wolf-eliminator.','Explaining why the wolf shifts with bridge or setup changes.']::text[],'Advanced',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wolf tones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c6b00be5-fb41-40ce-ab5a-a0f64bb80422','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c6b00be5-fb41-40ce-ab5a-a0f64bb80422') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c6b00be5-fb41-40ce-ab5a-a0f64bb80422');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d0389b1-540a-42fb-bcb0-6c571501090e','Woodwind directivity','The frequency-dependent way a woodwind instrument radiates sound into different directions. At low frequencies, where wavelengths are large and sound leaves mainly from open tone holes, radiation is nearly omnidirectional; at high frequencies it becomes more directional and beams more strongly from the bell and the first open holes.','A woodwind does not send sound out evenly. Low notes spread in all directions. High notes point more forward. The open holes radiate the low sounds. The bell and holes beam the highs. This is called directivity. Microphone placement should match it.','Understanding directivity guides microphone placement and helps predict how a woodwind''s tone changes with listening angle in a room or on stage.','A recordist mics a clarinet aimed slightly toward the upper tone holes, not straight down the bell, because much of the sound radiates from the open holes.','Instrument Acoustics',ARRAY['Tone holes','Directivity','Standing waves on strings','Radiation efficiency','Microphone placement']::text[],ARRAY['Assuming all woodwind sound comes out of the bell.','Miking straight down the bell and getting a harsh, unbalanced tone.','Ignoring that directivity changes with pitch and fingering.']::text[],ARRAY['Placing a microphone on a clarinet or oboe.','Predicting tone changes as a player turns on stage.','Designing directivity in an instrument model.']::text[],'Intermediate',NULL,NULL,'363e91ea-a50c-4692-a95c-cc8e52bfb0ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Woodwind directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d0389b1-540a-42fb-bcb0-6c571501090e','363e91ea-a50c-4692-a95c-cc8e52bfb0ca',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d0389b1-540a-42fb-bcb0-6c571501090e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d0389b1-540a-42fb-bcb0-6c571501090e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d54718e-fbbe-4bd7-adeb-f060dc7aaf03','Acoustic versus electrical crossover slopes','The electrical crossover slope is the roll-off produced by the crossover filter alone, while the acoustic slope is the actual on-axis response of the driver plus that filter. Because a driver has its own natural roll-off, the acoustic slope generally differs from the electrical slope, and designers target a desired acoustic alignment (such as Linkwitz-Riley) rather than the electrical one.','A crossover filter has a slope on paper. But each speaker driver also rolls off on its own. The real, measured slope is the two combined. Engineers aim for the correct measured slope, not just the filter setting.','It separates the filter''s designed roll-off from the driver''s real acoustic behaviour so a system can be tuned to a proper summed response at the crossover.','If a woofer already rolls off at about 12 dB/octave and you add a 12 dB/octave electrical low-pass, the slopes add in dB to give roughly a 24 dB/octave acoustic slope.','Crossovers',ARRAY['Linkwitz-Riley alignment','Butterworth response','Cascaded filters','Band-reject filter','Crossover frequency']::text[],ARRAY['Assuming the electrical filter slope equals the measured acoustic slope.','Ignoring the driver''s own roll-off when choosing a crossover order.','Setting an electrical Linkwitz-Riley slope and expecting a Linkwitz-Riley acoustic result without measuring.']::text[],ARRAY['Tuning an active loudspeaker so the summed response is flat through the crossover.','Choosing a filter order after measuring a driver''s natural high-frequency roll-off.','Diagnosing a dip at crossover caused by acoustic and electrical slopes not summing correctly.']::text[],'Advanced','S_acoustic ≈ S_electrical + S_driver','The acoustic slope in decibels per octave is approximately the electrical filter slope added to the driver''s own natural roll-off slope.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic versus electrical crossover slopes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d54718e-fbbe-4bd7-adeb-f060dc7aaf03','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d54718e-fbbe-4bd7-adeb-f060dc7aaf03') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d54718e-fbbe-4bd7-adeb-f060dc7aaf03');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c298ec9-b8dd-4909-b20d-2d0b59657efe','Algorithmic reverberation','Algorithmic reverberation synthesises the sound of a reverberant space using networks of delay lines, comb and all-pass filters, and feedback rather than a recorded impulse response. Classic structures include Schroeder''s comb-plus-all-pass reverberators and feedback delay networks, which build up dense, decaying echoes.','This makes reverb using math, not a recording of a real room. It uses delays and filters that feed back on themselves. Together they create many fading echoes. The result sounds like sound bouncing around a space.','It creates adjustable, efficient reverberation for mixing and sound design without needing a measured recording of a real space.','A technician loads an algorithmic reverb, sets decay time (RT) and pre-delay, and blends the wet signal to place a dry vocal in a virtual room.','Reverberation',ARRAY['Convolution reverberation','Chamber-reverb behavior','Comb filtering in short delays','Cascaded filters','Feedback delay network']::text[],ARRAY['Thinking algorithmic reverb copies a specific real room like convolution does.','Using too little pre-delay, which smears the dry sound.','Setting decay time far too long for a small, dry mix.']::text[],ARRAY['Adding space to a lead vocal in a pop mix.','Designing an evolving reverb tail for a film sound effect.','Choosing between algorithmic and convolution reverb for CPU or realism reasons.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Algorithmic reverberation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c298ec9-b8dd-4909-b20d-2d0b59657efe','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c298ec9-b8dd-4909-b20d-2d0b59657efe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c298ec9-b8dd-4909-b20d-2d0b59657efe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '760e8092-0c6b-402b-af89-e30cca94d21e','Aliasing from nonlinear processing','Nonlinear processes such as distortion, saturation, waveshaping and rectification generate new harmonics that can lie above the Nyquist frequency. Any content above half the sample rate folds back into the audible band as inharmonic alias tones, which oversampling before the nonlinearity helps reduce.','Distortion and similar effects create new higher harmonics. Some land above the digital frequency limit. Those fold back down as wrong, unmusical tones. Running the effect at a higher sample rate first reduces this problem.','Understanding this warns technicians why digital distortion can sound harsh and how to keep added harmonics from folding into the audio band.','A distortion plugin at 44.1 kHz can create a 30 kHz harmonic that folds to 44100 - 30000 = 14100 Hz; enabling 4x oversampling pushes such products above the audible fold.','Aliasing',ARRAY['Aliasing in digital oscillators','Clipping distortion','Compression-induced distortion','Band-limited oscillator generation','Oversampling']::text[],ARRAY['Believing a brick-wall anti-alias filter on the converter stops in-software aliasing.','Assuming oversampling is never needed for digital distortion.','Confusing pleasant added harmonics with the inharmonic tones caused by folding.']::text[],ARRAY['Choosing an oversampling setting on a saturation or clipper plugin.','Diagnosing a harsh, gritty tone on bright distorted guitar.','Comparing an analog distortion box with its digital emulation.']::text[],'Advanced','f_alias = |f - k·f_s|, chosen so 0 ≤ f_alias ≤ f_s/2','An alias appears at the distance between a generated frequency and the nearest multiple of the sample rate, folded into the zero-to-Nyquist band.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aliasing from nonlinear processing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '760e8092-0c6b-402b-af89-e30cca94d21e','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='760e8092-0c6b-402b-af89-e30cca94d21e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='760e8092-0c6b-402b-af89-e30cca94d21e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6659b9f6-58fd-4019-8c7c-f57469d3aef5','Aliasing in digital oscillators','A naive digital oscillator that draws ideal sawtooth, square or pulse shapes produces harmonics extending far above the Nyquist frequency. Those harmonics fold back as inharmonic alias tones, so high notes sound detuned and rough unless a band-limited generation method is used.','A basic digital synth wave has many harmonics. High-pitched notes push harmonics past the digital limit. Those fold back as wrong tones. So plain digital waves can sound rough or slightly out of tune.','It explains why simple waveform generators sound wrong at high pitches and motivates band-limited oscillator designs.','A trivial sawtooth at 44.1 kHz playing a 5 kHz note has a harmonic at 25 kHz that folds to 44100 - 25000 = 19100 Hz, an audible alias.','Aliasing',ARRAY['Band-limited oscillator generation','Aliasing from nonlinear processing','Nyquist frequency','Wavetable synthesis','Sawtooth wave']::text[],ARRAY['Assuming raising the sample rate alone fully removes oscillator aliasing.','Thinking a pure sine oscillator aliases the same way as a sawtooth.','Confusing aliasing with ordinary bright harmonic content.']::text[],ARRAY['Comparing a band-limited synth oscillator with a naive one at high notes.','Choosing an oscillator algorithm when building a soft synth.','Explaining why cheap virtual analog synths sound harsh in the top octaves.']::text[],'Advanced','f_alias = |n·f_0 - k·f_s|, folded into 0..f_s/2','Each harmonic above half the sample rate reflects back to the difference between it and the nearest multiple of the sample rate.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aliasing in digital oscillators');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6659b9f6-58fd-4019-8c7c-f57469d3aef5','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6659b9f6-58fd-4019-8c7c-f57469d3aef5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6659b9f6-58fd-4019-8c7c-f57469d3aef5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b0ef4ecb-e8c5-4945-a3eb-dc76413ac17a','Attack-decay-sustain-release behavior','An ADSR envelope generator produces a time-varying control contour with four stages: attack (rise to peak), decay (fall to a held level), sustain (the held level while a note is on), and release (fall to zero after the note ends). It commonly shapes amplitude or filter cutoff over the life of a note.','This is a four-stage shape for a synth sound. Attack is how fast it rises. Decay drops to a held level. Sustain is that held level. Release is how it fades after you let go.','It gives synthesists a standard way to shape how loudness or tone evolves from the start to the end of each note.','For a plucked sound, a technician sets a fast attack, short decay, low sustain and short release so the note starts sharply and dies away quickly.','Modulation & Envelopes',ARRAY['Automatic release','Control-rate versus audio-rate modulation','Control smoothing','Low-frequency oscillator','Envelope generator']::text[],ARRAY['Treating sustain as a time value rather than a held level.','Setting zero release and wondering why notes cut off with a click.','Assuming every synth uses exactly four stages.']::text[],ARRAY['Programming a pad with slow attack and long release.','Shaping a filter sweep with an envelope on a bass patch.','Explaining why a note keeps sounding after key release.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attack-decay-sustain-release behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b0ef4ecb-e8c5-4945-a3eb-dc76413ac17a','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b0ef4ecb-e8c5-4945-a3eb-dc76413ac17a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b0ef4ecb-e8c5-4945-a3eb-dc76413ac17a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42f93d7e-2b3d-4fd9-a0a9-808ec54228c4','Automatic release','Automatic (program-dependent) release lets a dynamics processor vary its release time according to the incoming signal instead of using one fixed setting. It typically combines fast and slow time constants so brief peaks recover quickly while sustained level changes recover slowly, reducing pumping and distortion.','A compressor normally has one release speed. Automatic release changes that speed to match the music. Short loud bits recover fast. Longer changes recover slowly. This helps the compressor sound smoother and more natural.','It adapts recovery time to the signal so a compressor stays transparent across varied material without constant manual adjustment.','On a full mix, a technician selects auto-release so quick drum peaks recover fast while the overall level changes recover gently, avoiding audible pumping.','Dynamics Processing',ARRAY['Compression-induced distortion','Attack-decay-sustain-release behavior','Averaging detection','Clipping versus limiting','Makeup gain']::text[],ARRAY['Assuming auto-release removes all pumping in every case.','Expecting the same sound from auto-release across different compressor designs.','Thinking auto-release also sets the attack time.']::text[],ARRAY['Compressing a dynamic vocal that shifts between soft and loud lines.','Using a bus compressor''s auto mode on a full mix.','Comparing manual and automatic release on program material.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Automatic release');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42f93d7e-2b3d-4fd9-a0a9-808ec54228c4','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42f93d7e-2b3d-4fd9-a0a9-808ec54228c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42f93d7e-2b3d-4fd9-a0a9-808ec54228c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '206b6974-5cf8-4d37-bea8-cf1f6edacf28','Averaging detection','Averaging (RMS) detection estimates signal level from the mean of the squared samples over a time window, rather than tracking instantaneous peaks. It correlates better with perceived loudness and power, so many compressors and meters offer an averaging or RMS detector for smoother response.','This measures level by averaging the signal over time. It does not chase every fast peak. The result tracks how loud something sounds. Compressors and meters use it for a smoother reaction.','It provides a level estimate tied to power and loudness, which suits musical compression and average-reading metering.','Over a window, level equals the square root of the mean of the squared samples; for example the RMS of a full-scale sine is 0.707 of its peak, about 3 dB below peak.','Dynamics Processing',ARRAY['Peak detection','Automatic release','Compression-induced distortion','Control smoothing','Loudness']::text[],ARRAY['Confusing an averaging (RMS) detector with a peak detector.','Assuming RMS level equals peak level for complex signals.','Forgetting that a short window behaves more like peak detection.']::text[],ARRAY['Choosing RMS versus peak detection on a compressor for a smoother sound.','Reading an averaging VU-style meter versus a peak meter.','Setting a compressor to respond to loudness rather than transients.']::text[],'Intermediate','x_rms = sqrt( (1/N) · Σ x[n]² )','The averaged level is the square root of the mean of the squared sample values over the measurement window.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Averaging detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '206b6974-5cf8-4d37-bea8-cf1f6edacf28','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='206b6974-5cf8-4d37-bea8-cf1f6edacf28') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='206b6974-5cf8-4d37-bea8-cf1f6edacf28');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3be6eba-4956-4292-9888-f522473a59ac','Band-limited oscillator generation','Band-limited oscillator generation produces classic waveforms (sawtooth, square, pulse) while keeping all harmonics below the Nyquist frequency, so no aliasing occurs. Common methods include additive synthesis, band-limited wavetables, and band-limited impulse train (BLIT) or band-limited step (BLEP) techniques.','This makes synth waves without the folding problem. It builds only the harmonics that fit below the digital limit. So the sound stays clean at every pitch. Several methods exist, such as special wavetables.','It lets digital synths recreate rich analog-style waveforms cleanly, avoiding the harsh alias tones of naive generators.','A synth designer uses band-limited wavetables per pitch range so a bright sawtooth stays clean even in the highest octaves.','Oscillators',ARRAY['Aliasing in digital oscillators','Wavetable synthesis','Nyquist frequency','Additive synthesis','Oversampling']::text[],ARRAY['Thinking any wavetable is automatically band-limited.','Assuming a single wavetable works cleanly across all pitches.','Confusing band-limiting with simply low-pass filtering the output.']::text[],ARRAY['Building a virtual analog oscillator that stays clean at high notes.','Choosing BLEP or wavetable methods for a soft synth.','Comparing a band-limited oscillator with a naive one for alias content.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Band-limited oscillator generation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3be6eba-4956-4292-9888-f522473a59ac','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3be6eba-4956-4292-9888-f522473a59ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3be6eba-4956-4292-9888-f522473a59ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7618c22e-b5e1-444c-85be-01e354c4d7b2','Band-reject filter','A band-reject filter attenuates a band of frequencies while passing those above and below it, the opposite of a band-pass filter. A narrow band-reject filter is called a notch filter and is described by its centre frequency and quality factor Q, which sets the width of the rejected band.','This filter cuts out one band of frequencies. It lets lower and higher frequencies through. A very narrow one is called a notch. Its Q controls how wide the cut is.','It removes an unwanted band, such as mains hum or a resonant ring, while leaving the rest of the spectrum intact.','To remove 60 Hz hum, a technician sets a notch at 60 Hz; with Q = f0/BW, a Q of 30 gives a bandwidth of 60/30 = 2 Hz.','Filters',ARRAY['Notch filter','Constant-Q equalizers','Butterworth response','Comb filtering in short delays','Band-pass filter']::text[],ARRAY['Confusing a band-reject filter with a band-pass filter.','Setting Q too low, which cuts wanted frequencies around the target.','Assuming one notch removes hum plus all its harmonics.']::text[],ARRAY['Notching out mains hum from a recording.','Removing a single feedback tone in a live sound system.','Taming a narrow resonant peak on a drum shell.']::text[],'Beginner','Q = f0 / BW','The quality factor equals the centre frequency divided by the bandwidth between the two half-power edges.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Band-reject filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7618c22e-b5e1-444c-85be-01e354c4d7b2','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7618c22e-b5e1-444c-85be-01e354c4d7b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7618c22e-b5e1-444c-85be-01e354c4d7b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d7e6cd2-e8a8-44d1-8dc3-45b24bd05a62','Bessel response','A Bessel filter is an all-pole response designed for maximally flat group delay, giving nearly linear phase and excellent transient (step) response with little overshoot. In exchange it has a gentle, gradual amplitude roll-off and poorer stopband selectivity than a Butterworth or Chebyshev filter of the same order.','A Bessel filter keeps timing very even across frequency. So waveforms pass through with little smearing. The trade-off is a slow roll-off. It is not sharp at rejecting unwanted frequencies.','It is chosen when preserving waveform shape and timing matters more than a steep cutoff, such as in crossovers or signal-shape-critical paths.','A technician picks a Bessel alignment where clean transient reproduction matters, accepting that the amplitude roll-off near cutoff is gentle.','Filters',ARRAY['Butterworth response','Chebyshev response','Group delay','Cascaded filters','Linear phase']::text[],ARRAY['Expecting a Bessel filter to roll off as steeply as a Butterworth of the same order.','Confusing flat group delay with a flat amplitude response.','Assuming Bessel is always the best crossover choice.']::text[],ARRAY['Choosing a filter that preserves square-wave shape for test signals.','Selecting a crossover alignment that favours transient accuracy.','Comparing phase behaviour of Bessel, Butterworth and Chebyshev filters.']::text[],'Advanced','τ_g(ω) = -dφ(ω)/dω (designed maximally flat)','Group delay is the negative slope of phase versus frequency, and the Bessel response makes this delay as flat as possible across the passband.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bessel response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d7e6cd2-e8a8-44d1-8dc3-45b24bd05a62','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d7e6cd2-e8a8-44d1-8dc3-45b24bd05a62') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d7e6cd2-e8a8-44d1-8dc3-45b24bd05a62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c0ee35d-b410-4140-b40e-1f6aca42c80a','Bessel-function sideband behavior','In frequency modulation synthesis, the spectrum consists of a carrier and sidebands spaced by the modulator frequency, whose amplitudes are given by Bessel functions of the first kind evaluated at the modulation index. As the modulation index rises, energy spreads to more and higher-order sidebands, brightening the tone.','In FM synthesis, one tone modulates another. This makes extra tones called sidebands. How loud each sideband is follows math curves called Bessel functions. More modulation spreads energy into more sidebands. This adds brightness to the sound.','It predicts how strong each sideband is in FM synthesis, so designers can shape timbre by choosing the modulation index.','At modulation index 1, the carrier weight is J0(1) ≈ 0.765 and the first sideband weight is J1(1) ≈ 0.440, so the first sidebands are clearly present but below the carrier.','Modulation Synthesis',ARRAY['Carrier suppression','Control-rate versus audio-rate modulation','Frequency modulation synthesis','Sideband','Modulation index']::text[],ARRAY['Assuming higher modulation index always increases the carrier level.','Forgetting that sidebands can fold (alias) at high modulation indices.','Thinking sideband spacing depends on the carrier frequency rather than the modulator.']::text[],ARRAY['Designing an FM synth patch and adjusting the modulation index for brightness.','Predicting which sidebands appear for a given carrier-to-modulator ratio.','Explaining why an FM tone gets brighter as an operator level rises.']::text[],'Advanced','a_n = J_n(β),  β = Δf / f_m','The amplitude of the nth sideband equals the nth-order Bessel function of the first kind of the modulation index, where the index is peak frequency deviation over modulator frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bessel-function sideband behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c0ee35d-b410-4140-b40e-1f6aca42c80a','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c0ee35d-b410-4140-b40e-1f6aca42c80a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c0ee35d-b410-4140-b40e-1f6aca42c80a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2171f347-54ad-4a2f-bd97-c82cb63939b0','Bilinear transformation','The bilinear transform maps an analog filter''s s-plane transfer function to a digital z-plane transfer function using s = (2/T)(z-1)/(z+1). It maps the entire analog frequency axis onto the unit circle, so a stable analog filter yields a stable digital one with no aliasing, at the cost of frequency warping that is corrected by pre-warping critical frequencies.','This is a method to turn an analog filter design into a digital one. It maps analog frequencies onto the digital circle. Stable analog filters stay stable. It bends the frequency scale, so designers pre-adjust key frequencies to compensate.','It lets engineers reuse classic analog filter designs (Butterworth, Chebyshev) as digital filters while guaranteeing stability and avoiding aliasing.','To place a digital cutoff correctly, a technician pre-warps it with ω_a = (2/T)·tan(ω_d·T/2) before applying the transform.','Filter Design',ARRAY['Butterworth response','Chebyshev response','Biquad filter','Cascaded filters','Frequency warping']::text[],ARRAY['Forgetting to pre-warp, which puts the digital cutoff at the wrong frequency.','Assuming the frequency mapping is linear.','Expecting the analog and digital phase responses to match exactly.']::text[],ARRAY['Deriving digital EQ coefficients from an analog prototype.','Implementing a digital Butterworth crossover from its analog design.','Explaining why a digital filter''s cutoff shifts near the Nyquist frequency.']::text[],'Advanced','s = (2/T)·(z-1)/(z+1);   ω_a = (2/T)·tan(ω_d·T/2)','Substitute the analog variable with two over the sample period times z minus one over z plus one; the digital frequency relates to the analog frequency through a tangent warping.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bilinear transformation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2171f347-54ad-4a2f-bd97-c82cb63939b0','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2171f347-54ad-4a2f-bd97-c82cb63939b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2171f347-54ad-4a2f-bd97-c82cb63939b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0db976ab-8585-4292-91b2-caff311fec50','Blue noise','Blue noise is a random signal whose power spectral density rises with frequency, gaining about 3 dB per octave, so high frequencies carry more energy than low ones. It is the spectral opposite of pink noise and appears in audio mainly through high-frequency-weighted (noise-shaped) dither.','Blue noise is random sound with more energy up high. Its level rises about 3 dB each octave. It is the opposite of pink noise. In audio it shows up in high-frequency-weighted dither.','Its rising spectrum pushes noise energy toward higher frequencies, which is useful when shaping quantisation noise away from sensitive mid frequencies.','When noise-shaped dither is applied at a bit-depth reduction, the added noise takes on a blue (high-frequency-weighted) character to sound less audible.','Noise',ARRAY['Brown noise','Noise shaping','Dither','White noise','Pink noise']::text[],ARRAY['Confusing blue noise (rising) with pink noise (falling).','Assuming blue noise sounds neutral like white noise.','Thinking all dither has a flat (white) spectrum.']::text[],ARRAY['Describing the spectrum of noise-shaped dither on a master.','Comparing color-of-noise test signals for a listening test.','Explaining why shaped dither is weighted toward high frequencies.']::text[],'Intermediate','S(f) ∝ f   (about +3 dB/octave)','The power spectral density is proportional to frequency, so power rises about three decibels for each doubling of frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blue noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0db976ab-8585-4292-91b2-caff311fec50','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0db976ab-8585-4292-91b2-caff311fec50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0db976ab-8585-4292-91b2-caff311fec50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd14996a0-df6e-425d-845c-e18569445bf2','Boost and cut asymmetry','Boost and cut asymmetry describes an equalizer whose boost and cut curves are not mirror images of each other. In proportional-Q graphic equalizers the bandwidth changes with the amount of gain, and analog tone stages can differ between boost and cut, so a +6 dB setting and a -6 dB setting have different shapes.','On some equalizers, a boost and a matching cut do not look the same. The width of the curve can change with the amount. So turning a band up is not a mirror of turning it down. Constant-Q designs avoid this.','It explains why some equalizers behave differently when boosting versus cutting, which affects how predictable and reversible EQ moves are.','On a proportional-Q graphic EQ, a technician notices a small boost is broad while a deep cut is narrow, so a cut does not exactly undo a boost.','Equalization',ARRAY['Constant-Q equalizers','Band-reject filter','Quality factor','Butterworth response','Parametric equalizer']::text[],ARRAY['Assuming a cut always exactly cancels an equal boost.','Confusing proportional-Q with constant-Q behaviour.','Expecting every equalizer''s boost and cut curves to match.']::text[],ARRAY['Comparing constant-Q and proportional-Q graphic equalizers.','Trying to reverse an EQ move with an equal and opposite setting.','Explaining why deep cuts sound narrower than gentle boosts on some EQs.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boost and cut asymmetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd14996a0-df6e-425d-845c-e18569445bf2','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d14996a0-df6e-425d-845c-e18569445bf2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d14996a0-df6e-425d-845c-e18569445bf2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bcebd076-182d-45f7-8f32-37a00b1030b1','Brown noise','Brown (also called red or Brownian) noise is a random signal whose power spectral density falls at about 6 dB per octave, proportional to one over frequency squared, so low frequencies dominate. It arises from integrating white noise, analogous to Brownian motion, and sounds deep and rumbling.','Brown noise is random sound with much more energy down low. Its level drops about 6 dB each octave. It sounds deep, like a low rumble. It comes from adding up white noise over time.','Its steeply low-weighted spectrum makes it a reference for low-frequency-heavy random signals and a distinct test and masking sound.','A technician generating brown noise expects its energy to drop 6 dB per octave, so it measures far stronger at 100 Hz than at 1 kHz.','Noise',ARRAY['Blue noise','White noise','Pink noise','Noise shaping','Random signal']::text[],ARRAY['Confusing brown noise (-6 dB/octave) with pink noise (-3 dB/octave).','Assuming ''brown'' refers to a color rather than Brownian motion.','Expecting brown noise to sound bright.']::text[],ARRAY['Choosing a low-heavy noise source for masking or relaxation audio.','Comparing pink and brown noise spectra on an analyzer.','Explaining the deep character of brown noise to a student.']::text[],'Intermediate','S(f) ∝ 1/f²   (about -6 dB/octave)','The power spectral density is proportional to one over frequency squared, so power falls about six decibels for each doubling of frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brown noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bcebd076-182d-45f7-8f32-37a00b1030b1','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bcebd076-182d-45f7-8f32-37a00b1030b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bcebd076-182d-45f7-8f32-37a00b1030b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34915c4b-fe33-41ab-947b-795ff94b6e1e','Butterworth response','A Butterworth filter has a maximally flat magnitude response in the passband, with no ripple and a monotonic roll-off. It is 3 dB down at the cutoff frequency and rolls off asymptotically at 6n dB per octave (20n dB per decade) for an order n, with poles equally spaced on a circle in the s-plane.','A Butterworth filter keeps the passband very flat with no ripple. It sits 3 dB down at its cutoff. Higher order means a steeper drop. It is a common, well-behaved general-purpose filter.','It provides a smooth, ripple-free passband and predictable roll-off, making it a default choice for crossovers, anti-alias filters and EQ shapes.','For a 4th-order Butterworth low-pass, the roll-off is 6 x 4 = 24 dB per octave, and the response is 3 dB down at the cutoff frequency.','Filters',ARRAY['Bessel response','Chebyshev response','Linkwitz-Riley alignment','Cascaded filters','Bilinear transformation']::text[],ARRAY['Confusing the -3 dB Butterworth cutoff with the -6 dB Linkwitz-Riley point.','Thinking maximally flat magnitude also means flat phase or group delay.','Assuming Butterworth has passband ripple like Chebyshev.']::text[],ARRAY['Selecting a Butterworth alignment for a general-purpose crossover.','Designing an anti-alias filter with a flat passband.','Cascading two Butterworth sections to make a Linkwitz-Riley crossover.']::text[],'Intermediate','|H(jω)|² = 1 / (1 + (ω/ω_c)^{2n})','The squared magnitude equals one divided by one plus the frequency ratio to the power of twice the filter order.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Butterworth response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34915c4b-fe33-41ab-947b-795ff94b6e1e','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34915c4b-fe33-41ab-947b-795ff94b6e1e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34915c4b-fe33-41ab-947b-795ff94b6e1e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f63c8bf-3de2-4856-9760-f6eff49e941a','Carrier suppression','Carrier suppression means removing or nulling the carrier tone so that mainly the sidebands remain. A balanced modulator or ring modulator performs double-sideband suppressed-carrier modulation, outputting sum and difference tones with the carrier cancelled; in FM synthesis the carrier also vanishes at modulation indices where the zero-order Bessel function is zero.','Carrier suppression removes the main tone and keeps only the side tones. A ring modulator does this: you hear the sum and difference tones, not the original carrier. In FM, the carrier can also disappear at certain settings.','It creates clangorous, inharmonic, or spectrally shifted sounds by leaving only the sidebands, and it underlies ring modulation effects.','Feeding two tones into a ring modulator suppresses the carrier so only sum and difference tones remain; in FM, the carrier first nulls near modulation index β ≈ 2.405, where J0(β) = 0.','Modulation Synthesis',ARRAY['Bessel-function sideband behavior','Ring modulation','Balanced modulator','Carrier signal','Sideband']::text[],ARRAY['Confusing ring modulation (carrier suppressed) with amplitude modulation (carrier present).','Assuming the carrier is always the loudest component in FM.','Thinking carrier suppression removes the sidebands too.']::text[],ARRAY['Creating metallic, bell-like tones with a ring modulator.','Designing an FM patch that nulls its carrier for a hollow sound.','Explaining why a ring-modulated voice loses its original pitch.']::text[],'Advanced','carrier amplitude = J_0(β) = 0 at β ≈ 2.4048 (first zero)','In frequency modulation the carrier amplitude follows the zero-order Bessel function of the modulation index, which first reaches zero near an index of about 2.4048.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Carrier suppression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f63c8bf-3de2-4856-9760-f6eff49e941a','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f63c8bf-3de2-4856-9760-f6eff49e941a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f63c8bf-3de2-4856-9760-f6eff49e941a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db68514e-bad2-4ff7-8df8-1c184c2d13e1','Cascaded filters','Cascading filters means connecting filter stages in series so the signal passes through each in turn. The overall transfer function is the product of the individual transfer functions, so their orders and decibel-per-octave slopes add, which is how higher-order responses are built from simpler sections such as biquads.','Cascading means putting filters one after another. The signal goes through each in order. Their slopes add up. This is how engineers build a steep filter from several gentler ones.','It builds steeper, higher-order filters and crossovers from stable second-order sections that are easier to design and implement.','Cascading two 12 dB/octave sections gives a 24 dB/octave slope; cascading two 2nd-order Butterworth low-passes yields a 4th-order Linkwitz-Riley response.','Filter Design',ARRAY['Butterworth response','Linkwitz-Riley alignment','Biquad filter','Bilinear transformation','Acoustic versus electrical crossover slopes']::text[],ARRAY['Adding filter magnitudes instead of multiplying transfer functions.','Forgetting that cascading two Butterworth filters gives a Linkwitz-Riley, not a higher-order Butterworth.','Ignoring that each stage adds phase shift.']::text[],ARRAY['Building a steep crossover from second-order sections.','Implementing a high-order EQ as a chain of biquads.','Explaining how two identical filters combine into a steeper one.']::text[],'Intermediate','H(z) = H_1(z)·H_2(z)·...·H_k(z)','The overall transfer function equals the product of the transfer functions of the individual cascaded stages.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cascaded filters');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db68514e-bad2-4ff7-8df8-1c184c2d13e1','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db68514e-bad2-4ff7-8df8-1c184c2d13e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db68514e-bad2-4ff7-8df8-1c184c2d13e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fb4056c-777c-47ed-81ba-3be2a5447c9b','Chamber-reverb behavior','A reverb chamber is a physical room fitted with a loudspeaker and microphones; sending a dry signal through it and recording the room adds natural, dense reverberation. Its behavior features a smooth diffuse decay colored by the room''s dimensions and surfaces, and digital ''chamber'' reverb programs emulate this medium-room character.','A reverb chamber is a real room with a speaker and mics. You play sound into it and record the echoes. This adds a dense, natural reverb. Digital chamber programs copy that room sound.','It provides dense, natural-sounding reverberation with a distinct room color, historically used before and alongside digital reverbs.','A technician selects a ''chamber'' reverb preset to add a smooth, medium-sized natural space to a vocal or snare.','Reverberation',ARRAY['Algorithmic reverberation','Convolution reverberation','Plate reverb','Reverberation time','Pre-delay']::text[],ARRAY['Assuming a chamber reverb is purely a digital algorithm with no physical origin.','Confusing a chamber''s dense decay with a bright plate reverb.','Expecting a chamber to sound like a very large hall.']::text[],ARRAY['Choosing a chamber reverb preset for a natural vocal space.','Comparing chamber, plate and hall reverb characters.','Explaining the history of physical echo chambers in studios.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chamber-reverb behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fb4056c-777c-47ed-81ba-3be2a5447c9b','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fb4056c-777c-47ed-81ba-3be2a5447c9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fb4056c-777c-47ed-81ba-3be2a5447c9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48b5dbaa-6088-4672-a9cc-1324b937e130','Chebyshev response','A Chebyshev Type I filter allows equal-amplitude ripple in the passband in exchange for a steeper roll-off than a Butterworth filter of the same order. The ripple depth is set by a parameter epsilon, while the Type II (inverse) form places the equal ripple in the stopband and keeps the passband flat.','A Chebyshev filter drops off faster than a Butterworth of the same order. The trade-off is small ripples in the passband. You choose how big those ripples are. A second type puts the ripples in the stopband instead.','It gives a sharper transition between pass and stop bands than Butterworth for the same order, when small passband ripple is acceptable.','For 0.5 dB passband ripple, epsilon comes from 10^(0.5/10) - 1 = 0.122, so epsilon ≈ 0.349, giving a steeper cutoff than Butterworth of the same order.','Filters',ARRAY['Butterworth response','Bessel response','Passband ripple','Cascaded filters','Bilinear transformation']::text[],ARRAY['Forgetting that Type I ripple lives in the passband, not the stopband.','Assuming steeper roll-off comes for free without ripple or phase cost.','Confusing Chebyshev with the ripple-free Butterworth response.']::text[],ARRAY['Choosing a Chebyshev filter when a sharp cutoff outweighs small ripple.','Comparing filter families for an anti-alias design.','Explaining the ripple-versus-steepness trade-off to a student.']::text[],'Advanced','|H(jω)|² = 1 / (1 + ε²·T_n²(ω/ω_c))','The squared magnitude equals one over one plus the ripple parameter squared times the squared nth-order Chebyshev polynomial of the frequency ratio.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chebyshev response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48b5dbaa-6088-4672-a9cc-1324b937e130','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48b5dbaa-6088-4672-a9cc-1324b937e130') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48b5dbaa-6088-4672-a9cc-1324b937e130');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45ea3e29-d094-4a70-b5fb-d333570d3867','Clipping distortion','Clipping distortion occurs when a signal exceeds the maximum level a stage can pass, so its peaks are flattened. Hard clipping truncates peaks abruptly and adds strong harmonics, while soft clipping rounds them more gently; both create new harmonic and intermodulation content not present in the original.','Clipping happens when a signal is too big for the equipment. The peaks get flattened off. This adds new harsh harmonics. Hard clipping sounds harsher than soft clipping.','Recognising clipping helps a technician avoid unwanted distortion, or use controlled clipping deliberately for tone.','If a converter''s input exceeds 0 dBFS, its peaks flatten and the meter pins at full scale, adding audible harmonic distortion.','Distortion',ARRAY['Clipping versus limiting','Compression-induced distortion','Aliasing from nonlinear processing','Headroom','Total harmonic distortion']::text[],ARRAY['Assuming a little clipping is always inaudible.','Confusing clipping with limiting, which controls gain instead of truncating.','Thinking only digital signals clip; analog stages clip too.']::text[],ARRAY['Diagnosing harsh distortion when an input meter reads full scale.','Setting gain structure to leave headroom and avoid clipping.','Using a soft clipper deliberately for a warmer tone.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clipping distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45ea3e29-d094-4a70-b5fb-d333570d3867','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45ea3e29-d094-4a70-b5fb-d333570d3867') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45ea3e29-d094-4a70-b5fb-d333570d3867');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bda1d4ec-0ce8-48ad-a192-4f4ac6aff77d','Clipping versus limiting','Limiting reduces gain automatically to keep a signal below a threshold using a high ratio, ideally preserving the waveform''s shape while lowering its level. Clipping instead truncates the waveform''s peaks instantaneously, flattening them and adding strong harmonics; limiting controls level, whereas clipping distorts shape.','A limiter turns the volume down fast to stop peaks getting too loud. It keeps the wave shape. Clipping instead chops the tops off the wave. Clipping adds harsh distortion; a clean limiter does not.','It distinguishes a smooth, level-controlling limiter from a peak-truncating clipper, which matters for both loudness and sound quality.','To catch occasional peaks cleanly, a technician uses a limiter with a high ratio; a clipper would instead flatten those peaks and add audible harmonics.','Dynamics Processing',ARRAY['Clipping distortion','Compression-induced distortion','Makeup gain','Averaging detection','Brickwall limiter']::text[],ARRAY['Believing a limiter and a clipper do the same thing.','Assuming limiting never distorts, even with very fast times on bass.','Thinking clipping is always worse; it can be used as a tool.']::text[],ARRAY['Choosing a limiter versus a clipper on a master bus for loudness.','Catching transient peaks without audible distortion.','Explaining why a clipper changes tone more than a clean limiter.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clipping versus limiting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bda1d4ec-0ce8-48ad-a192-4f4ac6aff77d','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bda1d4ec-0ce8-48ad-a192-4f4ac6aff77d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bda1d4ec-0ce8-48ad-a192-4f4ac6aff77d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9aab6a37-c956-4c3f-8842-5fdfaafab557','Clock noise','Clock noise is interference in the audio band caused by digital sample clocks, switching regulators and other high-frequency digital activity coupling into analog signal paths or through shared power and grounds. It can appear as tones, whine or a raised noise floor, and is aggravated by poor layout, grounding or clock jitter.','Clock noise is digital hum or whine leaking into the audio. It comes from the timing clocks and switching parts inside gear. It can add tones or a hiss-like floor. Good grounding and layout reduce it.','Understanding clock noise helps a technician track down digital-origin interference and keep converters and mixers quiet.','A technician hearing a faint high-pitched whine tied to a device''s clock checks grounding, cabling and power to stop the digital noise coupling in.','Noise',ARRAY['Common-mode noise','Ground loop','Jitter','Dither','Noise floor']::text[],ARRAY['Blaming analog hum when the source is actually digital clock noise.','Assuming clock noise only affects digital outputs, not nearby analog stages.','Ignoring shared power supplies as a coupling path.']::text[],ARRAY['Tracing a high-pitched whine in a computer-based recording setup.','Improving grounding to reduce digital interference in a mix.','Explaining why a phone or charger near a preamp raises the noise floor.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clock noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9aab6a37-c956-4c3f-8842-5fdfaafab557','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9aab6a37-c956-4c3f-8842-5fdfaafab557') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9aab6a37-c956-4c3f-8842-5fdfaafab557');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c826ca39-3f49-4882-ad9d-73529df12b59','Comb filtering in short delays','Summing a signal with a short-delayed copy of itself produces a comb-shaped frequency response of regularly spaced peaks and notches. The peaks and notches repeat every 1/τ in frequency, where τ is the delay time, so shorter delays spread the notches farther apart.','Mixing a sound with a slightly delayed copy causes comb filtering. This adds evenly spaced peaks and dips across frequency. The spacing depends on the delay time. Short delays spread the dips further apart.','It explains the hollow, phasey tone from delayed copies, whether from a doubled signal, a reflection, or two microphones.','With a 1 ms delay, notches recur every 1/0.001 = 1000 Hz; the first notch of a summed inverting comb falls near 500 Hz.','Time Effects',ARRAY['Algorithmic reverberation','Band-reject filter','Phase cancellation','Chamber-reverb behavior','Delay']::text[],ARRAY['Confusing comb filtering with simple equalization.','Assuming comb notches are unrelated to the delay time.','Ignoring comb filtering when placing two microphones on one source.']::text[],ARRAY['Diagnosing a hollow tone when two mics capture the same source.','Explaining phasey sound from a short slap-back or reflection.','Understanding the building block behind flanging and reverb.']::text[],'Intermediate','Δf = 1/τ;   notches at f = (2k-1)/(2τ)','The spacing between comb notches equals one over the delay time, and for a summed inverting copy the notches fall at odd multiples of half that spacing.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comb filtering in short delays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c826ca39-3f49-4882-ad9d-73529df12b59','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c826ca39-3f49-4882-ad9d-73529df12b59') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c826ca39-3f49-4882-ad9d-73529df12b59');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7fbf593-d888-4253-bd22-ae7e08b9effe','Common-mode noise','Common-mode noise is interference that appears identically, in the same polarity and amplitude, on both conductors of a balanced signal pair. A balanced or differential receiver responds only to the difference between the two conductors, so it rejects common-mode noise according to its common-mode rejection ratio (CMRR).','Common-mode noise appears the same on both wires of a balanced pair. A balanced input listens only to the difference between the wires. So it cancels this shared noise. How well it cancels is the CMRR.','It underlies why balanced interconnects reject hum and interference picked up equally by both signal conductors.','A balanced input with 80 dB CMRR reduces noise that is identical on both lines by a factor of 10,000 in voltage at the receiver.','Noise',ARRAY['Clock noise','Ground loop','Balanced line','Differential amplifier','Noise floor']::text[],ARRAY['Assuming any balanced cable removes noise regardless of receiver CMRR.','Confusing common-mode noise with normal (differential) signal.','Expecting an unbalanced input to reject common-mode interference.']::text[],ARRAY['Using balanced cables to reject hum on a long run.','Comparing the CMRR specs of two preamp inputs.','Diagnosing hum that a balanced connection should have rejected.']::text[],'Intermediate','CMRR (dB) = 20·log10( A_diff / A_cm )','The common-mode rejection ratio in decibels is twenty times the base-ten logarithm of the differential gain divided by the common-mode gain.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Common-mode noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7fbf593-d888-4253-bd22-ae7e08b9effe','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7fbf593-d888-4253-bd22-ae7e08b9effe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7fbf593-d888-4253-bd22-ae7e08b9effe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a69295f-2ec6-45d7-9f5c-67082e3dabfd','Compression-induced distortion','Compression-induced distortion is unwanted waveform distortion caused by a compressor''s gain changing quickly relative to the signal period. Very fast attack or release, especially on low-frequency material, modulates gain within a single cycle, adding harmonic and intermodulation distortion and audible pumping.','A compressor changes gain over time. If it moves too fast on low notes, it changes level within one wave cycle. This bends the waveform and adds distortion. Longer release times reduce it.','It warns technicians that aggressive compressor timing can distort the signal, not just control its level.','On a bass note near 50 Hz (20 ms period), a technician avoids a very short release so the compressor does not modulate gain within each cycle and distort the tone.','Dynamics Processing',ARRAY['Automatic release','Averaging detection','Clipping versus limiting','Control smoothing','Makeup gain']::text[],ARRAY['Using the fastest release on bass and blaming the source for distortion.','Assuming a compressor never adds harmonic distortion.','Confusing intended pumping with unwanted waveform distortion.']::text[],ARRAY['Setting release time on a bass compressor to avoid distortion.','Diagnosing gritty low end after heavy compression.','Choosing RMS detection to smooth a compressor''s response.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression-induced distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a69295f-2ec6-45d7-9f5c-67082e3dabfd','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a69295f-2ec6-45d7-9f5c-67082e3dabfd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a69295f-2ec6-45d7-9f5c-67082e3dabfd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe7a5054-8f1c-4d64-b95a-177f724a2f6a','Constant-Q equalizers','A constant-Q equalizer keeps each band''s quality factor Q, and therefore its bandwidth relative to center frequency, the same regardless of how much boost or cut is applied. This contrasts with proportional-Q designs, whose bandwidth widens at small settings and narrows at large ones.','A constant-Q equalizer keeps each band''s width steady. It does not matter how far you boost or cut. The shape stays the same width. Other designs get wider at small settings.','It gives predictable, consistent bandwidth for each band, which helps precise and repeatable equalization.','For a one-third-octave band centered at 1 kHz, the bandwidth is about 232 Hz, giving Q = 1000/232 ≈ 4.3, held constant at any boost or cut amount.','Equalization',ARRAY['Boost and cut asymmetry','Band-reject filter','Quality factor','Graphic equalizer','Parametric equalizer']::text[],ARRAY['Assuming all graphic equalizers are constant-Q.','Confusing constant-Q with constant absolute bandwidth in Hz.','Expecting proportional-Q and constant-Q to overlap identically.']::text[],ARRAY['Choosing a constant-Q graphic EQ for predictable ringing control.','Comparing constant-Q and proportional-Q equalizers on a system.','Explaining why band interaction differs between EQ types.']::text[],'Intermediate','Q = f0 / BW  (held constant vs. gain)','The quality factor equals center frequency divided by bandwidth, and a constant-Q design keeps this value fixed regardless of the boost or cut amount.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-Q equalizers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe7a5054-8f1c-4d64-b95a-177f724a2f6a','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe7a5054-8f1c-4d64-b95a-177f724a2f6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe7a5054-8f1c-4d64-b95a-177f724a2f6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9bc357d7-3065-4bdb-886c-7bbf8565f34c','Control smoothing','Control smoothing applies low-pass filtering or interpolation to control and parameter values so they change gradually instead of in abrupt steps. It prevents zipper noise and clicks that occur when a parameter such as gain or filter cutoff is updated once per audio block.','When you move a control, its value can jump in steps. Those jumps cause clicks or a zipper sound. Control smoothing eases each change gradually. This keeps parameter moves quiet.','It keeps parameter automation and knob movements quiet by removing the abrupt steps that cause clicks and zipper noise.','When automating a volume fade, a plugin smooths the gain changes over each block so the fade sounds continuous rather than stepped.','Modulation & Envelopes',ARRAY['Averaging detection','Control-rate versus audio-rate modulation','Attack-decay-sustain-release behavior','Zipper noise','Interpolation']::text[],ARRAY['Ignoring smoothing and getting zipper noise on fast automation.','Over-smoothing so controls feel sluggish.','Assuming block-rate parameter updates are always click-free.']::text[],ARRAY['Automating a filter sweep without audible stepping.','Fading a channel smoothly in a digital mixer.','Explaining zipper noise from coarse parameter updates.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Control smoothing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9bc357d7-3065-4bdb-886c-7bbf8565f34c','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9bc357d7-3065-4bdb-886c-7bbf8565f34c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9bc357d7-3065-4bdb-886c-7bbf8565f34c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32846abd-3488-45f5-862d-6efeb555f1ef','Control-rate versus audio-rate modulation','Control-rate (k-rate) signals update at a lower rate than the audio sample rate and drive slow parameters such as envelopes and low-frequency oscillators, saving computation. Audio-rate (a-rate) signals update every sample and are needed when a modulator itself must reach audio frequencies, as in audio-rate frequency or amplitude modulation.','Some control signals move slowly, like an envelope or a slow LFO. These can update less often to save power. Others must run at full audio speed. Fast modulation, like FM, needs the audio rate.','It balances efficiency and capability: slow controls run cheaply at a low rate, while fast modulation runs at the full audio rate.','A designer runs a 2 Hz vibrato LFO at control rate, but switches a modulator to audio rate when it must create audible FM sidebands.','Modulation & Envelopes',ARRAY['Bessel-function sideband behavior','Control smoothing','Attack-decay-sustain-release behavior','Low-frequency oscillator','Frequency modulation synthesis']::text[],ARRAY['Trying to make audio-rate FM with a control-rate modulator.','Assuming every modulator must run at the audio sample rate.','Ignoring stepping artifacts when a control-rate signal changes fast.']::text[],ARRAY['Choosing an LFO update rate in a modular or software synth.','Switching a modulator to audio rate to create FM timbres.','Explaining why some modulators can and others cannot make sidebands.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Control-rate versus audio-rate modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32846abd-3488-45f5-862d-6efeb555f1ef','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32846abd-3488-45f5-862d-6efeb555f1ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32846abd-3488-45f5-862d-6efeb555f1ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0dcce8ba-70fb-405d-ab28-2c72ae01b53f','Convolution reverberation','Convolution reverberation recreates the sound of a real space by convolving the dry signal with a measured impulse response of that space. The impulse response captures the room''s reflections and decay, and fast (partitioned) convolution makes the process practical in real time.','Convolution reverb copies a real space using a recording of it. That recording is called an impulse response. The dry sound is combined with it by math. The result sounds like the real room.','It provides highly realistic reverberation of specific real or modeled spaces by applying their measured impulse responses.','A technician loads a cathedral impulse response into a convolution reverb and mixes in the wet signal to place a dry voice in that space.','Reverberation',ARRAY['Algorithmic reverberation','Chamber-reverb behavior','Impulse response','Comb filtering in short delays','Reverberation time']::text[],ARRAY['Assuming convolution reverb can freely reshape decay like an algorithmic reverb.','Using a poor or noisy impulse response and expecting a clean result.','Confusing the impulse response file with an ordinary audio recording.']::text[],ARRAY['Placing a dry vocal into a captured concert hall.','Matching a re-recorded line to the reverb of an existing scene.','Choosing convolution over algorithmic reverb for realism.']::text[],'Advanced','y[n] = Σ_k x[k]·h[n-k]','The output equals the dry signal convolved with the space''s impulse response, summing delayed and scaled copies of the input.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Convolution reverberation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0dcce8ba-70fb-405d-ab28-2c72ae01b53f','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0dcce8ba-70fb-405d-ab28-2c72ae01b53f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0dcce8ba-70fb-405d-ab28-2c72ae01b53f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a1fdd29-5f2c-45c8-988f-6fa6ac0fe517','Convolution synthesis','Convolution synthesis (convolution processing) is a technique that combines an input signal with a recorded impulse response by discrete convolution, so the output carries the spectral and time behaviour of the captured system. It underlies convolution reverb, cabinet/mic emulation, and applying a measured filter to audio.','This method mixes a sound with a recorded ''fingerprint'' of a space or device. The fingerprint is called an impulse response. The result makes the sound seem to pass through that space or gear. Convolution reverb works this way.','It lets a technician impose the exact measured acoustics of a real room, speaker, or filter onto any signal, instead of approximating it with a synthetic algorithm.','Load a hall impulse response into a convolution reverb; the plugin convolves each input sample with the stored response so a dry vocal takes on that hall''s decay.','Effects Processing',ARRAY['Impulse response','Convolution reverb','Finite impulse response filters','Delay filtering','Cabinet emulation']::text[],ARRAY['Confusing convolution with simple mixing; convolution multiplies and sums shifted copies, it does not just add signals.','Forgetting that a long impulse response adds latency and heavy CPU cost in real time.','Assuming any recording works as an impulse response; it must be a clean impulse or swept-sine measurement.']::text[],ARRAY['Adding a real concert-hall tail to a dry studio vocal.','Emulating a specific guitar cabinet from its measured impulse response.','Applying a measured room correction filter stored as an impulse response.']::text[],'Advanced','y[n] = sum_{k} x[k] * h[n-k]','Each output sample is the sum, over all offsets, of the input sample multiplied by the impulse response shifted by that offset.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Convolution synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a1fdd29-5f2c-45c8-988f-6fa6ac0fe517','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a1fdd29-5f2c-45c8-988f-6fa6ac0fe517') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a1fdd29-5f2c-45c8-988f-6fa6ac0fe517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08cd2d10-5a3c-4f86-aa65-b353fd58b929','Corrective versus creative equalization','Corrective equalization removes problems such as resonances, room modes, or masking, aiming for a neutral result, while creative equalization deliberately shapes tone for artistic effect. The distinction is one of intent, not of the filter type used.','Corrective EQ fixes problems in a sound. It removes harsh peaks, hum, or muddiness. Creative EQ shapes tone for style, not repair. The same EQ tools do both jobs. Your goal decides which one you are doing.','It frames why an engineer reaches for an equalizer: either to repair a flaw toward neutrality or to sculpt a signature tone for the mix.','A technician cuts a 250 Hz room resonance on a mic (corrective), then adds a broad high-shelf boost to brighten the vocal for the chorus (creative).','Equalization',ARRAY['Dynamic equalization','Equalization versus resonance control','Parametric equalizer','Filter Q','Corrective filtering']::text[],ARRAY['Treating every EQ move as ''fixing'' when it is really taste, or the reverse.','Making large creative boosts that reintroduce the very resonance that was corrected.','Correcting each track in solo, ignoring how it fits the full mix.']::text[],ARRAY['Notching feedback frequencies in a live vocal (corrective).','Brightening an acoustic guitar to cut through a dense mix (creative).','Removing a boomy room mode from a podcast recording (corrective).']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Corrective versus creative equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08cd2d10-5a3c-4f86-aa65-b353fd58b929','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08cd2d10-5a3c-4f86-aa65-b353fd58b929') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08cd2d10-5a3c-4f86-aa65-b353fd58b929');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7f0804e-e5c2-492e-9560-1e0fe4022417','Correlated noise','Correlated noise consists of noise components that share a statistical or phase relationship, so they combine coherently rather than at random. Correlated signals add by voltage (about +6 dB per doubling), while uncorrelated noise adds by power (about +3 dB per doubling).','Correlated noise is noise that is linked between signals or channels. Because it lines up, it adds strongly when you combine paths. Random, unrelated noise adds more weakly. Knowing the difference helps you predict noise build-up.','It explains why some noise sources reinforce when signals are summed, guiding gain-staging, channel summing, and noise-reduction choices.','Sum two channels sharing the same correlated hum: level rises about 6 dB, whereas two independent hiss sources rise only about 3 dB.','Noise',ARRAY['Uncorrelated noise','Differential-mode noise','Common-mode noise','Dither noise','Ground loop']::text[],ARRAY['Assuming all noise adds at +3 dB; correlated noise can add at +6 dB.','Confusing correlated noise with correlated signal content that carries information.','Ignoring that mono summing of stereo can reinforce correlated low-frequency noise.']::text[],ARRAY['Predicting hum build-up when paralleling channels sharing a power source.','Deciding whether mid-side or mono summing worsens a common noise.','Comparing coherent (correlated) versus random noise on a spectrum analyzer.']::text[],'Intermediate','L_correlated = 20*log10(N);  L_uncorrelated = 10*log10(N)','Combining N correlated sources raises level by twenty times the log of N, while N uncorrelated sources raise it by ten times the log of N.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Correlated noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7f0804e-e5c2-492e-9560-1e0fe4022417','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7f0804e-e5c2-492e-9560-1e0fe4022417') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7f0804e-e5c2-492e-9560-1e0fe4022417');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc964aa7-afeb-4ebe-b913-7303579c9e26','De-essing','De-essing is frequency-selective dynamics processing that reduces excessive sibilance (the ''s'', ''sh'', and ''t'' sounds), typically in the 4 kHz to 10 kHz region, by attenuating only when energy in that band exceeds a threshold. It is implemented as a side-chain-filtered compressor or as split-band/dynamic EQ.','De-essing tames harsh ''s'' and ''sh'' sounds in speech and vocals. It listens to the high frequencies where sibilance lives. When those get too loud, it turns them down for a moment. The rest of the voice stays untouched.','It controls harsh sibilant peaks that can sound piercing or cause distortion, without dulling the whole vocal.','Set a de-esser''s detection band around 6 to 8 kHz on a vocal; it applies gain reduction only on the sibilant bursts, leaving the body of the voice unchanged.','Dynamics Processing',ARRAY['Dynamic equalization','Sibilance','Compressor','Side-chain','Split-band processing']::text[],ARRAY['Setting the threshold so low that the whole vocal is dulled, not just the ''s'' sounds.','Placing the detection band too low, so it clamps on non-sibilant vocal energy.','Over-de-essing until the singer sounds like they have a lisp.']::text[],ARRAY['Reducing harsh ''s'' sounds on a close-miked lead vocal.','Cleaning sibilance from a voice-over before broadcast.','Taming cymbal or hi-hat ''sizzle'' bleeding into a vocal bus.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='De-essing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc964aa7-afeb-4ebe-b913-7303579c9e26','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc964aa7-afeb-4ebe-b913-7303579c9e26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc964aa7-afeb-4ebe-b913-7303579c9e26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a3bbee0-6a90-40f8-b7a0-4bba4950a180','Delay filtering','Delay filtering is the frequency-shaping that arises when a signal is summed with a delayed copy of itself, producing a comb filter with regularly spaced peaks and notches. The notch spacing equals the reciprocal of the delay time.','Mixing a sound with a slightly delayed copy creates a filter. It adds a row of peaks and dips across the spectrum, called a comb filter. This is why short delays can make sound hollow or phasey. The delay length sets the notch spacing.','It explains both an unwanted effect (comb filtering from reflections or mis-timed mics) and a deliberate tool (flanging, chorus, and FIR filters built from delays).','Sum a signal with a 1 ms delayed copy; notches appear at 500 Hz, 1500 Hz, and so on, at odd multiples of 1/(2 x delay).','Filtering',ARRAY['Comb filtering','Flanger','Finite impulse response filters','Delay-line interpolation','Phase cancellation']::text[],ARRAY['Blaming EQ for a hollow sound that is really comb filtering from two mics.','Assuming the delayed copy must be long; even under a millisecond causes audible combing.','Forgetting that feedback (recirculating) delay sharpens the comb peaks versus a single feed-forward tap.']::text[],ARRAY['Diagnosing hollow tone when two mics on one source are not time-aligned.','Building a flanger by modulating a very short delay.','Understanding why a floor reflection colors a stage mic.']::text[],'Intermediate','f_notch = (2k-1) / (2*T),  k = 1,2,3,...','For a signal summed with its delayed copy, notches fall at odd multiples of one over twice the delay time.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay filtering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a3bbee0-6a90-40f8-b7a0-4bba4950a180','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a3bbee0-6a90-40f8-b7a0-4bba4950a180') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a3bbee0-6a90-40f8-b7a0-4bba4950a180');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12d67b8b-dd26-47e5-8d31-5f273ba0fc6d','Delay-line interpolation','Delay-line interpolation computes output at fractional (non-integer) sample delays by estimating values between stored samples, using methods such as linear, Lagrange, or allpass interpolation. It is required for smooth, click-free time-varying delays like chorus, flanging, and pitch shifting.','A digital delay stores whole samples. But effects often need a delay between samples. Interpolation estimates that in-between value. This lets the delay time glide smoothly. Without it, moving delays would click or step.','It provides continuous, artifact-free delay lengths so modulated-delay effects can sweep smoothly and pitch shifters can read at fractional rates.','For a delay of 100.4 samples using linear interpolation, blend sample 100 and 101: output = 0.6 x s[100] + 0.4 x s[101].','Effects Processing',ARRAY['Delay-line','Doppler effects during delay modulation','Chorus','Fractional delay','Pitch shifting']::text[],ARRAY['Using no interpolation on a modulated delay, causing zipper noise or clicks.','Assuming linear interpolation is transparent; it adds a gentle high-frequency roll-off.','Confusing fractional-delay interpolation with sample-rate upsampling.']::text[],ARRAY['Building a smooth chorus that sweeps delay time.','Implementing a pitch shifter that reads the buffer at a non-integer rate.','Fine-aligning loudspeaker delay to sub-sample accuracy.']::text[],'Advanced','y[n] = (1 - a) * x[n - M] + a * x[n - M - 1]','Linear interpolation blends the two nearest stored samples in proportion to the fractional part of the desired delay.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay-line interpolation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12d67b8b-dd26-47e5-8d31-5f273ba0fc6d','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12d67b8b-dd26-47e5-8d31-5f273ba0fc6d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12d67b8b-dd26-47e5-8d31-5f273ba0fc6d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66403560-eeb5-4322-a64c-850582417687','Denoising artifacts','Denoising artifacts are unwanted byproducts of noise-reduction processing, most notably ''musical noise'' (transient warbling tones, sometimes called birdies) produced when spectral-subtraction gains fluctuate on isolated frequency bins. Other artifacts include dulling of high frequencies, transient smearing, and pumping.','Noise reduction can leave odd sounds behind. A common one is ''musical noise'', a warbly, tinkling ringing. It happens when the tool cuts noise unevenly across frequencies. Push the reduction too hard and it also dulls or smears the sound.','It names the audible penalties of aggressive noise reduction so a technician can balance noise removal against fidelity.','When spectral-subtraction denoising leaves warbly birdies, reduce the amount of reduction or raise the noise-floor estimate so weak bins are not toggled on and off.','Noise',ARRAY['Spectral subtraction','Musical noise','Noise reduction','Transient smearing','Denoising']::text[],ARRAY['Pushing reduction so far that musical noise is worse than the original hiss.','Blaming the source recording for warble actually created by the denoiser.','Ignoring that heavy denoising smears transients and dulls the top end.']::text[],ARRAY['Cleaning hiss from a location dialogue recording.','Removing air-conditioning rumble from a podcast.','Restoring an old tape while avoiding warbly artifacts.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Denoising artifacts');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66403560-eeb5-4322-a64c-850582417687','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66403560-eeb5-4322-a64c-850582417687') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66403560-eeb5-4322-a64c-850582417687');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c99fe11b-1d32-45f2-a592-cf1fa9a53f0f','Detector circuit','A detector circuit (level detector or side-chain detector) is the part of a dynamics processor that estimates the signal''s level to drive gain control, using peak or RMS sensing followed by attack/release smoothing. Its output is the control signal that the gain-computer maps to gain reduction.','A compressor needs to know how loud the signal is. The detector measures that level. It can follow fast peaks or the average (RMS) energy. Attack and release settings smooth how quickly it reacts. This measurement then sets the gain change.','It converts the audio into a level estimate that determines when and how much a compressor, limiter, gate, or expander acts.','Choose peak detection for a limiter catching fast transients, or RMS detection for a compressor that should follow perceived loudness on a vocal bus.','Dynamics Processing',ARRAY['RMS detection','Peak detection','Side-chain','Attack and release','Gain computer']::text[],ARRAY['Confusing peak and RMS detection; RMS reads lower on transient-rich material.','Assuming the detector sets gain directly; it feeds a separate gain computer.','Overlooking that detector placement (log versus linear domain) changes the ballistics.']::text[],ARRAY['Selecting peak versus RMS mode on a bus compressor.','Feeding a de-esser''s detector from a filtered side-chain.','Tuning a gate''s detector to open on drum hits but not spill.']::text[],'Intermediate','y[n] = (1 - a) * x[n] + a * y[n-1]','A one-pole smoother blends the new level with the previous level, where the coefficient sets attack or release speed.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Detector circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c99fe11b-1d32-45f2-a592-cf1fa9a53f0f','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c99fe11b-1d32-45f2-a592-cf1fa9a53f0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c99fe11b-1d32-45f2-a592-cf1fa9a53f0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6f2c8f1-f247-47a9-bb39-27dd256e159c','Differential-mode noise','Differential-mode noise (normal-mode or transverse noise) is interference that appears as a voltage difference between the two signal conductors, in the same way as the wanted signal. Because it rides on the signal pair, a balanced input''s common-mode rejection cannot remove it.','Differential-mode noise sits between the two signal wires, just like real audio. A balanced input treats it as signal, so it passes through. This is the opposite of common-mode noise, which is on both wires equally. Filtering, not balancing, is what fights it.','It distinguishes noise that balanced interconnects cannot reject from common-mode noise that they can, guiding correct filtering and shielding decisions.','If hum survives on a balanced line, suspect differential-mode pickup and add a differential (normal-mode) filter or reroute the cable, since balancing alone will not cancel it.','Noise',ARRAY['Common-mode noise','Common-mode rejection','Correlated noise','Balanced audio','Shielding']::text[],ARRAY['Expecting a balanced connection to reject differential-mode noise; it cannot.','Confusing differential-mode (between conductors) with common-mode (conductor-to-ground).','Adding only a common-mode choke and expecting it to fix differential-mode hum.']::text[],ARRAY['Troubleshooting hum that persists on a properly balanced line.','Specifying EMI filters for a power or audio input.','Explaining why a ground lift does not cure certain noise.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differential-mode noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6f2c8f1-f247-47a9-bb39-27dd256e159c','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6f2c8f1-f247-47a9-bb39-27dd256e159c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6f2c8f1-f247-47a9-bb39-27dd256e159c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d7a4bec-00ac-41ea-b590-2814b6844a20','Distortion audibility','Distortion audibility describes the conditions under which nonlinear distortion becomes perceptible, which depends on the distortion''s level, harmonic order, spectrum, and on auditory masking by the program material. Higher-order and non-harmonically-related products are generally more audible than low-order harmonic distortion at the same level.','Not all distortion can be heard. Whether you notice it depends on how loud it is and its makeup. Low, even harmonics hide easily and can sound pleasant. High-order or clashing products stand out more. Loud, busy music also masks distortion.','It explains why measured total harmonic distortion alone does not predict what listeners hear, informing both quality thresholds and creative use of distortion.','A technician weighs that 1 percent second-harmonic distortion on a warm bass may be inaudible, while a smaller amount of high-order or intermodulation distortion on a cymbal is obvious.','Distortion',ARRAY['Total harmonic distortion','Intermodulation distortion','Even-order harmonics','Auditory masking','Distortion versus coloration']::text[],ARRAY['Assuming a single THD number tells you how audible distortion is.','Ignoring intermodulation distortion, which is often more audible than harmonic distortion.','Believing all distortion is bad; low-order harmonics can be euphonic.']::text[],ARRAY['Judging whether an amplifier''s distortion spec matters for a program.','Deciding how hard to drive a tube stage for pleasing warmth.','Setting acceptable distortion limits for a broadcast chain.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion audibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d7a4bec-00ac-41ea-b590-2814b6844a20','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d7a4bec-00ac-41ea-b590-2814b6844a20') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d7a4bec-00ac-41ea-b590-2814b6844a20');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1cfd713-1203-4cb0-bc81-4b2d5649c484','Distortion versus coloration','Distortion is a nonlinear alteration that adds new frequency components (harmonics and intermodulation products) not present in the input, whereas coloration is a linear change in the frequency and phase response that alters the balance of existing components without creating new ones. Distortion changes the signal''s content; coloration reshapes its spectrum.','Distortion adds new tones that were not in the original sound. Coloration only changes the balance of tones already there, like a fixed EQ. One is nonlinear, the other linear. A fuzz pedal distorts; a resonant box colors.','It separates two different ways gear alters sound so a technician can diagnose whether a change comes from nonlinearity or from response shaping.','When a preamp sounds ''thick'', test with a sine sweep: new harmonics on a spectrum analyzer mean distortion, while a smooth response bump with no new tones means coloration.','Distortion',ARRAY['Distortion audibility','Harmonic distortion','Frequency response','Equalization','Even-order harmonics']::text[],ARRAY['Calling any tonal change ''distortion'' when it is really linear coloration.','Assuming coloration adds harmonics; a linear filter cannot create new frequencies.','Judging warmth by ear alone without checking for added harmonics.']::text[],ARRAY['Describing the character of an analog console versus a clean converter.','Deciding whether a ''vibe'' plugin distorts or just EQs.','Explaining why an EQ boost is not the same as saturation.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion versus coloration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1cfd713-1203-4cb0-bc81-4b2d5649c484','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1cfd713-1203-4cb0-bc81-4b2d5649c484') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1cfd713-1203-4cb0-bc81-4b2d5649c484');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c5412a87-9b47-4da0-96d2-5077c43d3764','Dither noise','Dither noise is a small, carefully shaped random signal added before quantization (for example when reducing word length) to decorrelate quantization error from the signal, linearizing the quantizer and eliminating distortion at the cost of a low, constant noise floor. Triangular probability density (TPDF) dither of about 2 LSB peak-to-peak is the standard choice for audio.','When you lower a recording''s bit depth, tiny rounding errors cause distortion. Dither adds a faint, random noise before rounding. This trades ugly distortion for a soft, steady hiss. TPDF dither is the usual type. It keeps quiet fades smooth and clean.','It removes quantization distortion and noise modulation that would otherwise appear on low-level signals when audio is truncated to fewer bits.','When exporting a 24-bit mix to a 16-bit CD master, apply TPDF dither at the final stage so quiet fade-outs stay smooth instead of granular.','Quantization',ARRAY['Quantization','Noise shaping','TPDF dither','Bit depth','Truncation']::text[],ARRAY['Dithering more than once in a chain; dither should be applied only at the final bit-depth reduction.','Truncating instead of dithering, which leaves audible low-level distortion.','Assuming higher bit depths never need dither; any word-length reduction does.']::text[],ARRAY['Mastering a 24-bit mix down to 16-bit for CD.','Bouncing a session to a lower bit depth for delivery.','Explaining why quiet reverb tails need dither to stay clean.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dither noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c5412a87-9b47-4da0-96d2-5077c43d3764','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c5412a87-9b47-4da0-96d2-5077c43d3764') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c5412a87-9b47-4da0-96d2-5077c43d3764');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b5c3538-297b-4a78-a4a7-934cfb1ec474','Doppler effects during delay modulation','When a delay line''s length is changed over time, the read pointer moves relative to the write pointer, so the output is momentarily read faster or slower than it was written, producing a pitch shift analogous to the Doppler effect. This is the mechanism behind the pitch wobble in vibrato, chorus, flanging, and Leslie-style effects.','If you change a delay''s time while sound plays, the pitch bends. Shortening the delay raises pitch; lengthening it lowers pitch. This is like the Doppler shift of a passing siren. It gives chorus and vibrato their gentle warble.','It explains why modulated delays add pitch movement, which is desirable in modulation effects but can be an unwanted side effect in variable audio delays.','A vibrato using a delay swept sinusoidally at rate 5 Hz shifts pitch by the delay''s rate of change; a faster or deeper sweep gives a stronger warble.','Effects Processing',ARRAY['Delay-line interpolation','Chorus','Flanger','Vibrato','Pitch shifting']::text[],ARRAY['Expecting a modulated delay to keep pitch constant; changing delay time always shifts pitch.','Confusing the depth of pitch shift with delay length; it depends on the rate of change, not the delay itself.','Assuming only fast modulation causes Doppler; even slow sweeps bend pitch slightly.']::text[],ARRAY['Explaining the warble in a chorus or vibrato patch.','Designing a Leslie rotary-speaker emulation.','Troubleshooting unwanted pitch wobble in a variable audio delay.']::text[],'Advanced','f_out / f_in = 1 - dD/dt','The output-to-input frequency ratio equals one minus the rate at which the delay time is changing.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Doppler effects during delay modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b5c3538-297b-4a78-a4a7-934cfb1ec474','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b5c3538-297b-4a78-a4a7-934cfb1ec474') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b5c3538-297b-4a78-a4a7-934cfb1ec474');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '692f240f-18c6-4c0c-9a97-43ba93942154','Dotted and triplet delays','Dotted and triplet delays are tempo-synced delay times derived from note values, where a dotted note lasts 1.5 times its base value and a triplet lasts two-thirds of it. They are computed from tempo so echoes lock rhythmically to the music.','Delay times can be matched to the song''s tempo. A dotted delay is one and a half times a note length. A triplet delay is two-thirds of a note length. These groove differently from a straight delay. Dotted-eighth delays are common on guitars.','They let echoes sit rhythmically with the track, creating groove and space instead of random-sounding repeats.','At 120 BPM a quarter note is 500 ms; a dotted eighth is 375 ms and an eighth triplet is about 167 ms, so set the delay to 375 ms for a classic dotted-eighth part.','Effects Processing',ARRAY['Tempo sync','Delay','Note value','Groove','Ping-pong delay']::text[],ARRAY['Mixing up dotted (1.5x) and triplet (0.667x) multipliers.','Forgetting to halve or quarter the quarter-note time for eighth or sixteenth values.','Setting delay by ear to the wrong subdivision, muddying the rhythm.']::text[],ARRAY['Dialing a dotted-eighth delay on a lead guitar.','Adding triplet echoes to a synth for a rolling feel.','Syncing a delay plugin to the session tempo.']::text[],'Beginner','t_quarter(ms) = 60000 / BPM;  t_dotted = 1.5 * t;  t_triplet = (2/3) * t','A quarter-note delay in milliseconds is sixty thousand divided by tempo; a dotted note is one-and-a-half times the base and a triplet is two-thirds of it.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dotted and triplet delays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '692f240f-18c6-4c0c-9a97-43ba93942154','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='692f240f-18c6-4c0c-9a97-43ba93942154') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='692f240f-18c6-4c0c-9a97-43ba93942154');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7a43f069-a230-4a38-8fbf-7951961dfccc','Driver offset and crossover phase','Driver offset is the physical difference in the acoustic centers of a loudspeaker''s drivers along the listening axis, which introduces a frequency-dependent time and phase difference at the crossover region. If uncorrected, this offset shifts the summed response, tilts the coverage lobe, and can cause dips at the crossover frequency.','In a speaker, the woofer and tweeter sit at different depths. So their sound reaches your ears at slightly different times. Near the crossover, this timing gap changes how they combine. It can cause a dip or tilt the sound off-axis. Aligning the drivers fixes it.','It explains why loudspeaker designers time-align or physically offset drivers, and why crossover phase must be managed so bands sum flat.','When a two-way monitor dips at the crossover, apply delay to the closer driver or use a stepped baffle so both drivers'' outputs arrive in phase at the listener.','Crossovers',ARRAY['Crossover','Linkwitz-Riley crossover','Phase alignment','Acoustic center','Equivalent combined slope']::text[],ARRAY['Ignoring physical driver offset when setting a crossover, causing a crossover-region dip.','Assuming electrical alignment guarantees acoustic alignment; the acoustic centers still differ.','Confusing polarity inversion with time alignment; flipping polarity does not fix an offset.']::text[],ARRAY['Tuning a multi-driver PA cabinet''s crossover.','Time-aligning a subwoofer to main tops.','Diagnosing a response dip at a two-way monitor''s crossover.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Driver offset and crossover phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7a43f069-a230-4a38-8fbf-7951961dfccc','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7a43f069-a230-4a38-8fbf-7951961dfccc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7a43f069-a230-4a38-8fbf-7951961dfccc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ebcb35e4-130e-430f-a215-0aa915c4b886','Dynamic equalization','Dynamic equalization is EQ whose gain in a chosen band changes automatically with the signal level in that band, boosting or cutting only when a threshold is crossed. It combines the frequency selectivity of a parametric EQ with the level-dependence of a compressor.','A normal EQ change is fixed all the time. Dynamic EQ only acts when a band gets too loud or too quiet. It is like a compressor that works on one frequency range. This targets problems that come and go, like an occasional harsh note.','It lets an engineer tame or lift a specific frequency range only when needed, avoiding the static, always-on change of ordinary EQ.','Set a dynamic EQ band at 3 kHz on a vocal to cut 4 dB only when harshness spikes, leaving softer passages unaffected.','Equalization',ARRAY['De-essing','Multiband compression','Parametric equalizer','Compressor','Corrective versus creative equalization']::text[],ARRAY['Confusing dynamic EQ with multiband compression; dynamic EQ uses EQ-shaped filters, not crossover-split bands.','Setting the threshold so the band always acts, making it a static EQ.','Forgetting that attack and release still shape how naturally it reacts.']::text[],ARRAY['Taming an occasional harsh resonance on a vocal.','Controlling boomy notes on a bass only when they jump out.','Adding presence to a chorus that only needs lift when it swells.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ebcb35e4-130e-430f-a215-0aa915c4b886','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ebcb35e4-130e-430f-a215-0aa915c4b886') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ebcb35e4-130e-430f-a215-0aa915c4b886');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '128b32e9-8f5f-44d3-b185-0ca59545134d','Dynamic nonlinearities','Dynamic (memory) nonlinearities are nonlinear behaviours whose output depends not only on the present input but on past inputs, such as hysteresis, thermal drift, and level-dependent time effects. They contrast with static (memoryless) nonlinearities, whose output depends only on the instantaneous input.','Some distortion depends only on how loud the sound is right now. That kind has no memory. Other distortion also depends on what came before. Tape and heat effects work this way. This memory makes them harder to copy.','It explains why some analog devices cannot be captured by a simple waveshaping curve and require models with memory to reproduce faithfully.','When modeling a tape machine, a technician uses a hysteresis model because a static transfer curve cannot reproduce its level- and history-dependent distortion.','Distortion',ARRAY['Static nonlinearity','Hysteresis','Harmonic distortion','Waveshaping','Analog modeling']::text[],ARRAY['Modeling a memory-dependent device with a static transfer curve.','Assuming all distortion is instantaneous and level-only.','Confusing dynamic nonlinearity with a compressor''s dynamic gain change.']::text[],ARRAY['Emulating tape or transformer saturation.','Explaining why some analog gear sounds different at different levels over time.','Choosing a modeling approach for a nonlinear device.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic nonlinearities');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '128b32e9-8f5f-44d3-b185-0ca59545134d','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='128b32e9-8f5f-44d3-b185-0ca59545134d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='128b32e9-8f5f-44d3-b185-0ca59545134d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9dfdafc6-3cd4-47be-9ad9-1539fa952ae6','Dynamic range compression','Dynamic range compression reduces the level difference between loud and quiet parts of a signal by attenuating levels above a threshold according to a ratio, then optionally applying make-up gain. Its behaviour is shaped by threshold, ratio, knee, attack, and release controls.','A compressor makes loud parts quieter, shrinking the gap between soft and loud. Above a set level (the threshold), it turns the signal down by a chosen ratio. Attack and release set how fast it reacts. Make-up gain restores overall loudness.','It controls dynamic range for consistency, loudness, and protection, and can also add punch or glue as a creative tool.','With threshold -20 dB and ratio 4:1, an input at -8 dB (12 dB over threshold) leaves at -17 dB output, since the 12 dB excess is reduced to 3 dB.','Dynamics Processing',ARRAY['Threshold','Ratio','Attack and release','Make-up gain','Knee']::text[],ARRAY['Confusing threshold with ratio; threshold sets when it acts, ratio sets how hard.','Adding excessive make-up gain and mistaking loudness for better compression.','Setting attack too fast and killing transients you meant to keep.']::text[],ARRAY['Evening out an inconsistent vocal performance.','Adding punch to a drum bus.','Protecting a broadcast feed from overshoots.']::text[],'Beginner','y = T + (x - T) / R,  for x > T','Above the threshold, the output level equals the threshold plus the amount by which the input exceeds it, divided by the ratio.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic range compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9dfdafc6-3cd4-47be-9ad9-1539fa952ae6','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9dfdafc6-3cd4-47be-9ad9-1539fa952ae6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9dfdafc6-3cd4-47be-9ad9-1539fa952ae6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e3161c0-c3e3-47df-83f6-a14738e5c663','Dynamic-range processing in logarithmic versus linear domains','Dynamic-range processors can compute level and gain in the linear (amplitude) domain or the logarithmic (decibel) domain, and the choice changes the ballistics and the static curve. Log-domain gain computation gives level-independent time constants and a clean constant-ratio characteristic, which is why most digital compressors detect and compute gain in decibels.','A compressor can measure and adjust level using raw amplitude or using decibels. Working in decibels (the log domain) keeps its timing steady across levels. It also gives a clean, fixed ratio. This is why most digital compressors work in decibels.','It explains a key design decision in dynamics processing that determines how consistent a compressor''s ratio and timing feel across different signal levels.','A technician choosing a compressor design detects level in dB and smooths gain in the log domain, so a 4:1 ratio and a 100 ms release behave the same for loud and quiet passages.','Dynamics Processing',ARRAY['Gain computer','Detector circuit','Dynamic range compression','Attack and release','Decibel']::text[],ARRAY['Assuming the domain choice does not affect the sound; it changes ballistics and the curve shape.','Confusing the log detector with the log gain-smoothing stage.','Expecting a linear-domain smoother to give level-independent release times.']::text[],ARRAY['Comparing why two compressors with the same settings sound different.','Designing a digital dynamics algorithm.','Explaining level-dependent release behaviour to a student.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic-range processing in logarithmic versus linear domains');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e3161c0-c3e3-47df-83f6-a14738e5c663','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e3161c0-c3e3-47df-83f6-a14738e5c663') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e3161c0-c3e3-47df-83f6-a14738e5c663');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8bd1be57-7b56-45de-ac4a-24e0683c3139','Elliptic response','An elliptic (Cauer) filter response has equalized ripple (equiripple) in both the passband and the stopband, giving the steepest transition from passband to stopband for a given filter order. This sharpness comes at the cost of ripple in both bands and strongly nonlinear phase near cutoff.','An elliptic filter has the sharpest possible cutoff for its size. It gets this by allowing small ripples in both the pass and stop regions. The trade-off is uneven response and phase distortion near the corner. It is chosen when a very steep slope matters most.','It provides the most abrupt transition band of the common filter families, useful when a sharp cutoff is required and some ripple and phase distortion are acceptable.','A technician picks an elliptic anti-alias or brick-wall filter when the priority is rejecting frequencies just above cutoff, accepting passband ripple in exchange.','Filtering',ARRAY['Butterworth response','Chebyshev response','Bessel response','Passband ripple','Filter cutoff frequency']::text[],ARRAY['Assuming elliptic filters are flat in the passband; they ripple in both bands.','Choosing elliptic where phase linearity matters; its phase is highly nonlinear near cutoff.','Confusing elliptic (ripple in both bands) with Chebyshev (ripple in one band).']::text[],ARRAY['Designing a steep anti-aliasing filter.','Building a brick-wall crossover where slope is critical.','Comparing filter families for a sharp band-limiting task.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Elliptic response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8bd1be57-7b56-45de-ac4a-24e0683c3139','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8bd1be57-7b56-45de-ac4a-24e0683c3139') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8bd1be57-7b56-45de-ac4a-24e0683c3139');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f81be3c8-460d-40ba-972b-30c7cd9cfeec','Envelope generators','An envelope generator produces a time-varying control signal, most commonly the ADSR (attack, decay, sustain, release) contour, used to shape a parameter such as amplitude, filter cutoff, or pitch over the duration of a note. It is triggered by a gate or note event rather than being an audio signal itself.','An envelope generator makes a control shape over time, not a sound. The classic shape has four stages: attack, decay, sustain, and release (ADSR). It can control volume, filter, or pitch as a note plays. Pressing a key triggers it.','It gives synthesizers and processors a way to make parameters evolve through a note, creating natural-sounding swells, plucks, and fades.','Route an ADSR to a synth''s filter cutoff: a short attack and quick decay give a percussive pluck, while a long release lets the tone fade after key release.','Modulation',ARRAY['ADSR','Low-frequency oscillator','Gate','Attack and release','Modulation']::text[],ARRAY['Confusing an envelope generator with an LFO; the envelope runs once per trigger, the LFO cycles continuously.','Mixing up sustain (a level) with the other stages (which are times).','Expecting the envelope itself to be audible; it is a control signal.']::text[],ARRAY['Shaping a synth''s amplitude for a plucked or pad sound.','Modulating filter cutoff for an evolving tone.','Triggering a control contour from a MIDI note.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Envelope generators');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f81be3c8-460d-40ba-972b-30c7cd9cfeec','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f81be3c8-460d-40ba-972b-30c7cd9cfeec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f81be3c8-460d-40ba-972b-30c7cd9cfeec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c32111f-c3d6-4ae4-85b7-4c395b82defc','Equalization versus resonance control','Equalization adjusts the level of frequency bands, while resonance control specifically targets resonant peaks by adjusting their gain and, crucially, their Q (damping). Resonance control aims to tame narrow, ringing peaks, whereas general EQ shapes broad tonal balance.','EQ raises or lowers the level of frequency ranges. Resonance control is aimed at sharp, ringing peaks. It uses a narrow, high-Q filter to catch just the resonance. Broad EQ shapes overall tone; resonance control fixes one troublesome peak.','It clarifies when to use a broad tonal move versus a narrow, high-Q notch to control a specific resonance or ring.','To kill a ringing room mode, use a narrow high-Q cut at the exact frequency (resonance control) rather than a wide EQ dip that also thins nearby tones.','Equalization',ARRAY['Filter Q','Notch filter','Corrective versus creative equalization','Room modes','Filter ringing']::text[],ARRAY['Using a broad, low-Q cut to fix a narrow resonance, harming nearby frequencies.','Confusing the resonance (peak sharpness) with overall level.','Boosting instead of cutting when trying to find a resonance.']::text[],ARRAY['Notching a feedback frequency in a live rig.','Removing a ringing room mode in a control room.','Taming a resonant guitar body boom.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equalization versus resonance control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c32111f-c3d6-4ae4-85b7-4c395b82defc','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c32111f-c3d6-4ae4-85b7-4c395b82defc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c32111f-c3d6-4ae4-85b7-4c395b82defc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c3e6de9-8592-43ff-b753-1343ad435988','Equalizer interaction between adjacent bands','When two equalizer bands are set close in frequency, their responses overlap and sum, so the combined boost or cut at frequencies between them is greater than either band alone. In graphic equalizers this band interaction means the achieved curve differs from the slider positions unless the design is constant-Q.','Two EQ bands set near each other overlap. Where they meet, their boosts add up. So the real curve can be bigger than each slider shows. This is why a graphic EQ''s sliders may not match the sound. Constant-Q designs reduce this overlap effect.','It explains why closely spaced EQ moves add up unpredictably, and why graphic-EQ slider positions do not always match the resulting response.','Boosting adjacent 1 kHz and 1.25 kHz graphic-EQ bands by 6 dB each can yield more than 6 dB between them, so reduce both to hit the target level.','Equalization',ARRAY['Graphic equalizer','Constant-Q','Filter Q','Filter interaction','Parametric equalizer']::text[],ARRAY['Assuming a graphic EQ''s boost equals its slider setting; adjacent bands add.','Ignoring that non-constant-Q designs widen as boost increases, worsening overlap.','Stacking many small boosts and getting an unexpectedly large peak.']::text[],ARRAY['Ringing out a graphic EQ on a stage monitor.','Fine-shaping tone with two close parametric bands.','Understanding why a graphic EQ curve does not match the sliders.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equalizer interaction between adjacent bands');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c3e6de9-8592-43ff-b753-1343ad435988','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c3e6de9-8592-43ff-b753-1343ad435988') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c3e6de9-8592-43ff-b753-1343ad435988');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7fe83f73-6f0f-4e59-8732-d558d79c5af2','Equivalent combined slope','When filter stages are cascaded, their asymptotic roll-off slopes add, so the equivalent combined slope in decibels per octave is the sum of the individual slopes. For example, cascading two second-order (12 dB/octave) sections yields a fourth-order 24 dB/octave slope.','Put filters in series and their slopes add up. Two 12 dB-per-octave filters together give 24 dB per octave. Each filter order adds about 6 dB per octave. This is how designers build steeper cutoffs from simple stages.','It lets a technician predict the total roll-off of cascaded filter stages and choose how many sections are needed for a target slope.','To build a 24 dB/octave crossover from 12 dB/octave sections, cascade two of them; the equivalent combined slope is 12 + 12 = 24 dB/octave.','Filtering',ARRAY['Filter slope','Filter order','Linkwitz-Riley crossover','Cascaded filters','Butterworth response']::text[],ARRAY['Assuming slopes multiply or average; they add.','Forgetting that cascading changes the response shape (for example two Butterworth make a Linkwitz-Riley).','Confusing filter order with the number of poles in a way that mismatches the slope.']::text[],ARRAY['Designing a steeper crossover from lower-order sections.','Estimating attenuation an octave above cutoff.','Explaining why a fourth-order filter rolls off at 24 dB/octave.']::text[],'Intermediate','S_total = sum_i S_i  (approximately 6 dB/octave per filter order)','The total asymptotic slope equals the sum of the individual stage slopes, about six decibels per octave for each order of filtering.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent combined slope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7fe83f73-6f0f-4e59-8732-d558d79c5af2','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7fe83f73-6f0f-4e59-8732-d558d79c5af2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7fe83f73-6f0f-4e59-8732-d558d79c5af2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b8f4f8a4-c7f4-43e7-b81b-3406e00ee617','Even-order harmonics','Even-order harmonics are frequency components at even integer multiples of the fundamental (2f, 4f, 6f), produced by asymmetric (even-symmetry) nonlinearities. Because the second harmonic is one octave above the fundamental, even harmonics are often perceived as musically consonant or ''warm''.','Harmonics are tones at multiples of the main pitch. Even harmonics sit at two, four, and six times the fundamental. The second is exactly one octave up, so it blends musically. Gear that adds even harmonics often sounds warm. Asymmetric distortion creates them.','It identifies the harmonic content that asymmetric distortion adds and why it tends to sound pleasing, informing both tone shaping and distortion diagnosis.','A technician drives a tube or transformer stage to add second-harmonic (even) content for warmth, verifying on a spectrum analyzer that energy appears at twice the test-tone frequency.','Distortion',ARRAY['Odd-order harmonics','Harmonic distortion','Total harmonic distortion','Distortion versus coloration','Dynamic nonlinearities']::text[],ARRAY['Assuming even harmonics are always inaudible or always pleasant; level and context matter.','Confusing even-order (from asymmetric nonlinearity) with odd-order (from symmetric clipping).','Thinking harmonics appear below the fundamental; they are always above it.']::text[],ARRAY['Adding tube-style warmth with even-harmonic saturation.','Diagnosing distortion type from a spectrum plot.','Comparing the harmonic signature of different saturators.']::text[],'Intermediate','f_n = n * f0,  n = 2, 4, 6, ...','Even-order harmonic frequencies are even whole-number multiples of the fundamental frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Even-order harmonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b8f4f8a4-c7f4-43e7-b81b-3406e00ee617','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b8f4f8a4-c7f4-43e7-b81b-3406e00ee617') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b8f4f8a4-c7f4-43e7-b81b-3406e00ee617');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5cadb2b-496a-46a4-bea1-3a905eb38ab1','Feedback stability in delay networks','A recirculating (feedback) delay is bounded-input, bounded-output stable only if the total loop gain magnitude is less than one; a loop gain of one sustains oscillation and greater than one causes runaway build-up. In multi-delay reverb networks, stability requires the feedback matrix to be non-expansive (for example, lossless or contractive).','A delay that feeds its output back can build up. It stays stable only if the feedback gain is below one. At exactly one it never dies away. Above one it grows out of control and howls. Reverb networks must keep their feedback gains in check.','It sets the condition that keeps feedback delays and reverb algorithms from oscillating or blowing up, a core rule of echo and reverb design.','Set a feedback-delay effect''s regeneration to about 0.7 so echoes decay; pushing it to 1.0 or above makes the repeats grow into self-oscillation.','Effects Processing',ARRAY['Feedback delay network','Comb filter','Reverb','Regeneration','Delay-line']::text[],ARRAY['Setting feedback at or above 1.0 and getting runaway build-up.','Ignoring that added in-loop gain (EQ boost) can push loop gain over one.','Assuming a lossless reverb matrix decays; it needs damping to actually die away.']::text[],ARRAY['Setting the regeneration control on a delay pedal.','Designing a feedback-delay-network reverb.','Diagnosing a delay that howls or never decays.']::text[],'Advanced','|g| < 1','The delay loop is stable when the magnitude of the total feedback gain is less than one.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Feedback stability in delay networks');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5cadb2b-496a-46a4-bea1-3a905eb38ab1','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5cadb2b-496a-46a4-bea1-3a905eb38ab1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5cadb2b-496a-46a4-bea1-3a905eb38ab1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ae417a5-abbc-4de6-b7c7-8c95d4659429','Filter cutoff frequency','The cutoff frequency of a filter is the frequency at which its output power falls to half the passband value, equal to a 3 dB drop in level (the -3 dB or half-power point). For a simple first-order RC filter it is set by the resistance and capacitance.','A filter''s cutoff is where it starts to take effect. At that frequency the level has dropped by 3 dB. That is half the power. Below or above it, the filter passes or blocks more strongly. For a basic RC filter, the parts set this point.','It defines the reference point that marks where a filter transitions between passing and attenuating, used to set high-pass, low-pass, and crossover frequencies.','For a first-order high-pass with R = 1.6 kohm and C = 100 nF, cutoff = 1/(2*pi*R*C) is about 1 kHz, so set the mic''s low-cut there.','Filtering',ARRAY['Filter slope','Filter order','High-pass filter','Low-pass filter']::text[],ARRAY['Thinking the filter fully blocks everything past cutoff; it rolls off gradually by the slope.','Assuming cutoff is where level reaches zero, not -3 dB.','Confusing the -3 dB (amplitude) point with a -6 dB or other definition.']::text[],ARRAY['Setting a low-cut on a vocal mic.','Choosing a crossover frequency between a woofer and tweeter.','Placing a high-pass to remove rumble.']::text[],'Beginner','f_c = 1 / (2 * pi * R * C)','For a first-order RC filter, the cutoff frequency equals one divided by two pi times resistance times capacitance.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter cutoff frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ae417a5-abbc-4de6-b7c7-8c95d4659429','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ae417a5-abbc-4de6-b7c7-8c95d4659429') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ae417a5-abbc-4de6-b7c7-8c95d4659429');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '583231bc-da30-4ff3-b40e-622be032e7a5','Filter interaction','Filter interaction is the way multiple filters in a chain combine, where their magnitude and phase responses multiply so overlapping regions reinforce, cancel, or shift the overall response. Interaction is strongest when filters are close in frequency or have overlapping skirts.','When you use several filters together, they affect each other. Their responses multiply, not just stack neatly. Filters near the same frequency overlap and combine. This can make the total response differ from what each filter shows alone.','It explains why cascaded filters do not act independently, so a technician can anticipate the combined result of a filter chain.','When a low-cut at 120 Hz sits near a low-shelf boost at 150 Hz, their skirts interact, so the technician checks the summed response instead of trusting each control alone.','Filtering',ARRAY['Equalizer interaction between adjacent bands','Equivalent combined slope','Phase response','Cascaded filters','Crossover']::text[],ARRAY['Assuming filters in series act independently; their responses multiply.','Overlooking phase interaction that causes dips where magnitudes seem fine.','Placing a boost and cut close together and getting an unexpected net curve.']::text[],ARRAY['Stacking a high-pass and a low-shelf on the same track.','Combining crossover filters with driver-correction EQ.','Debugging an unexpected dip from two nearby filters.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '583231bc-da30-4ff3-b40e-622be032e7a5','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='583231bc-da30-4ff3-b40e-622be032e7a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='583231bc-da30-4ff3-b40e-622be032e7a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e29252a-e7a2-42a8-9d48-0de7937abe2d','Filter ringing','Filter ringing is time-domain oscillation in a filter''s impulse and step response, appearing as decaying overshoot after transients. It grows with high Q (resonance) and with steep, especially linear-phase, filters, where symmetric impulse responses produce pre-ringing before the transient as well as post-ringing after it.','A sharp filter can ''ring'' after a sudden sound. The output overshoots and wobbles briefly. High resonance and steep slopes make ringing worse. Linear-phase filters can even ring before the sound arrives. This smears transients like drum hits.','It warns that sharp or high-Q filtering trades frequency selectivity for time-domain smearing, guiding filter-type and slope choices on transient material.','A technician avoids a very steep linear-phase low-pass on a snare because its pre-ringing softens the attack; a gentler minimum-phase filter rings less.','Filtering',ARRAY['Filter Q','Linear-phase filter','Elliptic response','Impulse response','Transient response']::text[],ARRAY['Assuming steeper filters are always better; they ring and smear transients more.','Not knowing that linear-phase filters add pre-ringing before the transient.','Cranking Q for a tight EQ and introducing audible ring.']::text[],ARRAY['Choosing filter type for a mastering low-pass.','Diagnosing smeared drum transients after steep EQ.','Comparing linear-phase versus minimum-phase EQ on percussion.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter ringing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e29252a-e7a2-42a8-9d48-0de7937abe2d','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e29252a-e7a2-42a8-9d48-0de7937abe2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e29252a-e7a2-42a8-9d48-0de7937abe2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ad5652c5-36e5-439b-afa0-b7dc5f42f58f','Finite impulse response filters','A finite impulse response (FIR) filter computes each output as a weighted sum of a finite number of past and present input samples, so its impulse response settles to zero in finite time. FIR filters are always stable and can be made exactly linear-phase by using symmetric coefficients.','An FIR filter blends a fixed number of recent input samples with set weights. Its response to a single click dies out after a fixed time. It never uses its own past output, so it cannot go unstable. It can also keep phase perfectly linear.','It provides a filter that is inherently stable and can achieve exact linear phase, valued for phase-critical tasks like linear-phase EQ, convolution, and crossovers.','A technician uses an FIR linear-phase EQ on a mastering bus to boost highs without phase shift; the trade-off is higher latency from the long coefficient set.','Filtering',ARRAY['Infinite impulse response filters','Linear-phase filter','Convolution synthesis','Filter ringing','Filter order']::text[],ARRAY['Assuming FIR filters can be unstable; with no feedback they always are stable.','Forgetting FIR linear phase adds latency proportional to filter length.','Confusing the number of taps with filter order off by one, or with IIR poles.']::text[],ARRAY['Applying a linear-phase EQ in mastering.','Implementing convolution reverb (a long FIR).','Designing a phase-accurate loudspeaker crossover.']::text[],'Advanced','y[n] = sum_{k=0}^{M} b_k * x[n-k]','Each output sample is the sum of a finite set of input samples, each multiplied by its own coefficient.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite impulse response filters');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ad5652c5-36e5-439b-afa0-b7dc5f42f58f','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ad5652c5-36e5-439b-afa0-b7dc5f42f58f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ad5652c5-36e5-439b-afa0-b7dc5f42f58f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ca10c13-90b7-4aa1-811a-a7161be8d1d4','Foldback distortion','Foldback distortion is a nonlinear waveshaping process in which any part of a signal exceeding a set threshold is reflected (folded) back toward zero instead of being flattened by clipping. Repeated folding at high drive multiplies the transfer curve''s turning points, adding dense, inharmonic-sounding upper harmonics not present in simple clipping.','Foldback distortion bends a loud signal back on itself instead of chopping its top off. Each time the wave passes a limit, it folds and reverses direction. This adds many new bright harmonics. Synth wavefolders use it to enrich plain tones.','It shapes a waveform to add controllable harmonic content, giving synthesizers and effects a brighter, more complex timbre than plain clipping.','A technician patches a sine into a wavefolder and raises drive; at low fold the tone gains a few harmonics, and at high fold it becomes buzzy and metallic.','Nonlinear Distortion',ARRAY['Hard saturation','Wavefolding','Waveshaping','Harmonic distortion','Ring modulation']::text[],ARRAY['Confusing foldback distortion with ''foldback'' monitor sends, an unrelated British term for stage monitoring.','Assuming it only adds odd harmonics; folding produces a complex, drive-dependent harmonic pattern.','Expecting it to sound like normal clipping, when heavy folding is far more dissonant.']::text[],ARRAY['Using a West-Coast-style wavefolder module in a modular synthesizer patch.','Sound-designing an aggressive bass timbre from a simple triangle wave.','Diagnosing why an overdriven converter input produces oddly pitched artifacts.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Foldback distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ca10c13-90b7-4aa1-811a-a7161be8d1d4','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ca10c13-90b7-4aa1-811a-a7161be8d1d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ca10c13-90b7-4aa1-811a-a7161be8d1d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dadf7a72-bfad-4dea-aef7-cc2a1e0a4853','Formant synthesis','Formant synthesis generates speech or voice-like sounds using a source-filter model, driving an excitation source through a bank of resonant filters tuned to the formant frequencies of the vocal tract. Each resonator''s center frequency, bandwidth, and gain are set to reproduce the peaks (formants) that define vowel and consonant identity.','Formant synthesis builds a voice from a buzz source and a few resonant filters. Each filter forms a peak called a formant. These peaks are what make one vowel sound different from another. It does not replay recorded speech; it models how the mouth shapes sound.','It lets a system produce intelligible, tunable voice sounds from rules rather than stored recordings, saving memory and allowing full control of pitch and articulation.','A technician sets three resonators near 700, 1220, and 2600 Hz to make an ''ah'' vowel, then shifts them to morph toward ''ee'' while keeping pitch fixed.','Sound Synthesis',ARRAY['Source-filter model','Vocoder','Modal synthesis','Resonant filter','Additive synthesis']::text[],ARRAY['Thinking formants move with pitch; formant frequencies stay roughly fixed as pitch changes.','Confusing formant synthesis with sample playback of real speech.','Setting resonator bandwidths too narrow, which makes the voice sound artificial and ringing.']::text[],ARRAY['Programming a classic hardware speech synthesizer or ''talking'' synth patch.','Creating choir or vowel pad sounds on a subtractive synthesizer.','Building text-to-speech before concatenative and neural methods became common.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formant synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dadf7a72-bfad-4dea-aef7-cc2a1e0a4853','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dadf7a72-bfad-4dea-aef7-cc2a1e0a4853') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dadf7a72-bfad-4dea-aef7-cc2a1e0a4853');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66973f27-df55-44ee-907d-03c2047baeac','Frequency-conscious compression','Frequency-conscious compression is dynamics processing in which the compressor''s detector (side-chain) signal is frequency-shaped so gain reduction responds preferentially to chosen frequency bands rather than to broadband level. Filtering the side-chain, for example rolling off lows or emphasizing sibilance, makes the compressor ''listen'' selectively while still applying gain change across the full-band output.','Frequency-conscious compression makes a compressor react more to some frequencies than others. You filter the control signal it listens to, not the sound you hear. A de-esser is a common example; it clamps down mainly on harsh ''ess'' sounds. This tames one problem area without squashing everything.','It prevents a few strong frequencies, such as a kick thump or vocal sibilance, from triggering unwanted gain reduction across the whole signal.','A technician inserts a side-chain high-pass filter at about 100 Hz so a bass-heavy mix stops pumping every time the kick drum hits.','Dynamics Processing',ARRAY['Side-chain','De-esser','Multiband compression','Threshold','Detector path']::text[],ARRAY['Believing side-chain filtering changes the audible tone; it only changes what the detector responds to.','Confusing it with multiband compression, which actually splits and processes separate bands.','Over-filtering the detector so the compressor barely reacts at all.']::text[],ARRAY['De-essing a bright vocal by keying the compressor from a high-frequency band.','Stopping a full mix from pumping on kick-drum hits.','Keeping a bass guitar steady without reacting to low-string boom.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-conscious compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66973f27-df55-44ee-907d-03c2047baeac','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66973f27-df55-44ee-907d-03c2047baeac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66973f27-df55-44ee-907d-03c2047baeac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1e44f40-3f4e-4122-a35c-b7a2de87c331','Frequency-modulation index','The frequency-modulation index is the ratio of a carrier''s peak frequency deviation to the modulating frequency, and it governs how much spectral energy spreads into sidebands. In FM synthesis and FM radio, higher index values produce more, and higher-order, sidebands whose amplitudes follow Bessel functions of the index.','The FM index tells you how strong a frequency-modulation effect is. It compares how far the pitch swings to how fast it swings. A small index gives a nearly pure tone. A large index adds many extra sideband tones and makes the sound brighter or more complex.','It is the single control that sets timbral brightness in FM synthesis and signal bandwidth in FM transmission.','With peak deviation 200 Hz and modulator 100 Hz, the index is 2; significant sidebands span about the carrier plus and minus two modulator spacings, and Carson''s rule gives a bandwidth near 2*(200+100)=600 Hz.','Modulation',ARRAY['FM synthesis','Carrier frequency','Sideband','Carson''s bandwidth rule','Bessel function']::text[],ARRAY['Confusing the modulation index with the modulation ratio (carrier-to-modulator frequency ratio).','Assuming sideband amplitude grows smoothly with index; Bessel functions rise and fall, so a carrier can even vanish.','Forgetting that raising index widens the required bandwidth.']::text[],ARRAY['Dialing operator output level to brighten a DX-style FM synth patch.','Estimating the channel bandwidth needed for an FM radio signal.','Explaining why a carrier tone disappears at certain FM depths.']::text[],'Advanced','I = Delta_f / f_m ;   B_Carson ~= 2*(Delta_f + f_m) = 2*f_m*(I + 1)','The modulation index equals the peak frequency deviation divided by the modulating frequency. Carson''s rule estimates the occupied bandwidth as twice the sum of peak deviation and modulating frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-modulation index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1e44f40-3f4e-4122-a35c-b7a2de87c331','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1e44f40-3f4e-4122-a35c-b7a2de87c331') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1e44f40-3f4e-4122-a35c-b7a2de87c331');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb4494a9-c526-423d-b4e5-3ff6b339a870','Frequency-response distortion','Frequency-response distortion is a form of linear distortion in which a system''s gain (and often phase) varies with frequency, so different spectral components are amplified or delayed unequally. Unlike nonlinear distortion, it adds no new frequencies; it only reweights the level and timing of existing ones, altering tonal balance.','Frequency-response distortion means a system does not treat all frequencies equally. Some bands come out louder or quieter than they went in. It does not create new tones; it just changes the balance. A device with a bumpy response colors the sound this way.','Naming this class of error lets technicians separate tonal-balance problems from harmonic problems, since each has different causes and fixes.','A technician sweeps a sine and finds a 4 dB dip near 3 kHz; the flat input now sounds dull, confirming frequency-response distortion rather than added harmonics.','Linear Distortion',ARRAY['Magnitude response','Linear distortion','Harmonic distortion','Phase distortion','Equalization']::text[],ARRAY['Calling any tonal change ''distortion'' without distinguishing it from harmonic (nonlinear) distortion.','Assuming a flat magnitude response guarantees no phase-related timing errors.','Ignoring that room acoustics and speakers cause large frequency-response distortion.']::text[],ARRAY['Measuring an amplifier''s deviation from a flat response curve.','Diagnosing why a microphone sounds boxy or thin.','Comparing loudspeaker response plots during system tuning.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-response distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb4494a9-c526-423d-b4e5-3ff6b339a870','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb4494a9-c526-423d-b4e5-3ff6b339a870') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb4494a9-c526-423d-b4e5-3ff6b339a870');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd95cbf65-25d3-4498-941c-0fc152d52e83','Gain modulation','Gain modulation is the deliberate variation of a signal''s amplitude gain over time by a control signal, implemented with an element such as a voltage-controlled amplifier or a digital multiply. When the control varies in the audio range it becomes amplitude or ring modulation; when it varies slowly it produces effects like tremolo or envelope shaping.','Gain modulation means changing how loud a signal is, moment to moment, using another signal. A slow control gives tremolo, a gentle volume wobble. A fast control creates ring or amplitude modulation and new tones. Amplifiers and envelopes both rely on this idea.','It underlies volume envelopes, tremolo, auto-panning, and modulation effects, giving control over how loudness changes through time.','A technician routes a 5 Hz low-frequency oscillator to a channel''s gain to add a smooth tremolo without touching the fader.','Amplitude Modulation',ARRAY['Voltage-controlled amplifier','Tremolo','Ring modulation','Low-frequency oscillation','Envelope']::text[],ARRAY['Confusing slow tremolo with vibrato, which modulates pitch, not gain.','Assuming audio-rate gain modulation only changes loudness; it also creates sidebands.','Overlooking that a DC offset in the control signal shifts the average level.']::text[],ARRAY['Adding rhythmic tremolo to a guitar or keyboard part.','Building an amplitude-modulation effect for sound design.','Shaping a synth note''s loudness with an envelope generator.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gain modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd95cbf65-25d3-4498-941c-0fc152d52e83','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d95cbf65-25d3-4498-941c-0fc152d52e83') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d95cbf65-25d3-4498-941c-0fc152d52e83');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '756785d6-efe0-4b1c-bca1-2446fe54bc97','Gaussian noise','Gaussian noise is random noise whose instantaneous amplitude follows a Gaussian (normal) probability distribution, so values cluster around the mean and large excursions are increasingly rare. Thermal (Johnson-Nyquist) noise is Gaussian, and the term describes an amplitude distribution, which is separate from the flat power spectrum implied by ''white''.','Gaussian noise has amplitudes that follow the bell curve. Small values are common and big spikes are rare. It describes how loud each instant is, not which frequencies are present. Thermal noise in circuits behaves this way. ''Gaussian'' and ''white'' are not the same thing.','It is the standard model for thermal and many other random noises, letting engineers predict noise behavior and test systems with realistic disturbances.','For Gaussian noise with standard deviation 100 mV, about 99.7 percent of samples fall within plus or minus three sigma, so peaks rarely exceed about 300 mV.','Noise Type',ARRAY['White noise','Thermal noise','Probability distribution','Standard deviation','Noise density']::text[],ARRAY['Treating ''Gaussian'' and ''white'' as synonyms; one describes amplitude, the other spectrum.','Assuming Gaussian noise has a hard maximum amplitude; the tails are unbounded.','Forgetting that summing many independent noises tends toward a Gaussian distribution.']::text[],ARRAY['Modeling a preamp''s thermal noise floor in a design calculation.','Adding realistic test noise to evaluate a converter''s performance.','Explaining why a noise histogram forms a bell shape.']::text[],'Intermediate','p(x) = ( 1 / ( sigma * sqrt(2*pi) ) ) * exp( -(x - mu)^2 / (2*sigma^2) )','The probability density of an amplitude equals one over sigma times the square root of two pi, multiplied by e raised to minus the squared deviation from the mean divided by twice the variance.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gaussian noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '756785d6-efe0-4b1c-bca1-2446fe54bc97','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='756785d6-efe0-4b1c-bca1-2446fe54bc97') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='756785d6-efe0-4b1c-bca1-2446fe54bc97');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '166a5669-5d4d-4c7e-b5c8-0f9633b42b6f','Graphic equalization','Graphic equalization divides the audio band into a fixed set of adjacent bands, each with a preset center frequency and a slider that boosts or cuts that band''s level. The row of sliders forms a visual ''graph'' of the frequency response, with common formats using octave (about 10 bands) or third-octave (about 31 bands) spacing.','A graphic equalizer splits sound into fixed frequency bands. Each band has its own slider to turn it up or down. The line of sliders looks like a picture of your tone curve. That picture is where the name comes from. More sliders give finer control.','It gives quick, visual control of tonal balance across the spectrum, useful for shaping sound and reducing feedback in live systems.','A technician pulls the 2.5 kHz slider down a few decibels on a 31-band graphic EQ to stop a ringing feedback tone during soundcheck.','Equalization',ARRAY['Parametric equalization','Third-octave band','Constant-Q filter','Graphic-EQ ripple between filters','Feedback control']::text[],ARRAY['Assuming a slider''s actual boost matches its marked value; band interaction changes the real curve.','Boosting many bands at once instead of cutting, which wastes headroom.','Confusing fixed-frequency graphic EQ with fully adjustable parametric EQ.']::text[],ARRAY['Ringing out a monitor wedge before a live show.','Tuning a room''s response with a third-octave EQ.','Making broad tone corrections on a fixed installation.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Graphic equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '166a5669-5d4d-4c7e-b5c8-0f9633b42b6f','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='166a5669-5d4d-4c7e-b5c8-0f9633b42b6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='166a5669-5d4d-4c7e-b5c8-0f9633b42b6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c890b9d-a8d2-4c1d-86ed-fb1f3a214d58','Graphic-EQ ripple between filters','Graphic-EQ ripple between filters is the uneven combined frequency response that appears between a graphic equalizer''s fixed center frequencies when adjacent bands interact. With proportional-Q (non-constant-Q) designs, setting several sliders equally does not produce a smooth curve; the response dips or ripples between centers because each band''s bandwidth and summing behavior change with boost amount.','A graphic EQ''s real curve is not as smooth as the sliders suggest. Between the fixed band centers, the response can dip or wiggle. This ripple happens because neighboring bands overlap and add together unevenly. Some designs ripple more than others. The set-and-forget slider picture can mislead you.','Understanding this ripple explains why a graphic EQ''s measured response differs from the slider pattern, guiding realistic tone adjustments.','A technician boosts the 1 kHz and 2 kHz sliders equally, then measures a dip near 1.5 kHz between them, revealing inter-band ripple rather than a flat plateau.','Equalization',ARRAY['Graphic equalization','Constant-Q filter','Proportional-Q filter','Filter interaction','Magnitude response']::text[],ARRAY['Believing the slider positions equal the true response; band interaction adds ripple.','Assuming all graphic EQs ripple the same; constant-Q and proportional-Q differ.','Trying to fix a narrow problem with a graphic EQ whose bands are too broad to isolate it.']::text[],ARRAY['Comparing an analyzer trace to the slider settings during system tuning.','Choosing constant-Q versus proportional-Q hardware for accurate curves.','Explaining why identical slider boosts do not give a flat shelf.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Graphic-EQ ripple between filters');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c890b9d-a8d2-4c1d-86ed-fb1f3a214d58','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c890b9d-a8d2-4c1d-86ed-fb1f3a214d58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c890b9d-a8d2-4c1d-86ed-fb1f3a214d58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8aba6422-ab4b-4287-9801-d068824f3344','Ground noise','Ground noise is unwanted signal, typically hum and buzz, introduced when current flows through a shared ground path or when two interconnected devices sit at slightly different ground potentials. Common-impedance coupling and ground loops turn these small potential differences into audible interference, often at the mains frequency and its harmonics.','Ground noise is hum or buzz that leaks in through the wiring''s ground. It happens when two devices do not share the exact same ground voltage. Current then flows where it should not, adding noise. It usually sits at the power-line frequency and its overtones.','Recognizing ground noise helps technicians trace and cure hum and buzz that no amount of gain staging will remove.','A technician hears 60 Hz hum after linking two grounded racks; using balanced connections or a proper signal ground-lift (never the safety earth) breaks the loop.','Noise / Interference',ARRAY['Ground loop','Common-impedance coupling','Balanced interconnection','Hum','Shield']::text[],ARRAY['UNSAFE: Lifting a chassis safety-earth (mains ground) pin to kill hum; this creates a shock hazard and violates wiring codes.','Blaming a device''s noise floor when the real cause is a ground loop between units.','Assuming a single-point ground is unnecessary in a large system.']::text[],ARRAY['Curing 60/50 Hz hum between a mixer and powered speakers.','Interconnecting gear on separate power circuits.','Tracing buzz introduced by a cable-TV or video ground path.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8aba6422-ab4b-4287-9801-d068824f3344','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8aba6422-ab4b-4287-9801-d068824f3344') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8aba6422-ab4b-4287-9801-d068824f3344');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3be9e30c-641d-4ad7-9d4c-e14442a0747c','Hard saturation','Hard saturation is a strongly nonlinear transfer characteristic that flattens (clips) a signal abruptly once it reaches a level limit, producing a near-rectangular waveform at high drive. The sharp transfer ''corner'' generates strong, high-order harmonics and, for complex signals, prominent intermodulation, in contrast to the gradual curve of soft saturation.','Hard saturation chops the tops off a wave once it hits a limit. The change is sudden, giving a flat-topped shape. This adds strong, harsh harmonics. Soft saturation bends more gently and sounds smoother. Hard clipping is the extreme, edgy end of distortion.','It describes the abrupt clipping behavior of overdriven circuits and clippers, important for both aggressive tone shaping and for spotting undesirable overload.','A technician drives a limiter''s ceiling far below the signal peaks; the output flat-tops into hard saturation, and a spectrum analyzer shows a tall stack of harmonics.','Nonlinear Distortion',ARRAY['Clipping','Soft saturation','Harmonic distortion','Foldback distortion','Intermodulation distortion']::text[],ARRAY['Assuming hard clipping adds only odd harmonics; asymmetry and complex inputs also create even and intermodulation products.','Confusing gentle soft saturation with abrupt hard clipping.','Thinking a little hard clipping is inaudible on transient-rich material; it often is audible.']::text[],ARRAY['Identifying flat-topped waveforms on an overdriven amplifier output.','Using a hard clipper for aggressive distortion in sound design.','Diagnosing harshness from a converter driven past full scale.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hard saturation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3be9e30c-641d-4ad7-9d4c-e14442a0747c','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3be9e30c-641d-4ad7-9d4c-e14442a0747c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3be9e30c-641d-4ad7-9d4c-e14442a0747c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a51d0557-b4cc-45b4-9ac9-abf8bb5aa062','Hard-knee versus soft-knee behavior','Hard-knee versus soft-knee describes how abruptly a compressor''s gain-reduction curve transitions from unity gain to the set ratio near the threshold. A hard knee switches sharply at the threshold, while a soft knee applies a gradually increasing ratio across a level range spanning the threshold, easing the onset of compression.','The knee sets how gently compression starts. A hard knee kicks in suddenly at the threshold. A soft knee eases in over a range around it. Soft-knee compression sounds smoother and less obvious. Hard-knee is more precise and audible.','The knee choice controls how transparent or assertive the compression sounds, letting a technician match the processor to the material.','A technician picks a soft knee spanning about 10 dB around threshold for a vocal, so gain reduction fades in smoothly instead of grabbing hard on each loud syllable.','Dynamics Processing',ARRAY['Threshold','Compression ratio','Gain reduction','Compressor','Attack and release']::text[],ARRAY['Thinking soft knee changes the final ratio; it only softens the transition region.','Assuming hard knee is always more aggressive at every level; below threshold both pass unchanged.','Ignoring that a soft knee begins reducing gain below the marked threshold.']::text[],ARRAY['Choosing a gentle soft knee for transparent vocal leveling.','Using a hard knee for precise peak control on a bus.','Comparing how two compressors handle a program''s transients.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hard-knee versus soft-knee behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a51d0557-b4cc-45b4-9ac9-abf8bb5aa062','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a51d0557-b4cc-45b4-9ac9-abf8bb5aa062') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a51d0557-b4cc-45b4-9ac9-abf8bb5aa062');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6bfac586-37ae-4802-882a-80556a9cb4b0','Impulse-response capture','Impulse-response capture is the measurement of a system''s or space''s impulse response, the output produced by an ideal impulse input, from which magnitude and phase response and reverberation can be derived. Modern practice excites the system with a known signal such as an exponential sine sweep or a maximum-length sequence, then deconvolves the recording to recover the impulse response.','Impulse-response capture measures how a system or room reacts to a single click. In practice you play a special sweep or noise, not a real click. Then math extracts the true response from the recording. The result can drive a convolution reverb or reveal a room''s acoustics.','It characterizes rooms, speakers, and gear, and provides the impulse responses used by convolution reverbs and speaker/cabinet emulators.','A technician plays a 10-second exponential sine sweep in a hall, deconvolves it against the reference, and loads the resulting impulse response into a convolution reverb.','Measurement / Convolution',ARRAY['Convolution reverb','Exponential sine sweep','Maximum-length sequence','Deconvolution','Magnitude response']::text[],ARRAY['Using a real handclap or balloon pop and expecting the low noise immunity of a swept-sine capture.','Ignoring background noise and nonlinearity, which corrupt the deconvolved response.','Assuming a single measurement position represents an entire room.']::text[],ARRAY['Capturing a cathedral''s reverb for a convolution plugin.','Measuring a loudspeaker''s response in a treated room.','Profiling a guitar cabinet for an impulse-response loader.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulse-response capture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6bfac586-37ae-4802-882a-80556a9cb4b0','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6bfac586-37ae-4802-882a-80556a9cb4b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6bfac586-37ae-4802-882a-80556a9cb4b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3a5dec68-febf-492f-980f-9e3428484488','Infinite impulse response filters','Infinite impulse response (IIR) filters are recursive digital filters whose current output depends on past outputs as well as past and present inputs, giving them poles as well as zeros. This feedback lets them achieve a sharp magnitude response with few coefficients, but it makes their phase response nonlinear and requires care to keep them stable.','An IIR filter feeds part of its output back into itself. This feedback lets it shape sound sharply with very little computation. In theory its response never fully dies away. The trade-offs are nonlinear phase and possible instability. Most analog-style digital EQs are IIR.','IIR filters deliver steep, efficient filtering at low computational cost, making them the default for equalizers, crossovers, and tone controls.','A technician builds a second-order (biquad) peaking EQ; five coefficients set a sharp boost that a comparable linear-phase FIR would need hundreds of taps to match.','Digital Filter',ARRAY['Finite impulse response filter','Biquad','Pole-zero','Minimum-phase equalization','Linear-phase equalization']::text[],ARRAY['Assuming IIR filters have linear phase; their phase response is generally nonlinear.','Ignoring stability; poles outside the unit circle make an IIR filter blow up.','Expecting the same phase behavior as a symmetric FIR filter.']::text[],ARRAY['Implementing an efficient parametric EQ band as a biquad.','Designing an active or digital crossover with few coefficients.','Choosing IIR over FIR when latency and CPU must stay low.']::text[],'Advanced','y[n] = sum_{k=0}^{M} b_k*x[n-k] - sum_{j=1}^{N} a_j*y[n-j]','The current output equals the weighted sum of present and past inputs minus the weighted sum of past outputs, where the feedback (output) terms make the filter recursive.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infinite impulse response filters');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3a5dec68-febf-492f-980f-9e3428484488','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3a5dec68-febf-492f-980f-9e3428484488') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3a5dec68-febf-492f-980f-9e3428484488');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fb51d3b-fd5c-455d-a225-7e9f82af531c','Inter-sample overload','Inter-sample overload occurs when the continuous waveform reconstructed from digital samples peaks above full scale (0 dBFS) even though no individual sample does, so a sample-peak meter shows headroom that the analog output lacks. These inter-sample (true) peaks can clip digital-to-analog converters and encoders; standards such as ITU-R BS.1770 measure them by oversampling (at least 4x) to estimate the true-peak level in dBTP.','Digital samples are dots; the real wave connects them with curves. Those curves can rise higher than any single dot. So a level meter may read below full scale while the true signal clips. This is inter-sample overload. True-peak meters upsample the signal to catch it.','Knowing about inter-sample peaks lets technicians leave enough headroom so converters and lossy encoders do not clip a signal that looks legal on a sample meter.','A master reads -0.1 dBFS on a sample meter but +0.4 dBTP on a true-peak meter; the technician sets a limiter ceiling near -1.0 dBTP to stay safe after encoding.','Digital Audio / Metering',ARRAY['True-peak metering','0 dBFS','Reconstruction filter','Loudness maximization','dBTP']::text[],ARRAY['Trusting a sample-peak meter to prove a signal will not clip on playback.','Mastering to exactly 0 dBFS, leaving no room for inter-sample peaks after lossy encoding.','Assuming all meters measure true peak; many show only sample peaks.']::text[],ARRAY['Setting a safe true-peak ceiling before delivering a master.','Preparing audio for a lossy codec that adds inter-sample peaks.','Explaining why a ''legal'' file distorts on consumer playback.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inter-sample overload');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fb51d3b-fd5c-455d-a225-7e9f82af531c','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fb51d3b-fd5c-455d-a225-7e9f82af531c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fb51d3b-fd5c-455d-a225-7e9f82af531c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc26ce63-e39d-40bc-a25e-b9909c9315da','Linear-phase equalization','Linear-phase equalization uses a filter whose phase shift is a linear function of frequency, so all frequencies are delayed by the same constant time and waveform shape is preserved. It is typically realized with a symmetric finite-impulse-response filter, which avoids phase smearing but introduces latency and can produce pre-ringing before sharp transients.','Linear-phase EQ delays every frequency by the same amount of time. That keeps the waveform''s shape intact and avoids phase smearing. The cost is added latency and possible pre-ringing before sharp hits. Engineers often use it for mastering. It needs a symmetric FIR filter.','It equalizes tone without shifting the timing relationship between frequencies, valued when phase coherence across bands matters.','A technician EQs a stereo mix bus with a linear-phase filter to avoid phase shifts, accepting a few milliseconds of latency and watching for pre-ring on drum transients.','Equalization',ARRAY['Minimum-phase equalization','Mixed-phase equalization','Finite impulse response filter','Group delay','Pre-ringing']::text[],ARRAY['Assuming linear phase is always better; its latency and pre-ringing can hurt transient material.','Confusing ''linear phase'' (constant delay) with ''zero phase'' or ''no latency''.','Ignoring the added latency when tracking or monitoring live.']::text[],ARRAY['Mastering where phase coherence across bands is a priority.','Matching EQ on parallel copies of the same source.','Correcting tonal balance without shifting stereo imaging.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear-phase equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc26ce63-e39d-40bc-a25e-b9909c9315da','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc26ce63-e39d-40bc-a25e-b9909c9315da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc26ce63-e39d-40bc-a25e-b9909c9315da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f8eb52c-aa10-4b9f-a02a-82a3d01f1a82','Linkwitz–Riley response','A Linkwitz-Riley response is a crossover-filter alignment, formed by cascading two identical Butterworth filters, whose low-pass and high-pass outputs are each 6 dB down at the crossover frequency and remain in phase (0 degrees between them) at all frequencies. Because both outputs are -6 dB and in phase there, they sum to a flat magnitude, making it a standard for loudspeaker crossovers.','A Linkwitz-Riley crossover splits sound into low and high bands cleanly. At the split point each band is 6 dB down, not 3 dB. The two bands stay in phase, so they add back to a flat, even response. This avoids a bump or dip at the crossover. It is a common studio and PA choice.','It provides a crossover whose outputs recombine flat and in phase, giving smooth on-axis response and predictable driver blending.','A technician sets a fourth-order Linkwitz-Riley (LR-4, 24 dB/octave) crossover at 2 kHz; woofer and tweeter are each 6 dB down there and sum flat.','Crossover / Filter',ARRAY['Butterworth filter','Crossover frequency','Active crossover','Filter order','Magnitude response']::text[],ARRAY['Thinking the crossover point is 3 dB down; Linkwitz-Riley outputs are 6 dB down there.','Assuming odd-order filters can be Linkwitz-Riley; the alignment requires even order.','Confusing an LR-4 (two second-order Butterworth) with a single fourth-order Butterworth.']::text[],ARRAY['Configuring an active crossover for a two-way PA system.','Designing a studio monitor''s internal crossover.','Setting DSP crossover slopes in a loudspeaker processor.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linkwitz–Riley response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f8eb52c-aa10-4b9f-a02a-82a3d01f1a82','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f8eb52c-aa10-4b9f-a02a-82a3d01f1a82') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f8eb52c-aa10-4b9f-a02a-82a3d01f1a82');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ddc04437-4fe9-4dd5-aef0-ee358a5c8612','Loudness maximization','Loudness maximization is the process of raising a program''s perceived loudness by reducing its peak-to-average ratio, typically with limiting, clipping, and heavy compression, so more average energy fits under the peak ceiling. Pushed too far it flattens dynamics and adds distortion, the excesses associated with the ''loudness war'', and it is now constrained by loudness-normalization standards.','Loudness maximization makes a track sound louder without going past the peak limit. It squashes the peaks so the average level can rise. Overdoing it kills dynamics and adds distortion. Streaming loudness rules now reward restraint. So chasing maximum loudness often backfires.','It increases competitive perceived loudness and consistency, though modern loudness normalization has reduced the payoff of extreme processing.','A technician limits a master toward a target of about -14 LUFS integrated for streaming, gaining loudness while keeping transients intact instead of crushing to a much louder level.','Mastering / Dynamics',ARRAY['Limiter','LUFS','Crest factor','Inter-sample overload','Dynamic range']::text[],ARRAY['Assuming louder always wins; loudness normalization turns overly loud masters back down.','Confusing loudness (LUFS) with peak level (dBFS).','Crushing dynamics so hard that transients and distortion ruin the sound.']::text[],ARRAY['Preparing a master to hit a streaming loudness target.','Balancing loudness against dynamics in a competitive genre.','Explaining why an ultra-loud master sounds worse after normalization.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness maximization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ddc04437-4fe9-4dd5-aef0-ee358a5c8612','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ddc04437-4fe9-4dd5-aef0-ee358a5c8612') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ddc04437-4fe9-4dd5-aef0-ee358a5c8612');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '565b4870-3119-45ec-8005-1f86b7aa2c45','Low-frequency oscillation','Low-frequency oscillation refers to a periodic control signal, produced by a low-frequency oscillator (LFO), whose rate lies mostly below the audible range (roughly under 20 Hz). Rather than being heard directly, it modulates another parameter, such as pitch, amplitude, filter cutoff, or pan, to create effects like vibrato, tremolo, and filter sweeps.','A low-frequency oscillator makes a slow, steady wave you usually cannot hear. Instead of hearing it, you use it to move something else. It can wobble pitch for vibrato or volume for tremolo. It can also sweep a filter. Its shape and rate set the effect''s feel.','It supplies the slow, repeating modulation behind vibrato, tremolo, auto-pan, chorus, and filter-sweep effects.','A technician sets an LFO to a 6 Hz triangle and routes it to oscillator pitch for a gentle vibrato, then to filter cutoff for a slow sweep.','Modulation',ARRAY['Vibrato','Tremolo','Gain modulation','Modulation depth','Chorus']::text[],ARRAY['Assuming an LFO is heard directly; it is a control signal, not an audio tone.','Confusing LFO rate (speed) with depth (amount of modulation).','Forgetting that an unsynced LFO can drift out of time with the music.']::text[],ARRAY['Adding vibrato to a synth lead.','Creating a tempo-synced filter wobble in electronic music.','Setting auto-pan movement on a pad.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '565b4870-3119-45ec-8005-1f86b7aa2c45','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='565b4870-3119-45ec-8005-1f86b7aa2c45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='565b4870-3119-45ec-8005-1f86b7aa2c45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96184235-a09e-4225-bcfd-f9afde60577b','Magnitude response','The magnitude response of a system is the absolute value of its frequency response, giving the gain applied to a sinusoid as a function of frequency, independent of phase. For a system with frequency response H(e^{j*omega}), it is |H(e^{j*omega})|, often plotted in decibels to show boosts, cuts, and roll-offs.','The magnitude response shows how much a system boosts or cuts each frequency. It is the size of the response, ignoring timing. A flat line means every frequency passes at the same level. Bumps and dips show tonal coloring. It is usually drawn in decibels.','It summarizes a filter''s or system''s frequency-dependent gain, the primary tool for reading tonal balance and filter shape.','At a frequency where the response is 0.5 + j0.5, the magnitude is sqrt(0.25 + 0.25) = 0.707, which equals about -3.01 dB of gain.','Frequency Response',ARRAY['Phase response','Frequency response','Transfer function','Decibel','Frequency-response distortion']::text[],ARRAY['Assuming a flat magnitude response means no phase distortion; phase can still vary.','Reading magnitude ripple in dB as if it were a linear percentage.','Ignoring that magnitude alone does not fully describe a system''s behavior.']::text[],ARRAY['Reading an EQ curve or filter plot.','Comparing loudspeaker or microphone response graphs.','Verifying a filter meets its target gain versus frequency.']::text[],'Intermediate','|H(e^{j*omega})| = sqrt( Re{H}^2 + Im{H}^2 ) ;  gain_dB = 20*log10( |H| )','The magnitude response equals the square root of the sum of the squares of the real and imaginary parts of the frequency response; expressed in decibels it is twenty times the base-ten log of that magnitude.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnitude response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96184235-a09e-4225-bcfd-f9afde60577b','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96184235-a09e-4225-bcfd-f9afde60577b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96184235-a09e-4225-bcfd-f9afde60577b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7663715-f3e3-411c-8290-d7ff4128a1be','Masking of distortion products','Masking of distortion products is the psychoacoustic phenomenon in which a loud signal renders lower-level distortion components, such as harmonics or intermodulation tones, inaudible when those components fall within the signal''s masking region in frequency and time. It explains why some measurable distortion is unheard, and it is exploited in perceptual audio coding to hide quantization noise.','A loud sound can hide quieter distortion made alongside it. If the extra tones sit close in pitch and time, the ear does not notice them. This is called masking. It explains why measurable distortion is sometimes inaudible. Audio codecs use the same trick to hide their noise.','It connects measured distortion to what is actually heard and provides the basis for hiding quantization noise in lossy audio coding.','A technician notes that harmonics generated near a strong tone stay hidden, while the same distortion becomes audible when the masking signal drops out during a quiet passage.','Psychoacoustics',ARRAY['Auditory masking','Perceptual coding','Harmonic distortion','Intermodulation distortion','Noise shaping']::text[],ARRAY['Assuming masking makes all distortion inaudible; unmasked or distant products are still heard.','Ignoring that masking weakens in quiet passages when the masker is gone.','Believing a low THD number always means clean sound, or that a high one always sounds bad.']::text[],ARRAY['Explaining why some amplifier distortion is inaudible in a busy mix.','Understanding how a lossy codec hides quantization noise.','Judging distortion audibility during soft and loud passages.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masking of distortion products');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7663715-f3e3-411c-8290-d7ff4128a1be','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7663715-f3e3-411c-8290-d7ff4128a1be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7663715-f3e3-411c-8290-d7ff4128a1be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff254c0b-a885-425d-80e9-bdf8ec46eb0e','Memory effects in nonlinear systems','Memory effects in nonlinear systems occur when a device''s nonlinear behavior depends not only on the present input but also on past inputs or internal state, so the distortion changes with frequency, signal history, or temperature. Such dynamic nonlinearity, seen in amplifiers, transformers, and analog tape, requires models with memory (for example Volterra series or hysteresis models) rather than a static transfer curve.','Some devices distort based on the recent past, not just the current instant. Their distortion shifts with frequency, signal history, or heat. This is called a memory effect. A simple fixed curve cannot capture it. Tape, transformers, and power amps all show this behavior.','Recognizing memory effects tells engineers when a static distortion model is inadequate and a dynamic, history-dependent model is needed for accurate emulation or measurement.','A technician modeling analog tape adds hysteresis so the emulation''s distortion depends on prior magnetization, not just the instantaneous input level.','Nonlinear Systems',ARRAY['Volterra series','Hysteresis','Static nonlinearity','Intermodulation distortion','Tape saturation']::text[],ARRAY['Modeling a real device with a single static transfer curve when its distortion is frequency-dependent.','Assuming distortion measured at one frequency predicts it at all frequencies.','Ignoring thermal or magnetic history when emulating analog gear.']::text[],ARRAY['Building a convincing analog tape or transformer emulation.','Explaining why an amplifier''s distortion differs at low and high frequencies.','Choosing a Volterra model over a waveshaper for dynamic nonlinearity.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Memory effects in nonlinear systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff254c0b-a885-425d-80e9-bdf8ec46eb0e','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff254c0b-a885-425d-80e9-bdf8ec46eb0e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff254c0b-a885-425d-80e9-bdf8ec46eb0e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55f99c90-e094-4b29-b63d-a1efb38acfd6','Microtuning','Microtuning is the assignment of precise, often non-standard pitches to individual notes, allowing scales other than 12-tone equal temperament, such as just intonation, historical temperaments, or microtonal systems. Instruments implement it with tuning tables, and the MIDI Tuning Standard defines messages for loading per-note frequencies with fine (fraction-of-a-cent) resolution.','Microtuning lets you set the exact pitch of each note. This allows scales beyond the usual 12 equal steps. You can use pure ratios, old temperaments, or new microtonal scales. Synths store these in tuning tables. MIDI has a standard for sending them.','It frees instruments from 12-tone equal temperament, enabling just intonation, historical tunings, and experimental microtonal music.','A technician loads a just-intonation tuning table via MIDI Tuning Standard so a synth plays pure thirds instead of the slightly sharp equal-tempered ones.','Tuning / Pitch',ARRAY['Equal temperament','Just intonation','Cent','MIDI Tuning Standard','Pitch']::text[],ARRAY['Confusing microtuning with pitch bend; microtuning sets fixed per-note pitches.','Assuming all synths support loadable tuning tables.','Forgetting that a cent is 1/100 of an equal-tempered semitone when specifying offsets.']::text[],ARRAY['Setting up just intonation for a recording session.','Loading a historical temperament for early-music synthesis.','Composing microtonal music with a custom scale.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microtuning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55f99c90-e094-4b29-b63d-a1efb38acfd6','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55f99c90-e094-4b29-b63d-a1efb38acfd6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55f99c90-e094-4b29-b63d-a1efb38acfd6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07e37036-0499-4524-8a74-c917a40523d8','Minimum-phase equalization','Minimum-phase equalization uses a causal, stable filter that, among all filters with the same magnitude response, has the smallest possible phase shift and group delay and a stable inverse (all poles and zeros inside the unit circle). Its phase is tied to its magnitude by the Hilbert relationship, and it introduces no pre-ringing, behaving like conventional analog equalizers.','Minimum-phase EQ adds the least possible delay for a given tone change. Its phase is locked to its gain shape. It causes no pre-ringing before transients, only ringing after. Analog EQs work this way. It can also be undone by an inverse filter.','It provides low-latency equalization with analog-like behavior and an invertible response, the default for most EQs and tone controls.','A technician uses a minimum-phase EQ while tracking so there is negligible latency and no pre-ringing on drum transients, unlike a linear-phase filter.','Equalization',ARRAY['Linear-phase equalization','Mixed-phase equalization','Group delay','Infinite impulse response filters','Hilbert transform']::text[],ARRAY['Assuming minimum phase means zero phase shift; it means the least phase for that magnitude.','Expecting pre-ringing; minimum-phase filters ring only after a transient.','Confusing minimum-phase (invertible) with a general filter that may not have a stable inverse.']::text[],ARRAY['Tracking or live mixing where low latency is essential.','Emulating classic analog EQ behavior.','Correcting a minimum-phase speaker resonance with an inverse filter.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum-phase equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07e37036-0499-4524-8a74-c917a40523d8','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07e37036-0499-4524-8a74-c917a40523d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07e37036-0499-4524-8a74-c917a40523d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f0471c31-8005-4594-98f2-e061ca4b9d20','Mixed-phase equalization','Mixed-phase equalization uses a filter that is neither purely minimum-phase nor purely linear-phase, having zeros both inside and outside the unit circle so its phase response is not minimal for its magnitude. In practice it blends properties of the two, trading some latency and pre-ringing for a chosen balance of phase behavior and transient response.','Mixed-phase EQ sits between minimum-phase and linear-phase types. It is not the lowest-delay option, and it is not fully linear either. It blends their traits to strike a balance. Some equalizers offer this as a middle setting. It trades a little latency and pre-ring for a chosen character.','It offers a compromise between the low latency of minimum-phase and the phase coherence of linear-phase equalization.','A technician selects a plugin''s mixed-phase mode to reduce pre-ringing compared with linear phase while keeping better phase behavior than pure minimum phase.','Equalization',ARRAY['Minimum-phase equalization','Linear-phase equalization','Group delay','Pre-ringing','Finite impulse response filter']::text[],ARRAY['Assuming mixed-phase is just an average of the other two with no trade-offs.','Expecting no pre-ringing; mixed-phase can still ring before transients.','Treating ''mixed-phase'' as a single fixed behavior across all plugins.']::text[],ARRAY['Choosing a middle EQ phase mode in a mastering plugin.','Balancing transient integrity against phase coherence.','Comparing phase modes to hear their effect on drums.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mixed-phase equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f0471c31-8005-4594-98f2-e061ca4b9d20','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f0471c31-8005-4594-98f2-e061ca4b9d20') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f0471c31-8005-4594-98f2-e061ca4b9d20');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8047ee4d-8aeb-4616-95b4-80ce9ca158dc','Modal synthesis','Modal synthesis is a physical-modeling method that represents a vibrating object as a set of independent resonant modes, each a damped sinusoid with its own frequency, amplitude, and decay, summed and excited by an input force. It efficiently reproduces the sound of bells, bars, plates, and other resonant bodies by modeling their characteristic resonances rather than sampling them.','Modal synthesis builds a sound from an object''s natural ringing tones. Each mode is one decaying sine with its own pitch and fade. You hit the model with an excitation, and the modes ring. It is great for bells, chimes, and drums. It models physics instead of replaying samples.','It synthesizes the sound of resonant physical objects by modeling their modes, giving realistic, interactive struck and plucked timbres.','A technician models a metal bar as a handful of modes at set frequencies and decay times, then strikes it with a noise burst to produce a realistic, playable chime.','Sound Synthesis',ARRAY['Physical modeling','Resonant filter','Formant synthesis','Excitation','Impulse-response capture']::text[],ARRAY['Confusing modal synthesis with sampling; it computes resonances rather than replaying recordings.','Using too few modes, which makes metallic sounds thin and unrealistic.','Ignoring per-mode decay, which controls how the sound rings out.']::text[],ARRAY['Designing realistic bell, chime, or mallet-percussion sounds.','Building interactive game-audio objects that respond to hits.','Modeling a drum or plate for expressive physical control.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8047ee4d-8aeb-4616-95b4-80ce9ca158dc','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8047ee4d-8aeb-4616-95b4-80ce9ca158dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8047ee4d-8aeb-4616-95b4-80ce9ca158dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cda2e30-3d5c-443a-b8be-f9ecbcb11771','Musical noise','Musical noise is an artifact of frequency-domain noise reduction, especially spectral subtraction, in which random errors in the estimated spectrum leave isolated, short-lived spectral peaks that appear and vanish at random frequencies. Heard as warbling, tonal, bell-like ''blips'', it results from over-subtraction and the residual spectral fluctuation left after suppression.','Musical noise is a warbly artifact from noise-removal tools. As the software cuts noise, tiny random spectral peaks pop in and out. They sound like little bells or tones jumping around. Aggressive noise reduction makes it worse. It is a common side effect of spectral subtraction.','Naming this artifact helps technicians recognize and reduce it when tuning noise-reduction and speech-enhancement processing.','A technician backs off a de-noise plugin''s reduction amount and raises the noise-floor smoothing when a cleaned dialogue track develops warbling, bell-like musical noise.','Noise Reduction Artifact',ARRAY['Spectral subtraction','Noise reduction','Over-subtraction','Short-time Fourier transform','Residual noise']::text[],ARRAY['Pushing noise reduction too hard, which trades hiss for warbling musical noise.','Mistaking musical noise for a source problem rather than a processing artifact.','Assuming more aggressive subtraction always yields a cleaner result.']::text[],ARRAY['Cleaning noisy dialogue or field recordings.','Restoring an archival recording with spectral tools.','Tuning a communications denoiser to avoid warble.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Musical noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cda2e30-3d5c-443a-b8be-f9ecbcb11771','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cda2e30-3d5c-443a-b8be-f9ecbcb11771') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cda2e30-3d5c-443a-b8be-f9ecbcb11771');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0590d9d9-61b5-4ed4-b7ce-9823801fee9c','Noise correlation','Noise correlation describes the statistical relationship between two noise signals, ranging from fully correlated (identical) to uncorrelated (independent). Correlated noises add coherently, summing in voltage for about a 6 dB rise when equal, whereas uncorrelated noises add in power, giving only about a 3 dB rise; this distinction governs how noise combines across channels and stages.','Noise correlation tells you how alike two noises are. Identical noises add strongly, raising level about 6 dB. Unrelated noises add weakly, only about 3 dB. This is why random circuit noise builds up slowly. It also explains how noise combines when you sum channels.','It predicts how noise from multiple sources or channels combines, key to estimating noise floors and to techniques that cancel correlated interference.','Summing two channels of equal uncorrelated noise raises the level about 3 dB, while two identical (correlated) noise signals sum about 6 dB higher.','Noise Analysis',ARRAY['Uncorrelated noise','Coherent summation','Signal-to-noise ratio','Common-mode rejection','Noise density']::text[],ARRAY['Assuming all noise sums the same way; correlated and uncorrelated noise add differently.','Expecting a 6 dB rise from summing independent noise sources; it is about 3 dB.','Confusing correlated signal summing (+6 dB) with uncorrelated noise summing (+3 dB).']::text[],ARRAY['Estimating the noise floor when combining multiple mic channels.','Understanding why balanced lines reject correlated interference.','Predicting noise buildup through cascaded gain stages.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise correlation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0590d9d9-61b5-4ed4-b7ce-9823801fee9c','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0590d9d9-61b5-4ed4-b7ce-9823801fee9c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0590d9d9-61b5-4ed4-b7ce-9823801fee9c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f75d5751-a52d-42b9-aedf-23d85a29506d','Noise density','Noise density is the amount of noise power (or its square-root, amplitude) in a 1 Hz-wide band as a function of frequency, that is, the noise''s power spectral density. For white noise it is constant with frequency, and total noise over a band is found by integrating the density, so a voltage density (V per root-hertz) times the square root of the bandwidth gives the RMS noise.','Noise density is how much noise sits in each 1 Hz slice of the spectrum. It lets you compare noise regardless of bandwidth. To get total noise, you combine density over the whole band. For flat (white) noise, you multiply density by the square root of the bandwidth. It is often given in volts per root-hertz.','It specifies noise independently of measurement bandwidth, letting engineers compare devices and compute total noise for any chosen band.','A preamp with input noise density 12 nV per root-hertz over a 20 kHz bandwidth gives about 12e-9 * sqrt(20000) = 1.70 microvolts RMS of noise.','Noise Measurement',ARRAY['Power spectral density','White noise','Noise floor','Bandwidth','Signal-to-noise ratio']::text[],ARRAY['Confusing noise density (per root-hertz) with total noise over a band.','Forgetting that total RMS noise scales with the square root of bandwidth, not bandwidth itself.','Comparing two noise figures measured over different bandwidths as if equal.']::text[],ARRAY['Reading an op-amp or preamp datasheet''s input-noise spec.','Computing a stage''s total noise for the audio band.','Comparing converter noise floors across products.']::text[],'Intermediate','V_n(RMS) = e_n * sqrt(BW)   [white-noise case] ;  e_n has units V / sqrt(Hz)','For flat noise, the total RMS noise voltage equals the voltage noise density multiplied by the square root of the measurement bandwidth.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f75d5751-a52d-42b9-aedf-23d85a29506d','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f75d5751-a52d-42b9-aedf-23d85a29506d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f75d5751-a52d-42b9-aedf-23d85a29506d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3cbd97ae-eb90-4eed-818b-bf762946f89b','Noise figure','Noise figure (NF) is the decibel measure of how much a device or system degrades the signal-to-noise ratio of a signal passing through it. It equals ten times the base-ten logarithm of the noise factor, where the noise factor is the input SNR divided by the output SNR at a standard source temperature of 290 K.','Noise figure tells you how much noise a device adds on its own. Every amplifier makes the signal-to-noise ratio a bit worse. A low noise figure means the device is quiet and clean. Microphone preamps and radio front ends aim for low values.','It quantifies the noise an amplifier or receiver stage adds, so designers can compare devices and budget the noise of a whole chain.','If a stage has an input SNR of 40 dB and an output SNR of 37 dB, its noise figure is 40 - 37 = 3 dB, matching a noise factor of about 2.','Noise Metric',ARRAY['Signal-to-noise ratio','Noise floor','Thermal noise','Preamplifier','Dynamic range']::text[],ARRAY['Confusing noise figure in dB with the linear noise factor F.','Thinking noise figure depends on signal level rather than being a fixed device property.','Assuming cascaded stages simply add their dB noise figures, ignoring that the first stage dominates (Friis).']::text[],ARRAY['Specifying a low-noise microphone preamplifier.','Comparing the front ends of two wireless receivers.','Building a noise budget for a signal chain.']::text[],'Advanced','NF = 10 log10(F),  F = SNR_in / SNR_out','Noise figure in decibels equals ten times the base-ten logarithm of the noise factor, where the noise factor is input SNR divided by output SNR.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise figure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3cbd97ae-eb90-4eed-818b-bf762946f89b','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3cbd97ae-eb90-4eed-818b-bf762946f89b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3cbd97ae-eb90-4eed-818b-bf762946f89b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '100393f0-5493-4823-b5d7-c07be80ff006','Noise gating artifacts','Noise gating artifacts are the audible side effects a noise gate produces when it opens or closes, including chattering when the level hovers near threshold, clipped word or note beginnings from a slow attack, and abruptly truncated reverb or decay tails. They result from the interaction of the gate''s threshold, timing, and hysteresis settings with real program material.','A noise gate mutes sound below a set level. Set up badly, it makes ugly side effects. The gate can chatter open and shut on quiet parts. It can also chop the start of words or cut off tails.','The term names the failure modes of gating so technicians can recognise and avoid them when setting up dynamics processing.','Adding hysteresis and a hold time stops chatter; for example, set the close threshold about 6 dB below the open threshold and use a gentle release to protect decay tails.','Dynamics Artifact',ARRAY['Noise gate','Threshold','Hysteresis','Attack and release','Downward expander']::text[],ARRAY['Setting the threshold so high that wanted quiet passages are muted.','Using too fast a release, which causes the gate to chatter.','Using too slow an attack, which clips the transient at the start of a note.','Reaching for a hard gate when a gentler downward expander would avoid artifacts.']::text[],ARRAY['A tom mic gate chattering between drum hits.','A drum reverb tail being cut off abruptly.','A gate clipping the consonants at the start of spoken words.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise gating artifacts');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '100393f0-5493-4823-b5d7-c07be80ff006','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='100393f0-5493-4823-b5d7-c07be80ff006') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='100393f0-5493-4823-b5d7-c07be80ff006');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5a7c5c74-d596-414e-b0ee-ee6230fb42ce','Noise masking','Noise masking is the psychoacoustic effect in which the presence of noise raises the hearing threshold for another sound, making a signal at or below that raised threshold inaudible. Masking is strongest for components close in frequency to the masking noise, and it is exploited in perceptual audio coding to hide quantization noise beneath louder signal energy.','Loud noise can hide a quieter sound from your ears. This effect is called masking. The hidden sound is still present but you cannot hear it. Audio codecs use masking to hide their own errors under the music.','It explains why some sounds become inaudible when noise is present, and it is the basis of perceptual coding and noise shaping.','An MP3 or AAC encoder pushes its quantization noise into frequency bands where louder tones mask it; a technician relies on masking when shaping dither noise below the music.','Psychoacoustic Effect',ARRAY['Masking threshold','Critical band','Perceptual coding','Noise shaping','Dither']::text[],ARRAY['Confusing masking (a perceptual effect) with filtering (physical removal of energy).','Assuming a masked sound has actually been deleted from the signal.','Thinking a masker must be louder across all frequencies, rather than within the same critical band.']::text[],ARRAY['Understanding why lossy codecs can discard data without obvious change.','Placing dither noise so the music masks it.','Explaining why a soft detail vanishes under broadband hiss.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5a7c5c74-d596-414e-b0ee-ee6230fb42ce','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5a7c5c74-d596-414e-b0ee-ee6230fb42ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5a7c5c74-d596-414e-b0ee-ee6230fb42ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5318acf5-53b8-43a4-b3b6-cef8b46399fc','Noise spectrum','A noise spectrum is the distribution of a noise signal''s power as a function of frequency, usually expressed as a power spectral density. Its shape defines the colours of noise: white noise is flat per hertz, while pink noise falls about 3 dB per octave.','A noise spectrum shows how noise power spreads across frequencies. White noise has equal power in every hertz. Pink noise has less power as frequency rises. This shape gives each noise its colour and character.','It describes and quantifies the frequency content of noise for analysis, equipment testing, and masking studies.','A technician chooses pink noise for room tuning because it has equal power per octave, matching how we hear; the spectrum is read as a power spectral density on an analyzer.','Noise Analysis',ARRAY['White noise','Pink noise','Power spectral density','Random noise','Noise floor']::text[],ARRAY['Assuming white noise sounds tonally balanced (it actually sounds bright).','Confusing an amplitude spectrum with a power spectral density.','Thinking pink noise has equal power per hertz, when it has equal power per octave.']::text[],ARRAY['Choosing test noise for real-time-analyzer room tuning.','Describing the character of a device''s hiss.','Comparing the noise floors of two converters.']::text[],'Intermediate','S(f) is proportional to 1 / f^a','The power spectral density of coloured noise varies inversely with frequency raised to an exponent, and that exponent selects the colour.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5318acf5-53b8-43a4-b3b6-cef8b46399fc','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5318acf5-53b8-43a4-b3b6-cef8b46399fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5318acf5-53b8-43a4-b3b6-cef8b46399fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a54bdee-631b-46dd-9c65-5ade831190b7','Noise summation','Noise summation is the combining of noise from several sources into a total level. Uncorrelated (independent, random) noise adds on a power basis, so N equal uncorrelated sources raise the level by 10 log10(N) decibels, giving about +3 dB for a doubling; correlated noise instead adds coherently, up to +6 dB.','When noise sources add up, random noises combine by power, not by simple sum. Two equal, unrelated noises give about three decibels more, not six. This is why extra channels raise the hiss only slowly. Correlated noise, though, can add fully.','It lets technicians predict the total noise when many channels or stages are combined, and distinguishes correlated from uncorrelated noise.','Summing two uncorrelated channels each with a -60 dBu noise floor gives about -57 dBu, a 3 dB rise; ten equal uncorrelated sources raise it by 10 log10(10) = 10 dB.','Noise Analysis',ARRAY['Uncorrelated noise','Correlated noise','Noise floor','Decibel addition','Signal-to-noise ratio']::text[],ARRAY['Adding noise levels by direct decibel arithmetic instead of on a power basis.','Assuming doubling always adds 6 dB, which is true only for correlated sources.','Forgetting that common-mode hum is correlated and can add up to 6 dB.']::text[],ARRAY['Estimating a mix-bus noise floor from many open channels.','Predicting hiss build-up when summing parallel converters.','Explaining why one more quiet channel barely changes the noise.']::text[],'Intermediate','L_total = 10 log10( sum of 10^(L_i/10) );  equal sources: L_total = L + 10 log10(N)','Total uncorrelated noise in dB equals ten times the log of the summed power ratios; for N equal sources it is one source''s level plus ten times the log of N.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise summation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a54bdee-631b-46dd-9c65-5ade831190b7','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a54bdee-631b-46dd-9c65-5ade831190b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a54bdee-631b-46dd-9c65-5ade831190b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd38fd01b-9de8-46f0-b93e-af08c0dc90b3','Nonlinear transfer functions','A nonlinear transfer function is a static input-output relationship y = f(x) whose output is not proportional to its input, so it generates new frequency components (harmonics and, with multiple tones, intermodulation products) not present in the input. Such curves underlie distortion, saturation, waveshaping, and dynamics processing, and can be modelled by a power series of the input.','A nonlinear transfer function bends the input-to-output curve. The output is not a simple scaled copy of the input. This bending creates new tones, called harmonics. Distortion, saturation, and clipping all work this way.','It is the general model for any distorting or waveshaping process and explains how harmonics are generated.','Modelling a tube stage as y = x + a2*x^2 + a3*x^3 lets a technician predict that a symmetric curve makes mostly odd harmonics while an asymmetric one also adds even harmonics.','Nonlinear Processing',ARRAY['Harmonic distortion','Waveshaping','Saturation curves','Intermodulation','Odd-order harmonics']::text[],ARRAY['Assuming a nonlinearity only adds harmonics, forgetting it also makes intermodulation with multiple tones.','Thinking a simple gain change is nonlinear, when constant gain is still linear.','Confusing a static transfer curve with a frequency-dependent filter.']::text[],ARRAY['Modelling the ''warmth'' of analog gear.','Designing a waveshaper effect.','Explaining why two tones create sum and difference products.']::text[],'Advanced','y = f(x) = a1*x + a2*x^2 + a3*x^3 + ...','The output equals a power series in the input, with linear, squared, cubed, and higher terms; the higher-order terms create harmonics and intermodulation.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear transfer functions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd38fd01b-9de8-46f0-b93e-af08c0dc90b3','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d38fd01b-9de8-46f0-b93e-af08c0dc90b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d38fd01b-9de8-46f0-b93e-af08c0dc90b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7596f3dd-586e-435d-9f31-d491b2d99d0d','Note-value delay','Note-value delay is a delay time set to a musical note duration derived from tempo, so echoes lock to the beat. For a tempo in beats per minute, a quarter-note delay equals 60000 divided by the BPM in milliseconds, with other note values scaled proportionally.','Note-value delay sets the echo time to match the song''s tempo. You pick a note length, such as a quarter or eighth note. The delay then lines up with the beat. This keeps echoes musical instead of random.','It syncs time-based effects to the tempo so repeats sit in the groove instead of clashing with it.','At 120 BPM a quarter note is 60000 / 120 = 500 ms, an eighth note is 250 ms, and a dotted eighth is 375 ms.','Delay Parameter',ARRAY['Tempo sync','Delay time','Dotted note','Triplet','Beats per minute']::text[],ARRAY['Forgetting that a dotted note is 1.5x and a triplet is two-thirds of the plain value.','Mixing up milliseconds and seconds when entering the time.','Assuming the delay''s sync note matches the DAW tempo without checking.']::text[],ARRAY['Dialing a dotted-eighth delay on a lead guitar.','Setting a slap delay in time with the track.','Matching a delay to a click track.']::text[],'Beginner','t_quarter (ms) = 60000 / BPM','A quarter-note delay time in milliseconds equals sixty thousand divided by the tempo in beats per minute; multiply by the note fraction for other note values.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Note-value delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7596f3dd-586e-435d-9f31-d491b2d99d0d','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7596f3dd-586e-435d-9f31-d491b2d99d0d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7596f3dd-586e-435d-9f31-d491b2d99d0d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0171939-22ed-42c4-b9f4-aa83ae056173','Odd-order harmonics','Odd-order harmonics are frequency components at odd integer multiples of the fundamental, that is 3f, 5f, 7f and so on. Symmetric nonlinearities, such as symmetric soft or hard clipping, generate predominantly odd-order harmonics, which are often described as harsher or more square-wave-like than even harmonics.','Odd-order harmonics sit at odd multiples of the main tone. That means three, five, and seven times the pitch, and so on. Symmetric clipping makes mostly these. They can sound hard or hollow.','The term characterises the distortion spectrum produced by a symmetric nonlinearity.','A square wave contains only odd harmonics; for a 100 Hz fundamental these fall at 300, 500, and 700 Hz, and a technician hears their hollow character from symmetric clipping.','Harmonic Content',ARRAY['Even-order harmonics','Harmonic distortion','Symmetric clipping','Square wave','Nonlinear transfer functions']::text[],ARRAY['Assuming odd harmonics always sound bad.','Forgetting that the fundamental itself is the first (odd) harmonic.','Confusing harmonic order with overtone numbering.']::text[],ARRAY['Describing the tone of a fuzz pedal.','Analysing a clipped console output.','Comparing the harmonic character of tube and transistor distortion.']::text[],'Intermediate','f_n = (2k - 1) * f0,  k = 1, 2, 3, ...','Odd harmonics occur at odd whole-number multiples of the fundamental frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Odd-order harmonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0171939-22ed-42c4-b9f4-aa83ae056173','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0171939-22ed-42c4-b9f4-aa83ae056173') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0171939-22ed-42c4-b9f4-aa83ae056173');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e3d655b-31fe-4c23-a764-ce585fb39ca8','Oscillator synchronization','Oscillator synchronization, commonly hard sync, forces a slave oscillator to restart its cycle each time a master oscillator completes one, locking the slave''s fundamental to the master''s frequency while distorting its waveform. The abrupt phase reset adds harmonics and produces the characteristic aggressive sync timbre; soft sync resets more gently.','One oscillator forces another to restart in time with it. This is called hard sync. The forced restart bends the slave''s wave shape. The result is a sharp, tearing sound often used for leads.','It locks two oscillators in frequency and creates rich, sweepable harmonic timbres.','Sweeping the slave oscillator''s pitch while it stays synced to the master changes the harmonics without changing the perceived pitch, giving the classic sync-lead sound.','Synthesis Technique',ARRAY['Hard sync','Oscillator','Waveform','Harmonics','Subtractive synthesis']::text[],ARRAY['Confusing hard sync with simply tuning two oscillators in unison.','Thinking sync changes the pitch, when it mainly changes the timbre.','Assuming all sync is hard sync, ignoring that soft sync exists.']::text[],ARRAY['Programming a sync-lead synth patch.','Explaining a screaming synth pitch sweep.','Comparing analog and digital sync artifacts.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oscillator synchronization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e3d655b-31fe-4c23-a764-ce585fb39ca8','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e3d655b-31fe-4c23-a764-ce585fb39ca8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e3d655b-31fe-4c23-a764-ce585fb39ca8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '16e34a84-f022-49a9-8605-4e7c8c6c4887','Oversampling in nonlinear processors','Oversampling in nonlinear processors runs a distortion, saturation, or waveshaping algorithm at an internally raised sample rate so the harmonics and intermodulation it creates stay below the raised Nyquist frequency. The signal is upsampled before the nonlinearity and downsampled with anti-alias filtering afterward, reducing aliasing that would otherwise fold high harmonics back as inharmonic tones.','Distortion makes new high-frequency harmonics. At normal sample rates these can fold back as false tones, called aliasing. Oversampling runs the effect at a higher rate first. That keeps the new harmonics in range, so the sound stays clean.','It suppresses the aliasing artifacts that nonlinear processes would otherwise produce.','A saturation plugin at 4x oversampling processes 44.1 kHz audio at 176.4 kHz, then anti-alias filters and downsamples; a technician raises oversampling when bright material sounds harsh.','Nonlinear Processing',ARRAY['Aliasing','Nyquist frequency','Anti-aliasing filter','Nonlinear transfer functions','Saturation curves']::text[],ARRAY['Assuming oversampling removes aliasing entirely, when it only pushes it higher and filters it.','Thinking a higher project sample rate is the same as internal oversampling.','Ignoring the extra CPU cost of high oversampling factors.']::text[],ARRAY['Choosing oversampling on a clipper for a loud master.','Taming fizzy aliasing on a guitar amp simulator.','Comparing 2x and 8x oversampling settings.']::text[],'Advanced','fs_internal = L * fs','The internal processing sample rate equals the oversampling factor times the original sample rate.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oversampling in nonlinear processors');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '16e34a84-f022-49a9-8605-4e7c8c6c4887','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='16e34a84-f022-49a9-8605-4e7c8c6c4887') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='16e34a84-f022-49a9-8605-4e7c8c6c4887');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fcdfe99-6d00-493f-b664-ea570d9a755d','Parameter zipper noise','Zipper noise is the audible stepping or clicking heard when a control parameter, such as gain or filter cutoff, is changed in discrete jumps rather than being smoothly interpolated between values. Each abrupt coefficient change creates a small discontinuity in the output signal, producing the characteristic zipper sound.','Zipper noise is a stair-step clicking when a control is moved. It happens when a value jumps in big steps. Each jump makes a tiny click in the sound. Smoothing the control between steps removes it.','The term names the artifact caused by updating parameters in coarse, non-smoothed steps in digital audio.','It is fixed by parameter smoothing, ramping the value over a few milliseconds or updating per sample; a technician hears zipper noise when automating volume too coarsely.','Digital Artifact',ARRAY['Parameter smoothing','Interpolation','Automation','Control rate','Quantization']::text[],ARRAY['Blaming the source signal instead of the coarse automation steps.','Confusing zipper noise with quantization distortion.','Thinking a higher bit depth fixes it, when it is a control-update issue.']::text[],ARRAY['Automating a filter sweep that clicks on each step.','Hearing stepped MIDI CC volume changes.','Coarse fader automation in a DAW.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parameter zipper noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fcdfe99-6d00-493f-b664-ea570d9a755d','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fcdfe99-6d00-493f-b664-ea570d9a755d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fcdfe99-6d00-493f-b664-ea570d9a755d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '528271b1-bd06-420d-9884-1519b86f63a7','Parametric equalization','Parametric equalization is a form of tone control that gives independent, continuous adjustment of three parameters per band: centre frequency, gain (boost or cut), and bandwidth or Q. Each band is typically a second-order peaking (bell) filter, and full control of all three parameters distinguishes it from semi-parametric and graphic designs.','A parametric EQ gives full control over each band. You set the frequency, the amount of boost or cut, and the width. All three controls are adjustable and continuous. This makes it the most flexible tone tool.','It provides precise, surgical tone shaping with complete control of each band.','A technician notches a 400 Hz resonance with a narrow, high-Q cut, then adds a broad 3 dB shelf, setting frequency, gain, and Q for each move.','Equalizer Type',ARRAY['Semiparametric equalization','Graphic equalizer','Q factor','Bell filter','Shelving filter']::text[],ARRAY['Confusing parametric (adjustable Q) with semi-parametric (fixed Q).','Using very high-Q boosts that ring and sound unnatural.','Assuming a boost is always better than a cut for the same problem.']::text[],ARRAY['Removing a resonant frequency surgically.','Shaping a vocal with a bell boost.','Matching the tone of two instruments.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parametric equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '528271b1-bd06-420d-9884-1519b86f63a7','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='528271b1-bd06-420d-9884-1519b86f63a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='528271b1-bd06-420d-9884-1519b86f63a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67fb04bc-6dd1-47f4-aaaa-30bbf79cf4c8','Passband ripple','Passband ripple is the variation in gain within a filter''s passband, measured as the peak-to-peak deviation from the ideal flat response, usually in decibels. Filter families trade it against roll-off: Chebyshev Type I and elliptic filters allow passband ripple to gain a steeper transition, while Butterworth filters are maximally flat with no ripple.','Passband ripple is a small up-and-down gain wobble inside a filter''s pass area. The ideal response is perfectly flat. Some filter designs accept ripple to get a steeper cutoff. Butterworth filters avoid it; Chebyshev filters allow it.','It quantifies a filter''s flatness and the trade-off against how steeply the filter rolls off.','Choosing a 0.5 dB-ripple Chebyshev filter gives a sharper crossover than Butterworth, at the cost of slight passband unevenness measured in dB peak-to-peak.','Filter Characteristic',ARRAY['Butterworth filter','Chebyshev filter','Elliptic filter','Stopband attenuation','Roll-off']::text[],ARRAY['Confusing passband ripple with stopband ripple.','Assuming ripple is always a fault rather than a chosen design trade-off.','Thinking a Butterworth filter has passband ripple, when it does not.']::text[],ARRAY['Selecting a crossover filter type.','Reading a filter''s datasheet response.','Explaining the difference between Chebyshev and Butterworth.']::text[],'Advanced','A_p = 10 log10(1 + e^2)','Chebyshev passband ripple in decibels equals ten times the log of one plus the ripple factor squared.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passband ripple');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67fb04bc-6dd1-47f4-aaaa-30bbf79cf4c8','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67fb04bc-6dd1-47f4-aaaa-30bbf79cf4c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67fb04bc-6dd1-47f4-aaaa-30bbf79cf4c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92b892b5-213f-4de1-8c62-41a2f9d1eec2','Phase distortion','Phase distortion is a change in the phase relationships between a signal''s frequency components as they pass through a system, occurring when the phase shift is not a linear function of frequency (non-constant group delay). It leaves the magnitude spectrum unchanged but alters the waveform shape and transient timing; a linear-phase response avoids it.','Phase distortion shifts different frequencies by different amounts of time. All the tones are still present at the same loudness. But their timing relationship changes. This can smear transients and reshape the waveform.','It describes timing and phase errors that are separate from amplitude or frequency-response errors.','A minimum-phase EQ shifts phase near its bands, while a linear-phase EQ keeps phase flat but adds pre-ringing; group delay, the negative slope of phase, quantifies the distortion.','Filter Characteristic',ARRAY['Group delay','Linear phase','Minimum phase','Phase response','Pre-ringing']::text[],ARRAY['Confusing phase distortion with harmonic distortion, though no new frequencies are added.','Assuming any phase shift is automatically audible.','Thinking linear-phase filters are free of side effects, when they pre-ring.']::text[],ARRAY['Choosing between linear-phase and minimum-phase EQ.','Explaining comb filtering caused by phase shifts.','Time-aligning subwoofers and tops.']::text[],'Advanced','tau_g(w) = - d phi(w) / d w','Group delay is the negative derivative of phase with respect to angular frequency; phase distortion means this delay varies across frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92b892b5-213f-4de1-8c62-41a2f9d1eec2','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92b892b5-213f-4de1-8c62-41a2f9d1eec2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92b892b5-213f-4de1-8c62-41a2f9d1eec2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb616075-f902-481e-85f8-f94f1e59434b','Phase-distortion synthesis','Phase-distortion synthesis is a digital sound-synthesis method that shapes a waveform by warping the rate at which a stored sine-wave table is read, so the output''s phase advances non-uniformly and gains harmonics. It was introduced by Casio in its CZ-series synthesizers from 1984 as a patent-avoiding alternative to Yamaha''s FM synthesis, and the technique is proprietary to Casio.','Phase-distortion synthesis bends how a sine table is read out. Reading it unevenly changes the wave shape and adds harmonics. Casio created it for the CZ synthesizers in 1984. It gave FM-like sounds without using Yamaha''s patent.','It generates variable, harmonically rich timbres from a stored sine table, serving as Casio''s answer to FM synthesis.','On a Casio CZ synthesizer a technician selects waveforms and shapes brightness with the phase-distortion envelope; knowing the method helps in servicing or emulating CZ instruments.','Synthesis Technique',ARRAY['FM synthesis','Waveshaping','Wavetable','Casio CZ','Harmonics']::text[],ARRAY['Calling it the same technique as FM synthesis.','Thinking it is an analog method, when it is digital.','Assuming it is a generic public name rather than Casio''s proprietary method.']::text[],ARRAY['Emulating a Casio CZ-101 sound.','Comparing 1980s digital synthesis methods.','Teaching the history of digital synthesis.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase-distortion synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb616075-f902-481e-85f8-f94f1e59434b','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb616075-f902-481e-85f8-f94f1e59434b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb616075-f902-481e-85f8-f94f1e59434b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ddd16cc-04b3-46e1-a644-81a96156c84a','Plate-reverb behavior','Plate reverb is an artificial reverberation produced by driving a large suspended metal sheet with a transducer and picking up its vibrations, yielding a dense, bright, diffuse decay with no distinct early reflections. Its behaviour, a fast build-up of echo density and a smooth tail, is widely emulated digitally and modelled on classic electromechanical units such as the EMT 140.','A plate reverb uses a big metal sheet, not a room. A driver shakes the plate and pickups capture the ringing. The result is smooth, bright, and dense. It has no clear early echoes, unlike a real room.','It provides a dense, smooth, colouring reverberation and was historically a studio standard for adding space.','A technician adds an EMT-140-style plate to a vocal for a bright sheen, setting decay time and predelay and expecting no distinct early reflections.','Reverb Type',ARRAY['Reverberation','EMT 140','Spring reverb','Convolution reverb','Decay time']::text[],ARRAY['Expecting realistic room reflections from a plate.','Confusing plate reverb with spring reverb.','Assuming plate reverb is naturally dark, when it is characteristically bright.']::text[],ARRAY['Adding classic reverb to a vocal.','Placing a bright plate on a snare drum.','Emulating an EMT 140 in a plugin.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Plate-reverb behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ddd16cc-04b3-46e1-a644-81a96156c84a','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ddd16cc-04b3-46e1-a644-81a96156c84a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ddd16cc-04b3-46e1-a644-81a96156c84a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb35d2ab-8078-4c3d-9ae8-ec908f387178','Poles and zeros','Poles and zeros are the roots of the denominator and numerator, respectively, of a system''s transfer function in the s-plane or z-plane. Poles are frequencies where the transfer function tends to infinity and zeros where it goes to zero; their positions set a filter''s frequency response, resonance, and stability, and for a digital filter every pole must lie inside the unit circle for stability.','A filter''s math can be written as a fraction. Zeros are where the top of the fraction becomes zero. Poles are where the bottom becomes zero. Their positions set the filter''s shape and whether it stays stable.','They give a compact description of a filter''s response and stability from the roots of its transfer function.','Placing a pole close to the unit circle makes a sharp resonance; a technician checks that every digital pole sits inside the unit circle so the filter stays stable.','Filter Theory',ARRAY['Transfer function','Z-transform','Unit circle','Resonance','IIR filter']::text[],ARRAY['Swapping which roots are the numerator (zeros) and which are the denominator (poles).','Thinking a pole outside the unit circle can still be stable.','Confusing s-plane (left half) with z-plane (unit circle) stability rules.']::text[],ARRAY['Designing a resonant IIR filter.','Diagnosing an unstable digital filter.','Reading a pole-zero plot.']::text[],'Advanced','H(z) = ( product of (z - z_k) ) / ( product of (z - p_k) )','A transfer function equals a gain times the product of terms for each zero divided by the product of terms for each pole.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Poles and zeros');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb35d2ab-8078-4c3d-9ae8-ec908f387178','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb35d2ab-8078-4c3d-9ae8-ec908f387178') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb35d2ab-8078-4c3d-9ae8-ec908f387178');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5179395d-e9d5-44ba-a8d8-baa2acc15b79','Post-ringing','Post-ringing is an oscillatory decay that follows a transient at a filter''s output, appearing after the main event as the filter''s impulse response rings down. It is common in resonant and minimum-phase filters and in sharp anti-aliasing filters, where a high Q or steep cutoff lengthens the ring.','Post-ringing is a short wobble after a sharp sound passes through a filter. The filter keeps vibrating briefly. Sharper or more resonant filters ring for longer. It comes after the transient, not before it.','It names the after-transient artifact of resonant or steep filters, in contrast with pre-ringing.','A high-Q EQ boost rings after a snare hit; a technician lowers the Q to shorten the post-ringing, while a linear-phase filter spreads it into symmetric pre- and post-ringing.','Filter Artifact',ARRAY['Pre-ringing','Impulse response','Q factor','Resonance','Linear phase']::text[],ARRAY['Confusing post-ringing with pre-ringing, which is a linear-phase artifact.','Thinking only digital filters ring.','Assuming ringing means the filter is faulty.']::text[],ARRAY['A high-Q EQ smearing a drum transient.','A steep anti-aliasing filter ringing.','Comparing minimum-phase and linear-phase filters.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Post-ringing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5179395d-e9d5-44ba-a8d8-baa2acc15b79','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5179395d-e9d5-44ba-a8d8-baa2acc15b79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5179395d-e9d5-44ba-a8d8-baa2acc15b79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '120fe08d-b7cc-487b-b9f3-3d6e819c2fae','Power-supply noise','Power-supply noise is unwanted electrical fluctuation on a device''s supply rails, including mains-related hum and its harmonics, switching-regulator ripple, and broadband noise, that can couple into audio circuits and appear in the output. It is controlled by regulation, filtering, decoupling, grounding, and a device''s power-supply rejection ratio (PSRR), which measures how well a circuit ignores it.','Power-supply noise is dirt on the power rails feeding a circuit. It can be hum from the mains or buzz from a switching supply. If it leaks into the audio path, you hear it. Good regulation and filtering keep it out.','It identifies supply-borne interference and the design measures used to suppress it.','Tracing a hum to a poorly filtered supply, a technician checks PSRR figures and adds decoupling; mains hum shows up at the line frequency (50 or 60 Hz) and its harmonics.','Noise Source',ARRAY['Power-supply rejection ratio','Mains hum','Ground loop','Ripple','Decoupling']::text[],ARRAY['Confusing supply ripple with ground-loop hum.','Assuming battery power is noise-free, when regulators still add noise.','Ignoring the high-frequency noise from switching supplies.']::text[],ARRAY['Diagnosing hum in a preamplifier.','Comparing a switching supply with a linear one.','Adding decoupling capacitors to a noisy board.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Power-supply noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '120fe08d-b7cc-487b-b9f3-3d6e819c2fae','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='120fe08d-b7cc-487b-b9f3-3d6e819c2fae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='120fe08d-b7cc-487b-b9f3-3d6e819c2fae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c543513f-c9c8-4ab6-b9d2-539033b4a8ce','Proportional-Q equalizers','A proportional-Q (variable-Q) equalizer is a graphic equalizer whose per-band bandwidth changes with the amount of boost or cut: narrow at extreme slider settings and much wider at small settings. This is the traditional graphic-EQ behaviour, contrasted with constant-Q designs that hold bandwidth fixed regardless of the gain applied.','A proportional-Q equalizer changes each band''s width with the slider. Small moves give a wide, gentle curve. Large moves give a narrow, focused one. This is the classic graphic-EQ behaviour.','It describes the traditional graphic-EQ behaviour where the bandwidth (Q) tracks the amount of boost or cut.','Small proportional-Q cuts sound broad and musical, and a technician expects the response to narrow only at large boosts or cuts, unlike a constant-Q design that keeps a fixed 1/3-octave width.','Equalizer Type',ARRAY['Constant-Q equalizer','Graphic equalizer','Q factor','Bandwidth','Octave band']::text[],ARRAY['Assuming the slider positions match the actual response width at all settings.','Confusing proportional-Q with constant-Q designs.','Thinking the Q is narrow at small settings, when it is actually widest there.']::text[],ARRAY['Using a classic graphic EQ for broad tone shaping.','Comparing graphic-EQ design types.','Explaining why small cuts affect neighbouring bands.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Proportional-Q equalizers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c543513f-c9c8-4ab6-b9d2-539033b4a8ce','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c543513f-c9c8-4ab6-b9d2-539033b4a8ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c543513f-c9c8-4ab6-b9d2-539033b4a8ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d2ba5be-91a8-45df-97d5-29dc41885372','Quantization distortion','Quantization distortion is the error introduced when a continuous-amplitude signal is rounded to the nearest available digital level, appearing as added noise and, for low-level correlated signals, as harmonic distortion. For an ideal N-bit converter the theoretical signal-to-quantization-noise ratio is about 6.02*N + 1.76 dB for a full-scale sine wave, and dither is added to decorrelate the error into benign noise.','Digital audio must round each sample to a fixed step. That rounding error is quantization distortion. With few bits it can sound gritty and tied to the signal. Adding dither turns it into steady, gentle noise instead.','It describes the fundamental error of amplitude quantizing and how that error scales with bit depth.','A 16-bit converter gives about 6.02*16 + 1.76 = 98.1 dB signal-to-quantization-noise ratio, with a step size of full scale divided by 2^16; a technician dithers when reducing bit depth.','Digital Distortion',ARRAY['Dither','Bit depth','Noise shaping','Quantization noise','TPDF dither']::text[],ARRAY['Thinking quantization error is always white noise, when it correlates with the signal without dither.','Confusing bit depth (dynamic range) with sample rate (bandwidth).','Assuming more bits change the frequency response.']::text[],ARRAY['Choosing dither when bouncing to 16-bit.','Explaining a converter''s dynamic-range spec.','Teaching why very low bit depth sounds gritty.']::text[],'Advanced','SQNR = 6.02*N + 1.76 dB;  q = FS / 2^N','The signal-to-quantization-noise ratio in dB is about six-point-oh-two times the bit count plus one-point-seven-six; the step size is full scale divided by two raised to the bit count.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quantization distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d2ba5be-91a8-45df-97d5-29dc41885372','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d2ba5be-91a8-45df-97d5-29dc41885372') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d2ba5be-91a8-45df-97d5-29dc41885372');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b1e8999-e4fc-4168-95df-f3a66fce4adc','Random noise','Random noise is a signal whose instantaneous amplitude is unpredictable and can be described only statistically, by a probability distribution and a power spectral density, rather than by a repeating waveform. Common physical examples are thermal (Johnson) noise and shot noise; for white random noise the samples are uncorrelated in time, unlike periodic interference such as hum.','Random noise cannot be predicted sample by sample. You can only describe it with statistics, such as average power. Hiss from resistors and circuits is random noise. This differs from steady, repeating hum.','It defines statistically-described, non-periodic noise as distinct from periodic interference.','A technician measures a preamp''s random hiss as an RMS level and a spectrum, and separates it from periodic hum, which instead shows up as sharp spectral spikes.','Noise Type',ARRAY['White noise','Thermal noise','Shot noise','Noise spectrum','Uncorrelated noise']::text[],ARRAY['Confusing random broadband noise with periodic interference like hum.','Assuming ''random'' means it has no measurable properties.','Thinking all random noise is white, when its colour depends on its spectrum.']::text[],ARRAY['Characterising a microphone preamp''s hiss.','Distinguishing hum from broadband noise on an analyzer.','Generating test noise for measurements.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b1e8999-e4fc-4168-95df-f3a66fce4adc','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b1e8999-e4fc-4168-95df-f3a66fce4adc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b1e8999-e4fc-4168-95df-f3a66fce4adc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c8e5363-cdf7-44aa-b96d-d39fce31ad64','Reverb ducking','Reverb ducking is a technique that automatically reduces the reverb return''s level while the dry source is present and lets it rise in the gaps, usually by side-chaining a compressor on the reverb keyed from the dry signal. It keeps the reverb from masking the source, preserving clarity while still giving a full tail between phrases.','Reverb ducking lowers the reverb while the singer sings. In the pauses, the reverb swells back up. A compressor on the reverb, keyed by the dry vocal, does this. It keeps words clear but still spacious.','It preserves intelligibility by keeping the reverb out of the way of the dry source.','A technician side-chains a compressor on the reverb bus from the lead vocal, setting the threshold and release so the tail returns between phrases.','Reverb Technique',ARRAY['Side-chain compression','Reverb return','Ducking','Masking','Predelay']::text[],ARRAY['Confusing ducking with simply turning the reverb level down.','Forgetting to key the compressor from the dry signal.','Setting the release too fast, which makes the tail pump.']::text[],ARRAY['Keeping a lead vocal clear in a dense mix.','Ducking dialogue reverb for intelligibility.','Controlling reverb wash on a busy arrangement.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverb ducking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c8e5363-cdf7-44aa-b96d-d39fce31ad64','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c8e5363-cdf7-44aa-b96d-d39fce31ad64') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c8e5363-cdf7-44aa-b96d-d39fce31ad64');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97e446c9-cf9e-4353-b880-8c0ac39614e6','Reverb masking','Reverb masking is the loss of clarity that occurs when a reverb tail overlaps and psychoacoustically masks the dry source or other elements, blurring transients and reducing intelligibility. It is managed with predelay, ducking, EQ on the return, and controlled decay time.','Too much reverb can hide the dry sound. The tail overlaps the words and blurs them. This is reverb masking. Predelay, ducking, and EQ help keep the source clear.','It names the intelligibility problem caused by excessive or overlapping reverberation.','A technician adds predelay so the dry transient is heard before the tail, and cuts low-mids on the return while shortening the decay to reduce masking.','Reverb Technique',ARRAY['Masking','Predelay','Reverb ducking','Decay time','Intelligibility']::text[],ARRAY['Adding more reverb to fix a distant-sounding source, which worsens masking.','Ignoring predelay as a tool for separation.','Leaving a low-mid buildup on the reverb return.']::text[],ARRAY['A vocal getting lost under its reverb.','Muddy drum ambience.','Balancing a sense of space against clarity.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverb masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97e446c9-cf9e-4353-b880-8c0ac39614e6','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97e446c9-cf9e-4353-b880-8c0ac39614e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97e446c9-cf9e-4353-b880-8c0ac39614e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '19931988-758d-434c-9fd2-ef8c58376d91','Reverb predelay and source distance','Reverb predelay is the gap between the dry sound and the onset of its reverberation. A longer predelay perceptually implies the listener is closer to the source and farther from the reflecting surfaces, while short or zero predelay suggests distance or a small space; it mirrors the natural initial time delay gap between direct sound and the first reflections.','Predelay is the pause before the reverb starts. A longer pause makes the source feel close and up front. A very short pause makes it feel far away. It copies the natural gap before a room''s echoes arrive.','It uses the direct-to-reverb time gap to control the perceived distance and separation of a source.','Setting a 20 to 40 ms predelay keeps a vocal forward and clear; the value approximates the initial time delay gap, the extra travel time of the first reflection over the direct path.','Reverb Technique',ARRAY['Predelay','Initial time delay gap','Early reflections','Source distance','Decay time']::text[],ARRAY['Confusing predelay with the decay (reverb) time.','Thinking more predelay pushes the source back, when it actually brings it forward.','Ignoring predelay when a vocal sounds cluttered against its reverb.']::text[],ARRAY['Keeping a lead vocal present and clear.','Simulating a large hall''s sense of scale.','Separating dry and wet signals in time.']::text[],'Intermediate','t_pre = (d_reflected - d_direct) / c','Predelay approximates the extra time for the first reflection, equal to the reflected path length minus the direct path length, divided by the speed of sound.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverb predelay and source distance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '19931988-758d-434c-9fd2-ef8c58376d91','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='19931988-758d-434c-9fd2-ef8c58376d91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='19931988-758d-434c-9fd2-ef8c58376d91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9d0f3bb-390a-46f8-b7e8-96fdfede8df6','Room size as a perceptual parameter','Room size in a reverb algorithm is a control that scales the modelled dimensions of the virtual space, adjusting parameters such as early-reflection times, echo-density build-up, and modal spacing together so the listener perceives a larger or smaller enclosure. It is a perceptual macro-control rather than a single physical measurement.','A reverb''s room-size knob sets how big the space feels. It changes several things at once, such as echo timing and density. Bigger settings spread reflections further apart in time. It is a feel control, not one exact measurement.','It gives one intuitive control that scales several room parameters to change perceived size.','A technician increases room size to move from a booth feel to a hall feel, balancing it against decay time, which sets absorption rather than size.','Reverb Parameter',ARRAY['Decay time','Early reflections','Echo density','Predelay','Reverberation']::text[],ARRAY['Confusing room size (dimensions) with decay time (absorption).','Assuming room size alone controls how loud the tail is.','Treating the control as an exact measurement in metres.']::text[],ARRAY['Dialing a small-room ambience.','Scaling a reverb up to a cathedral feel.','Matching reverb size to an on-screen scene.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room size as a perceptual parameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9d0f3bb-390a-46f8-b7e8-96fdfede8df6','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9d0f3bb-390a-46f8-b7e8-96fdfede8df6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9d0f3bb-390a-46f8-b7e8-96fdfede8df6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33e261bf-31a3-47e4-84fa-a7ae63b9b2c6','Saturation curves','A saturation curve is the static input-output transfer characteristic of a soft-clipping nonlinearity, which progressively compresses and rounds signal peaks rather than clipping them abruptly, adding harmonic distortion. It is often modelled by smooth functions such as a hyperbolic tangent, and its shape, including symmetry and knee, sets the harmonic content produced.','A saturation curve shows how a soft clipper bends peaks. Instead of chopping the top flat, it gently rounds it. This adds harmonics and warmth. The curve''s shape decides which harmonics appear.','It describes the transfer shape of soft saturation and the harmonics that shape produces.','A tanh-modelled saturator rounds peaks and, when symmetric, adds mostly odd harmonics; a technician drives the input harder for more saturation. A common model is y = tanh(k*x).','Nonlinear Processing',ARRAY['Soft clipping','Hard clipping','Nonlinear transfer functions','Harmonic distortion','Waveshaping']::text[],ARRAY['Confusing soft saturation with hard clipping.','Assuming a hyperbolic tangent is the only saturation curve.','Thinking a symmetric curve makes even harmonics, when it makes odd ones.']::text[],ARRAY['Adding analog-style warmth to a track.','Taming peaks musically instead of hard clipping.','Modelling tube or tape distortion.']::text[],'Intermediate','y = tanh(k * x)','A common soft-saturation curve maps the input through a hyperbolic tangent, with a drive factor setting how hard it saturates.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Saturation curves');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33e261bf-31a3-47e4-84fa-a7ae63b9b2c6','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33e261bf-31a3-47e4-84fa-a7ae63b9b2c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33e261bf-31a3-47e4-84fa-a7ae63b9b2c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44ce6d4a-4962-4a3d-b52d-8a7b817edd0b','Semiconductor nonlinearity','Semiconductor nonlinearity is the inherently curved current-voltage relationship of devices such as diodes and transistors, in which current varies exponentially or by a power law with applied voltage rather than linearly. This nonlinearity is the physical source of harmonic and intermodulation distortion in analog audio circuits and is deliberately exploited in clipping and waveshaping stages.','Diodes and transistors do not respond in a straight line. Their current bends sharply with voltage. This curve creates harmonics and distortion in circuits. Designers either reduce it or use it on purpose for effects.','It explains the physical origin of distortion in transistor and diode audio circuits.','A diode clipper in a distortion pedal uses the exponential diode curve; the ideal diode law, I = Is*(e^(V/(n*Vt)) - 1), predicts the shape of that clipping.','Nonlinear Processing',ARRAY['Diode clipping','Transistor','Nonlinear transfer functions','Harmonic distortion','Intermodulation']::text[],ARRAY['Assuming transistors are naturally linear, when they need biasing and feedback for linearity.','Confusing intrinsic device nonlinearity with clipping at the supply rails.','Ignoring the temperature dependence of the device curve.']::text[],ARRAY['Designing a diode clipper stage.','Explaining the physics of amplifier distortion.','Modelling analog gear behaviour in software.']::text[],'Advanced','I = Is * ( e^(V / (n*Vt)) - 1 )','Diode current equals a saturation current times the exponential of the voltage over the ideality factor times the thermal voltage, minus one.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Semiconductor nonlinearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44ce6d4a-4962-4a3d-b52d-8a7b817edd0b','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44ce6d4a-4962-4a3d-b52d-8a7b817edd0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44ce6d4a-4962-4a3d-b52d-8a7b817edd0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68603e4d-59f7-46b1-b60b-749fc33b08b2','Semiparametric equalization','Semi-parametric (sweepable) equalization is a tone-control band that allows adjustment of centre frequency and gain but has a fixed, factory-set bandwidth or Q, unlike a full parametric band that also makes Q adjustable. It is common on mixing-console channel strips as a cost-effective mid-band control.','A semi-parametric EQ lets you pick the frequency and the amount of boost or cut. But its width is fixed and cannot be changed. It sits between a fixed EQ and a full parametric one. Mixing consoles often use it for the mids.','It offers frequency and gain control at lower cost and complexity than a full parametric band.','A technician sweeps a console''s mid band to find and cut a harsh frequency, accepting the fixed Q, and moves to a full parametric when Q control is needed.','Equalizer Type',ARRAY['Parametric equalization','Q factor','Graphic equalizer','Sweepable EQ','Channel strip']::text[],ARRAY['Calling it fully parametric.','Expecting the bandwidth to be adjustable.','Assuming a fixed Q makes it useless, when it is efficient for many tasks.']::text[],ARRAY['Mixing on a console channel strip.','Making quick tonal fixes with limited controls.','Teaching the differences between EQ types.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Semiparametric equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68603e4d-59f7-46b1-b60b-749fc33b08b2','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68603e4d-59f7-46b1-b60b-749fc33b08b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68603e4d-59f7-46b1-b60b-749fc33b08b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c1dd384-d012-4a24-9144-3941d6fcdbd9','Sideband formation','Sideband formation is the appearance of new frequency components above and below a carrier when that carrier is modulated. Amplitude modulation by a tone creates a single pair at the carrier plus and minus the modulator frequency, while frequency and phase modulation create multiple sideband pairs at the carrier plus and minus integer multiples of the modulator; these sidebands appear in effects such as ring modulation, FM synthesis, and tremolo.','Modulating a tone creates new tones beside it. These extra tones are called sidebands. Amplitude modulation adds just one pair, above and below. Frequency modulation adds many pairs. Ring modulators and FM synths rely on this.','It explains how modulation produces new spectral components in synthesis and effects.','Ring-modulating a 1000 Hz carrier with a 100 Hz tone yields sidebands at 900 and 1100 Hz; FM produces pairs at the carrier plus and minus whole multiples of the modulator.','Modulation',ARRAY['Amplitude modulation','Frequency modulation','Ring modulation','FM synthesis','Modulator']::text[],ARRAY['Thinking amplitude modulation makes many sidebands, when a single tone makes just one pair.','Forgetting that the number of FM sidebands grows with the modulation index.','Confusing sidebands with harmonics of the carrier.']::text[],ARRAY['Predicting the output tones of a ring modulator.','Programming FM synthesis timbres.','Explaining the spectrum of tremolo or amplitude modulation.']::text[],'Advanced','f_side = f_c +/- k * f_m,  k = 1, 2, 3, ...','Sidebands appear at the carrier frequency plus and minus whole-number multiples of the modulator frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sideband formation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c1dd384-d012-4a24-9144-3941d6fcdbd9','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c1dd384-d012-4a24-9144-3941d6fcdbd9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c1dd384-d012-4a24-9144-3941d6fcdbd9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88ca2a88-2b2c-4c66-ae0c-42ee6d549680','Sidechain filtering','Sidechain filtering is the application of a filter to the detection (sidechain) path of a dynamics processor, so the level detector responds to a frequency-shaped copy of the signal rather than the audio itself. A high-pass filter in the sidechain, for example, stops strong low frequencies from triggering gain reduction.','A compressor or gate watches the signal to decide when to act. Sidechain filtering shapes that watched copy with a filter. Often a high-pass filter stops deep bass from setting off the compressor. The sound you hear is not filtered, only the trigger is.','It controls which frequencies drive a compressor, limiter, or gate, so unwanted bands do not falsely trigger gain changes.','A technician sets a high-pass filter near 100 Hz in a vocal compressor''s sidechain so plosives and rumble stop causing pumping.','Dynamics Processing',ARRAY['Sidechain compression','De-essing','High-pass filter','Gate','Threshold']::text[],ARRAY['Thinking sidechain filtering changes the audible tone; it only shapes the detector signal.','Confusing an internal sidechain filter with an external key input.','Setting the high-pass too high, so the compressor ignores the material it should control.']::text[],ARRAY['High-passing a bus compressor''s sidechain to reduce kick-driven pumping.','Building a de-esser with a band-pass sidechain around sibilance.','Keying a gate only from the drum''s fundamental band.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sidechain filtering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88ca2a88-2b2c-4c66-ae0c-42ee6d549680','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88ca2a88-2b2c-4c66-ae0c-42ee6d549680') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88ca2a88-2b2c-4c66-ae0c-42ee6d549680');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df984593-909a-4ec3-8f7b-74267d6d5d4b','Slap delay','Slap delay (slapback) is a single, distinct echo produced with a short delay time, roughly in the tens to low hundreds of milliseconds, and little or no feedback, giving one clear repeat. It was popularised by 1950s tape-echo recordings.','Slap delay adds one short echo to a sound. The repeat comes quickly, usually under a fifth of a second. There is no long tail of repeats, just a single bounce. It gives a lively, vintage rock and roll feel.','It thickens and energises a voice or instrument with one quick echo, adding a sense of space without a long reverb tail.','A technician sets a delay of about 120 ms with feedback at zero on a lead vocal to get a classic rockabilly slapback.','Delay Effects',ARRAY['Delay','Feedback','Tape echo','Reverb','Echo']::text[],ARRAY['Adding feedback, which turns a single slap into a repeating echo.','Setting the time so short it becomes comb filtering instead of a clear echo.','Assuming slapback needs reverb; it is a discrete echo.']::text[],ARRAY['Adding vintage slapback to a rockabilly lead vocal.','Thickening an electric guitar without a reverb wash.','Recreating a Sun Records style tape-echo sound.']::text[],'Beginner',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slap delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df984593-909a-4ec3-8f7b-74267d6d5d4b','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df984593-909a-4ec3-8f7b-74267d6d5d4b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df984593-909a-4ec3-8f7b-74267d6d5d4b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10fc222f-04d9-4599-9fec-9576f8939b37','Slew-induced distortion','Slew-induced distortion arises when a signal demands a rate of change greater than an amplifier''s maximum slew rate, so the output cannot follow the input and its slopes flatten into ramps. With complex signals this produces harmonic distortion and transient intermodulation distortion (TIM).','Every amplifier can only change its output so fast. This speed limit is called the slew rate. If a fast, loud signal needs more speed than the amp has, the output falls behind. This lag bends the wave and adds unwanted tones.','The concept explains a distortion mechanism tied to amplifier speed limits, helping engineers pick devices fast enough for the levels and frequencies in use.','An op-amp with a 10 V/us slew rate driving a 10 V peak sine has a full-power bandwidth of 10e6 / (2*pi*10) ~ 159 kHz; above that, at that level, slew-induced distortion appears.','Amplifier Distortion',ARRAY['Slew rate','Transient intermodulation distortion','Full-power bandwidth','Op-amp','Harmonic distortion']::text[],ARRAY['Confusing slew-rate limiting with normal voltage clipping at the rails.','Assuming a wide small-signal bandwidth guarantees no slewing at high levels.','Ignoring that high frequencies at high amplitude demand the most slew rate.']::text[],ARRAY['Choosing an op-amp fast enough for high-level, high-frequency audio.','Diagnosing gritty distortion only on loud, bright transients.','Explaining transient intermodulation distortion in an amplifier design review.']::text[],'Advanced','SR = 2*pi*f*V_pk ;  f_max = SR / (2*pi*V_pk)','The slew rate needed to reproduce a sine equals two pi times the frequency times the peak voltage. Rearranged, the full-power bandwidth is the slew rate divided by two pi times the peak voltage.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slew-induced distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10fc222f-04d9-4599-9fec-9576f8939b37','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10fc222f-04d9-4599-9fec-9576f8939b37') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10fc222f-04d9-4599-9fec-9576f8939b37');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1cb7da8d-4ea3-487b-874f-c0cd620d5130','Soft saturation','Soft saturation is a gradual nonlinearity in which gain smoothly decreases as input level rises, rounding peaks instead of abruptly clipping them. It introduces harmonics progressively, giving a gentle onset of distortion often modelled with functions such as the hyperbolic tangent.','Soft saturation squashes loud peaks gently. As the signal gets louder, the device gives back less gain. The tops of the wave round off smoothly instead of being cut flat. This adds a mild, warm distortion rather than a harsh one.','It adds warmth and controls peaks without the harsh high harmonics of hard clipping, emulating tape and analogue circuit behaviour.','A technician drives a tape or saturation plug-in a few decibels into soft saturation to tame drum transients and add gentle harmonic colour.','Saturation',ARRAY['Hard clipping','Tube nonlinearity','Waveshaping','Harmonic distortion','Static nonlinearities']::text[],ARRAY['Assuming soft saturation is distortion-free; it still adds harmonics.','Confusing it with hard clipping, which cuts peaks flat.','Overdriving until the gentle curve becomes harsh, effectively hard clipping.']::text[],ARRAY['Adding analogue-style warmth to a digital mix bus.','Softening sharp transients on drums.','Emulating tape or valve overload in a plug-in.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Soft saturation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1cb7da8d-4ea3-487b-874f-c0cd620d5130','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1cb7da8d-4ea3-487b-874f-c0cd620d5130') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1cb7da8d-4ea3-487b-874f-c0cd620d5130');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c588c96-364a-458a-acef-89f95c90ec11','Soft sync','Soft sync is an oscillator synchronisation mode in which the synced oscillator is reset only under certain conditions, rather than being forced to restart every cycle of the master. Typically it reverses or resets only when moving in a particular direction, giving a gentler timbral change than hard sync.','In hard sync, one oscillator forces another to restart every cycle. Soft sync is milder. The second oscillator only resets some of the time, not always. Because of this, the tone change is subtler and less harsh than hard sync.','It gives synth players a softer synchronisation effect, adding harmonic movement while keeping a smoother, less aggressive character than hard sync.','A technician patches soft sync between two oscillators and sweeps the synced oscillator''s pitch to add gentle harmonic motion without hard-sync''s rasp.','Oscillator Synthesis',ARRAY['Hard sync','Oscillator sync','Waveshaping','Through-zero modulation','Subtractive synthesis']::text[],ARRAY['Expecting the strong tearing tone of hard sync from soft sync.','Assuming every synth defines soft sync the same way; behaviour varies by design.','Confusing oscillator sync with tempo or clock sync.']::text[],ARRAY['Creating subtle harmonic movement on a synth lead.','Comparing hard and soft sync timbres on a modular oscillator.','Programming an evolving pad using slow sync sweeps.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Soft sync');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c588c96-364a-458a-acef-89f95c90ec11','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c588c96-364a-458a-acef-89f95c90ec11') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c588c96-364a-458a-acef-89f95c90ec11');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5aa51dd8-5178-4e1d-b4ea-f775522141e1','Spectral synthesis','Spectral synthesis creates or manipulates sound in the frequency domain, building a signal from its spectral components (magnitudes and phases across frequency) rather than sample by sample. It includes additive synthesis and analysis-resynthesis via the inverse Fourier transform, as in spectral modelling synthesis.','Most sounds can be described as a set of frequencies. Spectral synthesis builds sound by setting those frequencies directly. The computer then turns the frequency picture back into audio. This lets you reshape a sound''s spectrum in detail.','It lets designers control the exact frequency content of a sound over time, enabling detailed resynthesis, morphing, and separation of tonal and noisy parts.','A technician analyses a flute note into sinusoids plus a noise residual, edits the spectral data, then resynthesises a new tone.','Synthesis',ARRAY['Additive synthesis','Fourier transform','Spectral modeling synthesis','Vocoder','Waveshaping']::text[],ARRAY['Confusing spectral synthesis with subtractive filtering of a waveform.','Assuming phase can always be ignored when rebuilding the sound.','Thinking it only recreates existing sounds, not new ones.']::text[],ARRAY['Resynthesising and morphing between two recorded instruments.','Separating a sound into tonal and noise components.','Building rich evolving textures by drawing a spectrum.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5aa51dd8-5178-4e1d-b4ea-f775522141e1','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5aa51dd8-5178-4e1d-b4ea-f775522141e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5aa51dd8-5178-4e1d-b4ea-f775522141e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '06273b3e-df71-4a26-b6b4-179d5d4b308a','Spring-reverb behavior','Spring-reverb behaviour is the characteristic reverberation created by driving audio as mechanical waves along a helical spring and picking them up at the far end. Dispersion makes wave speed depend on frequency, so an impulse spreads into a train of chirped echoes, producing a distinctive metallic, boingy sound.','A spring reverb sends the sound as vibrations down a metal spring. The spring bends and bounces the waves before a pickup collects them. Different frequencies travel at different speeds, which smears each hit. This gives the springy, metallic sound you hear on old guitar amps.','It provides an inexpensive mechanical reverb and a recognisable effect, and its physics guides digital models that recreate that sound.','A technician models spring reverb using dispersive all-pass chains to recreate the chirped bounces and metallic tail of a guitar-amp tank.','Reverb',ARRAY['Reverberation','Dispersion','Plate reverb','Impulse response','All-pass filter']::text[],ARRAY['Expecting a smooth room-like tail; springs are dispersive and metallic.','Handling a live spring tank roughly, which produces loud crashes.','Assuming spring and plate reverb sound alike.']::text[],ARRAY['Adding classic surf-guitar spring reverb from an amp tank.','Emulating a spring tank with a dispersive digital model.','Diagnosing crashy noises from a jostled spring reverb unit.']::text[],'Intermediate',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spring-reverb behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '06273b3e-df71-4a26-b6b4-179d5d4b308a','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='06273b3e-df71-4a26-b6b4-179d5d4b308a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='06273b3e-df71-4a26-b6b4-179d5d4b308a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2a2defb-ba49-455c-a03d-66d96353bb39','Static nonlinearities','A static (memoryless) nonlinearity is a system whose output depends only on the present input value, described by an instantaneous transfer function y = f(x). It generates harmonic and intermodulation distortion but has no frequency-dependent memory such as hysteresis or filtering.','A static nonlinearity reacts only to the input right now. It has no memory of past samples. Its output follows a fixed curve applied to each input value. This bends the wave and adds new tones, but the same way at every frequency.','It is the simplest model of distortion, useful for describing clipping, saturation, and waveshaping where memory effects are absent.','A technician models a soft clipper as a static tanh curve, knowing its added harmonics do not change with frequency.','Nonlinear Processing',ARRAY['Waveshaping','Soft saturation','Harmonic distortion','Transfer function','Tube nonlinearity']::text[],ARRAY['Assuming static nonlinearities can model tape or valve memory effects like hysteresis.','Forgetting they still create intermodulation between multiple tones.','Confusing a static curve with a time-varying envelope.']::text[],ARRAY['Modelling a clipping stage with a fixed transfer curve.','Explaining why simple distortion sounds the same across frequency.','Contrasting memoryless clipping with dynamic tape saturation.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Static nonlinearities');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2a2defb-ba49-455c-a03d-66d96353bb39','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2a2defb-ba49-455c-a03d-66d96353bb39') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2a2defb-ba49-455c-a03d-66d96353bb39');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e87e059-d2a5-4c60-a3d4-472ff0779ec6','Static versus modulated reverb','This distinction contrasts reverb algorithms that use fixed, time-invariant delay lengths with those that slowly modulate their internal delay lines or all-pass coefficients over time. Modulation breaks up periodic ringing and metallic resonances, giving a smoother, more natural decay at the cost of subtle pitch movement.','A static reverb keeps its inner delays fixed. This can ring in a harsh, metallic way. A modulated reverb gently wobbles those delays over time. This smooths the tail and hides the ringing, adding a slight chorus-like motion.','Modulation is used to reduce artificial ringing and comb-like colouration in digital reverbs, making the decay sound more like a real space.','A technician raises a plate reverb''s modulation depth to smooth a metallic ring, accepting a little pitch shimmer in the tail.','Reverb',ARRAY['Reverberation','All-pass filter','Chorus','Modulation','Comb filter']::text[],ARRAY['Adding too much modulation, which detunes and warbles the tail.','Assuming modulation is always better; some sources need a static tail.','Confusing reverb modulation with a separate chorus effect.']::text[],ARRAY['Smoothing a ringing digital plate on a snare.','Choosing static reverb for a clean, pitched sustain.','Setting modulation depth on a lush vocal reverb.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Static versus modulated reverb');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e87e059-d2a5-4c60-a3d4-472ff0779ec6','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e87e059-d2a5-4c60-a3d4-472ff0779ec6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e87e059-d2a5-4c60-a3d4-472ff0779ec6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a3a0bd76-0e3f-4a4b-a2e4-809d41293833','Stopband attenuation','Stopband attenuation is the amount by which a filter reduces signals in its stopband, expressed in decibels relative to the passband. It specifies how strongly the filter rejects unwanted frequencies, for example a minimum stopband attenuation of 60 dB.','A filter is meant to block certain frequencies. Stopband attenuation says how much it actually blocks them. It is given in decibels below the passed sound. A bigger number means stronger rejection of the unwanted band.','It quantifies a filter''s rejection performance, a key specification when designing anti-aliasing, crossover, or noise-rejection filters.','For a stopband response 60 dB down, A = -20*log10(|H|), so |H| = 10^(-60/20) = 0.001, meaning the signal passes at one thousandth of its amplitude.','Filter Specification',ARRAY['Stopband ripple','Passband','Transition band','Cutoff frequency','Filter order']::text[],ARRAY['Confusing stopband attenuation with the transition-band slope in dB per octave.','Assuming higher order always increases attenuation without cost to phase or ripple.','Reading attenuation as a positive gain instead of a reduction.']::text[],ARRAY['Specifying rejection for an anti-aliasing filter.','Comparing crossover filters by their out-of-band rejection.','Setting a noise filter to meet a minimum attenuation target.']::text[],'Intermediate','A_stop(dB) = -20*log10(|H(f)|)','Stopband attenuation in decibels equals negative twenty times the base-ten logarithm of the filter''s magnitude response in the stopband.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stopband attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a3a0bd76-0e3f-4a4b-a2e4-809d41293833','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a3a0bd76-0e3f-4a4b-a2e4-809d41293833') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a3a0bd76-0e3f-4a4b-a2e4-809d41293833');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2caa7201-74a4-4d3d-9e9e-c6fce4db8266','Stopband ripple','Stopband ripple is the variation of a filter''s magnitude response within its stopband. Filters such as Chebyshev Type II (inverse Chebyshev) and elliptic have equiripple stopbands, where the response oscillates but always stays below a specified attenuation level.','In the blocked band, a filter''s rejection is not always flat. It can ripple up and down with frequency. Stopband ripple describes that wobble. Some filter types trade this ripple for a sharper cutoff.','It describes a design trade-off: allowing controlled ripple in the stopband lets a filter achieve a steeper transition for a given order.','A technician picks an elliptic filter with a 60 dB equiripple stopband to get a steep cutoff, accepting that rejection dips back up to that limit.','Filter Specification',ARRAY['Stopband attenuation','Passband ripple','Elliptic filter','Chebyshev filter','Transition band']::text[],ARRAY['Assuming all filters have flat stopbands; Butterworth is flat, elliptic is not.','Confusing stopband ripple with passband ripple.','Thinking ripple means the filter fails; it stays under the attenuation limit.']::text[],ARRAY['Choosing an elliptic filter for a steep anti-aliasing cutoff.','Comparing Butterworth and Chebyshev stopband behaviour.','Reading a datasheet''s minimum stopband attenuation with ripple.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stopband ripple');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2caa7201-74a4-4d3d-9e9e-c6fce4db8266','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2caa7201-74a4-4d3d-9e9e-c6fce4db8266') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2caa7201-74a4-4d3d-9e9e-c6fce4db8266');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cd5fa4a0-8517-4322-9405-3352ba7be611','Sum-frequency distortion','Sum-frequency distortion is an intermodulation product created at the sum of two input frequencies, f1 + f2, by a nonlinearity''s second-order term. When two tones pass through a nonlinear device, second-order products appear at both the sum (f1 + f2) and difference (f1 - f2) frequencies.','Play two tones through a distorting device. The distortion creates new tones that were not in the input. One of them sits at the two frequencies added together. This is sum-frequency distortion, a form of intermodulation.','It names one intermodulation product used to characterise a device''s nonlinearity, since these tones are not musically related to the inputs.','With tones at 1 kHz and 1.5 kHz, sum-frequency distortion appears at f1 + f2 = 2.5 kHz, alongside the 500 Hz difference product.','Distortion',ARRAY['Intermodulation distortion','Difference-frequency distortion','Harmonic distortion','Nonlinearity','Total harmonic distortion']::text[],ARRAY['Confusing intermodulation sum products with simple harmonics of one tone.','Assuming only the difference tone matters for audibility.','Thinking a nonlinearity creates only sum, not also difference, products.']::text[],ARRAY['Reading an intermodulation distortion test with two tones.','Explaining unmusical tones added by a nonlinear device.','Evaluating an amplifier''s IMD performance.']::text[],'Intermediate','f_sum = f1 + f2','The sum-frequency distortion product occurs at a frequency equal to the first input frequency plus the second input frequency.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sum-frequency distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cd5fa4a0-8517-4322-9405-3352ba7be611','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cd5fa4a0-8517-4322-9405-3352ba7be611') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cd5fa4a0-8517-4322-9405-3352ba7be611');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c527e4d9-a160-4a10-aac4-e2fb9f3872b8','Through-zero modulation','Through-zero modulation is frequency or phase modulation in which the modulator can drive the carrier oscillator''s frequency down through zero and into negative rates, reversing its phase direction. Through-zero FM keeps the carrier phase coherent, avoiding the pitch-shifting and tuning errors of ordinary analogue FM.','In frequency modulation, one signal changes another oscillator''s pitch. In through-zero FM, the pitch can drop all the way to zero and reverse. The oscillator runs backward instead of just slowing to a stop. This keeps tuning stable and gives clean, digital-style FM tones.','It lets analogue and digital oscillators perform stable, deep FM without the average pitch drifting, matching the clean FM of digital synths.','A technician uses a through-zero FM oscillator so heavy modulation stays in tune, producing clangorous bell tones without pitch drift.','Modulation Synthesis',ARRAY['Frequency modulation','Phase modulation','Linear FM','Oscillator sync','Soft sync']::text[],ARRAY['Assuming ordinary analogue FM stays in tune under deep modulation.','Confusing through-zero FM with simple vibrato.','Thinking negative frequency is meaningless rather than a phase reversal.']::text[],ARRAY['Programming in-tune FM bells on an analogue modular.','Comparing linear through-zero FM to exponential FM.','Recreating classic digital FM timbres on hardware.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Through-zero modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c527e4d9-a160-4a10-aac4-e2fb9f3872b8','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c527e4d9-a160-4a10-aac4-e2fb9f3872b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c527e4d9-a160-4a10-aac4-e2fb9f3872b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8804fdd5-52b8-4892-bec8-4b0dd7cdcad8','Time constants','A time constant is the characteristic time of an exponential response, in a resistor-capacitor network equal to tau = R x C. It is the time to reach about 63.2% of a step''s final value, or to decay to about 36.8%, and it sets attack and release smoothing in dynamics and filter detectors.','Many circuits respond in a smooth curve, not instantly. The time constant tells you how fast that curve moves. After one time constant, the value reaches about 63% of its target. It is set by the resistor and capacitor multiplied together.','It quantifies how quickly detectors and filters respond, governing attack, release, and cutoff behaviour in audio circuits.','For R = 10 kilohm and C = 1 microfarad, tau = 10000 x 0.000001 = 0.01 s, so the smoothing settles to about 63% in 10 ms.','Circuit Fundamentals',ARRAY['Attack time','Release time','RC filter','Cutoff frequency','Envelope detector']::text[],ARRAY['Assuming the response finishes in one time constant; it needs about five to settle.','Mixing up microfarads and farads when computing tau.','Treating attack and release time constants as identical.']::text[],ARRAY['Setting a compressor''s release from its detector time constant.','Designing an RC smoothing filter for a control signal.','Estimating settling time of an envelope follower.']::text[],'Intermediate','tau = R * C ;  v(t) = V*(1 - e^(-t/tau))','The time constant equals resistance times capacitance. A charging voltage rises toward its final value as one minus e to the minus time over the time constant.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time constants');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8804fdd5-52b8-4892-bec8-4b0dd7cdcad8','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8804fdd5-52b8-4892-bec8-4b0dd7cdcad8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8804fdd5-52b8-4892-bec8-4b0dd7cdcad8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '044ac855-0332-4a3e-91a8-cc5be3ff0bae','Time variance in natural spaces','Time variance in natural spaces is the small, continual change in a room''s acoustic response caused by air movement, temperature and humidity shifts, and moving people or objects. As a result, the room''s impulse response drifts over time and repeated measurements differ slightly, so the space is not perfectly time-invariant.','A real room is never perfectly still. Air moves and temperature changes moment to moment. People and objects shift around. Because of this, the room''s sound response drifts, and two measurements are never exactly the same.','It explains why measured room responses vary and why real reverberation sounds livelier than a single fixed impulse response.','A technician averages several impulse-response captures because air currents and temperature drift make each measurement slightly different.','Room Acoustics',ARRAY['Impulse response','Reverberation','Time invariance','Room acoustics','Modulated reverb']::text[],ARRAY['Assuming a room is perfectly time-invariant like an ideal filter.','Blaming measurement noise for differences actually caused by air movement.','Ignoring temperature drift when averaging captures.']::text[],ARRAY['Averaging multiple sweeps to get a stable room measurement.','Explaining why real reverb sounds richer than a static convolution.','Accounting for HVAC airflow during acoustic testing.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time variance in natural spaces');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '044ac855-0332-4a3e-91a8-cc5be3ff0bae','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='044ac855-0332-4a3e-91a8-cc5be3ff0bae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='044ac855-0332-4a3e-91a8-cc5be3ff0bae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7fc73750-2c77-443f-9f2e-5cdd0501b22c','Tube nonlinearity','Tube nonlinearity is the curved, asymmetric transfer characteristic of a vacuum-tube (valve) amplifying stage. Its shape produces mainly low-order harmonics, notably strong second harmonic from asymmetry, and a soft, gradual approach to clipping that contributes the warm valve character.','A vacuum tube does not amplify perfectly evenly. Its response curve bends, and it bends differently on top and bottom. This adds mostly gentle, low harmonics, especially the second. It also clips softly, which many describe as a warm sound.','It explains the harmonic signature engineers seek from valve gear and guides circuit and software models of that behaviour.','A technician pushes a valve preamp gently so its second-harmonic-rich nonlinearity adds warmth without harsh high-order distortion.','Nonlinear Processing',ARRAY['Soft saturation','Static nonlinearities','Harmonic distortion','Waveshaping','Even harmonics']::text[],ARRAY['Assuming tubes add only pleasant harmonics; overdrive still sounds harsh.','Thinking all tube stages are strongly asymmetric; push-pull cancels even harmonics.','Confusing tube warmth with simple bass boost.']::text[],ARRAY['Adding valve warmth with a preamp on vocals.','Modelling a tube stage''s transfer curve in software.','Explaining second-harmonic colour in a guitar amp.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tube nonlinearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7fc73750-2c77-443f-9f2e-5cdd0501b22c','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7fc73750-2c77-443f-9f2e-5cdd0501b22c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7fc73750-2c77-443f-9f2e-5cdd0501b22c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47feb9af-cca3-472b-9bf2-2d294b3e76b9','Tuning systems','Tuning systems are schemes for choosing the pitches and intervals of a musical scale, such as 12-tone equal temperament, just intonation, and Pythagorean tuning. In 12-tone equal temperament each semitone is the ratio 2^(1/12); intervals are measured in cents, with 1200 cents to an octave.','A tuning system decides the exact pitches used in music. One common system splits the octave into twelve equal steps. Another uses simple whole-number ratios between notes. Musicians measure tiny pitch gaps in units called cents.','They define how instruments are tuned and let engineers compare and quantify pitch differences precisely.','An equal-tempered semitone spans 100 cents; a just major third (ratio 5:4) is 1200*log2(5/4) = 386 cents, about 14 cents flatter.','Pitch and Tuning',ARRAY['Equal temperament','Just intonation','Cent','Concert pitch','Interval']::text[],ARRAY['Assuming equal-tempered thirds match pure just ratios; they differ by several cents.','Confusing cents with hertz when describing pitch differences.','Thinking A440 is universal; orchestras sometimes tune higher.']::text[],ARRAY['Setting a tuner and pitch-correction plug-in to a temperament.','Explaining why just intonation sounds smoother on sustained chords.','Comparing intervals across historical tuning systems.']::text[],'Intermediate','cents = 1200 * log2(f2 / f1)','The interval in cents equals twelve hundred times the base-two logarithm of the ratio of the two frequencies.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tuning systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47feb9af-cca3-472b-9bf2-2d294b3e76b9','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47feb9af-cca3-472b-9bf2-2d294b3e76b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47feb9af-cca3-472b-9bf2-2d294b3e76b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ad5cac3-2651-4e4b-a6e7-5a79fbbacda0','Uncorrelated noise','Two noise signals are uncorrelated when their cross-correlation is zero, meaning they share no consistent phase relationship. When such signals are summed their powers add rather than their amplitudes, so combining N equal uncorrelated noises raises level by 10*log10(N) dB, giving +3 dB for two.','Two noise sources are uncorrelated when they have no matching pattern. When you add them, their powers add, not their voltages. So two equal, unrelated noises give a level rise of about three decibels. Correlated signals instead could add to six decibels.','It explains how independent noise sources combine, which matters for noise summing in mixers, arrays, and gain-staging calculations.','Summing two equal, uncorrelated noise sources raises the level by 10*log10(2) = 3.01 dB, not 6 dB.','Noise',ARRAY['Correlated noise','Power summation','Signal-to-noise ratio','White noise','Dither']::text[],ARRAY['Assuming two noise sources always add 6 dB like coherent signals.','Confusing uncorrelated (power adds) with correlated (amplitude adds).','Thinking uncorrelated refers to spectrum rather than phase relationship.']::text[],ARRAY['Estimating noise buildup when summing many mixer channels.','Comparing coherent versus incoherent signal summation.','Predicting SNR change when combining preamps.']::text[],'Intermediate','P_total = sum(P_i) ;  Delta_dB = 10*log10(N)','The total power of uncorrelated noises equals the sum of their individual powers. For N equal sources the level rise equals ten times the base-ten logarithm of N.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Uncorrelated noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ad5cac3-2651-4e4b-a6e7-5a79fbbacda0','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ad5cac3-2651-4e4b-a6e7-5a79fbbacda0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ad5cac3-2651-4e4b-a6e7-5a79fbbacda0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c5bd8ca-9f0d-495b-aa71-b2cb224e5298','Uniform noise','Uniform noise is noise whose instantaneous amplitude follows a uniform (rectangular) probability density, so every value within a range is equally likely; this is called a rectangular probability density function (RPDF). In dithering, one least-significant-bit of RPDF dither randomises quantisation but still allows noise modulation, so triangular (TPDF) dither is usually preferred.','Uniform noise describes how likely each amplitude value is, not its pitch. Every level in its range is equally likely. This shape is called rectangular. As dither, it works but can leave the noise floor slightly changing with signal.','It defines a basic dither and test signal, and it is the building block of triangular dither, which is two uniform sources summed.','A technician adds triangular (TPDF) dither, made from two uniform sources, instead of single uniform dither to avoid noise-floor modulation when reducing bit depth.','Dither and Noise',ARRAY['Dither','TPDF dither','Quantization','Noise shaping','White noise']::text[],ARRAY['Confusing uniform (amplitude distribution) with white (flat spectrum).','Assuming single uniform dither fully removes noise modulation.','Thinking uniform noise and Gaussian noise sound and behave the same.']::text[],ARRAY['Choosing a dither type before reducing bit depth.','Explaining why TPDF beats RPDF dither.','Generating a uniform random test signal.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Uniform noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c5bd8ca-9f0d-495b-aa71-b2cb224e5298','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c5bd8ca-9f0d-495b-aa71-b2cb224e5298') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c5bd8ca-9f0d-495b-aa71-b2cb224e5298');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b222d3d6-a46c-4089-a383-7fcb3a1b98fd','Variable-Q equalizers','Variable-Q equalisers are equalisers whose filter bandwidth (Q) can change, either set directly by the user as in parametric EQ or varied automatically with the amount of boost or cut. In proportional-Q graphic equalisers the bandwidth widens for small boosts and narrows for large ones.','An equaliser''s Q sets how wide or narrow each band is. A variable-Q equaliser lets that width change. On a parametric EQ, you dial it yourself. On some graphic EQs, the width shifts with how much you boost or cut.','It gives engineers control over how broad or surgical each equaliser band is, trading musical breadth against precise correction.','For a band centred at f0 = 1 kHz with bandwidth BW = 500 Hz, Q = f0 / BW = 1000 / 500 = 2.','Equalization',ARRAY['Parametric equalizer','Constant-Q equalizer','Bandwidth','Center frequency','Graphic equalizer']::text[],ARRAY['Confusing constant-Q with proportional-Q graphic EQ behaviour.','Assuming higher Q always sounds better; wide bands are often more musical.','Thinking Q and bandwidth move the same direction; higher Q means narrower.']::text[],ARRAY['Narrowing Q to notch out a resonant ring.','Comparing constant-Q and proportional-Q graphic equalisers.','Widening Q for gentle tonal shaping on a mix bus.']::text[],'Intermediate','Q = f0 / BW','The quality factor equals the band''s centre frequency divided by its bandwidth.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Variable-Q equalizers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b222d3d6-a46c-4089-a383-7fcb3a1b98fd','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b222d3d6-a46c-4089-a383-7fcb3a1b98fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b222d3d6-a46c-4089-a383-7fcb3a1b98fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd47d4f68-46d8-43e2-b8b0-69ef03196d44','Vector synthesis','Vector synthesis produces a composite timbre by continuously crossfading among usually four sound sources placed at the corners of an X-Y plane, with a joystick or envelope moving a point (vector) through that plane to blend them over time. It was introduced on the Sequential Circuits Prophet VS in 1986; the underlying two-axis crossfade mixing is a generic method.','Vector synthesis mixes four sounds using a small joystick. Each corner of a square holds one source. Moving the stick blends between them smoothly. An envelope can move it on its own, so the tone shifts over time.','It gives players an intuitive way to morph between several waveforms or samples, creating evolving, animated timbres.','A technician assigns four waveforms to the corners and programmes an envelope to sweep the vector, morphing a pad''s tone during the note.','Synthesis',ARRAY['Wavetable synthesis','Crossfade','Spectral synthesis','Joystick control','Sample-based synthesis']::text[],ARRAY['Confusing vector synthesis with wavetable scanning; vector blends four fixed sources.','Assuming the joystick only pans; it crossfades timbres.','Thinking it is a single-brand feature rather than a general crossfade method.']::text[],ARRAY['Morphing between four waveforms on an evolving pad.','Recreating classic Prophet VS or Wavestation timbres.','Automating a vector envelope for movement in a synth patch.']::text[],'Advanced',NULL,NULL,'fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vector synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd47d4f68-46d8-43e2-b8b0-69ef03196d44','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d47d4f68-46d8-43e2-b8b0-69ef03196d44') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d47d4f68-46d8-43e2-b8b0-69ef03196d44');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18b13b69-39ba-4abc-97b5-4116cf301aba','Violet noise','Violet (purple) noise is noise whose power spectral density rises at 6 dB per octave, meaning its power is proportional to frequency squared. It is the time derivative of white noise, making it the spectral opposite of Brownian (red) noise, and it appears in high-frequency-weighted dither noise shaping.','Violet noise has more energy at high frequencies. Its power climbs steadily as pitch rises. It is what you get by differentiating white noise. That makes it the mirror image of red noise, which favours low frequencies.','It describes a specific spectral shape used in noise-shaping dither and in testing, where rising high-frequency energy is wanted.','A technician recognises the +6 dB per octave rise of violet noise as the shape imposed by first-order high-frequency-weighted dither noise shaping.','Noise',ARRAY['White noise','Brownian noise','Pink noise','Noise shaping','Dither']::text[],ARRAY['Confusing violet (+6 dB/octave) with blue noise (+3 dB/octave).','Assuming all coloured noise emphasises low frequencies.','Thinking violet noise has a flat spectrum like white noise.']::text[],ARRAY['Identifying the spectrum from high-frequency dither noise shaping.','Comparing colours of noise in a test-signal set.','Explaining the derivative relationship to white noise.']::text[],'Advanced','S(f) is proportional to f^2','The power spectral density of violet noise is proportional to the square of frequency, a rise of six decibels per octave.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Violet noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18b13b69-39ba-4abc-97b5-4116cf301aba','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18b13b69-39ba-4abc-97b5-4116cf301aba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18b13b69-39ba-4abc-97b5-4116cf301aba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fba5778a-02a7-4a1f-8a79-e75883d44ebe','Waveshaping','Waveshaping is a nonlinear synthesis and processing technique that maps an input signal through a fixed nonlinear transfer function (shaping function) y = f(x) to add harmonics. Using Chebyshev polynomials as the shaping function lets a unit-amplitude cosine input generate exactly a chosen harmonic, allowing controlled spectra.','Waveshaping bends a signal through a fixed curve to change its tone. The curve adds new harmonics that were not there before. Special curves called Chebyshev polynomials give exact control. With them, one input tone can produce a chosen harmonic cleanly.','It creates rich, controllable timbres and distortion from simple inputs, letting designers shape a spectrum by choosing the transfer function.','Feeding a cosine into the n-th Chebyshev polynomial yields the n-th harmonic, since T_n(cos theta) = cos(n*theta), so the technician builds a target spectrum from a weighted sum.','Nonlinear Synthesis',ARRAY['Static nonlinearities','Soft saturation','Chebyshev polynomial','Harmonic distortion','Frequency modulation']::text[],ARRAY['Assuming output harmonics stay fixed; they change with input amplitude.','Forgetting that waveshaping strong inputs can alias without oversampling.','Confusing the shaping function with a simple gain control.']::text[],ARRAY['Designing a specific harmonic spectrum with Chebyshev shaping.','Building a distortion effect from a transfer curve.','Adding controlled brightness to a synth tone.']::text[],'Advanced','y = f(x) ;  T_n(cos(theta)) = cos(n*theta)','The output equals a nonlinear shaping function applied to the input. The n-th Chebyshev polynomial of a cosine equals the cosine of n times the angle, producing the n-th harmonic.','fb6ca315-ec17-4334-821c-a44751ae2532' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waveshaping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fba5778a-02a7-4a1f-8a79-e75883d44ebe','fb6ca315-ec17-4334-821c-a44751ae2532',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fba5778a-02a7-4a1f-8a79-e75883d44ebe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fba5778a-02a7-4a1f-8a79-e75883d44ebe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '882342cc-b977-46cd-af16-b8921ae2322d','Acoustic crossover between array elements','The frequency-and-position region in a loudspeaker array where two neighbouring elements radiate at comparable level and their sound waves combine in the air rather than being separated by an electrical filter. How smoothly they sum is set by the spacing between elements measured against the wavelength.','In a speaker array, next-door boxes overlap in coverage. The spot where they blend is an acoustic crossover. Their sound waves add together in the air, not through a filter. Close spacing keeps the blend smooth instead of patchy.','It describes how adjacent array elements share coverage so a designer can keep their combined response even across the listening area.','A technician keeps element spacing small relative to the shortest wavelength in use; for 10 kHz (about 34 mm wavelength) even a few centimetres of extra spacing can cause interference dips between elements.','Array behavior',ARRAY['Array coherence','Coherent wavefront','Broadside arrays','Beam narrowing','Acoustic-center offset']::text[],ARRAY['Confusing this acoustic overlap with an electrical crossover between drivers.','Spacing elements too far apart, which causes interference lobes at high frequencies.','Assuming elements sum perfectly regardless of frequency or angle.']::text[],ARRAY['Designing a line array so vertical coverage stays smooth between boxes.','Diagnosing high-frequency dips caused by element spacing.','Choosing splay angles so adjacent cabinets overlap correctly.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic crossover between array elements');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '882342cc-b977-46cd-af16-b8921ae2322d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='882342cc-b977-46cd-af16-b8921ae2322d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='882342cc-b977-46cd-af16-b8921ae2322d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12596eec-23a6-4725-81ab-1afc15f7e75a','Acoustic cutoff','The lowest frequency at which an acoustic loading system, most often a horn, still couples the diaphragm efficiently to the air; below it the loading collapses and radiated output falls off sharply. For an exponential horn the cutoff is fixed by the flare rate of the expanding cross-section.','A horn only works well down to a certain low frequency. That limit is the acoustic cutoff. Below it, the horn stops loading the driver properly. Output then drops off very fast.','It defines the usable low-frequency limit of a horn or acoustically loaded system so it is not asked to work where it becomes inefficient.','For an exponential horn with flare constant m = 3 per metre and sound speed c = 343 m/s, cutoff f_c = m*c/(4*pi) = 3*343/12.57 = about 82 Hz; the horn is used only above this.','Horn theory',ARRAY['Acoustic impedance transformation','Compression drivers','Beam narrowing','Acoustic mass loading']::text[],ARRAY['Trying to use a horn well below its cutoff frequency and expecting full output.','Confusing the horn''s acoustic cutoff with an electrical high-pass filter setting.','Ignoring that mouth size, not just flare, limits real low-frequency loading.']::text[],ARRAY['Choosing a horn whose cutoff sits below the crossover frequency.','Explaining why a small horn cannot reproduce low midrange.','Protecting a compression driver by not driving it below horn cutoff.']::text[],'Advanced','f_c = m*c / (4*pi)','The horn cutoff frequency equals the flare constant times the speed of sound, divided by four times pi.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic cutoff');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12596eec-23a6-4725-81ab-1afc15f7e75a','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12596eec-23a6-4725-81ab-1afc15f7e75a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12596eec-23a6-4725-81ab-1afc15f7e75a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa5c9e12-1a15-487b-bb6c-30599418147d','Acoustic damping','The dissipation of acoustic or mechanical vibration energy into heat, used inside loudspeaker enclosures and around resonances to reduce their amplitude and Q. Porous absorbers such as fibreglass or polyester fill convert sound energy to heat and tame internal standing waves and resonant peaks.','Damping soaks up unwanted vibration and turns it into a little heat. Inside a speaker box, stuffing does this job. It calms internal echoes and sharp resonant peaks. The result is a smoother, less coloured sound.','It controls resonances and internal reflections so a loudspeaker''s response is smoother and free of ringing.','A technician adds fibrous fill to a sealed box to absorb midrange standing waves; this also slightly raises the box''s apparent volume and lowers system resonance.','Enclosure design',ARRAY['Acoustic mass loading','Band-pass enclosures','Blocked impedance','Circumferential mode']::text[],ARRAY['Over-stuffing a vented enclosure, which can choke the port and reduce output.','Assuming damping material affects only the inside and never system tuning.','Confusing acoustic damping with electrical or magnetic (motor) damping.']::text[],ARRAY['Filling a sealed cabinet to cut internal resonances.','Lining panel walls to reduce standing waves.','Reducing the Q of a resonant peak in a monitor.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa5c9e12-1a15-487b-bb6c-30599418147d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa5c9e12-1a15-487b-bb6c-30599418147d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa5c9e12-1a15-487b-bb6c-30599418147d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee61cbf2-9766-419a-a18a-f882f75f27bb','Acoustic impedance transformation','The process by which a horn (or similar taper) matches the high acoustic impedance seen at a small-area throat to the low radiation impedance of open air at the large mouth, acting like an acoustic transformer. This improved match lets a small diaphragm radiate far more efficiently than it could directly into air.','Air resists a small vibrating surface poorly, so little sound escapes. A horn gradually widens to fix this. It matches the driver to the open air, like a gearbox. This lets a small driver play loud efficiently.','It raises loudspeaker efficiency by better coupling the diaphragm to the air, especially for compression drivers on horns.','A technician relies on this when a compression driver on a horn reaches roughly 10 times (about 10 dB) more efficiency than the same diaphragm radiating directly; the throat-to-mouth area change does the matching.','Horn theory',ARRAY['Compression drivers','Acoustic cutoff','Acoustic mass loading','Acoustic damping']::text[],ARRAY['Thinking a horn amplifies power rather than improving the impedance match.','Forgetting that the mouth must be large enough at low frequencies for good matching.','Assuming the transformation is flat with frequency; it is not, especially near cutoff.']::text[],ARRAY['Explaining why horn systems are more efficient than direct radiators.','Selecting a horn to load a compression driver.','Understanding throat compression ratio in a driver.']::text[],'Advanced','Z_a = rho*c / S','The acoustic impedance of a duct equals air density times the speed of sound, divided by the cross-sectional area.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impedance transformation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee61cbf2-9766-419a-a18a-f882f75f27bb','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee61cbf2-9766-419a-a18a-f882f75f27bb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee61cbf2-9766-419a-a18a-f882f75f27bb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '000bf49e-4cff-4405-bc65-5a8f721f4f12','Acoustic mass loading','The added inertia contributed by a plug or column of air, such as the air in a port, duct, or horn throat, which behaves as an acoustic mass and lowers the resonance of the system it loads. This inertance depends on the length and area of the air column and on air density.','A slug of air inside a port has weight, like a small mass. This air mass loads the driver and lowers its resonance. Longer or narrower ports add more mass. Designers use this to tune bass.','It lets designers tune a system''s resonance, for example setting a vented box''s port tuning frequency by choosing the air mass in the port.','A technician lengthens a port to add acoustic mass and lower the box tuning; the port air mass M_a = rho*L/S rises with length L and falls with area S.','Enclosure design',ARRAY['Band-pass enclosures','Acoustic damping','Acoustic impedance transformation','Alpha ratio']::text[],ARRAY['Forgetting the end correction, so the effective port length exceeds its physical length.','Assuming a wider port always lowers tuning; a wider port needs more length for the same mass.','Confusing acoustic mass with the mechanical moving mass of the cone.']::text[],ARRAY['Tuning a vented enclosure to a target frequency.','Designing a band-pass sub chamber.','Explaining why a longer port lowers box tuning.']::text[],'Advanced','M_a = rho*L / S','The acoustic mass of an air column equals air density times its effective length, divided by its cross-sectional area.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic mass loading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '000bf49e-4cff-4405-bc65-5a8f721f4f12','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='000bf49e-4cff-4405-bc65-5a8f721f4f12') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='000bf49e-4cff-4405-bc65-5a8f721f4f12');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab507b4e-d299-4638-b124-4727188eb94d','Acoustic-center offset','The difference in apparent source position (and therefore signal arrival time) between drivers in a multiway loudspeaker, because each driver''s acoustic center usually lies behind its diaphragm at a slightly different depth. This offset must be compensated, by physical alignment or delay, for the drivers to sum correctly through the crossover region.','Each driver''s sound seems to start from a point behind its cone. That point differs between a woofer and a tweeter. The gap is the acoustic-center offset. If ignored, the drivers do not blend cleanly at crossover.','It captures the small path-length or timing difference between drivers so a designer can time-align them for a flat, coherent crossover.','A technician steps back or delays the tweeter so its acoustic center lines up with the woofer''s; a 25 mm offset is about 73 microseconds of delay at 343 m/s.','Multiway design',ARRAY['Coaxial loudspeakers','Coherent wavefront','Compression drivers','Cone displacement']::text[],ARRAY['Assuming the acoustic center sits exactly at the visible dust cap or voice coil.','Ignoring offset and getting a dip or lobe tilt at the crossover frequency.','Treating the offset as frequency-independent when it can shift with frequency.']::text[],ARRAY['Time-aligning a two-way monitor.','Setting driver delay in a processor.','Explaining a crossover-region null caused by misaligned drivers.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-center offset');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab507b4e-d299-4638-b124-4727188eb94d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab507b4e-d299-4638-b124-4727188eb94d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab507b4e-d299-4638-b124-4727188eb94d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da404542-4417-474f-a185-9c6a9b61fe30','Air nonlinearity','The inherent nonlinear relationship between pressure and density of air, which becomes significant at very high sound pressure levels and generates harmonic distortion in the medium itself. It is most noticeable in the highly compressed air of a compression-driver throat or horn, where local pressures are large.','At normal levels, air carries sound cleanly. At very high pressure, air stops behaving in a simple straight-line way. This adds distortion the driver did not create. It matters most in the tight throat of a horn driver.','It explains a source of distortion that arises from the air itself, setting a limit on clean output at extreme levels.','A technician expects rising harmonic distortion from a horn compression driver pushed near maximum, partly because the compressed throat air distorts even if the diaphragm moves cleanly.','Distortion',ARRAY['Compression nonlinearity','Compression drivers','Amplitude modulation distortion','Air-noise-limited output']::text[],ARRAY['Blaming all high-level horn distortion on the diaphragm and ignoring the air.','Assuming air distortion matters at ordinary listening levels; it does not.','Confusing air nonlinearity with electrical amplifier clipping.']::text[],ARRAY['Explaining harshness from a horn driven very loud.','Understanding distortion limits of high-output compression drivers.','Comparing throat pressure between horn designs.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air nonlinearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da404542-4417-474f-a185-9c6a9b61fe30','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da404542-4417-474f-a185-9c6a9b61fe30') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da404542-4417-474f-a185-9c6a9b61fe30');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c084a10-c7ae-4280-b0a1-7f705aead6fa','Air-leak noise','Broadband turbulent noise, often heard as a hiss, chuff, or whistle, produced when air escapes at speed through unintended gaps in a loudspeaker system such as failed glue seams, torn surrounds, loose gaskets, or badly finished ports. The turbulence at the leak converts air movement into audible noise unrelated to the wanted signal.','A speaker box should be airtight where the maker intended. If air escapes through a gap, it makes a hiss or chuff. That extra noise is air-leak noise. It usually means a seal or seam has failed.','Recognizing it helps a technician find sealing faults that both add noise and change the driver''s loading.','A technician chasing a chuffing noise on bass notes checks gasket seals, terminal cups, and glue joints, then reseals the leak to remove the noise.','Faults & noise',ARRAY['Air-noise-limited output','Air nonlinearity','Band-pass enclosures','Acoustic damping']::text[],ARRAY['Mistaking a cabinet air leak for a damaged voice coil or amplifier noise.','Overlooking the terminal cup or screw holes as leak paths.','Assuming a small leak is harmless; it can cause noise and shift sealed-box behaviour.']::text[],ARRAY['Tracing a hiss that appears only on loud low notes.','Inspecting a repaired driver''s surround seal.','Quality-checking a new cabinet for airtightness.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-leak noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c084a10-c7ae-4280-b0a1-7f705aead6fa','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c084a10-c7ae-4280-b0a1-7f705aead6fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c084a10-c7ae-4280-b0a1-7f705aead6fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db2d8794-e043-49c9-88b1-bc60d5dbd5b0','Air-noise-limited output','A maximum output condition set not by excursion or heat but by audible turbulence as air velocity in a port or vent becomes high enough to generate noise. Once vent air speed approaches a small fraction of the speed of sound, chuffing appears and defines the practical output ceiling for that vent.','A ported speaker can hit a limit before the cone or coil gives out. Fast-moving port air starts to make turbulent noise. That noise, not damage, caps clean output. Bigger or flared ports push the limit higher.','It sets a design and operating limit for ported systems so ports are sized to stay below audible turbulence at target levels.','A technician sizes a vent so peak air velocity stays well below about 5 percent of the speed of sound (roughly 17 m/s); above that, chuffing typically becomes audible.','Enclosure design',ARRAY['Air-leak noise','Air nonlinearity','Acoustic mass loading','Band-pass enclosures']::text[],ARRAY['Using a port too small in area, which raises air speed and causes chuffing.','Treating the turbulence limit as a fixed number rather than a rough guideline.','Assuming a larger port has no downside; it needs more length to keep tuning.']::text[],ARRAY['Choosing vent diameter for a subwoofer.','Adding a flared port to delay turbulence.','Explaining why bass gets noisy before it gets loud enough.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-noise-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db2d8794-e043-49c9-88b1-bc60d5dbd5b0','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db2d8794-e043-49c9-88b1-bc60d5dbd5b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db2d8794-e043-49c9-88b1-bc60d5dbd5b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14fd3627-4964-421e-9d12-f3487f5cea2c','Alpha ratio','In sealed-box (closed-box) loudspeaker theory, the compliance ratio alpha equals the driver''s equivalent air-compliance volume Vas divided by the enclosed box volume Vb. It sets how much the box stiffens the suspension, raising both the system resonance and total Q above the driver''s free-air values.','A sealed box acts like an extra spring on the cone. Alpha compares the driver''s springiness to the box size. A small box means a large alpha. Larger alpha pushes resonance and Q higher.','It is the key design number for sealed enclosures, letting a designer predict system resonance and damping from box size.','For Vas = 40 L in a Vb = 20 L box, alpha = 2; system resonance f_c = f_s*sqrt(1+alpha) = f_s*1.73, so a 40 Hz driver resonates near 69 Hz in that box.','Thiele-Small',ARRAY['Acoustic mass loading','Band-pass enclosures','Blocked impedance','Cone displacement']::text[],ARRAY['Swapping Vas and Vb, which inverts the ratio.','Forgetting that added box fill slightly raises effective Vb and changes alpha.','Assuming alpha alone sets response; total Q (Qtc) matters too.']::text[],ARRAY['Sizing a sealed subwoofer box for a target Q.','Predicting how a smaller box raises system resonance.','Comparing driver suitability for sealed alignments.']::text[],'Advanced','alpha = Vas / Vb ,  f_c = f_s*sqrt(1 + alpha)','Alpha equals the driver''s equivalent air-compliance volume divided by the box volume; the sealed-box resonance equals the driver''s free-air resonance times the square root of one plus alpha.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Alpha ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14fd3627-4964-421e-9d12-f3487f5cea2c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14fd3627-4964-421e-9d12-f3487f5cea2c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14fd3627-4964-421e-9d12-f3487f5cea2c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c419b80-0260-4dd7-b147-81539acf8f2d','Amplitude modulation distortion','A form of intermodulation distortion in which a low-frequency signal varies the amplitude of a simultaneously radiated higher-frequency signal, producing sum-and-difference sidebands around the high tone. In loudspeakers it arises mainly because motor factor (BL) and coil inductance change with cone position, so a large low-frequency excursion modulates the level of higher tones.','Play a loud low note and a soft high note together. The high note''s loudness starts to wobble with the low note. That wobble adds unwanted tones. It happens because the motor''s strength changes as the cone moves.','It names and measures a real loudspeaker distortion so designers can reduce it by improving motor and suspension linearity.','A technician runs a two-tone test and sees sidebands beside the high tone when the low tone drives large excursion; better linear BL versus displacement reduces them.','Distortion',ARRAY['Compression nonlinearity','Back electromotive force','Cone displacement','Air nonlinearity']::text[],ARRAY['Confusing amplitude-modulation distortion with frequency-modulation (Doppler) distortion.','Assuming it appears with a single tone; it needs two widely spaced tones.','Blaming the amplifier when the cause is the driver''s position-dependent motor.']::text[],ARRAY['Interpreting a two-tone intermodulation test.','Explaining muddiness when a woofer plays deep bass and midrange together.','Comparing motor linearity between drivers.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Amplitude modulation distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c419b80-0260-4dd7-b147-81539acf8f2d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c419b80-0260-4dd7-b147-81539acf8f2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c419b80-0260-4dd7-b147-81539acf8f2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f8f5eeb-f197-4773-8dc0-2a697f34fa1d','Array coherence','The degree to which the individual elements of a loudspeaker array radiate with a consistent phase relationship so their outputs add to form a single, predictable wavefront. High coherence gives smooth, controlled summation; poor coherence produces interference, comb filtering, and unpredictable coverage.','An array works best when its boxes act as one source. Coherence measures how well their waves stay in step. High coherence means clean, even coverage. Low coherence causes ragged, patchy sound.','It expresses how well array elements combine, guiding spacing, splay, and processing so the array behaves as intended.','A technician improves coherence by keeping element spacing under a wavelength and matching delays, so an array sums smoothly instead of forming lobes.','Array behavior',ARRAY['Coherent wavefront','Acoustic crossover between array elements','Broadside arrays','Beam narrowing']::text[],ARRAY['Assuming more boxes always means better coverage regardless of coherence.','Ignoring the frequency dependence; coherence usually worsens at high frequencies.','Forgetting that timing and polarity errors destroy coherence.']::text[],ARRAY['Tuning a line array for even coverage.','Diagnosing comb filtering in a multi-box system.','Deciding element spacing for a given top frequency.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array coherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f8f5eeb-f197-4773-8dc0-2a697f34fa1d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f8f5eeb-f197-4773-8dc0-2a697f34fa1d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f8f5eeb-f197-4773-8dc0-2a697f34fa1d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6df6cb70-10b4-4cb5-abc7-b4186160a4c9','Back electromotive force','The voltage generated by the voice coil as it moves through the magnetic gap, which by Lenz''s law opposes the applied voltage and is proportional to motor factor BL and coil velocity. This motional voltage creates the motional part of the driver''s impedance and provides electromagnetic (electrical) damping of cone motion.','When the voice coil moves in the magnet, it acts like a small generator. It makes a voltage that pushes back against the drive. This is back electromotive force. It helps the amplifier control and damp the cone.','It underlies electrical damping and the impedance peak at resonance, letting the amplifier''s low output impedance control cone motion.','A technician uses a strong amplifier damping factor because the coil''s back-EMF, e = BL*v, is best controlled by a low source impedance, tightening bass.','Motor system',ARRAY['Blocked impedance','Amplitude modulation distortion','Cone motion','Alpha ratio']::text[],ARRAY['Thinking back-EMF is a fault; it is normal and provides damping.','Confusing motional impedance (from back-EMF) with the blocked coil impedance.','Assuming amplifier damping factor controls the cone at all frequencies equally.']::text[],ARRAY['Explaining the impedance peak at driver resonance.','Understanding why amplifier output impedance affects bass control.','Analysing electromagnetic damping in a motor.']::text[],'Intermediate','e = BL * v','The back electromotive force equals the motor factor (magnetic flux density times coil length in the gap) multiplied by the coil''s velocity.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Back electromotive force');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6df6cb70-10b4-4cb5-abc7-b4186160a4c9','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6df6cb70-10b4-4cb5-abc7-b4186160a4c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6df6cb70-10b4-4cb5-abc7-b4186160a4c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '385ccf1f-3850-4a25-8fbf-eae0af0f2ce3','Balanced armature','A miniature electroacoustic transducer in which a ferromagnetic armature is suspended between two magnetic poles; a signal in a surrounding coil tips the armature, and a drive rod couples that tiny motion to a diaphragm. It is compact and efficient but band-limited, and is widely used in hearing aids and in-ear monitors rather than as a full-range speaker.','This tiny driver holds a small metal arm balanced between magnets. The audio signal makes the arm tip back and forth. A rod passes that motion to a small diaphragm. It is efficient and small, so it suits earphones and hearing aids.','It provides high efficiency and small size for in-ear and hearing-aid use, where a moving-coil driver would be too large or power-hungry.','A technician selects several balanced-armature units, each covering a limited band, and crosses them over to build a multi-driver in-ear monitor.','Driver types',ARRAY['Compression drivers','Coaxial loudspeakers','Blocked impedance','Back electromotive force']::text[],ARRAY['Expecting one balanced-armature unit to cover the full audio range.','Assuming it is just a tiny moving-coil driver; the motor topology is different.','Ignoring its sharp mechanical resonances when designing crossovers.']::text[],ARRAY['Building or repairing a multi-driver in-ear monitor.','Servicing a hearing-aid receiver.','Comparing balanced-armature and dynamic earphone drivers.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Balanced armature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '385ccf1f-3850-4a25-8fbf-eae0af0f2ce3','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='385ccf1f-3850-4a25-8fbf-eae0af0f2ce3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='385ccf1f-3850-4a25-8fbf-eae0af0f2ce3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11fd90f3-76a3-40f3-babb-2252f56b438b','Band-pass enclosures','A loudspeaker enclosure type in which the driver is fully hidden between chambers and sound reaches the outside only through a port, so the system radiates over a band and rolls off both above and below it. A single-reflex (fourth-order) design has one sealed and one ported chamber; a dual-reflex (sixth-order) design has two ported chambers.','In a band-pass box the driver is trapped inside. Sound only comes out through a port. This gives output over a chosen band, with roll-off on both sides. Subwoofers often use this design.','It gives a built-in band-limited response and can boost efficiency over a narrow range, useful for subwoofers.','A technician builds a fourth-order band-pass sub with a sealed rear chamber and a ported front chamber, tuning the port and chamber volumes to set the passband.','Enclosure design',ARRAY['Acoustic mass loading','Alpha ratio','Acoustic damping','Air-noise-limited output']::text[],ARRAY['Assuming a band-pass box has flat wide response; it is deliberately band-limited.','Neglecting that the hidden driver''s cone excursion still needs headroom.','Mis-tuning chambers so the passband ripples or narrows.']::text[],ARRAY['Designing a compact high-output subwoofer.','Explaining why a band-pass sub protects the driver above its passband.','Tuning front and rear chamber volumes.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Band-pass enclosures');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11fd90f3-76a3-40f3-babb-2252f56b438b','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11fd90f3-76a3-40f3-babb-2252f56b438b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11fd90f3-76a3-40f3-babb-2252f56b438b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6bcab81b-9695-4a44-ab55-8777095e03d8','Beam narrowing','The progressive reduction of a radiator''s coverage angle as frequency rises, because the source becomes large compared with the wavelength and radiation concentrates on axis. The effect scales with the size parameter ka, so larger diaphragms narrow their beam at lower frequencies than smaller ones.','A speaker spreads sound wide at low frequencies. As pitch rises, the beam gets narrower. Bigger cones start narrowing sooner. This is beam narrowing, and it changes off-axis tone.','It explains how a driver''s coverage changes with frequency, guiding driver size choices and crossover points for even coverage.','A technician crosses over a large woofer before its beam narrows too much, handing off to a horn that keeps controlled coverage at high frequencies.','Directivity',ARRAY['Acoustic crossover between array elements','Array coherence','Coaxial loudspeakers','Compression drivers']::text[],ARRAY['Assuming coverage stays constant with frequency for a plain cone.','Crossing over a big driver too high, so its top end beams badly off axis.','Judging a speaker only on axis and ignoring off-axis narrowing.']::text[],ARRAY['Choosing crossover frequency to control directivity.','Explaining dull off-axis high frequencies from a large driver.','Matching a horn''s coverage to a woofer''s.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam narrowing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6bcab81b-9695-4a44-ab55-8777095e03d8','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6bcab81b-9695-4a44-ab55-8777095e03d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6bcab81b-9695-4a44-ab55-8777095e03d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2dcdbba-a6bb-4a1a-ad47-063115812efa','Bending-wave driver','A loudspeaker driver that produces sound from flexural (bending) waves travelling across its diaphragm or panel, rather than from rigid, pistonic motion of the whole surface. The exciter launches bending waves whose distributed motion radiates over a wide band, as used in distributed-mode and related panel loudspeakers.','Most speakers move their cone as one solid piston. A bending-wave driver instead sends ripples across a panel. Those bending ripples make the sound. This spreads output in an unusual, wide way.','It offers an alternative radiation method with wide, diffuse dispersion and thin, light panels for special applications.','A technician mounts a compact exciter on a stiff, light panel to create a flat distributed-mode radiator for a discreet installed system.','Driver types',ARRAY['Bending-wave radiator','Circumferential mode','Cone motion','Coherent wavefront']::text[],ARRAY['Assuming it behaves like a pistonic cone driver in modelling.','Expecting tight imaging; radiation is deliberately diffuse.','Confusing the exciter (the driver) with the radiating panel.']::text[],ARRAY['Installing discreet flat-panel speakers.','Explaining diffuse dispersion of a panel radiator.','Comparing pistonic and bending-wave transducers.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bending-wave driver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2dcdbba-a6bb-4a1a-ad47-063115812efa','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2dcdbba-a6bb-4a1a-ad47-063115812efa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2dcdbba-a6bb-4a1a-ad47-063115812efa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df60e1fc-a681-45d7-8dfa-7c2afe693525','Bending-wave radiator','The radiating surface, typically a thin, stiff, light panel or diaphragm, that emits sound through flexural (bending) waves excited across it. It is the counterpart to the exciter in a bending-wave system, and its material stiffness, mass, and damping set the range and smoothness of its output.','A bending-wave radiator is the panel that actually makes the sound. Bending ripples travel across it. Its stiffness, weight, and damping shape the result. It is the surface, not the little exciter that drives it.','It is the sound-producing surface of a bending-wave system, converting flexural motion into radiated acoustic power.','A technician chooses a panel material with the right stiffness-to-mass and adds edge damping to smooth the radiator''s response.','Driver types',ARRAY['Bending-wave driver','Circumferential mode','Cone motion','Acoustic damping']::text[],ARRAY['Treating the radiator as a simple flat piston.','Choosing a panel that is too heavy or too lossy, cutting output.','Confusing the radiator (panel) with the exciter that drives it.']::text[],ARRAY['Selecting panel material for a flat loudspeaker.','Damping panel edges to control resonances.','Explaining how bending waves radiate sound.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bending-wave radiator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df60e1fc-a681-45d7-8dfa-7c2afe693525','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df60e1fc-a681-45d7-8dfa-7c2afe693525') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df60e1fc-a681-45d7-8dfa-7c2afe693525');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c024ae21-e0d6-4f7d-8c39-0d27b70a416c','Blocked impedance','The electrical impedance of a loudspeaker''s voice coil measured with the diaphragm held motionless, so that no back-EMF is generated and only the coil''s resistance and inductance remain. It represents the purely electrical part of the driver impedance, without the motional component that appears when the cone can move.','Hold a driver''s cone still and measure the coil. You get only its wire resistance and coil inductance. No motion means no generator effect. This baseline is the blocked impedance.','It separates the coil''s electrical properties from motional effects, which is essential for modelling and parameter measurement.','A technician clamps or heavily loads the cone to measure blocked impedance, obtaining Re and Le without the resonance peak that motion adds.','Motor system',ARRAY['Back electromotive force','Cone motion','Alpha ratio','Balanced armature']::text[],ARRAY['Confusing blocked impedance with the driver''s nominal or rated impedance.','Ignoring that real coil inductance rises less steeply than an ideal inductor (semi-inductive behaviour).','Forgetting the motional peak vanishes only when the cone truly cannot move.']::text[],ARRAY['Measuring a driver''s electrical parameters.','Modelling a driver''s impedance curve.','Separating motor motion effects from coil electrical effects.']::text[],'Advanced','Z_b = R_e + j*omega*L_e','The blocked impedance equals the coil''s DC resistance plus the reactance of its inductance, which rises with frequency.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blocked impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c024ae21-e0d6-4f7d-8c39-0d27b70a416c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c024ae21-e0d6-4f7d-8c39-0d27b70a416c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c024ae21-e0d6-4f7d-8c39-0d27b70a416c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17bdcc8d-1d6a-4ed3-8b2e-a000e0be6871','Break-in effect','A small change in a driver''s suspension compliance after initial exercising, which can lower the free-air resonance and slightly raise compliance as the spider and surround relax. Controlled measurements show the effect is generally minor and often partly recoverable with rest, so large audible ''break-in'' claims are not well supported.','A new driver''s suspension is a little stiff at first. Some flexing can loosen it slightly. Its resonance may drop a small amount. The change is usually small, and some of it comes back after rest.','It reminds technicians that measured parameters can shift slightly after exercising, so measurements should be taken under consistent conditions.','A technician exercises a driver briefly and lets it settle before measuring Thiele-Small parameters, so readings are repeatable rather than taken cold.','Suspension',ARRAY['Cone motion','Cone displacement','Alpha ratio','Blocked impedance']::text[],ARRAY['Overstating break-in as a large, permanent sound improvement.','Forgetting that compliance changes can partly reverse after the driver rests.','Measuring parameters cold and treating them as final.']::text[],ARRAY['Preconditioning a driver before parameter measurement.','Explaining a small resonance shift on a new woofer.','Judging claims about speaker ''burn-in''.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Break-in effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17bdcc8d-1d6a-4ed3-8b2e-a000e0be6871','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17bdcc8d-1d6a-4ed3-8b2e-a000e0be6871') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17bdcc8d-1d6a-4ed3-8b2e-a000e0be6871');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7c89bad-8bb9-4c72-ada9-6623d540d038','Broadside arrays','A loudspeaker array in which sources are arranged in a line and driven in phase so the strongest radiation is broadside, that is perpendicular to the line of sources. Element spacing relative to wavelength controls the main-lobe width and the appearance of side lobes.','Line up several speakers and feed them the same signal in step. The loudest output goes straight out from the line. That sideways-facing pattern is a broadside array. Spacing sets how tight the beam is.','It shapes coverage by concentrating output perpendicular to the source line, useful for controlling directivity such as in subwoofer lines.','A technician places subs in an in-phase broadside row to widen or focus low-frequency coverage across an audience, watching spacing to avoid side lobes.','Array behavior',ARRAY['Cardioid subwoofer arrays','Array coherence','Coherent wavefront','Acoustic crossover between array elements']::text[],ARRAY['Confusing broadside (perpendicular) with end-fire (along the line) behaviour.','Spacing elements too far apart, creating side lobes and uneven coverage.','Assuming in-phase drive always gives the narrowest possible beam.']::text[],ARRAY['Laying out a subwoofer line across a stage front.','Controlling low-frequency directivity in a venue.','Comparing broadside and end-fire sub arrays.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Broadside arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7c89bad-8bb9-4c72-ada9-6623d540d038','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7c89bad-8bb9-4c72-ada9-6623d540d038') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7c89bad-8bb9-4c72-ada9-6623d540d038');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e58bf37-ba15-4436-95eb-60bb0a4c5a5d','Cardioid subwoofer arrays','Subwoofer configurations that use multiple units with deliberate spacing, delay, and polarity to create a directional, cardioid (heart-shaped) low-frequency pattern with strong forward output and reduced radiation to the rear. Common realisations include end-fire, front-to-back gradient, and reversed-and-delayed arrangements.','Bass normally spreads in all directions. A cardioid sub array aims it forward instead. It uses several subs with set delays and polarity. This keeps low end off the stage and back walls.','It gives directional bass so the audience gets low-frequency energy while the stage and rear are quieter, improving clarity and control.','A technician sets up a front-to-back gradient pair, reversing polarity and delaying the rear sub, so rearward bass cancels while forward output adds.','Array behavior',ARRAY['Broadside arrays','Array coherence','Coherent wavefront','Acoustic crossover between array elements']::text[],ARRAY['Setting the wrong delay or polarity, which weakens or reverses the cancellation.','Expecting equal cancellation at every low frequency; performance varies with frequency.','Forgetting that the array trades some forward output for rear rejection.']::text[],ARRAY['Keeping stage bass low for the performers.','Reducing low-frequency reflections off a rear wall.','Configuring end-fire versus gradient sub arrays.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cardioid subwoofer arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e58bf37-ba15-4436-95eb-60bb0a4c5a5d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e58bf37-ba15-4436-95eb-60bb0a4c5a5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e58bf37-ba15-4436-95eb-60bb0a4c5a5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96587240-c11b-4c56-a5ff-2e016d001d8f','Ceiling bounce','The interference between a loudspeaker''s direct sound and its reflection off the ceiling, which combine at the listener with a time delay and cause peaks and dips (comb filtering), typically a notch whose frequency depends on the path-length difference. It is the ceiling counterpart of floor bounce and colours response, especially in the low-mid range.','Sound from a speaker reaches you directly and also after bouncing off the ceiling. The two arrive slightly apart in time. Where they clash, you get a dip in response. That is ceiling bounce.','Recognizing it helps technicians predict and treat response dips caused by ceiling reflections in rooms and monitoring setups.','A technician moves a speaker or adds ceiling absorption to lengthen or damp the reflected path, reducing the comb-filter notch heard at the mix position.','Room interaction',ARRAY['Acoustic-center offset','Coherent wavefront','Array coherence','Acoustic damping']::text[],ARRAY['Blaming a response dip on the speaker when it is a ceiling reflection.','Assuming the notch frequency is fixed; it moves with listener and speaker position.','Treating only the floor bounce and ignoring the ceiling.']::text[],ARRAY['Diagnosing a low-mid dip at a mix position.','Placing absorption on a reflective ceiling.','Choosing speaker height to shift the notch.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ceiling bounce');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96587240-c11b-4c56-a5ff-2e016d001d8f','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96587240-c11b-4c56-a5ff-2e016d001d8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96587240-c11b-4c56-a5ff-2e016d001d8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d8e52ad-2dcc-45e3-acd2-2c1dd6403e91','Circumferential mode','A diaphragm break-up vibration pattern whose nodal lines run around the circumference of the cone, dividing it into sectors that move out of phase, as distinct from radial modes with nodes along the radius. These modes appear above the piston band and cause response irregularities and distortion.','At high frequencies a cone stops moving as one piece. It flexes into patterns. A circumferential mode splits the cone around its rim into sectors. These sectors move against each other, roughening the sound.','It identifies a class of cone break-up that limits the usable upper range of a driver and guides cone material and shape choices.','A technician crosses a woofer over below its strong circumferential break-up modes, or chooses a stiffer, better-damped cone to push those modes higher.','Diaphragm behavior',ARRAY['Cone motion','Cone displacement','Bending-wave radiator','Beam narrowing']::text[],ARRAY['Assuming a cone stays perfectly pistonic across its whole range.','Confusing circumferential modes with radial (concentric) break-up modes.','Pushing a driver above its break-up region and blaming the amplifier for harshness.']::text[],ARRAY['Setting a crossover below cone break-up.','Interpreting a ragged high-frequency response from a woofer.','Comparing cone materials for break-up control.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Circumferential mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d8e52ad-2dcc-45e3-acd2-2c1dd6403e91','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d8e52ad-2dcc-45e3-acd2-2c1dd6403e91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d8e52ad-2dcc-45e3-acd2-2c1dd6403e91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02d66631-d1e7-4011-a440-65e264df1811','Coaxial loudspeakers','A loudspeaker in which two (or more) drivers, usually a low-frequency cone and a high-frequency unit, share a common axis so their acoustic centres are nearly coincident, approximating a point source. Well-known implementations include Tannoy''s Dual Concentric and KEF''s Uni-Q designs, each a registered trademark of its respective owner; the underlying coaxial method itself is generic.','A coaxial speaker stacks a tweeter on the same axis as the woofer. The two drivers sit at one point in space. This helps them act like a single source. It improves how the sound blends and images.','It provides point-source behaviour and consistent coverage by making the drivers radiate from nearly the same place.','A technician chooses a coaxial studio monitor for a small room so the stereo image stays stable and consistent across listening positions.','Driver types',ARRAY['Acoustic-center offset','Compression drivers','Coherent wavefront','Beam narrowing']::text[],ARRAY['Assuming coaxial drivers have zero acoustic-center offset; a small offset remains.','Ignoring diffraction from the front driver blocking the rear driver''s output.','Treating brand names like Dual Concentric or Uni-Q as generic terms.']::text[],ARRAY['Selecting a point-source studio monitor.','Explaining consistent imaging from a coaxial driver.','Servicing a two-way coaxial in a live cabinet.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coaxial loudspeakers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02d66631-d1e7-4011-a440-65e264df1811','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02d66631-d1e7-4011-a440-65e264df1811') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02d66631-d1e7-4011-a440-65e264df1811');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66430f8b-0f10-4551-9100-660c6d18c1b3','Coherent wavefront','A radiated wavefront across which the phase relationship is consistent, so contributions from the source surface or array combine constructively into a single, smoothly expanding front. Coherence over the radiating area gives predictable directivity and clean summation, whereas phase disorder produces interference and lobing.','A coherent wavefront keeps its phase in order across the sound-emitting surface. The parts add up cleanly into one smooth wave. This gives even, predictable coverage. Phase disorder instead causes ragged interference.','It is the ideal a designer aims for so a driver or array radiates a single controlled wavefront rather than a scattered one.','A technician aligns array elements in time and phase so they launch one coherent wavefront, giving smooth response across the coverage area.','Radiation',ARRAY['Array coherence','Acoustic crossover between array elements','Coaxial loudspeakers','Acoustic-center offset']::text[],ARRAY['Assuming any array automatically makes a coherent wavefront.','Ignoring high-frequency phase errors that break coherence.','Confusing coherence (phase order) with loudness alone.']::text[],ARRAY['Time-aligning array elements.','Explaining smooth coverage from a well-designed source.','Diagnosing lobing from a non-coherent array.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coherent wavefront');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66430f8b-0f10-4551-9100-660c6d18c1b3','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66430f8b-0f10-4551-9100-660c6d18c1b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66430f8b-0f10-4551-9100-660c6d18c1b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4dfdd909-9970-4829-9d76-0b1aa776e8d4','Compression drivers','A high-frequency transducer in which a diaphragm drives a small compression chamber and couples to a horn through a phasing plug, with the throat area much smaller than the diaphragm area (the compression ratio). This impedance matching gives high efficiency and high output, and the driver is always intended to work loaded by a horn. Products are made by makers such as JBL, B&C Speakers, and FaitalPRO; the underlying method is generic.','A compression driver squeezes sound from a diaphragm into a narrow throat. A phasing plug guides it, and a horn then spreads it. The squeeze makes it very efficient and loud. It must always be used on a horn.','It delivers efficient, high-output high frequencies for horn-loaded professional systems, from studio to large sound reinforcement.','A technician mates a one-inch-exit compression driver to a matching horn and crosses it over above the horn''s cutoff to protect the driver.','Driver types',ARRAY['Acoustic impedance transformation','Acoustic cutoff','Compression nonlinearity','Coaxial loudspeakers']::text[],ARRAY['UNSAFE: Standing at the mouth of a horn-loaded compression driver at high output can exceed safe exposure limits and damage hearing; use hearing protection and keep clear during high-level testing.','UNSAFE: Driving a compression driver below horn cutoff or beyond its rating overheats the voice coil, which can burn out and fail; respect crossover and power limits.','Running a compression driver without a horn, which unloads it and can cause damage.','Setting the crossover too low, near or below the horn''s cutoff frequency.']::text[],ARRAY['Assembling a horn-loaded high-frequency section.','Protecting a driver with a suitable high-pass crossover.','Comparing compression drivers by exit size and diaphragm material.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression drivers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4dfdd909-9970-4829-9d76-0b1aa776e8d4','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4dfdd909-9970-4829-9d76-0b1aa776e8d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4dfdd909-9970-4829-9d76-0b1aa776e8d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d789a50-b96d-4ac6-ab8c-12d5ed246427','Compression nonlinearity','Distortion arising in the highly compressed air within a compression driver''s throat and phasing plug, where the pressure-density relationship of air is nonlinear at the large local pressures involved, generating harmonics that rise with level. It is a physical limit of horn-loaded high-frequency reproduction, distinct from thermal power compression.','Inside a compression driver the air gets squeezed hard. At high levels, that squeezed air does not respond in a simple way. It adds harmonics the signal did not have. This is compression nonlinearity.','It explains a fundamental distortion limit of compression drivers so designers set realistic maximum clean-output targets.','A technician expects rising second-harmonic distortion from a compression driver near its limits and keeps levels within a cleaner range for critical work.','Distortion',ARRAY['Air nonlinearity','Compression drivers','Amplitude modulation distortion','Acoustic impedance transformation']::text[],ARRAY['Confusing this air-compression distortion with thermal power compression (level loss from heat).','Blaming the amplifier for distortion that comes from the compressed throat air.','Assuming a larger diaphragm alone removes it; throat pressure still matters.']::text[],ARRAY['Explaining distortion from a loud horn system.','Comparing throat designs for lower distortion.','Setting safe clean-output levels for a compression driver.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression nonlinearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d789a50-b96d-4ac6-ab8c-12d5ed246427','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d789a50-b96d-4ac6-ab8c-12d5ed246427') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d789a50-b96d-4ac6-ab8c-12d5ed246427');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cc3effb-0417-4179-9009-1f1af5211fb6','Cone displacement','The instantaneous linear distance the cone travels from its rest position along the axis, usually expressed in millimetres, with the peak linear travel defined by Xmax. At low frequencies the radiated output depends on volume velocity, the product of cone area and displacement, so more displacement is needed as frequency falls.','Cone displacement is how far the cone moves from its resting spot. It is measured in millimetres. Deep bass needs a lot of movement. The safe limit for clean travel is called Xmax.','It links how far the cone moves to how much low-frequency sound is produced, and it sets the driver''s clean excursion limit.','A technician checks that required displacement stays within Xmax; halving frequency at the same output roughly quadruples the displacement needed.','Diaphragm behavior',ARRAY['Cone motion','Alpha ratio','Amplitude modulation distortion','Air-noise-limited output']::text[],ARRAY['Exceeding Xmax, which causes rising distortion and possible mechanical damage.','Assuming a bigger cone always needs more displacement; larger area needs less for the same output.','Confusing peak displacement with root-mean-square or average values.']::text[],ARRAY['Checking a woofer''s excursion for deep bass.','Choosing a driver with enough Xmax for a target level.','Explaining distortion that rises as bass gets louder.']::text[],'Intermediate','U = S_d * x','The volume velocity equals the effective cone area multiplied by the cone''s displacement (velocity uses the rate of change of displacement).','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cone displacement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cc3effb-0417-4179-9009-1f1af5211fb6','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cc3effb-0417-4179-9009-1f1af5211fb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cc3effb-0417-4179-9009-1f1af5211fb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7ae31a2-6b45-4260-bfee-60f7dd2cd697','Cone motion','The overall movement of a loudspeaker cone in response to the force on the voice coil (F = BL times current), ideally rigid, pistonic motion within the driver''s passband and increasingly modal break-up above it. Its behaviour is governed by the driver''s mechanical mass, compliance, and damping together with the motor force.','Cone motion is how the whole cone moves when driven. In its normal range it moves as one solid piston. Higher up, it flexes and breaks into patterns. The motor force and the cone''s mass and springiness control it.','It ties the electrical drive to the acoustic output, and its ideal pistonic form defines the driver''s clean operating band.','A technician keeps a driver within its pistonic band, where the driving force F = BL*i moves the whole cone together, and crosses over before break-up dominates.','Diaphragm behavior',ARRAY['Cone displacement','Circumferential mode','Back electromotive force','Break-in effect']::text[],ARRAY['Assuming the cone stays pistonic across the whole audio range.','Ignoring break-up modes that appear above the piston band.','Confusing the driving force (BL times current) with back-EMF (BL times velocity).']::text[],ARRAY['Explaining why drivers are crossed over below break-up.','Relating amplifier current to cone force.','Diagnosing distortion from non-pistonic behaviour.']::text[],'Intermediate','F = BL * i','The force driving the cone equals the motor factor (flux density times coil length in the gap) multiplied by the current through the voice coil.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cone motion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7ae31a2-6b45-4260-bfee-60f7dd2cd697','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7ae31a2-6b45-4260-bfee-60f7dd2cd697') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7ae31a2-6b45-4260-bfee-60f7dd2cd697');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1007510e-ef3f-4305-b39c-89029f70a7b6','Constant-directivity horns','A constant-directivity (CD) horn is a horn or waveguide shaped so its coverage angle stays roughly uniform across most of its operating frequency band, rather than narrowing at high frequencies. The geometry deliberately trades some on-axis high-frequency output for stable, predictable pattern control, which is why CD horns are usually paired with high-frequency equalisation.','Older horns beam high notes into a narrow spot. A constant-directivity horn spreads sound over the same angle at most frequencies. This makes coverage even for a crowd. The trade-off is that highs need a boost to stay flat.','It exists to give a loudspeaker a defined, frequency-stable coverage angle so a known area gets even sound, which is essential for arraying and for room coverage design.','A technician picks a CD horn by its rated pattern, such as 90 degrees by 40 degrees, and applies the specified high-frequency shelf so the on-axis response measures flat.','Horns / Waveguides',ARRAY['Exit aperture','Constant-directivity equalisation','Waveguide','Coverage angle','Compression driver']::text[],ARRAY['Assuming a CD horn needs no equalisation, when it requires high-frequency boost by design.','Confusing the horn''s rated coverage angle with its true pattern at every frequency.','Believing wider coverage always means better; the correct angle depends on the venue.']::text[],ARRAY['Choosing a horn pattern to cover an audience area without wasting energy on walls.','Setting the high-frequency shelf equalisation a CD horn requires for flat response.','Building a horizontal array where each box must have predictable pattern overlap.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-directivity horns');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1007510e-ef3f-4305-b39c-89029f70a7b6','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1007510e-ef3f-4305-b39c-89029f70a7b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1007510e-ef3f-4305-b39c-89029f70a7b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d0efda6-5b32-453e-a15f-d19b414e225e','Constrained-layer damping','Constrained-layer damping bonds a stiff constraining layer to a panel through a thin viscoelastic adhesive, so panel bending forces the middle layer to shear and convert vibration energy to heat. In loudspeaker work it is applied to enclosure walls, baffles, or brackets to suppress resonant panel radiation and colouration.','A cabinet wall can vibrate and add unwanted sound. This method glues a stiff layer onto the wall with a soft, sticky middle layer. When the wall flexes, the sticky layer smears and turns motion into heat. That quiets the panel.','It exists to reduce unwanted panel vibration and its radiated colouration, giving a quieter, more inert enclosure without adding large amounts of mass.','A builder laminates two thinner boards with a viscoelastic damping compound between them, instead of using one thick board, to tame midrange cabinet ring.','Enclosure / Damping',ARRAY['Panel resonance','Viscoelastic material','Enclosure colouration','Cabinet bracing','Diaphragm breakup']::text[],ARRAY['Thinking any glue works; the middle layer must be viscoelastic to shear and damp.','Adding only mass and expecting the same damping as a constrained-layer sandwich.','Ignoring brackets and baffles, which can radiate resonances as much as side walls.']::text[],ARRAY['Reducing a hollow, boxy colouration heard on a resonant monitor cabinet.','Designing a stiff, inert baffle for a studio loudspeaker.','Damping a metal bracket that rings inside a subwoofer enclosure.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constrained-layer damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d0efda6-5b32-453e-a15f-d19b414e225e','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d0efda6-5b32-453e-a15f-d19b414e225e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d0efda6-5b32-453e-a15f-d19b414e225e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e3674dd-79a9-4921-ae74-60a622ed5685','Crossover interference','Crossover interference is the constructive and destructive summation that occurs near the crossover frequency, where two drivers radiate the same band from physically separate positions. Because their outputs overlap with frequency-dependent phase differences, the combined response shows lobing, tilting, and on- or off-axis peaks and dips.','Near the crossover point, two drivers play the same notes at once. They sit a small distance apart. Their sounds meet slightly out of step. This can add up or cancel, creating peaks and dips that change with listening angle.','Understanding it lets a designer align driver phase, spacing, and slopes so the two outputs sum cleanly instead of creating a distorted, angle-dependent response.','A technician measures on-axis and above and below the crossover; a deep null that moves with height signals interference from driver spacing and phase.','Crossovers',ARRAY['Driver spacing','Lobing error','Crossover frequency','Linkwitz-Riley alignment','Polar response']::text[],ARRAY['Judging a crossover only on-axis and missing large off-axis lobing.','Assuming correct filter slopes guarantee clean summation regardless of driver spacing.','Ignoring driver phase alignment, which shifts the interference lobe off the main axis.']::text[],ARRAY['Diagnosing a response dip that appears only when the mic moves off-axis.','Choosing crossover frequency low enough that driver spacing stays small in wavelengths.','Time-aligning a woofer and tweeter to steer the crossover lobe on-axis.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crossover interference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e3674dd-79a9-4921-ae74-60a622ed5685','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e3674dd-79a9-4921-ae74-60a622ed5685') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e3674dd-79a9-4921-ae74-60a622ed5685');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9914502b-87ed-4efc-9da3-abb482ab6210','Cylindrical spreading assumptions','Cylindrical spreading is an idealised model in which sound from a long line source spreads outward as expanding cylinders, so intensity falls with 1/r and the level drops about 3 dB per doubling of distance. It is an approximation used for line arrays in the near field, valid only over a limited distance and frequency range before the source behaves like a point.','A tall line of speakers can act like a line source. Its sound spreads sideways like a growing cylinder. Level then drops about 3 decibels each time distance doubles. This only holds close to the array and over a limited band.','The model explains why a tall line array loses level more slowly with distance than a point source, helping predict coverage for large audiences.','In the cylindrical near field, doubling the distance from 8 m to 16 m gives roughly a 3 dB drop, versus about 6 dB for a point source.','Radiation / Arrays',ARRAY['Line array','Spherical spreading','Near field','Inverse-square law','Effective source size']::text[],ARRAY['Assuming 3 dB per doubling holds at all distances; the field reverts to spherical far away.','Applying the model to short arrays that never behave as long line sources.','Ignoring frequency: the cylindrical region shrinks toward the lower frequencies.']::text[],ARRAY['Estimating how a tall line array covers a deep audience with less front-to-back level change.','Explaining why a line source seems louder at the rear than a single point source.','Judging the transition distance where an array stops behaving cylindrically.']::text[],'Advanced','ΔL = 10·log₁₀(r₁/r₂)  (cylindrical)','The level change equals ten times the base-ten logarithm of the ratio of the first distance to the second distance, giving about minus three decibels per doubling.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cylindrical spreading assumptions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9914502b-87ed-4efc-9da3-abb482ab6210','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9914502b-87ed-4efc-9da3-abb482ab6210') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9914502b-87ed-4efc-9da3-abb482ab6210');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55c30b4e-d7df-414d-b3cd-3a5a38d13a7c','DC resistance','DC resistance (Re) is the ohmic resistance of the voice-coil winding measured with direct current, set by the wire material, length, and cross-section. It is the lowest impedance point in the driver''s response and is typically well below the rated nominal impedance.','The voice coil is a long piece of wire. Its plain resistance to steady current is the DC resistance. You measure it with a meter set to ohms. It sits below the speaker''s rated impedance, such as 6 ohms for an 8-ohm driver.','Re is a core Thiele-Small parameter; it sets the minimum load the amplifier sees and feeds directly into electrical Q and efficiency calculations.','Measure across the terminals with a DC ohmmeter; an 8-ohm nominal woofer often reads about 5.5 to 6.5 ohms, confirming a healthy coil.','T-S Parameters',ARRAY['Voice coil','Nominal impedance','Electrical quality factor','Thiele-Small parameters','Impedance curve']::text[],ARRAY['Confusing DC resistance with nominal impedance; Re is always lower.','Using an AC impedance reading and calling it Re.','Assuming a shorted or open reading is normal, when it signals a damaged coil.']::text[],ARRAY['Quickly testing a suspected blown driver by reading terminal resistance.','Feeding Re into a box-modelling program alongside other Thiele-Small values.','Estimating amplifier load and current draw for a low-impedance driver.']::text[],'Beginner','R = ρ·l / A','Resistance equals the wire resistivity times its length, divided by its cross-sectional area.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='DC resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55c30b4e-d7df-414d-b3cd-3a5a38d13a7c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55c30b4e-d7df-414d-b3cd-3a5a38d13a7c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55c30b4e-d7df-414d-b3cd-3a5a38d13a7c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6f48e65-373c-4610-babf-77c32acaba26','Damage limit','The damage limit is the input level or excursion above which a driver suffers permanent mechanical or thermal harm, such as coil former deformation, suspension tearing, or adhesive and coil burnout. It is distinct from the rated continuous power, which is a safe long-term operating figure.','Every speaker has a point where more power breaks it. Push past that and the coil overheats or the cone bottoms out. This is the damage limit. It sits above the safe rated power, not at it.','Knowing the damage limit lets a technician set gain and limiters so peaks never drive a driver into thermal burnout or mechanical failure.','Set a limiter a few decibels below the manufacturer''s stated peak so brief transients stay clear of the mechanical and thermal damage threshold.','Power / Reliability',ARRAY['Excursion limits','Power handling','Dynamic compression','Fast thermal time constant','Voice coil']::text[],ARRAY['UNSAFE: Driving a system near its damage limit for long periods, risking coil burnout, overheating, and fire.','UNSAFE: Removing or bypassing limiters, exposing drivers and listeners to uncontrolled peak levels and hearing damage.','Treating rated continuous power as the maximum safe input; peaks can still exceed the damage limit.','Assuming clipping a small amplifier cannot harm a large speaker; clipped output adds damaging heat.']::text[],ARRAY['Setting system limiters during commissioning to protect drivers from transients.','Investigating a burnt voice coil after a show run at excessive level.','Explaining why a driver failed below its rated power due to amplifier clipping.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Damage limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6f48e65-373c-4610-babf-77c32acaba26','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6f48e65-373c-4610-babf-77c32acaba26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6f48e65-373c-4610-babf-77c32acaba26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd623e044-0c3a-4d0d-ac89-d37742d8b516','Diaphragm breakup','Diaphragm breakup is the frequency region where a cone or dome stops moving as a rigid piston and flexes into standing-wave bending modes across its surface. These modes create sharp resonant peaks and dips and add distortion, usually setting the practical upper frequency limit of the driver.','At low notes a cone moves as one solid piece. Higher up, parts of it flex out of step with each other. This is breakup. It causes ragged peaks and dips. It usually marks the top of the driver''s useful range.','Recognising breakup tells a designer where a driver stops behaving predictably, so the crossover can be set below the messy resonant region.','On a metal-cone woofer, a tall spike near 5 kHz marks breakup; the crossover is set an octave or more below it, often with a notch filter.','Diaphragm Behaviour',ARRAY['Cone material','Distributed-mode behavior','Pistonic range','Crossover frequency','Constrained-layer damping']::text[],ARRAY['Crossing over inside or just below the breakup peak, letting the resonance leak through.','Assuming a stiffer cone removes breakup; it usually just shifts it higher and sharper.','Reading a smooth published curve and missing sharp breakup hidden by smoothing.']::text[],ARRAY['Choosing a low-pass frequency safely under a metal cone''s breakup spike.','Adding a notch filter to tame a stubborn breakup resonance.','Comparing paper, metal, and composite cones by where breakup begins.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm breakup');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd623e044-0c3a-4d0d-ac89-d37742d8b516','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d623e044-0c3a-4d0d-ac89-d37742d8b516') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d623e044-0c3a-4d0d-ac89-d37742d8b516');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90d7d4fe-892a-4d14-8d7d-e49ae7e6df69','Distributed-mode behavior','Distributed-mode behavior describes a flat panel radiator that is driven to vibrate in many overlapping bending modes spread evenly across its surface, rather than moving as a piston. Distributed Mode Loudspeaker (DML) is a trademark associated with NXT (New Transducers Ltd); the underlying method is generic bending-wave panel radiation.','A normal speaker cone pushes air like a piston. A distributed-mode panel instead vibrates in a spread of small waves all over its face. Exciters shake the panel to make many modes at once. The result radiates sound over a wide, diffuse angle.','The approach makes thin, wide-dispersion panel speakers whose diffuse radiation suits some background and architectural applications rather than precise imaging.','A technician mounts an exciter on a stiff, light panel and feeds it full-range audio; coverage is broad and diffuse but bass output is limited.','Diaphragm Behaviour',ARRAY['Bending waves','Diaphragm breakup','Panel resonance','Exciter','Pistonic range']::text[],ARRAY['Expecting deep, high-output bass from a thin distributed-mode panel.','Treating DML as a generic term; it is a trademark for a bending-wave panel method.','Assuming pinpoint stereo imaging from an intentionally diffuse radiator.']::text[],ARRAY['Installing flat panel speakers for even background coverage in a lobby.','Comparing a diffuse panel radiator with a conventional pistonic driver.','Explaining why a panel speaker images differently from a cone loudspeaker.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distributed-mode behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90d7d4fe-892a-4d14-8d7d-e49ae7e6df69','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90d7d4fe-892a-4d14-8d7d-e49ae7e6df69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90d7d4fe-892a-4d14-8d7d-e49ae7e6df69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6cbc8703-2741-4453-9aed-f0e9d70ec8da','Doppler modulation','Doppler modulation, or Doppler distortion, is a frequency modulation of a high-frequency tone caused by the large excursion of a low-frequency tone reproduced by the same diaphragm. As the cone moves toward and away from the listener, it shifts the momentary frequency of the higher tone, adding sidebands.','One cone playing bass moves a lot back and forth. If it also plays a high note, that motion shifts the high note''s pitch slightly up and down. This is Doppler distortion. Splitting bass and treble to separate drivers reduces it.','It explains one reason to use multiple drivers, since separating high and low frequencies onto different cones removes the excursion-driven pitch smearing.','A full-range single cone reproducing loud bass plus a melody will smear the melody''s pitch; a two-way design giving bass to the woofer avoids it.','Distortion',ARRAY['Excursion limits','Intermodulation distortion','Full-range driver','Cone excursion','Two-way system']::text[],ARRAY['Confusing Doppler modulation with amplitude intermodulation; the mechanism is pitch shift.','Assuming it matters at small excursions; it grows with large low-frequency cone motion.','Believing a single full-range cone has no such distortion at high levels.']::text[],ARRAY['Explaining why a two-way splits bass and treble to separate drivers.','Analysing pitch smearing on a loud single-cone full-range speaker.','Teaching the difference between Doppler and intermodulation distortion.']::text[],'Advanced','Δf / f ≈ v_cone / c','The fractional frequency shift of the high tone roughly equals the instantaneous cone velocity divided by the speed of sound.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Doppler modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6cbc8703-2741-4453-9aed-f0e9d70ec8da','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6cbc8703-2741-4453-9aed-f0e9d70ec8da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6cbc8703-2741-4453-9aed-f0e9d70ec8da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32861aa0-8b11-48a3-a136-2f7795c17397','Driver spacing','Driver spacing is the centre-to-centre distance between two drivers radiating the same frequencies, which governs how their outputs sum and lobe off-axis. When spacing approaches or exceeds a wavelength at the shared frequency, deep nulls and multiple lobes appear in the polar response.','Two drivers playing the same band sit a certain distance apart. That gap controls how their sounds combine at different angles. If the gap is large compared with the wavelength, you get strong nulls. Keeping it small keeps coverage smooth.','Controlling spacing lets a designer keep summation smooth and lobing minimal through the crossover region, especially off the main axis.','For a 3 kHz crossover, wavelength is about 0.11 m; keeping centre-to-centre spacing under that helps avoid deep off-axis nulls.','Arrays / Crossovers',ARRAY['Crossover interference','Lobing error','Line array','Comb filtering','Crossover frequency']::text[],ARRAY['Ignoring spacing and blaming the filter when off-axis nulls appear.','Assuming any spacing is fine as long as slopes are correct.','Forgetting that higher crossover frequencies demand tighter spacing.']::text[],ARRAY['Laying out woofer and tweeter close together to smooth vertical coverage.','Setting array element spacing to control lobing at the crossover band.','Diagnosing comb filtering caused by two widely spaced drivers.']::text[],'Intermediate','d ≤ λ = c / f','Centre-to-centre spacing should be no more than the wavelength, which equals the speed of sound divided by the shared frequency.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Driver spacing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32861aa0-8b11-48a3-a136-2f7795c17397','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32861aa0-8b11-48a3-a136-2f7795c17397') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32861aa0-8b11-48a3-a136-2f7795c17397');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20a4b3f1-f52f-4e01-83ad-500aef851f1d','Dynamic compression','Dynamic compression, or power compression, is the reduction in acoustic output relative to input as the voice coil heats up during high-power operation. Rising coil temperature increases the voice-coil resistance, which draws less power from the amplifier and lowers sensitivity, so loud passages gain less level than expected.','As a speaker plays loud, its voice coil gets hot. Hot copper has more resistance. That pulls less power from the amp and drops output. So the speaker cannot keep getting louder in step with the input. This is power compression.','It explains why real loudspeakers lose sensitivity under sustained high power, a key factor when predicting maximum usable level in a system.','As a coil heats, copper resistance rises about 0.39 percent per degree Celsius; a 100 degree rise adds roughly 39 percent to Re, cutting several decibels of output.','Power / Thermal',ARRAY['Fast thermal time constant','DC resistance','Power handling','Sensitivity','Damage limit']::text[],ARRAY['UNSAFE: Pushing more power to chase lost output as the coil heats, risking thermal burnout and fire.','Assuming published sensitivity holds at high, sustained power levels.','Mistaking power compression for amplifier clipping or limiter action.','Ignoring cooling and enclosure venting, which worsen compression when neglected.']::text[],ARRAY['Explaining why a system stops getting louder late in a loud show.','Estimating true maximum level after allowing for power compression.','Comparing drivers whose thermal design resists compression differently.']::text[],'Intermediate','R(T) = R₀·[1 + α·(T − T₀)]','The hot resistance equals the cold resistance times one plus the temperature coefficient multiplied by the temperature rise.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20a4b3f1-f52f-4e01-83ad-500aef851f1d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20a4b3f1-f52f-4e01-83ad-500aef851f1d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20a4b3f1-f52f-4e01-83ad-500aef851f1d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8468c0c-ccdd-4451-97bf-b15f0122ccb5','Dynamic driver','A dynamic driver is an electrodynamic (moving-coil) transducer in which a voice coil sits in a fixed magnetic gap and moves a diaphragm when audio current flows through it. It is the most common loudspeaker and headphone motor type, working by the force on a current-carrying conductor in a magnetic field.','A dynamic driver is the usual kind of speaker. A coil of wire sits in a magnet''s gap. Audio current in the coil makes a force. That force pushes a cone or dome to make sound. Most speakers and earphones use it.','It converts an electrical audio signal into diaphragm motion and sound, serving as the standard motor for woofers, tweeters, and headphones.','A technician recognises a dynamic driver by its magnet, voice coil, and cone; it drives most passive speakers and needs no external power itself.','Transducer Types',ARRAY['Voice coil','Electromagnetic force','Electroacoustic driver','Moving-coil','Compression driver']::text[],ARRAY['UNSAFE: Handling strong neodymium motor magnets carelessly, risking pinched fingers and hazards for pacemaker wearers.','Confusing a dynamic (moving-coil) driver with a balanced-armature or electrostatic type.','Assuming all dynamic drivers are full-range; most cover only part of the band.','Believing a dynamic driver needs external power like a powered speaker.']::text[],ARRAY['Identifying the motor type when servicing a passive loudspeaker.','Explaining how a moving-coil driver turns current into cone motion.','Comparing dynamic, electrostatic, and planar transducer designs.']::text[],'Beginner',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic driver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8468c0c-ccdd-4451-97bf-b15f0122ccb5','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8468c0c-ccdd-4451-97bf-b15f0122ccb5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8468c0c-ccdd-4451-97bf-b15f0122ccb5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf2f5281-b005-4a95-ac27-085b1f90fdf4','Dynamic parameter measurement','Dynamic parameter measurement is the procedure for extracting a driver''s Thiele-Small parameters by measuring its impedance while it moves, typically with a small added mass or a known test enclosure. From the free-air resonance and a second loaded condition, parameters such as compliance, moving mass, and equivalent volume are derived.','To model a speaker you need its key numbers. You measure the impedance curve while the cone moves. Then you add a small weight or a test box and measure again. The two curves let you calculate the moving mass and springiness.','It provides the measured Thiele-Small values a designer needs to predict box alignment, bass response, and system behaviour before building an enclosure.','Measure free-air resonance, add a known mass to lower it, then compute moving mass and compliance from the two resonance frequencies.','Measurement',ARRAY['Thiele-Small parameters','Free-air resonance','Added-mass method','Impedance curve','Vas']::text[],ARRAY['Measuring a cold, unexercised driver, which reads a shifted resonance.','Using too small an added mass or test volume to shift resonance reliably.','Ignoring that parameters drift with drive level and temperature.']::text[],ARRAY['Characterising a raw driver before designing its enclosure.','Verifying that a batch of drivers meets published parameter tolerances.','Re-measuring a used driver whose suspension has softened over time.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic parameter measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf2f5281-b005-4a95-ac27-085b1f90fdf4','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf2f5281-b005-4a95-ac27-085b1f90fdf4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf2f5281-b005-4a95-ac27-085b1f90fdf4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '892fbc3d-219d-4df7-9bbe-df41091a834b','EBP','EBP (efficiency bandwidth product) is a rule-of-thumb figure equal to a driver''s free-air resonance frequency divided by its electrical quality factor, used to suggest a suitable enclosure type. Values around 50 point toward a sealed box, values around 100 or above point toward a vented box, with the range between being flexible.','EBP is a quick number that hints which box suits a woofer. You divide the resonance frequency by the electrical Q. A low result near 50 suggests a sealed box. A high result near 100 suggests a vented box.','It gives designers a fast first guess at enclosure type from two common parameters, before detailed modelling.','For Fs of 40 Hz and Qes of 0.4, EBP is 100, which suggests the driver suits a vented enclosure.','T-S Parameters',ARRAY['Electrical quality factor','Free-air resonance','Fb','Sealed enclosure','Vented enclosure']::text[],ARRAY['Treating EBP as a hard rule instead of a starting guide.','Using total Q instead of electrical Q in the ratio.','Ignoring the middle range, where either alignment can work.']::text[],ARRAY['Making a first guess at enclosure type from a driver''s datasheet.','Comparing two woofers to see which favours a ported box.','Teaching how resonance and electrical Q hint at box choice.']::text[],'Intermediate','EBP = Fs / Qes','The efficiency bandwidth product equals the free-air resonance frequency divided by the electrical quality factor.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='EBP');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '892fbc3d-219d-4df7-9bbe-df41091a834b','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='892fbc3d-219d-4df7-9bbe-df41091a834b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='892fbc3d-219d-4df7-9bbe-df41091a834b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0d98cbd-85a4-48be-9c1b-cfa0b16766f7','Early-reflections curve','The early-reflections curve is a spatially averaged frequency response, defined in the ANSI/CTA-2034-A loudspeaker measurement method, that estimates the first reflections a listener hears from typical room surfaces. It combines specified floor, ceiling, and wall bounce directions to predict how a loudspeaker''s off-axis behaviour colours early room sound.','A speaker''s sound reaches you directly and after bouncing off nearby surfaces. The early-reflections curve averages those first bounces. It comes from a standard set of off-axis measurements. It helps predict how a speaker will sound in a normal room.','It helps predict in-room tonal balance by summarising the off-axis energy that arrives soon after the direct sound, guiding loudspeaker and room evaluation.','A technician reads the early-reflections curve from a spinorama data set to judge whether a speaker''s first reflections stay smooth and well balanced.','Measurement',ARRAY['Spinorama','Off-axis response','Sound power','Listening window','Directivity index']::text[],ARRAY['Reading the early-reflections curve as an on-axis response.','Ignoring it and judging a speaker only by its on-axis curve.','Assuming it captures late reverberation rather than early bounces.']::text[],ARRAY['Evaluating a monitor''s predicted in-room balance from standardised data.','Comparing two loudspeakers'' off-axis smoothness before purchase.','Explaining why on-axis flatness alone does not predict room sound.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Early-reflections curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0d98cbd-85a4-48be-9c1b-cfa0b16766f7','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0d98cbd-85a4-48be-9c1b-cfa0b16766f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0d98cbd-85a4-48be-9c1b-cfa0b16766f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '239e8c8b-3b37-4cc6-9db7-113bd7c12cc5','Edge diffraction','Edge diffraction is the re-radiation of sound from the boundaries of a loudspeaker baffle, where a wavefront meeting the cabinet edge acts as a secondary source. The delayed diffracted wave combines with the direct output to cause frequency-response ripples and small changes in directivity.','Sound spreads across the speaker''s front panel until it reaches the edges. At each edge it bends and re-radiates a little late. This second wave mixes with the direct sound. The result is small ripples in the response.','Understanding it lets designers shape baffles, round edges, or offset drivers to reduce response ripple caused by delayed edge re-radiation.','A technician rounds or chamfers baffle edges and offsets the tweeter from the centre so diffraction ripples spread out and shrink.','Radiation / Baffle',ARRAY['Baffle step','Effective source size','Off-axis response','Waveguide','Comb filtering']::text[],ARRAY['Placing a tweeter centred on a small square baffle, which strengthens diffraction.','Ignoring sharp edges and blaming ripple on the crossover.','Assuming felt or foam alone fully removes diffraction effects.']::text[],ARRAY['Rounding cabinet edges to smooth a rippled high-frequency response.','Offsetting a tweeter to spread diffraction artefacts.','Explaining small response wiggles measured on a bare flat baffle.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Edge diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '239e8c8b-3b37-4cc6-9db7-113bd7c12cc5','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='239e8c8b-3b37-4cc6-9db7-113bd7c12cc5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='239e8c8b-3b37-4cc6-9db7-113bd7c12cc5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '368cdbbb-fa26-4cd2-a94b-a7a90cfdf782','Effective source size','Effective source size is the acoustic dimension of a radiator relative to the wavelength, which determines its directivity. When the source is small compared with the wavelength it radiates nearly omnidirectionally, and as it grows large relative to the wavelength its output narrows into a beam.','How wide a speaker seems to the sound depends on its size versus the wavelength. Small compared to the wavelength, it spreads sound everywhere. Large compared to the wavelength, it beams straight ahead. This size-to-wavelength ratio sets the pattern.','It explains why the same driver spreads low frequencies widely but beams highs, guiding driver-size and crossover choices for controlled coverage.','A large woofer starts to beam once its circumference approaches one wavelength, which is why smaller drivers or horns handle the higher frequencies.','Radiation / Directivity',ARRAY['Directivity','Beaming','Wavelength','Edge diffraction','Cylindrical spreading assumptions']::text[],ARRAY['Assuming directivity depends on frequency alone, not size versus wavelength.','Expecting a large cone to stay wide-dispersion at high frequencies.','Ignoring that a horn changes the effective radiating aperture.']::text[],ARRAY['Choosing a small tweeter to keep wide dispersion up high.','Explaining why a subwoofer''s placement is less directional than a tweeter''s.','Deciding a crossover frequency before a woofer starts to beam.']::text[],'Advanced','ka = 2πa / λ','The directivity factor equals two pi times the source radius divided by the wavelength.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective source size');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '368cdbbb-fa26-4cd2-a94b-a7a90cfdf782','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='368cdbbb-fa26-4cd2-a94b-a7a90cfdf782') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='368cdbbb-fa26-4cd2-a94b-a7a90cfdf782');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5ec4aeb-1683-4be3-9a3e-f393fb0e05a7','Electrical branch','In a loudspeaker''s equivalent circuit, the electrical branch is the part representing the voice coil''s own electrical properties, chiefly its DC resistance and inductance. It is separate from the mechanical and acoustic branches that model the moving mass, suspension compliance, and radiation load.','Engineers model a speaker as a small circuit. The electrical branch is the part for the voice coil''s resistance and inductance. Other branches stand for the moving parts and the air load. Together they predict how the speaker behaves.','It isolates the coil''s purely electrical behaviour in the model, so designers can analyse impedance and how electrical energy enters the moving system.','A technician links the electrical branch to the mechanical side through the force factor, letting a lumped model predict the impedance curve.','Modelling',ARRAY['Electro-mechano-acoustic equivalent circuit','Voice-coil inductance','DC resistance','Force factor','Electrical damping']::text[],ARRAY['Forgetting voice-coil inductance and modelling only DC resistance.','Confusing the electrical branch with the mechanical branch of the model.','Assuming the branch alone predicts sound output without the acoustic load.']::text[],ARRAY['Building a lumped-element model of a driver''s impedance.','Explaining how coil resistance and inductance shape the impedance curve.','Teaching how electrical energy couples into the mechanical system.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical branch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5ec4aeb-1683-4be3-9a3e-f393fb0e05a7','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5ec4aeb-1683-4be3-9a3e-f393fb0e05a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5ec4aeb-1683-4be3-9a3e-f393fb0e05a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3bb71748-e262-462a-b4f0-8bd6249cbb68','Electrical damping','Electrical damping is the control of cone motion provided by the driver''s own generated back-EMF working into the amplifier''s low output impedance. As the coil moves it generates a voltage that opposes motion, and a low source impedance lets this current flow and damp resonance, which is the electrical basis of speaker damping factor.','A moving voice coil also acts like a tiny generator. It makes a voltage that fights its own motion. A low-resistance amplifier lets that current flow and brakes the cone. This electrical braking tames the bass resonance.','It provides the main mechanical control of a driver''s resonance, tightening bass and reducing overhang when the amplifier output impedance is low.','Connecting a woofer to a low-impedance amplifier output raises damping and controls the resonant peak; long, thin speaker cable adds resistance and weakens it.','Damping',ARRAY['Electrical quality factor','Damping factor','Back-EMF','Electrical branch','Force factor']::text[],ARRAY['Believing very high damping factors dramatically change audible bass control.','Ignoring speaker cable and connector resistance, which reduce effective damping.','Confusing electrical damping with mechanical suspension damping.']::text[],ARRAY['Explaining why a low-output-impedance amplifier tightens bass.','Diagnosing loose, boomy bass caused by high series resistance.','Teaching how back-EMF brakes cone motion at resonance.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3bb71748-e262-462a-b4f0-8bd6249cbb68','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3bb71748-e262-462a-b4f0-8bd6249cbb68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3bb71748-e262-462a-b4f0-8bd6249cbb68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9c5db4a-7c00-4816-bf46-46b21294a934','Electrical quality factor','The electrical quality factor (Qes) is the Thiele-Small parameter describing the damping of a driver''s resonance by electrical means, mainly the motor''s back-EMF acting through the voice-coil resistance. A lower Qes means stronger electrical damping, and it combines with the mechanical quality factor to give the total quality factor Qts.','Qes measures how strongly the motor electrically brakes the cone at resonance. It comes mostly from the coil and magnet acting as a generator. A small Qes means tight electrical control. It joins with the mechanical Q to give the total Q.','Qes quantifies the motor''s electrical damping, feeding directly into total Q, enclosure alignment, and predicted bass behaviour.','For Fs 30 Hz, Mms 0.05 kg, Re 6 ohm, and Bl 10 T·m, Qes = 2π×30×0.05×6 / 10² ≈ 0.57.','T-S Parameters',ARRAY['Mechanical quality factor','Total quality factor','Electrical damping','Force factor','EBP']::text[],ARRAY['Confusing electrical Q (Qes) with total Q (Qts).','Assuming a higher Qes means better control; lower means stronger damping.','Forgetting that a strong motor (high Bl) lowers Qes.']::text[],ARRAY['Combining Qes and Qms to find total Q for box design.','Comparing motor strength between drivers by their Qes.','Feeding Qes into an enclosure-alignment calculation.']::text[],'Advanced','Qes = 2π·Fs·Mms·Re / (Bl)²','The electrical quality factor equals two pi times resonance frequency times moving mass times DC resistance, divided by the square of the force factor.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical quality factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9c5db4a-7c00-4816-bf46-46b21294a934','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9c5db4a-7c00-4816-bf46-46b21294a934') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9c5db4a-7c00-4816-bf46-46b21294a934');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '971e6c2a-3a1d-42b6-a14d-2d4576d2f829','Electro-mechano-acoustic equivalent circuit','An electro-mechano-acoustic equivalent circuit is a lumped-element model that represents a loudspeaker''s electrical, mechanical, and acoustic behaviour as connected circuit elements. Voltage and current stand in for mechanical force and velocity or acoustic pressure and volume velocity, linked by the motor''s force factor and the diaphragm''s radiating area.','Engineers model a whole speaker as one circuit. Part of it is the real electrical side. Other parts stand for the moving mass, springiness, and air load. Coupling terms tie them together. The model predicts impedance and response.','It lets designers analyse a complete loudspeaker with familiar circuit tools, predicting impedance, resonance, and frequency response before building hardware.','A technician uses this model, with the force factor and cone area as couplers, to predict a driver''s impedance peak and low-frequency roll-off.','Modelling',ARRAY['Electrical branch','Force factor','Thiele-Small parameters','Lumped-element model','Radiation impedance']::text[],ARRAY['Mixing up which quantities map to voltage and current across domains.','Applying the lumped model above frequencies where dimensions stay small.','Omitting the radiation load, which sets low-frequency behaviour.']::text[],ARRAY['Deriving a driver''s impedance curve from a lumped model.','Teaching how force factor and cone area couple the three domains.','Predicting resonance and roll-off before a prototype is built.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electro-mechano-acoustic equivalent circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '971e6c2a-3a1d-42b6-a14d-2d4576d2f829','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='971e6c2a-3a1d-42b6-a14d-2d4576d2f829') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='971e6c2a-3a1d-42b6-a14d-2d4576d2f829');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e43451ca-baab-4230-b3e0-2c3c3a4218b0','Electroacoustic driver','An electroacoustic driver is any transducer that converts electrical audio signals into acoustic output or the reverse, including moving-coil, compression, electrostatic, and piezoelectric types. The term is a general category covering the powered radiating element of a loudspeaker or similar device.','An electroacoustic driver changes electricity into sound. It can also change sound into electricity. It is the general name for the working part of a speaker. There are many types, such as moving-coil and electrostatic. A dynamic driver is one common type.','It names the broad class of sound-producing transducers, letting engineers group different motor technologies under one functional heading.','A technician uses the term when a design could use any transducer type, then specifies the exact kind, such as a compression driver, when it matters.','Transducer Types',ARRAY['Dynamic driver','Compression driver','Electrostatic transducer','Transducer','Diaphragm']::text[],ARRAY['Treating electroacoustic driver as meaning only a moving-coil type.','Assuming the term specifies a size or frequency range.','Confusing the driver element with the finished loudspeaker system.']::text[],ARRAY['Describing the transducer class in a general system specification.','Comparing different driver technologies under one umbrella term.','Teaching the range of ways electricity becomes sound.']::text[],'Beginner',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electroacoustic driver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e43451ca-baab-4230-b3e0-2c3c3a4218b0','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e43451ca-baab-4230-b3e0-2c3c3a4218b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e43451ca-baab-4230-b3e0-2c3c3a4218b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '129a8b40-f218-48b3-a0b3-bb8b443acbbc','Electromagnetic force','In a moving-coil driver, the electromagnetic (motor) force is the force on the current-carrying voice coil in the magnet gap, equal to the product of the gap flux density, the coil wire length in the gap, and the current. The product of flux density and wire length is the force factor Bl, a key measure of motor strength.','A speaker''s motor makes force from current in a magnetic field. The force equals the field strength times the wire length in the gap times the current. The field strength times wire length is called Bl. A bigger Bl means a stronger motor.','This force is what drives the diaphragm; its strength, set by Bl, governs sensitivity, electrical damping, and how firmly the motor controls the cone.','With a force factor Bl of 10 T·m and 2 A of coil current, the motor force is 10 × 2 = 20 N acting on the cone.','Motor / Magnet',ARRAY['Force factor','Voice coil','Magnetic flux density','Electrical quality factor','Dynamic driver']::text[],ARRAY['UNSAFE: Bringing strong magnet assemblies near pacemakers, tools, or fingers, risking injury and device interference.','Confusing the force factor Bl with the magnet''s raw flux density alone.','Assuming higher current always means proportionally more force at large excursion, where Bl falls.','Ignoring that Bl varies with coil position off centre.']::text[],ARRAY['Estimating motor force from a driver''s force factor and drive current.','Explaining why a higher Bl raises sensitivity and damping.','Comparing motor strength between two drivers by their Bl.']::text[],'Intermediate','F = B·l·i = Bl·i','The motor force equals the gap flux density times the wire length in the gap times the coil current, where flux density times length is the force factor.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electromagnetic force');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '129a8b40-f218-48b3-a0b3-bb8b443acbbc','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='129a8b40-f218-48b3-a0b3-bb8b443acbbc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='129a8b40-f218-48b3-a0b3-bb8b443acbbc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53a1060c-0a00-418a-a5bd-c794881ee5f0','Electronic beamforming','Electronic beamforming steers or shapes the radiation pattern of a multi-driver array by applying individual delay, gain, and sometimes filtering to each element. By controlling the relative timing across the array, the summed wavefront can be aimed and its coverage tailored without physically tilting the loudspeaker.','An array of drivers can aim its sound using electronics. Each driver gets its own small delay and level. The delays make the combined wavefront point in a chosen direction. This steers coverage without moving the speaker.','It lets a fixed column or array steer and shape its coverage electronically, useful where physical aiming is hard, as in reverberant public spaces.','A technician programs per-driver delays in a steerable column so its main beam points down at the seated audience and away from a reflective ceiling.','Arrays / DSP',ARRAY['End-fire arrays','Line array','Driver spacing','Delay','Directivity']::text[],ARRAY['Assuming beamforming gives unlimited control regardless of array length and spacing.','Ignoring frequency limits set by element spacing and array size.','Confusing electronic steering with simply tilting the loudspeaker.']::text[],ARRAY['Aiming a steerable column''s beam at seating in a reverberant church.','Reducing reflections by steering energy away from hard surfaces.','Setting per-element delays to shape vertical coverage.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53a1060c-0a00-418a-a5bd-c794881ee5f0','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53a1060c-0a00-418a-a5bd-c794881ee5f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53a1060c-0a00-418a-a5bd-c794881ee5f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b42b96a0-1a49-44ec-badc-6a86184e2656','End-fire arrays','An end-fire array places several sources in a line along the intended radiation axis and applies delay so their outputs add in the forward direction and cancel to the rear. It is used mainly with subwoofers to achieve directional low-frequency control and reduce energy radiated behind the array.','An end-fire array lines up subwoofers front to back. Each one is delayed by the right amount. Their sound adds up going forward. Going backward, it cancels. This gives bass more control and less spill behind the stage.','It provides directional bass control, cutting low-frequency energy radiated backward toward the stage or neighbours from a set of subwoofers.','A technician spaces subwoofers along the aim axis and delays the rear ones by the acoustic travel time so front output adds and rear output cancels.','Arrays',ARRAY['Cardioid subwoofer','Delay','Electronic beamforming','Driver spacing','Directivity']::text[],ARRAY['Setting the delay wrong, so rear cancellation and front summation both fail.','Spacing the subs incorrectly for the target frequency band.','Expecting perfect rejection across all low frequencies from a simple array.']::text[],ARRAY['Reducing subwoofer bleed onto a stage using delayed, in-line subs.','Directing low-frequency energy toward the audience and away from neighbours.','Comparing end-fire and cardioid subwoofer techniques.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='End-fire arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b42b96a0-1a49-44ec-badc-6a86184e2656','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b42b96a0-1a49-44ec-badc-6a86184e2656') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b42b96a0-1a49-44ec-badc-6a86184e2656');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a5dec7bb-5b78-4a91-b327-4ac5edc76b4f','Excursion limits','Excursion limits describe how far a diaphragm can move from rest, with Xmax marking the peak linear travel over which the motor and suspension stay reasonably proportional, and Xmech marking the physical limit before damage. Beyond Xmax distortion rises sharply, and beyond Xmech the coil or suspension can be destroyed.','A cone can only move so far each way. Xmax is the range where motion stays clean and linear. Push past it and distortion climbs fast. Push past the mechanical limit and parts break. These are the excursion limits.','They set how much clean low-frequency output a driver can make and warn where distortion and mechanical damage begin.','A geometric estimate takes Xmax as half the difference between coil winding height and gap height; a technician limits drive so peaks stay within it.','Excursion / Reliability',ARRAY['Xmax','Damage limit','Doppler modulation','Voice coil','Suspension']::text[],ARRAY['UNSAFE: Driving a woofer past its mechanical excursion limit, tearing the suspension or wrecking the coil.','Treating Xmax as a hard clean-until-then value rather than a distortion threshold.','Comparing Xmax figures from different definitions as if identical.','Ignoring that ports and filters can unload a cone and raise excursion below tuning.']::text[],ARRAY['Setting a high-pass filter to keep cone travel within Xmax.','Explaining rising distortion as a woofer nears its excursion limit.','Choosing a driver with enough linear travel for target bass output.']::text[],'Intermediate','Xmax ≈ (L_coil − L_gap) / 2','Peak linear excursion is roughly the voice-coil winding height minus the magnetic gap height, divided by two.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excursion limits');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a5dec7bb-5b78-4a91-b327-4ac5edc76b4f','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a5dec7bb-5b78-4a91-b327-4ac5edc76b4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a5dec7bb-5b78-4a91-b327-4ac5edc76b4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a7571e2-ebb3-46b0-848e-72d1f76eb0f0','Exit aperture','The exit aperture is the small opening where a compression driver''s phasing plug meets the throat of the horn, setting the throat cross-sectional area that couples the driver to the horn. Its size relative to the diaphragm area gives the compression ratio and strongly influences high-frequency loading and output.','A compression driver squeezes its sound through a small hole into the horn. That hole is the exit aperture, or throat. Its size compared with the diaphragm sets the compression ratio. It shapes how the horn loads the driver.','It couples the compression driver to the horn and sets the throat loading, affecting sensitivity, high-frequency extension, and distortion.','A technician matches a horn''s throat diameter, such as 1 inch or 1.4 inch, to the driver''s exit aperture so the loading and response stay correct.','Horns / Drivers',ARRAY['Compression driver','Phasing plug','Constant-directivity horns','Throat','Compression ratio']::text[],ARRAY['Mismatching horn throat and driver exit sizes, disturbing loading and response.','Confusing the exit aperture with the horn''s mouth opening.','Ignoring that compression ratio affects distortion and output.']::text[],ARRAY['Matching a compression driver to a horn of the same throat size.','Explaining how throat area sets a driver''s high-frequency loading.','Comparing 1-inch and 1.4-inch exit compression drivers.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exit aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a7571e2-ebb3-46b0-848e-72d1f76eb0f0','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a7571e2-ebb3-46b0-848e-72d1f76eb0f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a7571e2-ebb3-46b0-848e-72d1f76eb0f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1822c39d-8791-4f95-8fcb-b3036fe81142','Extended bass shelf','An extended bass shelf (EBS) is a vented-box alignment that tunes the enclosure below the classic maximally flat point, trading a gently drooping shelf in the low bass for deeper extension and greater cone control near tuning. It suits drivers whose parameters do not fit a flat alignment and is popular for extending low-frequency reach.','A vented box is usually tuned for flat bass. An extended bass shelf tunes it lower instead. The response droops a little in the low bass. In return you get deeper reach and better cone control near the port tuning.','It gives deeper low-frequency extension and better excursion control near tuning, at the cost of a small shelf-shaped droop in the deep bass.','A designer tunes the port below the flat-alignment frequency, accepting a mild low-bass shelf so the system reaches lower with safer cone motion.','Enclosure Alignment',ARRAY['Fb','Vented enclosure','Bass reflex','Excursion limits','EBP']::text[],ARRAY['Expecting a perfectly flat response from an extended bass shelf alignment.','Confusing the shelf droop with a fault in the driver or amplifier.','Applying it to drivers whose parameters better suit a flat alignment.']::text[],ARRAY['Extending a subwoofer''s reach lower using a shelved vented alignment.','Choosing an alignment for a driver that will not tune flat.','Trading a little deep-bass level for more extension and cone control.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Extended bass shelf');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1822c39d-8791-4f95-8fcb-b3036fe81142','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1822c39d-8791-4f95-8fcb-b3036fe81142') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1822c39d-8791-4f95-8fcb-b3036fe81142');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a619f4e-ef60-440f-af82-51e63a5b7735','Fast thermal time constant','The fast thermal time constant characterises how quickly the voice coil itself heats and cools, set by its small thermal mass and its thermal resistance to the surrounding structure. It is short, on the order of seconds, while the magnet and frame have a much longer, slow time constant of minutes.','A voice coil is light, so it heats and cools quickly. Its fast time constant is measured in seconds. The heavy magnet and frame change temperature slowly, over minutes. Short bursts mainly heat the coil, not the whole motor.','It explains why brief high-power transients raise coil temperature fast, informing limiter design and short-term versus long-term power ratings.','Because the coil heats in seconds, a limiter with a matching short time constant can protect it from damaging transient bursts.','Power / Thermal',ARRAY['Dynamic compression','Power handling','Voice coil','Damage limit','Thermal resistance']::text[],ARRAY['UNSAFE: Assuming brief loud bursts are always safe, when the light coil can overheat within seconds.','Confusing the fast coil time constant with the slow magnet-structure one.','Setting limiter timing that ignores the coil''s short thermal response.','Believing average power alone predicts coil temperature on transients.']::text[],ARRAY['Setting limiter attack and release to match the coil''s fast heating.','Explaining why short bursts heat the coil but not the whole motor.','Distinguishing short-term from long-term power ratings.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fast thermal time constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a619f4e-ef60-440f-af82-51e63a5b7735','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a619f4e-ef60-440f-af82-51e63a5b7735') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a619f4e-ef60-440f-af82-51e63a5b7735');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '098e8107-e860-4a83-8f67-0b344e399e2b','Fb','Fb is the tuning frequency of a vented (bass-reflex) enclosure, the Helmholtz resonance formed by the port mass of air working against the box air compliance. At Fb the port radiates most strongly and cone motion reaches a minimum, which shapes the system''s low-frequency response and excursion behaviour.','Fb is the tuning frequency of a ported speaker box. It comes from the air in the port bouncing on the springy air in the box. At Fb the port does most of the work. The cone barely moves there.','Fb sets where a vented box is tuned, controlling low-frequency extension, response shape, and the frequency of minimum cone excursion.','Fb rises with a larger port area and falls with a longer port or bigger box; a designer adjusts port length to hit a target such as 40 Hz.','Enclosure Alignment',ARRAY['Vented enclosure','Helmholtz resonance','Extended bass shelf','Port','EBP']::text[],ARRAY['Forgetting the port end correction, so the calculated Fb is off.','Assuming Fb equals the driver''s free-air resonance Fs.','Ignoring that a smaller box raises Fb for the same port.']::text[],ARRAY['Cutting a port to length to tune a bass-reflex box to a target Fb.','Explaining the impedance dip between the two peaks of a vented box.','Choosing Fb to balance extension against cone excursion.']::text[],'Intermediate','Fb = (c / 2π)·√(Av / (Vb·L_eff))','Box tuning equals the speed of sound over two pi, times the square root of the port area divided by the product of box volume and effective port length.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fb');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '098e8107-e860-4a83-8f67-0b344e399e2b','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='098e8107-e860-4a83-8f67-0b344e399e2b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='098e8107-e860-4a83-8f67-0b344e399e2b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c2a6f98-8560-4b83-83f9-277688f81a67','Fc','Fc is the resonance frequency of a driver after it is mounted in a sealed (closed) enclosure. The stiffness of the trapped air adds to the driver''s own suspension, raising the resonance above the free-air value Fs. Fc largely sets the low-frequency roll-off of a sealed-box system.','Fc is how low a sealed speaker box can play. Sealing a driver traps air behind the cone. That trapped air acts like an extra spring. The extra stiffness raises the resonance above the driver''s free value. So a smaller box gives a higher Fc.','It tells the designer the resonance and the -3 dB corner of a closed-box system, which controls its bass extension and transient behaviour.','With Fs=30 Hz, Vas=50 L, and box Vb=25 L: Fc = 30*sqrt(1+50/25) = 30*sqrt(3) = 52 Hz, and the system Q rises by the same square-root factor.','Thiele-Small Parameter',ARRAY['Fs','Qtc','Vas','Impedance peak','Sealed enclosure']::text[],ARRAY['Confusing Fc, the sealed-box system resonance, with fc used for a crossover frequency.','Assuming Fc equals the driver''s free-air Fs; the box air always raises it.','Forgetting that a smaller box raises both Fc and the total Q together.']::text[],ARRAY['Sizing a sealed subwoofer box for a target bass roll-off.','Predicting the -3 dB point of a closed monitor cabinet.','Explaining why the same driver sounds tighter in a smaller sealed box.']::text[],'Intermediate','Fc = Fs * sqrt(1 + Vas/Vb) ;  Qtc = Qts * sqrt(1 + Vas/Vb)','The closed-box resonance equals the free-air resonance multiplied by the square root of one plus the ratio of the driver''s equivalent air-compliance volume to the box volume.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fc');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c2a6f98-8560-4b83-83f9-277688f81a67','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c2a6f98-8560-4b83-83f9-277688f81a67') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c2a6f98-8560-4b83-83f9-277688f81a67');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80cd8e69-9506-4aaf-9bf2-1f28a4067695','Flexural radiator','A flexural radiator produces sound through bending (flexural) waves traveling across a plate or panel, rather than moving as a single rigid piston. Distributed-mode and bending-wave loudspeakers exploit this deliberately, while uncontrolled flexural motion in a cone appears as break-up.','A flexural radiator makes sound by bending, not by moving as one solid piece. Waves ripple across a flat panel or cone. Some speakers use this on purpose for wide, diffuse sound. In a normal cone the same bending is unwanted break-up.','It describes radiators that convert vibration into sound through panel bending, enabling thin flat-panel loudspeakers and explaining cone break-up behaviour.','A technician recognises flexural behaviour as the ragged region above a cone''s piston band, or as the operating principle of a flat distributed-mode panel speaker.','Radiator Type',ARRAY['Cone break-up','Distributed-mode loudspeaker','Diaphragm','Internal damping']::text[],ARRAY['Treating a bending-wave panel as if it behaved like a simple pistonic driver.','Assuming all cone motion is pistonic; above break-up it is flexural.','Believing flexural radiation is always a defect; some designs use it by intent.']::text[],ARRAY['Analysing why a metal cone has a sharp high-frequency break-up peak.','Specifying a flat-panel distributed-mode speaker for diffuse coverage.','Explaining ragged off-axis response caused by cone bending modes.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flexural radiator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80cd8e69-9506-4aaf-9bf2-1f28a4067695','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80cd8e69-9506-4aaf-9bf2-1f28a4067695') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80cd8e69-9506-4aaf-9bf2-1f28a4067695');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0fe7ccde-42ce-4cb1-bea9-d721d51cfafc','Floor bounce','Floor bounce is comb-filter interference caused when sound reflected from the floor combines with the direct sound at the listener or microphone. The path-length difference produces a cancellation dip (and following peaks) in the frequency response, usually in the low-midrange.','Floor bounce is a dip in sound caused by the floor. Sound reaches you two ways: straight, and bounced off the floor. The two paths differ in length. At some frequency they cancel, leaving a dip. It usually lands in the lower mids.','It explains a common measurement and listening artefact, letting a technician predict where a reflection-caused response dip will fall.','Source and ear 1.2 m high, loudspeaker 0.3 m off floor, 3 m away: direct=3.13 m, reflected=3.35 m, difference 0.22 m, so first null f = 343/(2*0.22) = about 770 Hz.','Acoustic Interference',ARRAY['Comb filtering','Boundary interference','Reflection','Horizontal off-axis response']::text[],ARRAY['Blaming the loudspeaker for a dip that is really a floor reflection.','Assuming the notch is fixed; it moves as source or mic height changes.','Ignoring floor bounce when making quasi-anechoic measurements at low height.']::text[],ARRAY['Explaining a persistent 200-400 Hz dip in an in-room response.','Choosing microphone height to place the floor null outside the band of interest.','Diagnosing why a speaker measures differently on a stand versus the floor.']::text[],'Intermediate','f_null = c / (2*d);  d = sqrt(D^2+(h_s+h_m)^2) - sqrt(D^2+(h_s-h_m)^2)','The first cancellation frequency equals the speed of sound divided by twice the extra distance the floor-reflected sound travels compared with the direct sound.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Floor bounce');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0fe7ccde-42ce-4cb1-bea9-d721d51cfafc','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0fe7ccde-42ce-4cb1-bea9-d721d51cfafc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0fe7ccde-42ce-4cb1-bea9-d721d51cfafc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6528f1bb-50ba-422b-b132-147b2ee7fc5b','Force-factor asymmetry','Force-factor asymmetry is an imbalance in the Bl(x) curve, where the motor develops more force for coil travel in one direction than the other. The rest position then sits off the Bl peak, producing even-order harmonic distortion and a signal-dependent DC shift of the coil.','Force-factor asymmetry means the motor pushes harder one way than the other. The strength of the motor changes with cone position. If the two sides are unequal, distortion appears. The cone can also drift off-centre when driven hard.','It flags a motor design flaw that raises distortion and can push the coil out of its gap under strong signals.','A technician sees force-factor asymmetry in a Klippel Bl(x) plot as a lopsided curve, warning of even-order distortion and dynamic coil offset at high level.','Motor Nonlinearity',ARRAY['Bl(x)','Force-factor modulation','Linear excursion','DC displacement']::text[],ARRAY['Confusing asymmetry (lopsided Bl) with modulation (Bl simply varying with travel).','Assuming a symmetric Bl curve; real motors are rarely perfectly balanced.','Overlooking that asymmetry can drive the coil steadily off-centre under bass drive.']::text[],ARRAY['Reading a lopsided Bl(x) curve during driver quality control.','Diagnosing even-order distortion that grows with output level.','Explaining why a woofer''s coil creeps off-centre on heavy bass.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Force-factor asymmetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6528f1bb-50ba-422b-b132-147b2ee7fc5b','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6528f1bb-50ba-422b-b132-147b2ee7fc5b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6528f1bb-50ba-422b-b132-147b2ee7fc5b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '027b78bb-e92a-4d9f-896b-4abea41a99ce','Force-factor modulation','Force-factor modulation is the variation of the motor''s force factor Bl as the voice coil moves through the gap (and, to a lesser degree, as current changes the flux). Because output force is Bl times current, a Bl that changes with position multiplies the signal and creates harmonic and intermodulation distortion.','Force-factor modulation means motor strength changes as the cone moves. Bl is strongest with the coil centred in the gap. As the cone swings out, Bl drops. This changing strength distorts the sound. It gets worse at large excursions.','It names the core motor nonlinearity that limits clean output, tying distortion directly to how far the coil leaves the magnetic gap.','A technician uses the Bl(x) curve''s width to set a safe excursion, since force-factor modulation causes distortion to rise steeply once Bl falls well below its centred value.','Motor Nonlinearity',ARRAY['Bl(x)','Force-factor asymmetry','Linear excursion','Intermodulation distortion']::text[],ARRAY['Assuming Bl is a single constant number rather than a function of position.','Ignoring modulation until the coil reaches Xmax; distortion rises well before that.','Confusing Bl modulation with inductance modulation Le(x); both act but differently.']::text[],ARRAY['Setting excursion limits from the shape of a measured Bl(x) curve.','Explaining rising distortion as bass level and cone travel increase.','Comparing motor topologies by how flat their Bl stays with travel.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Force-factor modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '027b78bb-e92a-4d9f-896b-4abea41a99ce','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='027b78bb-e92a-4d9f-896b-4abea41a99ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='027b78bb-e92a-4d9f-896b-4abea41a99ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9ef3ff7-690f-4b3d-b27d-59aa245426a5','Gradient arrays','Gradient arrays combine two or more sources with controlled spacing, delay, and polarity so their radiated sound adds in wanted directions and cancels in others. Exploiting the pressure gradient between the sources yields directional patterns such as cardioid, reducing rearward or off-axis radiation.','A gradient array steers sound using two or more speakers. Their spacing, timing, and polarity are set carefully. In front the outputs add up. Behind, they cancel out. This gives a one-sided, directional pattern.','It provides directional control at low frequencies, where a single box is nearly omnidirectional, by using interference between spaced sources.','A technician builds a cardioid gradient by pairing a rear-facing, delayed, polarity-inverted source with a front source so their low-frequency outputs cancel behind the array.','Array Technique',ARRAY['Gradient subwoofer array','Cardioid pattern','End-fire array','Pressure gradient']::text[],ARRAY['Expecting cancellation over all frequencies; gradient control is band-limited by spacing.','Getting the delay or polarity wrong, which cancels the front instead of the rear.','Assuming perfect rejection; real gradient arrays give finite, frequency-dependent rejection.']::text[],ARRAY['Reducing low-frequency spill onto a stage behind a subwoofer system.','Steering bass away from a reflective rear wall.','Designing directional low-frequency coverage for a noise-sensitive site.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gradient arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9ef3ff7-690f-4b3d-b27d-59aa245426a5','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9ef3ff7-690f-4b3d-b27d-59aa245426a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9ef3ff7-690f-4b3d-b27d-59aa245426a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9c62a5e-81ed-4597-bce8-c86a3cbfe2f7','Gradient subwoofer array','A gradient subwoofer array applies pressure-gradient techniques to subwoofers, using spacing, delay, and polarity between cabinets to shape low-frequency directivity. Common forms are the cardioid array (front and rear boxes with delay and polarity) and the end-fire array (a line of delayed boxes).','A gradient subwoofer array makes bass one-directional. Several subs are spaced and timed together. Delay and polarity are set so bass adds up front. Behind the array, the bass cancels. This keeps low end off the stage.','It controls where subwoofer energy goes, keeping strong bass in the audience while cutting it on stage or behind the system.','A technician sets a cardioid sub array by delaying and inverting a rear-facing box so its output cancels the front boxes'' rearward radiation, cutting on-stage bass.','Array Technique',ARRAY['Gradient arrays','End-fire array','Cardioid subwoofer','Subwoofer']::text[],ARRAY['UNSAFE: Lifting or stacking heavy subwoofer cabinets without correct rigging or team lifting, risking crush injury.','Using the wrong delay so rejection lands in front instead of behind.','Expecting deep cancellation far below the array''s design band.','Ignoring spacing, which sets the frequency range over which the pattern works.']::text[],ARRAY['Keeping bass off a stage to reduce microphone and monitor rumble.','Steering subwoofer energy away from a neighbouring residential boundary.','Setting up an end-fire sub line for forward-directed low end at a festival.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gradient subwoofer array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9c62a5e-81ed-4597-bce8-c86a3cbfe2f7','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9c62a5e-81ed-4597-bce8-c86a3cbfe2f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9c62a5e-81ed-4597-bce8-c86a3cbfe2f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4d209ff-0d17-4eb5-8879-dd4724b0755d','Grating lobes','Grating lobes are unwanted secondary radiation maxima produced by a regularly spaced array when the element spacing is comparable to or larger than the wavelength. They are the spatial-domain equivalent of aliasing and steer strong energy into off-axis angles the array was not meant to cover.','Grating lobes are extra beams of sound from an array. They appear when speakers sit too far apart for the frequency. The array then sends strong sound off to the sides. This is like aliasing, but in space. Closer spacing pushes these lobes higher in frequency.','It warns array designers that too-wide element spacing scatters energy into unintended directions, harming pattern control and coverage.','With 0.30 m spacing at 2 kHz (wavelength 0.17 m): the first grating lobe is at sin(theta) = 0.17/0.30 = 0.57, so about 35 degrees off the main axis.','Array Directivity',ARRAY['Line arrays','Line-source approximation','Spatial aliasing','Line-array curvature']::text[],ARRAY['Believing more, wider-spaced boxes always improve pattern control; wide spacing creates lobes.','Assuming grating lobes affect all frequencies; they appear only when spacing approaches the wavelength.','Confusing grating lobes with normal side lobes, which exist even with tight spacing.']::text[],ARRAY['Explaining high-frequency splatter above a poorly spaced driver array.','Choosing driver spacing to push grating lobes above the crossover.','Diagnosing off-axis coverage anomalies in a large subwoofer array.']::text[],'Advanced','sin(theta_g) = m * (lambda / d),  m = +/-1, +/-2, ...','A grating lobe appears at each angle whose sine equals an integer multiple of the wavelength divided by the element spacing.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grating lobes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4d209ff-0d17-4eb5-8879-dd4724b0755d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4d209ff-0d17-4eb5-8879-dd4724b0755d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4d209ff-0d17-4eb5-8879-dd4724b0755d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f28234d-bb03-4fe7-978a-0eb7ca013fb6','Group delay in loudspeaker systems','Group delay is the negative slope of a system''s phase response with respect to angular frequency, expressing how long the envelope of a narrow band of frequencies is delayed. In loudspeakers it rises near roll-offs, resonances, and crossovers, where different frequencies emerge at slightly different times.','Group delay is how long a band of tones takes to pass through a speaker. It is not the same at all frequencies. It grows near the bass roll-off and near crossovers. Large, sudden changes can smear transients. Small amounts are usually inaudible.','It quantifies frequency-dependent time smear, helping judge whether a system''s phase behaviour will blur transients.','If phase drops by pi radians across a 100 Hz span, group delay = pi / (2*pi*100) = about 5 ms; audibility thresholds are typically a few milliseconds in the bass.','Time-Domain Response',ARRAY['Phase response','Crossover','Fc','Minimum phase']::text[],ARRAY['Treating group delay as a single number rather than a curve versus frequency.','Assuming any group delay is audible; thresholds are often several milliseconds.','Confusing group delay with a simple constant latency, which is flat with frequency.']::text[],ARRAY['Assessing whether a steep high-pass adds audible bass time smear.','Comparing crossover topologies by their group-delay behaviour.','Explaining transient blur near a system''s low-frequency roll-off.']::text[],'Intermediate','tau_g(omega) = - d(phi)/d(omega)','Group delay equals the negative rate of change of the phase response with respect to angular frequency.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Group delay in loudspeaker systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f28234d-bb03-4fe7-978a-0eb7ca013fb6','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f28234d-bb03-4fe7-978a-0eb7ca013fb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f28234d-bb03-4fe7-978a-0eb7ca013fb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da2da055-8c4b-4e70-b500-1111a28ec9bf','Horizontal off-axis response','Horizontal off-axis response is the loudspeaker''s frequency response measured at angles to the left and right of its main (on-axis) direction, in the horizontal plane. Comparing these curves to the on-axis curve reveals how coverage and tonal balance change across the listening width.','This is how a speaker sounds when you sit off to the side. It is measured at set angles left and right of centre. The curves show where the treble narrows. It tells you how wide the good coverage is.','It characterises a loudspeaker''s horizontal coverage and off-axis tonal consistency, key to predicting how it sounds across an audience.','A technician reads the family of horizontal curves (for example at 0, 30, and 60 degrees) to find the angle where high-frequency output has dropped by 6 dB, defining coverage width.','Directivity Measurement',ARRAY['Directivity','Coverage angle','Horn directivity','Polar pattern']::text[],ARRAY['Judging a speaker only by its on-axis curve and ignoring off-axis behaviour.','Assuming coverage is the same at all frequencies; treble usually narrows.','Confusing horizontal with vertical off-axis behaviour, which can differ greatly.']::text[],ARRAY['Choosing a loudspeaker whose coverage matches an audience width.','Explaining why listeners at the sides hear duller treble.','Reading a directivity (spinorama) data set for a monitor.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Horizontal off-axis response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da2da055-8c4b-4e70-b500-1111a28ec9bf','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da2da055-8c4b-4e70-b500-1111a28ec9bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da2da055-8c4b-4e70-b500-1111a28ec9bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a3ca7a1b-1228-466b-b6a2-252884981576','Horn directivity','Horn directivity is the control of a loudspeaker''s coverage pattern by the flare geometry of a horn or waveguide placed in front of a driver. The mouth size and wall profile set how tightly the horn confines sound, with directivity narrowing at higher frequencies unless a constant-directivity design is used.','Horn directivity is how a horn aims sound. The horn''s shape and mouth size set the coverage angle. Bigger mouths control lower frequencies. Simple horns narrow their beam as pitch rises. Special shapes keep coverage steadier across frequency.','It lets designers set and hold a defined coverage angle, improving efficiency and directing sound where it is wanted.','A technician picks a 60-by-40-degree constant-directivity horn to cover a defined seating block, checking that its low-frequency limit suits the crossover point.','Directivity',ARRAY['Compression driver','Waveguide','Coverage angle','Constant directivity']::text[],ARRAY['Assuming a horn keeps the same coverage at all frequencies; plain horns beam at highs.','Thinking a small horn mouth can control very low frequencies; mouth size sets the limit.','Confusing higher on-axis sensitivity with wider coverage; horns often trade width for level.']::text[],ARRAY['Selecting a horn to match a specific seating coverage angle.','Explaining why a horn''s pattern narrows toward the top of its range.','Comparing constant-directivity and radial horn behaviour.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Horn directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a3ca7a1b-1228-466b-b6a2-252884981576','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a3ca7a1b-1228-466b-b6a2-252884981576') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a3ca7a1b-1228-466b-b6a2-252884981576');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6ed7bf7-8b8d-4ec8-85b0-64c5897f586f','Hysteresis distortion','Hysteresis distortion arises from the nonlinear, history-dependent magnetization of the iron in a loudspeaker motor, described by the B-H loop. As the voice-coil current modulates flux in the pole pieces, the lag between magnetizing force and flux, together with eddy-current losses, adds harmonic distortion, chiefly at low frequencies.','Hysteresis distortion comes from the iron in the motor. Iron does not magnetize in a straight line. Its magnetism lags behind the coil current. This lag bends the signal and adds distortion. It shows up mostly at low frequencies.','It identifies a distortion source in the magnetic circuit, guiding use of shorting rings and better pole materials to reduce it.','A technician reduces hysteresis and eddy losses by choosing a motor with a copper or aluminium shorting ring (Faraday ring), which stabilises the gap flux against current.','Motor Nonlinearity',ARRAY['Flux modulation','Le(i)','Shorting ring','Eddy currents']::text[],ARRAY['Confusing magnetic hysteresis distortion with mechanical suspension hysteresis.','Assuming distortion comes only from Bl or suspension, overlooking iron losses.','Believing a shorting ring cures all distortion; it mainly addresses flux modulation.']::text[],ARRAY['Explaining low-frequency distortion that a shorting ring reduces.','Comparing motors with and without Faraday rings for cleaner bass.','Diagnosing current-dependent distortion in a woofer motor.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hysteresis distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6ed7bf7-8b8d-4ec8-85b0-64c5897f586f','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6ed7bf7-8b8d-4ec8-85b0-64c5897f586f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6ed7bf7-8b8d-4ec8-85b0-64c5897f586f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7677182c-b044-43ed-94cc-4a59f033587c','Hysteretic damping','Hysteretic (structural) damping is energy dissipation inside a material caused by internal friction as it is stressed and released each cycle. Unlike viscous damping, the energy lost per cycle is roughly independent of frequency and scales with displacement amplitude, so it is modelled with a complex stiffness or loss factor.','Hysteretic damping is loss inside a material as it flexes. Bending it turns some energy into heat. This loss happens with each cycle of motion. Unlike sticky (viscous) damping, it barely changes with frequency. Cone and surround materials show this behaviour.','It models the internal-friction losses of cone, surround, and spider materials, which help tame resonances.','A technician treats a cone''s loss factor (tan delta) as hysteretic damping, using higher-loss materials to lower the height of break-up peaks.','Damping Mechanism',ARRAY['Internal damping','Loss factor','Cone break-up','Viscous damping']::text[],ARRAY['Assuming all damping is viscous and scales with velocity; hysteretic loss does not.','Confusing hysteretic (mechanical) damping with magnetic hysteresis distortion.','Thinking damping is free; it usually costs some efficiency.']::text[],ARRAY['Choosing a cone material to control break-up resonance.','Modelling suspension losses that are nearly frequency-independent.','Explaining why coated paper cones have smoother response than bare metal.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hysteretic damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7677182c-b044-43ed-94cc-4a59f033587c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7677182c-b044-43ed-94cc-4a59f033587c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7677182c-b044-43ed-94cc-4a59f033587c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35af5a71-bc95-481a-8c5a-318a383a979a','Impedance analogy','The impedance analogy is a modelling convention that represents mechanical and acoustical systems as electrical circuits, mapping force to voltage and velocity to current. Mass becomes inductance, mechanical compliance becomes capacitance, and mechanical resistance becomes electrical resistance, so elements that share a velocity are placed in series.','The impedance analogy turns a mechanical system into a circuit. Force acts like voltage. Velocity acts like current. Mass acts like an inductor, and springiness like a capacitor. This lets engineers use circuit maths on speakers.','It lets loudspeaker mechanics and acoustics be analysed with familiar electrical circuit tools and lumped-element methods.','A technician reading a driver''s equivalent circuit interprets the moving mass as an inductance and the suspension compliance as a capacitance under the impedance analogy.','Modelling Method',ARRAY['Mobility analogy','Lumped-element model','Thiele-Small Parameter','Impedance curves']::text[],ARRAY['Mixing up the impedance and mobility analogies, which swap series and parallel connections.','Assuming force always maps to current; in the impedance analogy force maps to voltage.','Forgetting the analogy is a model, not the literal electrical impedance of the coil.']::text[],ARRAY['Reading an equivalent-circuit model of a loudspeaker driver.','Teaching how mechanical resonance maps onto an electrical resonance.','Deriving Thiele-Small relations from a circuit analogy.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impedance analogy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35af5a71-bc95-481a-8c5a-318a383a979a','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35af5a71-bc95-481a-8c5a-318a383a979a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35af5a71-bc95-481a-8c5a-318a383a979a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d927e33-05ac-4b00-b538-47eb48b8c661','Impedance curves','An impedance curve is a plot of a loudspeaker''s electrical input impedance magnitude (and often phase) against frequency. Its shape reveals the driver''s resonance peak, the rising inductive region at high frequencies, and, in vented boxes, the twin peaks that flank the port tuning.','An impedance curve shows how a speaker''s electrical resistance changes with frequency. It is plotted across the audio band. A tall peak marks the driver''s resonance. The curve rises again at high frequencies from coil inductance. Ports add extra bumps.','It is a primary diagnostic that exposes resonance, box tuning, and inductance, and confirms the nominal impedance rating.','A technician measures the impedance curve to find Fs at the peak, to read box tuning from vented-box twin peaks, and to check the minimum value against the amplifier''s load rating.','Measurement',ARRAY['Impedance peak','Fs','Nominal impedance','Vented enclosure']::text[],ARRAY['Reading nominal impedance as the minimum; the nominal value is a rounded figure.','Assuming impedance is flat; it varies widely across frequency.','Ignoring phase, which also loads the amplifier along with magnitude.']::text[],ARRAY['Finding a driver''s resonance and box tuning from a measurement.','Verifying that a load stays within an amplifier''s safe range.','Confirming a sealed-versus-vented alignment from the curve shape.']::text[],'Beginner',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impedance curves');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d927e33-05ac-4b00-b538-47eb48b8c661','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d927e33-05ac-4b00-b538-47eb48b8c661') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d927e33-05ac-4b00-b538-47eb48b8c661');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd44920b2-43f3-4efa-ade0-aff5282ca9c0','Impedance peak','The impedance peak is the tall rise in a driver''s electrical impedance at its mechanical resonance frequency Fs, where the moving system''s back-EMF is greatest and it draws least current. Its height and the surrounding -3 dB bandwidth are used to derive the driver''s Q factors.','The impedance peak is a tall spike in a speaker''s impedance. It sits at the driver''s resonance. There the cone moves most freely and draws the least current. Its height and width reveal the driver''s damping.','It marks the resonance frequency and provides the data needed to calculate Qms, Qes, and Qts.','With Re=6.5 ohm and peak Zmax=45 ohm, r0 = Zmax/Re = 6.9, and Qes = Qms/(r0-1); the peak also directly locates Fs for the driver.','Measurement',ARRAY['Impedance curves','Fs','Qts','Free-air resonance']::text[],ARRAY['Mistaking the resonance impedance peak for the driver''s rated impedance.','Assuming a taller peak means a louder speaker; it reflects damping, not sensitivity.','Reading Fs from the wrong feature when box tuning adds extra peaks.']::text[],ARRAY['Measuring Fs and Q of a raw driver in free air.','Deriving Thiele-Small Q factors from an impedance sweep.','Detecting a shifted resonance that signals a damaged suspension.']::text[],'Intermediate','r0 = Zmax / Re ;  Qes = Qms / (r0 - 1) ;  Qms = (Fs/(f2-f1)) * sqrt(r0)','The impedance ratio is the peak impedance divided by the coil DC resistance; the electrical Q equals the mechanical Q divided by that ratio minus one.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impedance peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd44920b2-43f3-4efa-ade0-aff5282ca9c0','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d44920b2-43f3-4efa-ade0-aff5282ca9c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d44920b2-43f3-4efa-ade0-aff5282ca9c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9221e4df-d9dd-4f05-a287-dcc51ed5e0f1','Instantaneous compression','Instantaneous compression is the short-term, dynamic component of loudspeaker power compression: the immediate reduction in acoustic output relative to input that appears on loud peaks, before the voice coil reaches thermal equilibrium. It stems from rapid coil heating and motor and suspension nonlinearities acting on a fast time scale, unlike slow, long-term thermal compression.','A loudspeaker gives less output than expected when driven hard. Part of this loss happens fast, on loud peaks. The voice coil heats quickly and its resistance rises. Motor limits also cut the peaks. This fast loss differs from slow, steady heat build-up.','It describes the fast-acting part of power compression, helping explain why loud transients fall short of their expected level.','A technician who sees peaks fail to track drive level suspects short-term power compression, and checks coil temperature rise and headroom rather than assuming amplifier clipping.','Power Compression',ARRAY['Power compression','Thermal compression','Voice coil','Power handling']::text[],ARRAY['UNSAFE: Pushing a driver hard to test compression can overheat the voice coil and cause thermal failure or burns.','Confusing power compression with amplifier clipping; both cut output but differ in cause.','Assuming all compression is slow and thermal; a fast dynamic part also exists.','Treating the term as a formal standard; it is a descriptive name, not a standardized parameter.']::text[],ARRAY['Explaining why loud transients do not scale with input at high drive.','Comparing short-term versus long-term compression in a power test.','Diagnosing peak level loss during a sustained high-output show.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instantaneous compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9221e4df-d9dd-4f05-a287-dcc51ed5e0f1','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9221e4df-d9dd-4f05-a287-dcc51ed5e0f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9221e4df-d9dd-4f05-a287-dcc51ed5e0f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60ff6c63-1c5f-4c70-a156-2ad7224f80bc','Internal damping','Internal damping is the energy loss inherent in a diaphragm or suspension material as it flexes, expressed by its loss factor (tan delta). A high loss factor suppresses the peak amplitude of cone break-up resonances, smoothing the response, usually at the cost of a small reduction in efficiency.','Internal damping is how much a material soaks up its own vibration. A cone that loses energy as it flexes rings less. This flattens sharp break-up peaks. It makes the response smoother. It can slightly lower efficiency.','It controls the severity of diaphragm break-up, trading a little sensitivity for a smoother, better-behaved frequency response.','A technician chooses a coated-paper or filled-polymer cone over bare metal when a high internal loss factor is needed to tame a sharp break-up peak.','Material Property',ARRAY['Hysteretic damping','Loss factor','Cone break-up','Diaphragm']::text[],ARRAY['Assuming stiffer cone materials are always better; low damping leaves sharp peaks.','Confusing internal (material) damping with electrical damping from the amplifier.','Believing damping is cost-free; it usually trades against efficiency.']::text[],ARRAY['Selecting a cone material to smooth a break-up resonance.','Explaining why metal cones need notch filtering more than paper cones.','Comparing diaphragm materials for a wide-band driver.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Internal damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60ff6c63-1c5f-4c70-a156-2ad7224f80bc','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60ff6c63-1c5f-4c70-a156-2ad7224f80bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60ff6c63-1c5f-4c70-a156-2ad7224f80bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02406508-a755-4b0b-8811-6c0812e4f441','Kapton former','A Kapton former is a voice-coil bobbin (the tube the coil is wound on) made from Kapton, a polyimide film. Kapton is a registered trademark of DuPont; the generic material is a high-temperature polyimide that tolerates continuous use over a very wide range (about -269 to +400 C) and is non-magnetic and electrically insulating.','A Kapton former is the tube a voice coil is wound onto. It is made from a tough plastic film called polyimide. Kapton is DuPont''s brand name for that film. It handles very high heat without melting. Being non-metal, it avoids adding eddy-current losses.','It provides a heat-resistant, non-magnetic, insulating bobbin for the voice coil, avoiding the eddy-current losses that a metal former would add.','A technician selects a Kapton (polyimide) former where a light, high-temperature, non-conductive bobbin is needed, accepting less heat-sinking than an aluminium former provides.','Voice-Coil Component',ARRAY['Voice coil former','Aluminium former','Polyimide','Power handling']::text[],ARRAY['Treating ''Kapton'' as generic; it is DuPont''s trademark for a polyimide film.','UNSAFE: Assuming a Kapton former makes a coil immune to burnout; overpowering still causes thermal failure.','Expecting a Kapton former to sink heat like an aluminium one; polyimide conducts heat poorly.','Confusing the former material with the coil wire''s insulation.']::text[],ARRAY['Choosing a non-conducting former to avoid eddy-current damping.','Reading a driver spec that lists a polyimide (Kapton) voice-coil former.','Comparing former materials for high-power thermal handling.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kapton former');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02406508-a755-4b0b-8811-6c0812e4f441','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02406508-a755-4b0b-8811-6c0812e4f441') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02406508-a755-4b0b-8811-6c0812e4f441');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e18fc447-21d3-4ec6-be74-3d4f57ce6d85','Large-signal identification','Large-signal identification is the measurement process that extracts a loudspeaker''s nonlinear parameters, such as Bl(x), Kms(x), and Le(x,i), by driving the transducer at realistic high levels and fitting a nonlinear model to the measured current and displacement. It captures behaviour that small-signal Thiele-Small tests cannot show.','Large-signal identification measures a speaker while it is driven hard. It records how the motor and suspension change with big cone travel. From this it builds a nonlinear model. Normal small-signal tests miss this behaviour.','It reveals how a driver behaves at real operating levels, quantifying the nonlinearities that cause distortion and coil offset.','A technician runs a large-signal identification (for example on a Klippel analyzer) to obtain Bl(x), Kms(x), and Le(x) curves for setting safe excursion and protection limits.','Measurement Method',ARRAY['Large-signal model','Bl(x)','Le(x)','Linear excursion']::text[],ARRAY['Assuming Thiele-Small small-signal data describes loud behaviour; it does not.','Confusing identification (measuring) with modelling (simulating) the nonlinearities.','Ignoring the drive level; parameters must be found at realistic amplitudes.']::text[],ARRAY['Characterising a new woofer''s nonlinear behaviour for quality control.','Deriving Bl(x) and Kms(x) curves to set excursion protection.','Comparing prototypes by their large-signal distortion performance.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Large-signal identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e18fc447-21d3-4ec6-be74-3d4f57ce6d85','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e18fc447-21d3-4ec6-be74-3d4f57ce6d85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e18fc447-21d3-4ec6-be74-3d4f57ce6d85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '79e99988-5a0b-4d01-b211-62df282de358','Large-signal model','A large-signal model is a nonlinear lumped-parameter representation of a loudspeaker in which key parameters vary with state, such as force factor Bl(x), suspension stiffness Kms(x), and inductance Le(x,i). It predicts distortion, dynamic coil offset, and power compression that the linear small-signal model cannot.','A large-signal model describes a speaker driven hard. Its parameters change with cone position and current. Motor strength, spring stiffness, and coil inductance all vary. The model predicts distortion and cone drift. A simple linear model cannot.','It provides a physics-based framework for predicting nonlinear distortion and protection limits at realistic drive levels.','A technician uses a large-signal model, populated from measured Bl(x) and Kms(x) curves, to simulate distortion and set a safe maximum excursion for a driver.','Model',ARRAY['Large-signal identification','Small-signal model','Bl(x)','Le(x)']::text[],ARRAY['Using a linear (small-signal) model to predict high-level distortion.','Assuming parameters are constant; in the large-signal model they vary with state.','Forgetting that the model is only as good as the measured parameter curves.']::text[],ARRAY['Simulating a driver''s distortion before building a prototype.','Designing excursion-limiting protection from modelled nonlinearities.','Explaining dynamic coil offset predicted by an asymmetric Bl(x).']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Large-signal model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '79e99988-5a0b-4d01-b211-62df282de358','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='79e99988-5a0b-4d01-b211-62df282de358') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='79e99988-5a0b-4d01-b211-62df282de358');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ded25ac5-2717-4c5b-bcb8-293ee3470469','Le(i)','Le(i) is the voice-coil inductance expressed as a function of the instantaneous current through the coil. Current-dependent flux in the pole iron (saturation and para-inductance effects) makes the inductance vary with signal level, generating intermodulation distortion, especially where a large low-frequency current coexists with higher-frequency content.','Le(i) means coil inductance changes with the current in it. Large currents push the iron toward saturation. That shifts how much the coil resists fast current changes. The result is intermodulation distortion. It is worst when strong bass and treble play together.','It captures how signal current modulates the motor''s inductance, a distinct nonlinearity from position-dependent inductance.','A technician reading a Klippel Le(i) curve infers current-driven flux modulation and considers a shorting ring, which stabilises gap flux and flattens the curve.','Motor Nonlinearity',ARRAY['Le(x)','Flux modulation','Shorting ring','Intermodulation distortion']::text[],ARRAY['Confusing Le(i) (current-dependent) with Le(x) (position-dependent) inductance.','Assuming voice-coil inductance is a single fixed value.','Overlooking that Le(i) rises sharply as the iron approaches saturation.']::text[],ARRAY['Interpreting a current-dependent inductance curve from large-signal testing.','Explaining intermodulation distortion between bass and midrange.','Evaluating whether a shorting ring will reduce flux modulation.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Le(i)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ded25ac5-2717-4c5b-bcb8-293ee3470469','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ded25ac5-2717-4c5b-bcb8-293ee3470469') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ded25ac5-2717-4c5b-bcb8-293ee3470469');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f549fa37-fe9a-4ea7-acb4-ca72ac6bd851','Le(x)','Le(x) is the voice-coil inductance expressed as a function of coil displacement. As the coil moves in and out of the iron pole structure, the amount of surrounding magnetic material changes, so the inductance rises when the coil is inside the iron and falls when it moves out, producing distortion and a position-dependent reluctance force.','Le(x) means coil inductance changes with cone position. Moving into the iron core raises inductance. Moving out lowers it. This changing inductance distorts the signal. It also creates an extra pulling force that depends on position.','It describes a position-dependent motor nonlinearity that adds distortion and a reluctance force pulling the coil toward the iron.','A technician reads an asymmetric Le(x) curve as a sign of a reluctance force that can bias the coil, and looks for symmetry-correcting features such as pole extensions or shorting rings.','Motor Nonlinearity',ARRAY['Le(i)','Reluctance force','Shorting ring','Bl(x)']::text[],ARRAY['Confusing Le(x) (position-dependent) with Le(i) (current-dependent) inductance.','Ignoring the reluctance force that an asymmetric Le(x) creates.','Assuming inductance stays constant as the coil travels.']::text[],ARRAY['Reading a position-dependent inductance curve from large-signal testing.','Explaining a reluctance force that offsets the coil at rest.','Comparing motor designs by the symmetry of their Le(x).']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Le(x)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f549fa37-fe9a-4ea7-acb4-ca72ac6bd851','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f549fa37-fe9a-4ea7-acb4-ca72ac6bd851') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f549fa37-fe9a-4ea7-acb4-ca72ac6bd851');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14a2e4ab-3728-4343-a831-f1ee271f4a96','Leakage loss','Leakage loss is the acoustic energy lost through small air leaks and absorption in a loudspeaker enclosure, quantified by the box leakage quality factor QL. In vented-box design a typical assumption is QL of about 7 to 10; a lower QL means greater loss, which lowers and flattens the impedance saddle at the port tuning.','Leakage loss is bass energy lost through tiny gaps and absorption in a box. It is rated by a quality factor called QL. Well-sealed boxes have a higher QL. More leakage lowers the port''s tuning effect. Designers often assume a QL near seven.','It accounts for real enclosure losses in vented-box alignment maths, so predicted tuning and response match the built box.','A technician modelling a vented box uses QL near 7 as a realistic default; measuring a lower value than expected points to an air leak or excess internal absorption.','Enclosure Loss',ARRAY['Vented enclosure','Port tuning','Qtc','Impedance curves']::text[],ARRAY['Ignoring leakage loss and assuming an ideal lossless box in simulations.','Reading a higher QL as worse; higher QL actually means lower loss.','Confusing box leakage QL with the driver''s electrical or mechanical Q.']::text[],ARRAY['Choosing a realistic QL when simulating a vented subwoofer.','Diagnosing a lower-than-expected impedance saddle as an air leak.','Explaining why a poorly sealed box mistunes its port.']::text[],'Advanced','QL = R_leak / sqrt(L/C)   (box leakage quality factor at the tuning frequency Fb)','The leakage quality factor is the ratio of the box''s loss resistance to the reactance of its acoustic mass and compliance at the port tuning frequency; higher means lower loss.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Leakage loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14a2e4ab-3728-4343-a831-f1ee271f4a96','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14a2e4ab-3728-4343-a831-f1ee271f4a96') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14a2e4ab-3728-4343-a831-f1ee271f4a96');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de98604f-cc54-4f25-ab20-be348d6033a2','Line arrays','A line array is a set of loudspeaker elements arranged in a vertical column so that, over a range of frequencies, they behave like a single coherent line source. This narrows vertical directivity and reduces the rate at which level falls with distance, aiding long-throw coverage in large venues.','A line array is a tall stack of speaker boxes. Together they act like one long sound source. This tightens how sound spreads up and down. It carries level farther into a big room. Curving the array shapes the coverage.','It delivers even, long-throw coverage over large audiences by combining many elements into a controlled vertical line source.','A technician hangs and splays a line array so its coverage matches the seating rake, keeping level consistent from the front rows to the back.','Array Type',ARRAY['Line-source approximation','Line-array curvature','Grating lobes','Coverage angle']::text[],ARRAY['Assuming a line array acts as a perfect line source at all frequencies; it does so only over a band.','UNSAFE: Flying array elements without rated rigging and secondary safety chains, risking a fall.','Neglecting element spacing, which sets where grating lobes appear.','Expecting even a straight hang to cover a raked audience without curvature.']::text[],ARRAY['Covering a deep concert audience with even level.','Setting splay angles to match a sloped seating plan.','Explaining why a column source controls vertical spread.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de98604f-cc54-4f25-ab20-be348d6033a2','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de98604f-cc54-4f25-ab20-be348d6033a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de98604f-cc54-4f25-ab20-be348d6033a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '953eeed8-0a97-4635-8018-fd25c050af09','Line stuffing','Line stuffing is acoustic damping material, such as long-fibre wool or polyester fill, placed inside a transmission-line or vented enclosure. It absorbs midband energy, damps pipe (organ-pipe) resonances, and slows the speed of sound in the line, which lowers and smooths the effective tuning.','Line stuffing is fluffy material packed inside a speaker line. It soaks up unwanted midrange sound. It also calms sharp pipe resonances. Because it slows sound in the line, it lowers the tuning. Too much stuffing kills the bass output.','It tames resonances and shapes the tuning of a transmission line, trading some low-frequency output for a smoother response.','A technician adjusts stuffing density in a transmission line, adding fill to damp a peaky resonance and lower tuning, while watching that bass output is not over-damped.','Enclosure Damping',ARRAY['Transmission line','Line taper','Damping material','Leakage loss']::text[],ARRAY['Overstuffing a line, which chokes the intended low-frequency output.','Assuming stuffing only absorbs; it also lowers the effective tuning frequency.','Using the wrong material, changing both damping and airflow unpredictably.']::text[],ARRAY['Tuning a transmission-line subwoofer by adjusting fill density.','Damping an organ-pipe resonance in a ported cabinet.','Trading output for smoothness in a floor-standing tower.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line stuffing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '953eeed8-0a97-4635-8018-fd25c050af09','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='953eeed8-0a97-4635-8018-fd25c050af09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='953eeed8-0a97-4635-8018-fd25c050af09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e27bbff1-8f76-4061-936d-b5be59045ccd','Line taper','Line taper is the gradual change of a transmission line''s cross-sectional area along its length, either narrowing (tapered) or widening (expanding). The taper profile shapes the line''s resonant behaviour and impedance, controlling ripple in the response and how strongly higher-order pipe modes appear.','Line taper is how a speaker line changes width along its path. It may get narrower or wider from driver to opening. This shape controls the line''s resonances. It smooths bumps in the response. It also sets how the tuning behaves.','It gives the designer control over a transmission line''s resonances and response ripple through the shape of its cross-section.','A technician selects a tapered line that narrows toward the terminus to suppress higher-order pipe resonances and smooth the low-frequency response.','Enclosure Geometry',ARRAY['Transmission line','Line stuffing','Port tuning','Tapered quarter-wave']::text[],ARRAY['Assuming line cross-section must be constant; many designs taper it.','Confusing a narrowing taper with a widening (horn-like) expansion; they behave differently.','Ignoring taper when predicting resonance frequencies of the line.']::text[],ARRAY['Designing a tapered quarter-wave transmission line.','Suppressing higher-order pipe modes with a narrowing cross-section.','Comparing straight and tapered lines for response smoothness.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line taper');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e27bbff1-8f76-4061-936d-b5be59045ccd','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e27bbff1-8f76-4061-936d-b5be59045ccd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e27bbff1-8f76-4061-936d-b5be59045ccd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfcbfd76-5b93-487d-bcfa-6be0d00a82fa','Line-array curvature','Line-array curvature is the set of splay angles between adjacent elements of a line array, which bends the array from straight to progressively curved. Increasing splay toward the bottom spreads sound over nearer seats, shaping vertical coverage to match the audience geometry while keeping level even with distance.','Line-array curvature is the bend built into a hung array. Small angles are set between each box. A straight top section throws far. More angle at the bottom covers close seats. This shaping keeps level even across the crowd.','It shapes an array''s vertical coverage to match audience depth, trading tight long-throw at the top for wider spread lower down.','A technician uses prediction software to set inter-box splay angles, keeping the top boxes near-straight for distance and opening the lower angles to cover front seats evenly.','Array Design',ARRAY['Line arrays','Line-source approximation','Coverage angle','Splay angle']::text[],ARRAY['Hanging an array dead straight, leaving the front rows underserved.','Adding too much curvature, which spreads energy and loses throw.','Assuming one curvature suits all venues; it must match each geometry.']::text[],ARRAY['Shaping array coverage for a raked or flat audience.','Balancing level between front and rear seats.','Using prediction software to set inter-cabinet splay angles.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line-array curvature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfcbfd76-5b93-487d-bcfa-6be0d00a82fa','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfcbfd76-5b93-487d-bcfa-6be0d00a82fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfcbfd76-5b93-487d-bcfa-6be0d00a82fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '52c339d3-df9a-4c8b-9f51-f8ddf15d4985','Line-source approximation','The line-source approximation models a vertical array as an ideal continuous line radiator. In its cylindrical near field the wavefront spreads in two dimensions, so level falls about 3 dB per doubling of distance rather than the 6 dB of a point source; beyond a frequency- and length-dependent transition it reverts to point-source (6 dB) behaviour.','This model treats a speaker column as one long line of sound. Close in, its sound spreads like a cylinder. Level then drops about 3 dB each time distance doubles. A point source loses 6 dB instead. Far away, the line acts like a point again.','It provides the theory behind line arrays, predicting their slower level loss with distance and their controlled vertical coverage.','A technician applies the line-source approximation to expect roughly 3 dB loss per distance doubling in the near field, so a long array holds level deep into a venue.','Radiation Model',ARRAY['Line arrays','Line-array curvature','Cylindrical wave','Grating lobes']::text[],ARRAY['Assuming the 3 dB rule holds at all distances; it applies only in the near field.','Treating a short array as an ideal line source across the whole band.','Forgetting that the near-field length shrinks at lower frequencies.']::text[],ARRAY['Estimating level loss versus distance for a hung array.','Explaining why long arrays throw farther than single boxes.','Judging where an array stops behaving as a line source.']::text[],'Advanced','near field: SPL falls ~3 dB per doubling of distance (p ~ 1/sqrt(r)); far field: ~6 dB per doubling (p ~ 1/r)','A continuous line source loses about three decibels per doubling of distance in its cylindrical near field, then about six decibels per doubling once the far field begins.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line-source approximation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '52c339d3-df9a-4c8b-9f51-f8ddf15d4985','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='52c339d3-df9a-4c8b-9f51-f8ddf15d4985') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='52c339d3-df9a-4c8b-9f51-f8ddf15d4985');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3caf1e04-b07c-409c-b650-1a99a5a15046','Linear excursion','Linear excursion is the range of voice-coil displacement over which the motor and suspension stay approximately linear, so output rises in proportion to input with low distortion. Its limit is usually stated as Xmax, defined geometrically from coil and gap heights or, in large-signal testing, where the force factor Bl falls to about 82 percent of its rest value.','Linear excursion is how far the cone can move cleanly. Within this range, louder input gives proportionally louder output. Push past it and distortion climbs fast. The limit is called Xmax. It can be set by geometry or by a distortion criterion.','It defines the clean working range of a driver, setting the maximum undistorted output and guiding excursion-protection limits.','Geometric Xmax with an 8 mm coil winding and a 4 mm gap is (8-4)/2 = 2 mm; the Klippel criterion instead marks Xmax where Bl(x) drops to about 82 percent of its centred value.','Excursion Limit',ARRAY['Xmax','Bl(x)','Force-factor modulation','Large-signal identification']::text[],ARRAY['Treating geometric Xmax and the distortion-based Xmax as identical; they often differ.','Assuming excursion beyond Xmax is safe; distortion and damage risk rise sharply.','UNSAFE: Driving a woofer well past Xmax can bottom or tear the suspension and burn the coil.','Confusing Xmax (one-way peak) with peak-to-peak or mechanical Xlim travel.']::text[],ARRAY['Setting a subwoofer''s excursion-limiter threshold from Xmax.','Comparing drivers by clean output at a target frequency.','Reading Xmax from a Bl(x) curve during large-signal testing.']::text[],'Intermediate','Xmax(geom) = (Hvc - Hg)/2 ;  Xmax(Bl) at |Bl(x)| = 0.82 * Bl(0)','Geometric peak linear excursion equals half the difference between the voice-coil winding height and the magnetic gap height; a distortion-based limit is the travel where the force factor falls to about 82 percent of its rest value.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear excursion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3caf1e04-b07c-409c-b650-1a99a5a15046','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3caf1e04-b07c-409c-b650-1a99a5a15046') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3caf1e04-b07c-409c-b650-1a99a5a15046');
